insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('acc-001', null, '¿Qué es una base de datos?', '¿Qué extensión de archivo tienen las bases de datos creadas con Access para Microsoft 365?', array['.accdb', '.mdb', '.dbf', '.xlsx']::text[], 0, 'Las bases de datos con formato de Access 2007-2016, que también usa Access para Microsoft 365, «tienen la extensión de archivo .accdb»; las de formatos anteriores usan «.mdb».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
