insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ae-002', (select id from leyes where slug = 'ley-39-2015'), '9.3', 'Los recursos técnicos de los sistemas de identificación de la letra c) del artículo 9.2 deben estar situados, con carácter general, en:', array['Territorio español en todo caso', 'Territorio del Consejo de Europa', 'Territorio de la Unión Europea', 'Cualquier país con decisión de adecuación']::text[], 2, 'El artículo 9.3 exige que esos recursos técnicos «se encuentren situados en territorio de la Unión Europea», y en territorio español solo si se trata de categorías especiales de datos.', 2, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
