insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ae-003', (select id from leyes where slug = 'ley-39-2015'), '9.4', 'La aceptación de un sistema de identificación por la Administración General del Estado acredita la identificación electrónica:', array['Frente a todas las Administraciones, salvo prueba en contrario', 'Solo ante la Administración General del Estado', 'Ante las Administraciones adheridas por convenio', 'Frente a todas las Administraciones, sin prueba en contrario']::text[], 0, 'El artículo 9.4 señala que esa aceptación «servirá para acreditar frente a todas las Administraciones Públicas, salvo prueba en contrario, la identificación electrónica de los interesados».', 3, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
