insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ae-004', (select id from leyes where slug = 'ley-39-2015'), '9.1', 'Las Administraciones verifican la identidad de los interesados comprobando el nombre y apellidos que constan en:', array['El Padrón Municipal de habitantes', 'La inscripción en el Registro Civil', 'El certificado electrónico de firma', 'El DNI o documento identificativo equivalente']::text[], 3, 'Según el artículo 9.1, se comprueba el nombre y apellidos o razón social «que consten en el Documento Nacional de Identidad o documento identificativo equivalente».', 1, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
