insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ae-005', (select id from leyes where slug = 'ley-39-2015'), '10.5', 'Cuando un interesado utiliza un sistema de firma admitido por la Ley 39/2015, su identidad:', array['Debe acreditarse además con el DNI', 'Debe comprobarla un funcionario habilitado', 'Se entiende acreditada por el propio acto de la firma', 'Se acredita después mediante clave concertada']::text[], 2, 'El artículo 10.5 dispone que, cuando los interesados utilicen un sistema de firma, «su identidad se entenderá ya acreditada mediante el propio acto de la firma».', 1, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
