insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ae-006', (select id from leyes where slug = 'ley-39-2015'), '11.2.c', '¿Para cuál de estas actuaciones exigen las Administraciones el uso obligatorio de firma?', array['Interponer recursos', 'Consultar el estado del expediente', 'Acceder a una notificación', 'Pedir información general']::text[], 0, 'El artículo 11.2 limita la firma obligatoria a unos supuestos, entre ellos: «c) Interponer recursos.»', 1, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
