insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ae-007', (select id from leyes where slug = 'ley-39-2015'), '11.1', 'Con carácter general, para realizar cualquier actuación del procedimiento basta con que el interesado:', array['Firme con un certificado electrónico cualificado', 'Comparezca en una oficina de asistencia en registros', 'Aporte poder notarial de representación', 'Acredite antes su identidad con un medio de identificación de la ley']::text[], 3, 'El artículo 11.1 dice que «será suficiente con que los interesados acrediten previamente su identidad a través de cualquiera de los medios de identificación previstos en esta Ley».', 2, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
