insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ae-009', (select id from leyes where slug = 'ley-39-2015'), '14.2.c', 'Dentro de los profesionales con colegiación obligatoria, el artículo 14.2.c) menciona expresamente como incluidos a:', array['Los notarios y registradores de la propiedad y mercantiles', 'Los abogados y procuradores de los tribunales', 'Los gestores administrativos y graduados sociales', 'Los arquitectos e ingenieros colegiados']::text[], 0, 'El artículo 14.2.c) añade: «En todo caso, dentro de este colectivo se entenderán incluidos los notarios y registradores de la propiedad y mercantiles».', 2, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
