insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ae-010', (select id from leyes where slug = 'ley-39-2015'), '41.1.a', 'Cabe practicar una notificación por medios no electrónicos cuando el interesado:', array['La solicita por teléfono al órgano que tramita', 'Es una persona jurídica sin certificado electrónico', 'Comparece espontáneamente en una oficina de registro y la pide en ese momento', 'No accede a la sede electrónica en cinco días']::text[], 2, 'El artículo 41.1.a) lo permite «cuando la notificación se realice con ocasión de la comparecencia espontánea del interesado o su representante en las oficinas de asistencia en materia de registro y solicite la comunicación o notificación personal en ese momento».', 2, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
