insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ae-012', (select id from leyes where slug = 'ley-39-2015'), '41.7', 'Si el interesado ha sido notificado por distintos cauces, se toma como fecha de notificación:', array['La de la que se produjo en último lugar', 'La de la que se produjo en primer lugar', 'La de la notificación electrónica en todo caso', 'La que elija el propio interesado']::text[], 1, 'El artículo 41.7 dispone que «se tomará como fecha de notificación la de aquélla que se hubiera producido en primer lugar».', 1, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
