insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ae-015', (select id from leyes where slug = 'ley-39-2015'), '43.1', 'A efectos de las notificaciones electrónicas, se entiende por comparecencia en la sede electrónica:', array['El acceso del interesado identificado al contenido de la notificación', 'La puesta a disposición de la notificación en la sede', 'El envío del aviso al correo electrónico del interesado', 'La visita presencial a una oficina de asistencia']::text[], 0, 'El artículo 43.1 dice: «se entiende por comparecencia en la sede electrónica, el acceso por el interesado o su representante debidamente identificado al contenido de la notificación».', 2, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
