insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ae-016', (select id from leyes where slug = 'ley-39-2015'), '44', 'Cuando se ignora el lugar de la notificación, esta se hace por medio de un anuncio publicado en:', array['El boletín oficial de la provincia', 'El tablón de edictos del Ayuntamiento', 'El diario oficial de la Comunidad Autónoma', 'El Boletín Oficial del Estado']::text[], 3, 'El artículo 44 dispone que, en esos casos, «la notificación se hará por medio de un anuncio publicado en el» Boletín Oficial del Estado; los demás anuncios son facultativos.', 1, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
