insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ae-020', (select id from leyes where slug = 'ley-40-2015'), '38.2', 'El establecimiento de una sede electrónica conlleva la responsabilidad del titular respecto de:', array['La gratuidad, rapidez y confidencialidad del servicio', 'La disponibilidad continua y el soporte técnico', 'La integridad, veracidad y actualización de la información', 'La neutralidad, publicidad y traducción de contenidos']::text[], 2, 'El artículo 38.2 habla de «la responsabilidad del titular respecto de la integridad, veracidad y actualización de la información y los servicios».', 2, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
