insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ae-023', (select id from leyes where slug = 'ley-40-2015'), '40.2', 'Se entiende identificada la Administración Pública respecto de la información que:', array['Envíe por correo electrónico ordinario', 'Publique como propia en su portal de internet', 'Enlace desde webs de otras Administraciones', 'Difunda en sus perfiles de redes sociales']::text[], 1, 'El artículo 40.2 dice: «Se entenderá identificada la Administración Pública respecto de la información que se publique como propia en su portal de internet».', 2, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
