insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ae-024', (select id from leyes where slug = 'ley-40-2015'), '41.1', 'Para que haya actuación administrativa automatizada, el acto debe realizarse íntegramente por medios electrónicos y:', array['Con la firma manuscrita del titular del órgano', 'Fuera de un procedimiento administrativo', 'Sin intervención directa de un empleado público', 'Previa conformidad expresa del interesado']::text[], 2, 'El artículo 41.1 la define como la actuación electrónica «en la que no haya intervenido de forma directa un empleado público».', 1, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
