insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ae-030', (select id from leyes where slug = 'ley-40-2015'), '46.3', 'Las medidas de seguridad de los soportes de documentos electrónicos se ajustarán a lo previsto en:', array['El Esquema Nacional de Seguridad', 'El Esquema Nacional de Interoperabilidad', 'La Ley de Patrimonio Histórico', 'El Reglamento de registros']::text[], 0, 'El artículo 46.3 exige medidas de seguridad «de acuerdo con lo previsto en el Esquema Nacional de Seguridad».', 1, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
