insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('adu-001', (select id from leyes where slug = 'reg-ue-952-2013'), '18.1', 'En la representación aduanera directa, el representante aduanero actúa:', array['En su propio nombre pero por cuenta de otra persona', 'En su propio nombre y por cuenta propia', 'En nombre y por cuenta de otra persona', 'En nombre de otra persona pero por cuenta propia']::text[], 2, 'Según el artículo 18.1, en la representación directa «el representante aduanero actuará en nombre y por cuenta de otra persona».', 1, '2013-10-10', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
