insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('adu-002', (select id from leyes where slug = 'reg-ue-952-2013'), '18.1', 'Un agente de aduanas actúa ante la aduana en su propio nombre pero por cuenta de su cliente. Se trata de una representación:', array['Indirecta', 'Directa', 'Voluntaria sin poder', 'Subsidiaria']::text[], 0, 'El artículo 18.1 define la representación indirecta como aquella «en cuyo caso actuará en su propio nombre pero por cuenta de otra persona».', 1, '2013-10-10', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'adu-002', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 32 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('adu-003', (select id from leyes where slug = 'reg-ue-952-2013'), '18.2', 'Los representantes aduaneros deberán estar establecidos en el territorio aduanero de la Unión, salvo que actúen por cuenta de personas que:', array['Sean operadores económicos autorizados', 'Presenten una declaración de tránsito', 'Tengan su domicilio en un Estado miembro limítrofe', 'No tengan obligación de estar establecidas en dicho territorio']::text[], 3, 'El artículo 18.2 dispone que «Los representantes aduaneros deberán estar establecidos en el territorio aduanero de la Unión» y que estarán dispensados «cuando actúen por cuenta de personas que no tengan obligación de estar establecidas en el territorio aduanero de la Unión».', 2, '2013-10-10', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'adu-003', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 32 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('adu-004', (select id from leyes where slug = 'reg-ue-952-2013'), '19.1', 'Quien declare ante la aduana actuar como representante aduanero sin poseer poder de representación para ello se considera que actúa:', array['En nombre del supuesto representado', 'En su propio nombre y por cuenta propia', 'Como representante indirecto del supuesto representado', 'Como representante directo, con responsabilidad subsidiaria']::text[], 1, 'El artículo 19.1 establece que quien «declare estar actuando en tal condición sin poseer un poder de representación para ello, se considerará que actúa en su propio nombre y por cuenta propia».', 2, '2013-10-10', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'adu-004', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 32 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('adu-005', (select id from leyes where slug = 'reg-ue-952-2013'), '19.2', 'Respecto del poder de representación, las autoridades aduaneras podrán exigir a quien declare actuar como representante aduanero:', array['La inscripción previa en un registro de la aduana de entrada', 'La constitución de una garantía global en todo caso', 'La presentación de la prueba del poder de representación', 'Un informe del operador económico autorizado del representado']::text[], 2, 'El artículo 19.2 señala que «Las autoridades aduaneras podrán exigir a cualquier persona que declare estar actuando como representante aduanero la presentación de la prueba del poder de representación que le haya otorgado la persona representada».', 2, '2013-10-10', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'adu-005', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 32 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('adu-006', (select id from leyes where slug = 'reg-ue-952-2013'), '77.1', 'Nace una deuda aduanera de importación cuando las mercancías no UE sujetas a derechos se incluyen en el régimen de:', array['Despacho a libre práctica o importación temporal con exención parcial', 'Tránsito externo o depósito aduanero', 'Perfeccionamiento activo o zona franca', 'Importación temporal con exención total o tránsito interno']::text[], 0, 'Según el artículo 77.1, la deuda nace al incluirse las mercancías en «el despacho a libre práctica» o en «la importación temporal con exención parcial de derechos de importación».', 1, '2013-10-10', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
