insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('adu-030', (select id from leyes where slug = 'reg-ue-952-2013'), '144', 'Las mercancías no pertenecientes a la Unión se mantienen en depósito temporal a partir del momento de:', array['Su presentación en aduana', 'Su introducción en el territorio aduanero', 'La admisión de la declaración en aduana', 'El levante de las mercancías']::text[], 0, 'El artículo 144 dispone: «Las mercancías no pertenecientes a la Unión se mantendrán en depósito temporal a partir del momento de su presentación en aduana».', 1, '2013-10-10', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
