insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('adu-031', (select id from leyes where slug = 'reg-ue-952-2013'), '149', 'Las mercancías no UE en depósito temporal deben incluirse en un régimen aduanero o reexportarse antes de que transcurran:', array['30 días', '60 días', '180 días', '90 días']::text[], 3, 'El artículo 149 establece que las mercancías «se incluirán en un régimen aduanero o se reexportarán antes de que transcurran 90 días».', 1, '2013-10-10', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'adu-031', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 32 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('adu-032', (select id from leyes where slug = 'reg-ue-952-2013'), '147.2', 'Las mercancías en depósito temporal no pueden ser objeto de más manipulaciones que las destinadas a:', array['Facilitar su venta a terceros', 'Garantizar que se conserven inalteradas', 'Adaptar su presentación al mercado de destino', 'Modificar sus características técnicas para su despacho']::text[], 1, 'Según el artículo 147.2, las mercancías en depósito temporal «no podrán ser objeto de más manipulaciones que las destinadas a garantizar que se conserven inalteradas, sin modificar su presentación o sus características técnicas».', 3, '2013-10-10', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'adu-032', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 32 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('adu-033', (select id from leyes where slug = 'reg-ue-952-2013'), '158.1', 'Todas las mercancías que se incluyan en un régimen aduanero requieren declaración en aduana, salvo en el régimen de:', array['Tránsito externo', 'Depósito aduanero', 'Zona franca', 'Perfeccionamiento activo']::text[], 2, 'El artículo 158.1 exige declaración en aduana para «Todas las mercancías que vayan a incluirse en un régimen aduanero, salvo el régimen de zona franca».', 2, '2013-10-10', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'adu-033', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 32 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('adu-034', (select id from leyes where slug = 'reg-ue-952-2013'), '171', 'Se presenta una declaración en aduana antes de presentar las mercancías. Si estas no se presentan, la declaración se considera no presentada transcurrido un plazo de:', array['30 días', '10 días', '15 días', '45 días']::text[], 0, 'El artículo 171 prevé que «Si las mercancías no se presentan en un plazo de 30 días a partir de la presentación de la declaración en aduana, se considerará que dicha declaración no ha sido presentada».', 2, '2013-10-10', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'adu-034', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 32 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('adu-035', (select id from leyes where slug = 'reg-ue-952-2013'), '195.1', 'Cuando la inclusión de mercancías en un régimen aduanero implica el nacimiento de una deuda aduanera, el levante está supeditado:', array['Al pago de los derechos, sin posibilidad de garantía', 'A la previa extinción de la deuda aduanera', 'Solo a la admisión de la declaración en aduana', 'Al pago de los derechos o a la constitución de una garantía que cubra la deuda']::text[], 3, 'El artículo 195.1 dispone que «el levante de las mercancías estará supeditado al pago del importe de los derechos de importación o de exportación correspondiente a la deuda aduanera o a la constitución de una garantía que cubra dicha deuda».', 1, '2013-10-10', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
