insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dec-001', (select id from leyes where slug = 'ley-58-2003'), '23.1', 'La obligación tributaria de realizar pagos a cuenta, respecto de la obligación tributaria principal, tiene carácter:', array['Accesorio', 'Autónomo', 'Subsidiario', 'Solidario']::text[], 1, 'El artículo 23.1 dispone que «esta obligación tributaria tiene carácter autónomo respecto de la obligación tributaria principal».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
