insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dec-002', (select id from leyes where slug = 'ley-58-2003'), '23.2', '¿Quién puede deducir de la obligación tributaria principal el importe de los pagos a cuenta soportados?', array['El retenedor', 'El sustituto del contribuyente', 'El obligado a practicar ingresos a cuenta', 'El contribuyente']::text[], 3, 'Según el artículo 23.2, «el contribuyente podrá deducir de la obligación tributaria principal el importe de los pagos a cuenta soportados».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
