insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dec-021', (select id from leyes where slug = 'rd-1065-2007'), '118.1', 'Según el Reglamento de gestión e inspección, son declaraciones sustitutivas las que se refieran a la misma obligación tributaria y periodo que otras presentadas con anterioridad y que:', array['Las reemplacen en su contenido', 'Incluyan nuevos datos no declarados', 'Modifiquen parcialmente su contenido, subsistiendo en la parte no afectada', 'Se presenten fuera del plazo reglamentario']::text[], 0, 'El artículo 118.1 establece que «tendrán la consideración de declaraciones sustitutivas las que se refieran a la misma obligación tributaria y periodo que otras presentadas con anterioridad y que las reemplacen en su contenido».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
