insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dec-022', (select id from leyes where slug = 'rd-1065-2007'), '119.3', 'Al presentar una autoliquidación complementaria, de la cuota tributaria resultante se deducirá:', array['El importe de los pagos fraccionados del ejercicio siguiente', 'Únicamente los intereses de demora devengados', 'El importe de la sanción que pudiera corresponder', 'El importe de la autoliquidación inicial']::text[], 3, 'El artículo 119.3 indica que «de la cuota tributaria resultante de la autoliquidación complementaria se deducirá el importe de la autoliquidación inicial».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
