insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dec-023', (select id from leyes where slug = 'rd-1065-2007'), '126.2', 'El obligado tributario no podrá solicitar la rectificación de su autoliquidación cuando:', array['No haya transcurrido un mes desde su presentación inicial', 'Se tramite un procedimiento de comprobación o investigación que incluya esa obligación', 'Haya presentado antes una autoliquidación complementaria', 'Se haya ingresado la deuda dentro del periodo voluntario']::text[], 1, 'Según el artículo 126.2, no podrá solicitarla «cuando se esté tramitando un procedimiento de comprobación o investigación cuyo objeto incluya la obligación tributaria a la que se refiera la autoliquidación presentada».', 3, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
