insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dec-024', (select id from leyes where slug = 'rd-1065-2007'), '128.4', 'El plazo máximo para notificar la resolución del procedimiento de rectificación de autoliquidaciones es de:', array['Tres meses', 'Nueve meses', 'Seis meses', 'Doce meses']::text[], 2, 'El artículo 128.4 fija que «el plazo máximo para notificar la resolución de este procedimiento será de seis meses».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
