insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dad-001', (select id from leyes where slug = 'constitucion'), '9.1', 'Según el artículo 9.1 de la Constitución, están sujetos a ella y al resto del ordenamiento jurídico:', array['Únicamente los poderes públicos', 'Únicamente los ciudadanos', 'Los poderes públicos y los tribunales', 'Los ciudadanos y los poderes públicos']::text[], 3, 'El artículo 9.1 dispone que «Los ciudadanos y los poderes públicos están sujetos a la Constitución y al resto del ordenamiento jurídico».', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
