insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dad-002', (select id from leyes where slug = 'constitucion'), '9.3', 'Entre los principios que garantiza el artículo 9.3 de la Constitución figura la irretroactividad de las disposiciones:', array['Tributarias que graven la renta de las personas físicas', 'Reglamentarias dictadas por el Gobierno', 'Sancionadoras no favorables o restrictivas de derechos individuales', 'Civiles que regulen el estado de las personas']::text[], 2, 'El artículo 9.3 garantiza «la irretroactividad de las disposiciones sancionadoras no favorables o restrictivas de derechos individuales».', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
