insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dad-003', (select id from leyes where slug = 'constitucion'), '81.1', 'Según el artículo 81.1 de la Constitución, son leyes orgánicas, entre otras, las que aprueben:', array['Los Presupuestos Generales del Estado', 'Los Estatutos de Autonomía y el régimen electoral general', 'Los tributos estatales y su régimen de gestión', 'Los tratados internacionales con la Unión Europea']::text[], 1, 'El artículo 81.1 establece que son leyes orgánicas «las que aprueben los Estatutos de Autonomía y el régimen electoral general».', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
