insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dad-004', (select id from leyes where slug = 'constitucion'), '82.1', 'Las Cortes Generales pueden delegar en el Gobierno la potestad de dictar normas con rango de ley sobre materias determinadas:', array['Incluidas en el artículo 81 de la Constitución', 'No incluidas en el artículo 81 de la Constitución', 'Relativas a los derechos fundamentales', 'Relativas al régimen electoral general']::text[], 1, 'El artículo 82.1 dice que podrán delegar en el Gobierno la potestad de dictar normas con rango de ley «sobre materias determinadas no incluidas en el artículo anterior».', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
