insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dad-005', (select id from leyes where slug = 'constitucion'), '82.2', 'Según el artículo 82.2 de la Constitución, la delegación para refundir varios textos legales en uno solo se otorga mediante:', array['Una ley ordinaria', 'Una ley de bases', 'Una ley orgánica', 'Un decreto-ley']::text[], 0, 'El artículo 82.2 señala que la delegación se otorgará «por una ley ordinaria cuando se trate de refundir varios textos legales en uno solo».', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
