insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dad-006', (select id from leyes where slug = 'constitucion'), '82.3', 'La delegación legislativa en el Gobierno NO podrá permitir la subdelegación a autoridades distintas de:', array['El Presidente del Gobierno', 'Los Ministros', 'El Consejo de Estado', 'El propio Gobierno']::text[], 3, 'Según el artículo 82.3, la delegación «Tampoco podrá permitir la subdelegación a autoridades distintas del propio Gobierno».', 3, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
