insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dad-007', (select id from leyes where slug = 'constitucion'), '86.2', 'Dentro del plazo de que dispone, el Congreso debe pronunciarse expresamente sobre un decreto-ley acerca de su:', array['Sanción o promulgación', 'Tramitación como proyecto de ley únicamente', 'Convalidación o derogación', 'Remisión al Senado para su veto']::text[], 2, 'El artículo 86.2 establece que «El Congreso habrá de pronunciarse expresamente dentro de dicho plazo sobre su convalidación o derogación».', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
