insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dad-008', (select id from leyes where slug = 'constitucion'), '87.1', 'La iniciativa legislativa, de acuerdo con la Constitución y los Reglamentos de las Cámaras, corresponde:', array['Solo al Gobierno y al Congreso', 'Al Gobierno, al Congreso y al Rey', 'Al Gobierno, al Congreso y al Senado', 'Solo a las Cortes Generales']::text[], 2, 'El artículo 87.1 dispone que «La iniciativa legislativa corresponde al Gobierno, al Congreso y al Senado, de acuerdo con la Constitución y los Reglamentos de las Cámaras».', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
