insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dad-012', (select id from leyes where slug = 'constitucion'), '96.1', 'Según el artículo 96.1 de la Constitución, los tratados internacionales válidamente celebrados forman parte del ordenamiento interno una vez:', array['Ratificados por el Rey', 'Aprobados por el Senado', 'Firmados por el Gobierno', 'Publicados oficialmente en España']::text[], 3, 'El artículo 96.1 dispone que «Los tratados internacionales válidamente celebrados, una vez publicados oficialmente en España, formarán parte del ordenamiento interno».', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
