insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dad-013', (select id from leyes where slug = 'constitucion'), '97', 'Según el artículo 97 de la Constitución, el Gobierno ejerce la función ejecutiva y la potestad reglamentaria:', array['Con total independencia de las leyes', 'Solo en desarrollo de leyes orgánicas', 'De acuerdo con la Constitución y las leyes', 'Previa autorización de las Cortes Generales']::text[], 2, 'El artículo 97 establece que el Gobierno «Ejerce la función ejecutiva y la potestad reglamentaria de acuerdo con la Constitución y las leyes».', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'dad-013', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 8 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dad-014', (select id from leyes where slug = 'constitucion'), '106.1', 'Según el artículo 106.1 de la Constitución, los Tribunales controlan la potestad reglamentaria y:', array['El presupuesto de las Administraciones Públicas', 'La legalidad de la actuación administrativa', 'La oportunidad de las decisiones políticas', 'El nombramiento de los altos cargos']::text[], 1, 'El artículo 106.1 dispone que «Los Tribunales controlan la potestad reglamentaria y la legalidad de la actuación administrativa, así como el sometimiento de ésta a los fines que la justifican».', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
