insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dad-015', (select id from leyes where slug = 'ley-50-1997'), '24.1.b', 'Según la Ley del Gobierno, adoptan la forma de Real Decreto del Presidente del Gobierno:', array['Las disposiciones y actos cuya adopción venga atribuida al Presidente', 'Las normas reglamentarias de la competencia del Consejo de Ministros', 'Las decisiones del Consejo de Ministros que no sean Real Decreto', 'Las disposiciones y resoluciones de los Ministros']::text[], 0, 'El artículo 24.1.b) dice que son Reales Decretos del Presidente del Gobierno «las disposiciones y actos cuya adopción venga atribuida al Presidente».', 2, '2025-04-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
