insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dad-016', (select id from leyes where slug = 'ley-50-1997'), '24.1.d', 'Revisten la forma de Acuerdos del Consejo de Ministros:', array['Las decisiones del Consejo que no deban adoptar la forma de Real Decreto', 'Las decisiones que aprueben normas reglamentarias de su competencia', 'Las disposiciones y resoluciones de las Comisiones Delegadas', 'Las disposiciones y resoluciones de los Ministros']::text[], 0, 'El artículo 24.1.d) señala que son Acuerdos del Consejo de Ministros «las decisiones de dicho órgano colegiado que no deban adoptar la forma de Real Decreto».', 2, '2025-04-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
