insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dad-017', (select id from leyes where slug = 'ley-39-2015'), '128.1', 'Según la Ley 39/2015, la potestad reglamentaria corresponde, entre otros, a los órganos de gobierno de las Comunidades Autónomas:', array['Según lo que disponga cada Delegación del Gobierno', 'Previa autorización del Consejo de Ministros', 'De acuerdo con la legislación básica del Senado', 'De conformidad con lo establecido en sus respectivos Estatutos']::text[], 3, 'El artículo 128.1 atribuye la potestad reglamentaria a «los órganos de Gobierno de las Comunidades Autónomas, de conformidad con lo establecido en sus respectivos Estatutos».', 2, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
