insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dad-020', (select id from leyes where slug = 'tfue'), '297.1', 'Según el TFUE, los actos legislativos de la Unión entran en vigor, a falta de fecha propia, a los:', array['Diez días de su publicación en el Diario Oficial', 'Veinte días de su publicación en el Diario Oficial', 'Treinta días de su publicación en el Diario Oficial', 'Tres meses de su publicación en el Diario Oficial']::text[], 1, 'El artículo 297.1 señala que los actos legislativos «Entrarán en vigor en la fecha que ellos mismos fijen o, a falta de ella, a los veinte días de su publicación».', 3, '2016-06-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
