insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dad-021', (select id from leyes where slug = 'ley-39-2015'), '34.2', 'Según el artículo 34.2 de la Ley 39/2015, el contenido de los actos administrativos será:', array['Determinado y adecuado a los fines de aquéllos', 'Genérico y flexible según el órgano', 'Fijado libremente por el órgano competente', 'Aprobado por el órgano superior jerárquico']::text[], 0, 'El artículo 34.2 dispone que «El contenido de los actos se ajustará a lo dispuesto por el ordenamiento jurídico y será determinado y adecuado a los fines de aquéllos».', 1, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
