insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dad-022', (select id from leyes where slug = 'ley-39-2015'), '35.1.a', 'Deben ser motivados, con sucinta referencia de hechos y fundamentos de derecho, los actos que:', array['Concedan derechos sin carga alguna', 'Meramente comuniquen un trámite', 'Se dicten en ejercicio de potestades regladas', 'Limiten derechos subjetivos o intereses legítimos']::text[], 3, 'El artículo 35.1.a) obliga a motivar «Los actos que limiten derechos subjetivos o intereses legítimos».', 1, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'dad-022', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 9 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dad-023', (select id from leyes where slug = 'ley-39-2015'), '35.1.f', 'Según el artículo 35 de la Ley 39/2015, deben motivarse los actos que:', array['Admitan las pruebas propuestas por los interesados', 'Acuerden la apertura del trámite de audiencia', 'Rechacen pruebas propuestas por los interesados', 'Acusen recibo de la solicitud del interesado']::text[], 2, 'El artículo 35.1.f) incluye entre los actos motivados «Los actos que rechacen pruebas propuestas por los interesados».', 2, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
