insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dad-024', (select id from leyes where slug = 'ley-39-2015'), '35.1.g', 'Debe motivarse el acto que acuerde el desistimiento por la Administración en procedimientos:', array['Iniciados a solicitud del interesado', 'De carácter sancionador únicamente', 'Iniciados de oficio', 'De revisión de actos anulables']::text[], 2, 'El artículo 35.1.g) exige motivar «los que acuerden el desistimiento por la Administración en procedimientos iniciados de oficio».', 3, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'dad-024', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 9 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dad-025', (select id from leyes where slug = 'ley-39-2015'), '35.2', 'La motivación de los actos que pongan fin a los procedimientos selectivos y de concurrencia competitiva se realizará conforme a:', array['Lo que decida el tribunal calificador libremente', 'Lo que dispongan las normas que regulen sus convocatorias', 'La Ley de Contratos del Sector Público', 'El criterio de la Intervención General']::text[], 1, 'El artículo 35.2 dice que la motivación «se realizará de conformidad con lo que dispongan las normas que regulen sus convocatorias, debiendo, en todo caso, quedar acreditados en el procedimiento los fundamentos de la resolución».', 3, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
