insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dad-026', (select id from leyes where slug = 'ley-39-2015'), '36.2', 'Si un órgano ejerce su competencia de forma verbal, la constancia escrita del acto, cuando sea necesaria, se efectuará y firmará por:', array['El titular del órgano inferior o funcionario que la reciba oralmente', 'El titular de la competencia que dictó el acto', 'El secretario del órgano superior jerárquico', 'El interesado al que se dirige el acto']::text[], 0, 'El artículo 36.2 dispone que la constancia escrita «se efectuará y firmará por el titular del órgano inferior o funcionario que la reciba oralmente».', 3, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
