insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dad-043', (select id from leyes where slug = 'ley-39-2015'), '106.1', 'Para declarar de oficio la nulidad de un acto que ha puesto fin a la vía administrativa se exige el previo dictamen:', array['Vinculante de la Abogacía del Estado en todo caso', 'Favorable del Tribunal de Cuentas del Estado', 'Del superior jerárquico del órgano autor', 'Favorable del Consejo de Estado u órgano consultivo autonómico']::text[], 3, 'El artículo 106.1 exige «previo dictamen favorable del Consejo de Estado u órgano consultivo equivalente de la Comunidad Autónoma, si lo hubiere».', 2, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
