insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dap-029', (select id from leyes where slug = 'ley-39-2015'), '61.2', 'La petición razonada de un órgano sin competencia para iniciar un procedimiento de oficio:', array['Obliga al órgano competente a iniciar el procedimiento', 'Solo puede formularla el superior jerárquico del competente', 'No vincula al órgano competente, que debe comunicar los motivos si no inicia', 'Convierte al órgano peticionario en interesado']::text[], 2, 'Según el artículo 61.2 «La petición no vincula al órgano competente para iniciar el procedimiento, si bien deberá comunicar al órgano que la hubiera formulado los motivos por los que, en su caso, no procede la iniciación».', 2, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
