insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dap-030', (select id from leyes where slug = 'ley-39-2015'), '62.5', 'La presentación de una denuncia:', array['Confiere la condición de interesado si se inicia el procedimiento', 'Obliga a la Administración a iniciar el procedimiento', 'No confiere, por sí sola, la condición de interesado en el procedimiento', 'Impide iniciar de oficio otro procedimiento por los mismos hechos']::text[], 2, 'El artículo 62.5 establece que «La presentación de una denuncia no confiere, por sí sola, la condición de interesado en el procedimiento».', 1, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
