insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dap-035', (select id from leyes where slug = 'ley-39-2015'), '77.2', 'El período extraordinario de prueba, que el instructor puede abrir a petición de los interesados, tendrá un plazo no superior a:', array['Cinco días', 'Diez días', 'Quince días', 'Treinta días']::text[], 1, 'El artículo 77.2 prevé, a petición de los interesados, «un período extraordinario de prueba por un plazo no superior a diez días».', 3, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
