insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dap-036', (select id from leyes where slug = 'ley-39-2015'), '80.1', 'Salvo disposición expresa en contrario, los informes en el procedimiento administrativo son:', array['Preceptivos y no vinculantes', 'Facultativos y vinculantes', 'Facultativos y no vinculantes', 'Preceptivos y vinculantes']::text[], 2, 'El artículo 80.1 establece: «Salvo disposición expresa en contrario, los informes serán facultativos y no vinculantes».', 1, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
