insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dap-037', (select id from leyes where slug = 'ley-39-2015'), '85.3', 'Si el infractor reconoce su responsabilidad o paga voluntariamente una sanción solo pecuniaria, el órgano aplicará reducciones sobre la sanción propuesta de, al menos:', array['El 10 %', 'El 30 %', 'El 40 %', 'El 20 %']::text[], 3, 'El artículo 85.3 dispone que se aplicarán «reducciones de, al menos, el 20 % sobre el importe de la sanción propuesta, siendo éstos acumulables entre sí».', 2, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
