insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dap-045', (select id from leyes where slug = 'ley-39-2015'), '98.1.d', 'Los actos de las Administraciones sujetos al Derecho Administrativo son inmediatamente ejecutivos, salvo que:', array['Se trate de una sanción contra la que no quepa recurso administrativo', 'El interesado haya presentado alegaciones durante la instrucción', 'Hayan sido dictados por un órgano inferior en grado', 'Se necesite aprobación o autorización superior']::text[], 3, 'El artículo 98.1 establece que los actos serán inmediatamente ejecutivos salvo que, entre otros supuestos, «Se necesite aprobación o autorización superior».', 2, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
