insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dap-046', (select id from leyes where slug = 'ley-39-2015'), '98.2', '¿Cuál de estos medios NO figura entre los medios electrónicos preferentes para pagar una sanción pecuniaria o un derecho a la Hacienda pública?', array['Tarjeta de crédito y débito', 'Transferencia bancaria', 'Cheque conformado', 'Domiciliación bancaria']::text[], 2, 'El artículo 98.2 enumera «Tarjeta de crédito y débito», «Transferencia bancaria», «Domiciliación bancaria» y «Cualesquiera otros que se autoricen por el órgano competente en materia de Hacienda Pública».', 1, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'dap-046', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 11 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dap-047', (select id from leyes where slug = 'ley-39-2015'), '100.2', 'Si son varios los medios de ejecución forzosa admisibles, se elegirá:', array['El más rápido y eficaz para la Administración', 'El menos oneroso para la Administración actuante', 'El que designe el propio interesado obligado', 'El menos restrictivo de la libertad individual']::text[], 3, 'El artículo 100.2 dispone: «Si fueran varios los medios de ejecución admisibles se elegirá el menos restrictivo de la libertad individual».', 1, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
