insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dap-048', (select id from leyes where slug = 'ley-39-2015'), '102.1', 'Habrá lugar a la ejecución subsidiaria cuando se trate de actos que:', array['Sean personalísimos y consistan en una obligación de no hacer', 'No sean personalísimos y puedan realizarse por otro sujeto', 'Consistan en satisfacer una cantidad líquida a la Administración', 'Exijan entrar en el domicilio del afectado sin su consentimiento']::text[], 1, 'Según el artículo 102.1 «Habrá lugar a la ejecución subsidiaria cuando se trate de actos que por no ser personalísimos puedan ser realizados por sujeto distinto del obligado».', 1, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
