insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dap-049', (select id from leyes where slug = 'ley-39-2015'), '103.2', 'La multa coercitiva, respecto de las sanciones que puedan imponerse con tal carácter, es:', array['Independiente de ellas y compatible con ellas', 'Incompatible con ellas, que se excluyen entre sí', 'Sustitutiva de ellas cuando se imponga antes', 'Subsidiaria de ellas, solo si no se pagan']::text[], 0, 'El artículo 103.2 señala: «La multa coercitiva es independiente de las sanciones que puedan imponerse con tal carácter y compatible con ellas».', 2, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
