insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dap-050', (select id from leyes where slug = 'ley-39-2015'), '105', 'Contra las actuaciones de los órganos administrativos realizadas en materia de su competencia y conforme al procedimiento legal, no se admitirán a trámite:', array['Recursos de alzada', 'Acciones de responsabilidad patrimonial', 'Recursos contencioso-administrativos', 'Acciones posesorias']::text[], 3, 'El artículo 105 establece: «No se admitirán a trámite acciones posesorias contra las actuaciones de los órganos administrativos realizadas en materia de su competencia y de acuerdo con el procedimiento legalmente establecido».', 1, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
