insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dar-010', (select id from leyes where slug = 'ley-39-2015'), '119.2', 'Si en un recurso existe vicio de forma y no se estima procedente resolver sobre el fondo, el órgano ordenará:', array['La retroacción del procedimiento al momento en que el vicio fue cometido', 'La inadmisión del recurso por defecto de forma insubsanable', 'La declaración de nulidad de todo el procedimiento', 'El archivo de las actuaciones y la devolución del expediente']::text[], 0, 'El artículo 119.2 dice que «se ordenará la retroacción del procedimiento al momento en el que el vicio fue cometido».', 2, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
