insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dar-011', (select id from leyes where slug = 'ley-39-2015'), '121.2', 'Si el recurso de alzada se interpone ante el órgano que dictó el acto, este debe remitirlo al competente para resolver, con su informe y copia del expediente, en el plazo de:', array['Cinco días', 'Diez días', 'Quince días', 'Un mes']::text[], 1, 'El artículo 121.2 establece que «éste deberá remitirlo al competente en el plazo de diez días, con su informe y con una copia completa y ordenada del expediente».', 2, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
