insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dar-012', (select id from leyes where slug = 'ley-39-2015'), '123.2', 'Interpuesto un recurso de reposición, el recurso contencioso-administrativo no puede interponerse hasta que:', array['Se obtenga la autorización del órgano que dictó el acto', 'Se resuelva expresamente o se produzca su desestimación presunta', 'Se interponga previamente recurso de alzada', 'Se notifique resolución expresa, sin que valga el silencio']::text[], 1, 'El artículo 123.2 dispone: «No se podrá interponer recurso contencioso-administrativo hasta que sea resuelto expresamente o se haya producido la desestimación presunta del recurso de reposición interpuesto».', 2, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
