insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dar-017', (select id from leyes where slug = 'ley-29-1998'), '9.1.d', 'Los Juzgados Centrales conocen de las resoluciones de Ministros y Secretarios de Estado en materia de responsabilidad patrimonial cuando lo reclamado no exceda de:', array['30.050 euros', '6.000 euros', '18.000 euros', '60.000 euros']::text[], 0, 'El artículo 9.1.d) atribuye a los Juzgados Centrales «los recursos contra las resoluciones dictadas por los Ministros y Secretarios de Estado en materia de responsabilidad patrimonial cuando lo reclamado no exceda de 30.050 euros».', 3, '2026-03-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
