insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dar-018', (select id from leyes where slug = 'ley-29-1998'), '12.1.a', 'La Sala de lo Contencioso-administrativo del Tribunal Supremo conoce en única instancia de los actos y disposiciones:', array['De los Ministros y de los Secretarios de Estado', 'De los Delegados del Gobierno en las Comunidades Autónomas', 'Del Consejo de Ministros y de las Comisiones Delegadas del Gobierno', 'De los Tribunales Económico-Administrativos Regionales']::text[], 2, 'El artículo 12.1.a) atribuye al Tribunal Supremo, en única instancia, «Los actos y disposiciones del Consejo de Ministros y de las Comisiones Delegadas del Gobierno».', 1, '2026-03-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
