insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dar-021', (select id from leyes where slug = 'ley-29-1998'), '44.3', 'En el requerimiento previo entre Administraciones públicas, este se entiende rechazado si el requerido no lo contesta dentro de:', array['El mes siguiente a su recepción', 'Los diez días siguientes a su recepción', 'Los quince días siguientes a su recepción', 'Los dos meses siguientes a su recepción']::text[], 0, 'El artículo 44.3 establece: «El requerimiento se entenderá rechazado si, dentro del mes siguiente a su recepción, el requerido no lo contestara».', 1, '2026-03-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
