insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dar-022', (select id from leyes where slug = 'ley-29-1998'), '46.2', 'En la inactividad de la Administración del artículo 29, los dos meses para recurrir se cuentan desde el día siguiente a:', array['El vencimiento de los plazos señalados en dicho artículo', 'La notificación del acto presunto', 'La fecha de la reclamación del interesado', 'La publicación de la disposición impugnada']::text[], 0, 'El artículo 46.2 señala que «los dos meses se contarán a partir del día siguiente al vencimiento de los plazos señalados en dicho artículo».', 3, '2026-03-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
