insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dar-024', (select id from leyes where slug = 'ley-29-1998'), '46.5', 'El plazo de dos meses para interponer el recurso de lesividad se cuenta desde:', array['El día siguiente a la notificación del acto lesivo al interesado', 'La fecha en que se dictó el acto declarado lesivo', 'El día siguiente a la fecha de la declaración de lesividad', 'El día siguiente a la publicación de la declaración en el BOE']::text[], 2, 'El artículo 46.5 establece: «El plazo para interponer recurso de lesividad será de dos meses a contar desde el día siguiente a la fecha de la declaración de lesividad».', 2, '2026-03-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
