insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dar-025', (select id from leyes where slug = 'ley-29-1998'), '48.3', 'La Administración debe remitir al órgano judicial el expediente administrativo en el plazo improrrogable de:', array['Diez días', 'Quince días', 'Treinta días', 'Veinte días']::text[], 3, 'El artículo 48.3 dice: «El expediente deberá ser remitido en el plazo improrrogable de veinte días, a contar desde que la comunicación judicial tenga entrada en el registro general del órgano requerido».', 1, '2026-03-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
