insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dar-026', (select id from leyes where slug = 'ley-29-1998'), '50.2', 'Las Administraciones públicas demandadas se entienden personadas en el recurso contencioso-administrativo:', array['Por la contestación a la demanda', 'Por el nombramiento de su representante procesal', 'Por la recepción del emplazamiento judicial', 'Por el envío del expediente']::text[], 3, 'El artículo 50.2 establece: «Las Administraciones públicas se entenderán personadas por el envío del expediente».', 3, '2026-03-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
