insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dar-027', (select id from leyes where slug = 'ley-29-1998'), '56.1', 'En los escritos de demanda y de contestación pueden alegarse cuantos motivos procedan:', array['Solo si se plantearon antes en vía administrativa', 'Solo si constan en el escrito de interposición', 'Solo si los aprecia de oficio el Tribunal', 'Hayan sido o no planteados ante la Administración']::text[], 3, 'El artículo 56.1 permite «alegarse cuantos motivos procedan, hayan sido o no planteados ante la Administración».', 2, '2026-03-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'dar-027', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 12 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dar-028', (select id from leyes where slug = 'ley-29-1998'), '58.1', 'Las partes demandadas pueden alegar incompetencia o inadmisibilidad del recurso dentro de los primeros días del plazo para contestar la demanda, que son:', array['Tres', 'Diez', 'Cinco', 'Quince']::text[], 2, 'El artículo 58.1 dice: «Las partes demandadas podrán alegar, dentro de los primeros cinco días del plazo para contestar la demanda, los motivos que pudieren determinar la incompetencia del órgano jurisdiccional o la inadmisibilidad del recurso».', 3, '2026-03-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
