insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dar-029', (select id from leyes where slug = 'ley-29-1998'), '67.1', 'Declarado concluso el pleito, la sentencia se dicta en el plazo de:', array['Cinco días', 'Quince días', 'Veinte días', 'Diez días']::text[], 3, 'El artículo 67.1 establece: «La sentencia se dictará en el plazo de diez días desde que el pleito haya sido declarado concluso».', 1, '2026-03-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'dar-029', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 12 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dar-030', (select id from leyes where slug = 'ley-29-1998'), '72.2', 'Una sentencia firme anula una disposición general. Sus efectos generales se producen desde:', array['La fecha en que la sentencia adquiere firmeza', 'La publicación de su fallo en el mismo periódico oficial que la disposición anulada', 'La notificación de la sentencia a las partes', 'La fecha de entrada en vigor de la disposición anulada']::text[], 1, 'El artículo 72.2 dice que las sentencias firmes que anulen una disposición general «tendrán efectos generales desde el día en que sea publicado su fallo y preceptos anulados en el mismo periódico oficial en que lo hubiera sido la disposición anulada».', 2, '2026-03-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
