insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dtr-015', (select id from leyes where slug = 'ley-58-2003'), '20.1', 'El presupuesto fijado por la ley para configurar cada tributo, cuya realización origina el nacimiento de la obligación tributaria principal, es:', array['El devengo', 'El hecho imponible', 'La base imponible', 'La exigibilidad']::text[], 1, 'El artículo 20.1 define: «El hecho imponible es el presupuesto fijado por la ley para configurar cada tributo y cuya realización origina el nacimiento de la obligación tributaria principal».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
