insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dtr-016', (select id from leyes where slug = 'ley-58-2003'), '21.1', 'Salvo que la ley de cada tributo disponga otra cosa, la fecha del devengo determina:', array['El plazo de prescripción de la obligación tributaria', 'El interés de demora aplicable a la deuda', 'El lugar de presentación de la autoliquidación', 'Las circunstancias relevantes para la configuración de la obligación tributaria']::text[], 3, 'El artículo 21.1 establece: «La fecha del devengo determina las circunstancias relevantes para la configuración de la obligación tributaria, salvo que la ley de cada tributo disponga otra cosa».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'dtr-016', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 15 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dtr-017', (select id from leyes where slug = 'ley-58-2003'), '22', 'En los supuestos de exención, la ley exime del cumplimiento de la obligación tributaria principal:', array['Porque no llega a realizarse el hecho imponible', 'A pesar de realizarse el hecho imponible', 'Porque no se ha producido el devengo', 'Porque la base imponible resulta nula']::text[], 1, 'El artículo 22 define: «Son supuestos de exención aquellos en que, a pesar de realizarse el hecho imponible, la ley exime del cumplimiento de la obligación tributaria principal».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
