insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dtr-018', (select id from leyes where slug = 'ley-58-2003'), '23.1', 'La obligación tributaria de realizar pagos a cuenta tiene, respecto de la obligación tributaria principal, carácter:', array['Accesorio', 'Subsidiario', 'Formal', 'Autónomo']::text[], 3, 'El artículo 23.1 señala: «Esta obligación tributaria tiene carácter autónomo respecto de la obligación tributaria principal».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
