insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dtr-019', (select id from leyes where slug = 'ley-58-2003'), '25.2', 'Respecto de las obligaciones tributarias accesorias, las sanciones tributarias:', array['No tienen la consideración de obligaciones accesorias', 'Tienen siempre la consideración de obligaciones accesorias', 'Son accesorias solo cuando se imponen por infracciones graves', 'Son accesorias cuando se imponen en el período ejecutivo']::text[], 0, 'El artículo 25.2 dispone: «Las sanciones tributarias no tienen la consideración de obligaciones accesorias».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
