insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dtr-020', (select id from leyes where slug = 'ley-58-2003'), '26.1', 'La exigencia del interés de demora tributario:', array['Requiere la previa intimación de la Administración tributaria', 'Requiere que el retraso del obligado sea culpable', 'No requiere la previa intimación de la Administración ni un retraso culpable del obligado', 'Requiere resolución expresa que declare el incumplimiento']::text[], 2, 'El artículo 26.1 señala: «La exigencia del interés de demora tributario no requiere la previa intimación de la Administración ni la concurrencia de un retraso culpable en el obligado».', 3, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
