insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dtr-021', (select id from leyes where slug = 'ley-58-2003'), '26.6', 'Salvo que la Ley de Presupuestos Generales del Estado establezca otro diferente, el interés de demora es el interés legal del dinero incrementado en:', array['Un 10 por ciento', 'Un 20 por ciento', 'Un 25 por ciento', 'Un 50 por ciento']::text[], 2, 'El artículo 26.6 dispone que el interés de demora será el interés legal del dinero vigente «incrementado en un 25 por ciento, salvo que la Ley de Presupuestos Generales del Estado establezca otro diferente».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
