insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dtr-022', (select id from leyes where slug = 'ley-58-2003'), '27.2', 'El recargo por declaración extemporánea sin requerimiento previo es del 1 por ciento más otro 1 por ciento adicional por cada:', array['Mes completo de retraso', 'Día natural de retraso', 'Semana completa de retraso', 'Trimestre completo de retraso']::text[], 0, 'El artículo 27.2 fija: «El recargo será un porcentaje igual al 1 por ciento más otro 1 por ciento adicional por cada mes completo de retraso».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
