insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dtr-026', (select id from leyes where slug = 'ley-58-2003'), '54', 'La magnitud resultante de practicar en la base imponible las reducciones establecidas en la ley es:', array['La cuota íntegra', 'La base liquidable', 'La cuota líquida', 'La cuota diferencial']::text[], 1, 'El artículo 54 define: «La base liquidable es la magnitud resultante de practicar, en su caso, en la base imponible las reducciones establecidas en la ley».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
