insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dtr-027', (select id from leyes where slug = 'ley-58-2003'), '55.1', 'La cifra, coeficiente o porcentaje que se aplica a la base liquidable para obtener la cuota íntegra se denomina:', array['Tipo de gravamen', 'Tarifa', 'Deducción', 'Bonificación']::text[], 0, 'El artículo 55.1 establece: «El tipo de gravamen es la cifra, coeficiente o porcentaje que se aplica a la base liquidable para obtener como resultado la cuota íntegra».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
