insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('emb-020', (select id from leyes where slug = 'rd-939-2005'), '120.2', 'Si no se notifica en seis meses la resolución de una reclamación de tercería, el tercerista puede entenderla, para formular demanda judicial:', array['Estimada', 'Admitida a trámite', 'Caducada', 'Desestimada']::text[], 3, 'El artículo 120.2 fija que la resolución se notifique «en el plazo de seis meses» y que, transcurrido, «se podrá entender desestimada la reclamación a efectos de formular la correspondiente demanda judicial».', 1, '2026-08-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
