insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('emb-024', (select id from leyes where slug = 'rd-939-2005'), '79.6', 'Las cantidades retenidas por el embargo de una cuenta se ingresan en el Tesoro cuando transcurran, desde el día siguiente a la traba y sin comunicación en contrario:', array['10 días naturales', '20 días hábiles', '20 días naturales', '30 días naturales']::text[], 2, 'El artículo 79.6 establece que el importe se ingresará «una vez transcurridos 20 días naturales desde el día siguiente a la fecha de la traba» sin comunicación en contrario del órgano de recaudación.', 1, '2026-08-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'emb-024', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 24 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('emb-025', (select id from leyes where slug = 'rd-939-2005'), '82.2', 'Si el obligado percibe varios sueldos o pensiones, ¿cómo se determina la parte inembargable?', array['Se considera solo la percepción de mayor cuantía', 'Se aplica a cada percepción por separado', 'Se considera solo la percepción cobrada en primer lugar', 'Se acumulan todas las percepciones y se deduce sobre su suma']::text[], 3, 'El artículo 82.2 dispone que «se acumularán para deducir sobre la suma de todas ellas la parte inembargable».', 2, '2026-08-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
