insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('emb-026', (select id from leyes where slug = 'rd-939-2005'), '97.3', 'El obligado presenta valoración contradictoria de los bienes embargados. Si la diferencia entre ambas no excede del 20 por ciento de la menor, se estima como valor:', array['El de la tasación más baja', 'La media aritmética de ambas', 'El fijado por un tercer perito', 'El de la tasación más alta']::text[], 3, 'El artículo 97.3 señala que, si la diferencia «no excede del 20 por ciento de la menor, se estimará como valor de los bienes el de la tasación más alta».', 2, '2026-08-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
