insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('emb-027', (select id from leyes where slug = 'rd-939-2005'), '103 bis.1.b', 'Un licitador quiere pujar por un lote con un vehículo y un inmueble. El depósito obligatorio es del:', array['10 por ciento del tipo de subasta', '2 por ciento del tipo de subasta', '20 por ciento del tipo de subasta', '5 por ciento del tipo de subasta']::text[], 3, 'El artículo 103 bis.1.b) exige «Un depósito del 5 por ciento del tipo de subasta cuando los bienes o los lotes por los que desee pujar sean bienes inmuebles o contengan al menos un bien inmueble».', 3, '2026-08-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'emb-027', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 24 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('emb-028', (select id from leyes where slug = 'rd-939-2005'), '104 bis.3.b', 'Notificada la adjudicación en una subasta, el adjudicatario debe pagar la diferencia entre el precio y el depósito en los:', array['5 días siguientes a la notificación', '10 días siguientes a la notificación', '15 días siguientes a la notificación', '30 días siguientes a la notificación']::text[], 2, 'El artículo 104 bis.3.b) insta al pago de la diferencia «en los 15 días siguientes a la fecha de la notificación, con la advertencia de que si no lo completa en dicho plazo perderá el importe del depósito».', 2, '2026-08-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
