insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('emb-029', (select id from leyes where slug = 'rd-939-2005'), '113.2.b', '¿Cuál de estos gastos es una costa del procedimiento de apremio?', array['Los gastos ordinarios de los órganos de la Administración', 'Las retribuciones del personal funcionario de recaudación', 'Los gastos generales de funcionamiento del órgano de recaudación', 'Los honorarios de los registradores por actuaciones en los registros públicos']::text[], 3, 'Son costas «Los honorarios de los registradores y demás gastos que deban abonarse por las actuaciones en los registros públicos.» En cambio, «No podrán incluirse como costas los gastos ordinarios de los órganos de la Administración.»', 1, '2026-08-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
