insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('emb-030', (select id from leyes where slug = 'rd-939-2005'), '115.6', 'Terminado el apremio, si lo obtenido no cubre las costas devengadas, la parte restante de las costas:', array['Se exigirá al obligado en un procedimiento posterior', 'Será a cargo de la Administración', 'Se repartirá entre los responsables de la deuda', 'Se reclamará a los acreedores con derecho preferente']::text[], 1, 'El artículo 115.6 prevé que, si las cantidades obtenidas no cubrieran las costas devengadas, «la parte restante será a cargo de la Administración».', 2, '2026-08-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
