insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('oex-005', (select id from leyes where slug = 'ley-58-2003'), '73.1', 'La Administración Tributaria compensará de oficio las deudas tributarias que se encuentren:', array['En período voluntario de pago', 'En período ejecutivo', 'Aplazadas o fraccionadas', 'Suspendidas por la interposición de un recurso']::text[], 1, 'El artículo 73.1 dispone: «La Administración Tributaria compensará de oficio las deudas tributarias que se encuentren en período ejecutivo».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'oex-005', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 22 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('oex-006', (select id from leyes where slug = 'ley-58-2003'), '73.2', 'Las deudas tributarias vencidas, líquidas y exigibles de una comunidad autónoma con el Estado son compensables de oficio:', array['Desde el momento del devengo de la deuda', 'Solo con la conformidad expresa de la comunidad autónoma', 'Únicamente tras notificar la providencia de apremio', 'Una vez transcurrido el plazo de ingreso en período voluntario']::text[], 3, 'El artículo 73.2 prevé que serán compensables de oficio, «una vez transcurrido el plazo de ingreso en período voluntario, las deudas tributarias vencidas, líquidas y exigibles que las comunidades autónomas, entidades locales y demás entidades de derecho público tengan con el Estado».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'oex-006', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 22 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('oex-007', (select id from leyes where slug = 'ley-58-2003'), '74.1', 'Las deudas tributarias vencidas, líquidas y exigibles de las entidades locales con el Estado pueden extinguirse mediante:', array['Deducciones sobre las cantidades que la Administración del Estado deba transferirles', 'Condonación acordada por el Consejo de Ministros', 'Prescripción declarada de oficio al vencer el período voluntario', 'Dación en pago de bienes patrimoniales de la entidad']::text[], 0, 'El artículo 74.1 señala que esas deudas «podrán extinguirse con las deducciones sobre las cantidades que la Administración del Estado deba transferir a las referidas entidades».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
