insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('oex-008', (select id from leyes where slug = 'ley-58-2003'), '74.2', 'El inicio del procedimiento de deducción sobre transferencias a una entidad de derecho público determina:', array['La extinción inmediata de dichas deudas', 'El inicio del período ejecutivo de las deudas', 'La suspensión del cobro de las deudas a las que se refiera', 'La condonación parcial de los intereses de demora']::text[], 2, 'Según el artículo 74.2, «el inicio del procedimiento determinará la suspensión del cobro de las deudas a las que el mismo se refiera».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
