insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('oex-009', (select id from leyes where slug = 'ley-58-2003'), '75', 'Las deudas tributarias solo podrán condonarse:', array['Por acuerdo del Consejo de Ministros, por razones de equidad', 'Por resolución motivada del órgano de recaudación competente', 'Por orden ministerial, previo informe del Consejo de Estado', 'En virtud de ley, en la cuantía y con los requisitos que en ella se determinen']::text[], 3, 'El artículo 75 establece que «las deudas tributarias sólo podrán condonarse en virtud de ley, en la cuantía y con los requisitos que en la misma se determinen».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
