insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('oex-010', (select id from leyes where slug = 'ley-58-2003'), '76.1', 'Las deudas que no hayan podido hacerse efectivas por insolvencia probada de los obligados se dan de baja en cuentas mediante:', array['La declaración de prescripción de la deuda', 'La declaración del crédito como incobrable, total o parcial', 'El acuerdo de condonación de la deuda', 'La resolución de aplazamiento sin garantía']::text[], 1, 'El artículo 76.1 indica que se darán de baja en cuentas «mediante la declaración del crédito como incobrable, total o parcial, en tanto no se rehabiliten dentro del plazo de prescripción».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
