insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('oex-011', (select id from leyes where slug = 'ley-58-2003'), '76.2', 'Si, vencido el plazo de prescripción, un crédito dado de baja por insolvencia no se hubiera rehabilitado, la deuda tributaria:', array['Se mantendrá en cuentas hasta que el deudor recupere su solvencia', 'Se rehabilitará de oficio por un nuevo plazo de prescripción', 'Se extinguirá', 'Pasará a ser exigible únicamente a los responsables subsidiarios']::text[], 2, 'El artículo 76.2 es claro: «La deuda tributaria se extinguirá si, vencido el plazo de prescripción, no se hubiera rehabilitado».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
