insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('oex-012', (select id from leyes where slug = 'ley-58-2003'), '173.2', 'Declarado incobrable un crédito, el procedimiento de apremio se reanudará, dentro del plazo de prescripción, cuando:', array['Se tenga conocimiento de la solvencia de algún obligado al pago', 'Transcurra un año desde la declaración de incobrable', 'Lo solicite el propio obligado al pago', 'Lo acuerde el tribunal económico-administrativo competente']::text[], 0, 'El artículo 173.2 dispone que «el procedimiento de apremio se reanudará, dentro del plazo de prescripción, cuando se tenga conocimiento de la solvencia de algún obligado al pago».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
