insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('oex-013', (select id from leyes where slug = 'rd-939-2005'), '56.3', 'Si una solicitud de compensación no reúne los requisitos, el órgano competente requerirá su subsanación en el plazo de:', array['10 días, contados desde el día siguiente al de la notificación del requerimiento', '5 días, contados desde el día siguiente al de la notificación', '15 días, contados desde el día siguiente al de la notificación', '20 días, contados desde el día siguiente al de la notificación']::text[], 0, 'El artículo 56.3 prevé requerir al solicitante «para que en el plazo de 10 días contados a partir del día siguiente al de la notificación del requerimiento subsane el defecto o aporte los documentos preceptivos».', 1, '2026-08-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
