insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('oex-014', (select id from leyes where slug = 'rd-939-2005'), '56.7', 'La resolución de una solicitud de compensación a instancia del obligado al pago debe notificarse en el plazo de:', array['Tres meses', 'Cuatro meses', 'Seis meses', 'Un año']::text[], 2, 'Según el artículo 56.7, «la resolución deberá notificarse en el plazo de seis meses».', 1, '2026-08-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'oex-014', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 22 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('oex-015', (select id from leyes where slug = 'rd-939-2005'), '56.5.a', 'Denegada una compensación solicitada en período voluntario, con la notificación del acuerdo denegatorio:', array['Comienza directamente el período ejecutivo, sin plazo adicional de ingreso', 'Se inicia el plazo de ingreso regulado en el artículo 62.2 de la Ley General Tributaria', 'Debe dictarse la providencia de apremio en ese mismo acto', 'Se archiva el expediente y se devuelve al solicitante el crédito ofrecido']::text[], 1, 'El artículo 56.5.a) establece que «con la notificación del acuerdo denegatorio se iniciará el plazo de ingreso regulado en el artículo 62.2 de la Ley 58/2003, de 17 de diciembre, General Tributaria».', 3, '2026-08-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'oex-015', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 22 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('oex-016', (select id from leyes where slug = 'rd-939-2005'), '58.1', 'Cuando un deudor a la Hacienda pública es a su vez acreedor por un crédito reconocido, una vez transcurrido el período voluntario se compensa de oficio:', array['Solo el principal de la deuda, sin recargos', 'La deuda, los recargos y las costas del apremio', 'Solo los recargos del período ejecutivo', 'La deuda y los recargos del período ejecutivo que procedan']::text[], 3, 'El artículo 58.1 dispone que «se compensará de oficio la deuda y los recargos del periodo ejecutivo que procedan con el crédito».', 2, '2026-08-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'oex-016', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 22 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('oex-017', (select id from leyes where slug = 'rd-939-2005'), '59.2.a', 'Si el crédito compensado es inferior a la deuda, la parte de deuda que exceda del crédito:', array['Queda extinguida por la compensación', 'Sigue el régimen ordinario, iniciándose el apremio si no se ingresa a su vencimiento', 'Se condona de forma automática', 'Se da de baja por insolvencia parcial']::text[], 1, 'Según el artículo 59.2.a), «la parte de deuda que exceda del crédito seguirá el régimen ordinario, iniciándose el procedimiento de apremio, si no es ingresada a su vencimiento».', 2, '2026-08-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'oex-017', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 22 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('oex-018', (select id from leyes where slug = 'rd-939-2005'), '60.2.a', 'En el procedimiento de deducción sobre transferencias, a la entidad deudora se le concede para efectuar alegaciones un plazo de:', array['15 días, contados desde el día siguiente al de la notificación', '10 días, contados desde el día siguiente al de la notificación', '20 días, contados desde el día siguiente al de la notificación', 'Un mes, contado desde el día siguiente al de la notificación']::text[], 0, 'El artículo 60.2.a) indica que «se concederá un plazo de 15 días contados a partir del día siguiente a aquel en que aquella se produzca para efectuar las alegaciones que estime convenientes».', 2, '2026-08-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
