insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pgo-001', (select id from leyes where slug = 'ley-58-2003'), '59.1', '¿Cuál de los siguientes es un medio de extinción de la deuda tributaria previsto en la LGT?', array['La novación', 'La compensación', 'La caducidad', 'La confusión de derechos']::text[], 1, 'El artículo 59.1 dispone que las deudas tributarias «podrán extinguirse por pago, prescripción, compensación o condonación».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'pgo-001', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 21 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pgo-002', (select id from leyes where slug = 'ley-58-2003'), '59.2', 'Según la LGT, el pago, la compensación, la deducción sobre transferencias o la condonación tienen efectos liberatorios:', array['Sobre la totalidad de la deuda, aunque el importe sea solo parcial', 'Exclusivamente por el importe pagado, compensado, deducido o condonado', 'Sobre la deuda y los recargos, con independencia del importe satisfecho', 'Solo si cubren al menos la cuota íntegra de la deuda tributaria']::text[], 1, 'El artículo 59.2 establece que tienen efectos liberatorios «exclusivamente por el importe pagado, compensado, deducido o condonado».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'pgo-002', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 21 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pgo-003', (select id from leyes where slug = 'ley-58-2003'), '60.2', 'El pago en especie de la deuda tributaria podrá admitirse en período voluntario o ejecutivo cuando:', array['Lo solicite el obligado y el órgano de recaudación lo acepte', 'La deuda supere la cuantía que fije la Administración', 'Lo autorice el titular del órgano de recaudación de forma discrecional', 'Una Ley lo disponga expresamente']::text[], 3, 'El artículo 60.2 permite el pago en especie «cuando una Ley lo disponga expresamente y en los términos y condiciones que se prevean reglamentariamente».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'pgo-003', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 21 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pgo-004', (select id from leyes where slug = 'ley-58-2003'), '60.2', 'Un obligado solicita pagar en especie una deuda que, según el artículo 65.2 LGT, es inaplazable. ¿Qué ocurrirá con la solicitud?', array['Se tramitará, pero exigiendo garantía suficiente', 'Será objeto de inadmisión', 'Se resolverá de forma motivada en el plazo de seis meses', 'Se tramitará como una solicitud de aplazamiento']::text[], 1, 'El artículo 60.2 dispone que «Las solicitudes de pago en especie a que se refiere este apartado serán objeto de inadmisión» cuando las deudas tengan la condición de inaplazables.', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'pgo-004', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 21 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pgo-005', (select id from leyes where slug = 'ley-58-2003'), '61.1', 'Se entiende pagada en efectivo una deuda tributaria cuando:', array['Se presenta la autoliquidación correspondiente ante la Administración tributaria', 'El obligado da la orden de pago a su entidad de crédito para el ingreso', 'La Administración notifica al obligado la liquidación de la deuda tributaria', 'Se ingresa su importe en las cajas de los órganos competentes o entidades autorizadas']::text[], 3, 'El artículo 61.1 señala que se entiende pagada «cuando se haya realizado el ingreso de su importe en las cajas de los órganos competentes, oficinas recaudadoras o entidades autorizadas para su admisión».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'pgo-005', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 21 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pgo-006', (select id from leyes where slug = 'ley-58-2003'), '62.2.a', 'Una liquidación practicada por la Administración se notifica el día 10 de marzo. El pago en período voluntario podrá hacerse, si los días fueran hábiles, hasta el:', array['20 de abril', '20 de marzo', '5 de abril', '5 de mayo']::text[], 0, 'El artículo 62.2.a) fija el plazo, si la notificación se hace entre los días uno y 15 de cada mes, «hasta el día 20 del mes posterior o, si éste no fuera hábil, hasta el inmediato hábil siguiente».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'pgo-006', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 21 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pgo-007', (select id from leyes where slug = 'ley-58-2003'), '62.2.b', 'Una liquidación practicada por la Administración se notifica el día 25 de mayo. El pago en período voluntario podrá hacerse, si los días fueran hábiles, hasta el:', array['20 de junio', '5 de julio', '5 de junio', '20 de julio']::text[], 1, 'El artículo 62.2.b) dispone que, si la notificación se realiza entre los días 16 y último de cada mes, el plazo llega «hasta el día cinco del segundo mes posterior o, si éste no fuera hábil, hasta el inmediato hábil siguiente».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'pgo-007', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 21 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pgo-008', (select id from leyes where slug = 'ley-58-2003'), '62.3', 'Si sus normas reguladoras no establecen otro plazo, el pago en período voluntario de las deudas de notificación colectiva y periódica se hará entre el día uno de septiembre y el:', array['20 de noviembre', '5 de noviembre', '20 de diciembre', '5 de diciembre']::text[], 0, 'El artículo 62.3 indica que deberá efectuarse «en el período comprendido entre el día uno de septiembre y el 20 de noviembre o, si éste no fuera hábil, hasta el inmediato hábil siguiente».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'pgo-008', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 21 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pgo-009', (select id from leyes where slug = 'ley-58-2003'), '62.3', 'La Administración tributaria competente puede modificar el plazo de pago de las deudas de notificación colectiva y periódica siempre que el nuevo plazo no sea inferior a:', array['Un mes', 'Dos meses', 'Tres meses', 'Cuarenta y cinco días naturales']::text[], 1, 'El artículo 62.3 permite modificar el plazo «siempre que dicho plazo no sea inferior a dos meses».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'pgo-009', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 21 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pgo-010', (select id from leyes where slug = 'ley-58-2003'), '63.1', 'Quien debe pagar varias deudas tributarias a la Administración, ¿a qué deuda puede imputar cada pago?', array['A la que libremente determine', 'A la más antigua, siempre', 'A la de mayor importe', 'A la que designe la Administración']::text[], 0, 'El artículo 63.1 establece que «El obligado al pago de varias deudas podrá imputar cada pago a la deuda que libremente determine».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'pgo-010', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 21 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pgo-011', (select id from leyes where slug = 'ley-58-2003'), '63.3', 'En una ejecución forzosa con varias deudas acumuladas de un mismo obligado que no pueden extinguirse totalmente, la Administración aplicará el pago:', array['A la deuda de mayor importe de todas las acumuladas', 'A la deuda que el obligado determine libremente', 'A la deuda más reciente, para evitar la prescripción de las demás', 'A la más antigua, según la fecha en que fue exigible']::text[], 3, 'El artículo 63.3 dice que la Administración «aplicará el pago a la deuda más antigua. Su antigüedad se determinará de acuerdo con la fecha en que cada una fue exigible».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'pgo-011', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 21 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pgo-012', (select id from leyes where slug = 'ley-58-2003'), '64', 'Los obligados tributarios pueden consignar el importe de la deuda tributaria y, en su caso, de las costas reglamentariamente devengadas en:', array['Cualquier entidad colaboradora en la recaudación de la Administración competente', 'El Banco de España, que actúa como único depositario de las consignaciones', 'La Caja General de Depósitos u órgano equivalente de otras Administraciones', 'El órgano de recaudación que tramite la deuda, mediante ingreso en su caja']::text[], 2, 'El artículo 64 permite consignar el importe «en la Caja General de Depósitos u órgano equivalente de las restantes Administraciones públicas, o en alguna de sus sucursales».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'pgo-012', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 21 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pgo-013', (select id from leyes where slug = 'ley-58-2003'), '65.2.b', '¿Cuál de las siguientes deudas tributarias no puede ser objeto de aplazamiento o fraccionamiento?', array['Las resultantes de liquidaciones practicadas por la Administración tributaria', 'Las que se encuentren ya en período ejecutivo de recaudación', 'Las que deba cumplir el retenedor o el obligado a realizar ingresos a cuenta', 'Las derivadas de la declaración anual del IRPF presentada en plazo']::text[], 2, 'El artículo 65.2.b) excluye «Las correspondientes a obligaciones tributarias que deban cumplir el retenedor o el obligado a realizar ingresos a cuenta».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'pgo-013', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 21 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pgo-014', (select id from leyes where slug = 'ley-58-2003'), '65.2.g', '¿Cuál de las siguientes deudas tributarias es inaplazable e infraccionable?', array['Las del obligado a realizar pagos fraccionados del IRPF por actividades económicas', 'La cuota diferencial del Impuesto sobre Sociedades resultante de la autoliquidación', 'Las del obligado a realizar pagos fraccionados del Impuesto sobre Sociedades', 'Las resultantes de actas de inspección firmadas en disconformidad']::text[], 2, 'El artículo 65.2.g) excluye «Las correspondientes a obligaciones tributarias que deba cumplir el obligado a realizar pagos fraccionados del Impuesto sobre Sociedades».', 3, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'pgo-014', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 21 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pgo-015', (select id from leyes where slug = 'ley-58-2003'), '65.4', 'Cuando la totalidad de la deuda aplazada se garantice con aval solidario de entidad de crédito, el interés de demora exigible será:', array['El interés de demora incrementado en un 25 por ciento', 'El interés de demora vigente en cada momento del aplazamiento', 'No se exigirá interés alguno mientras dure el aplazamiento', 'El interés legal que corresponda hasta su ingreso']::text[], 3, 'El artículo 65.4 establece que «el interés de demora exigible será el interés legal que corresponda hasta la fecha de su ingreso».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
