insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pgo-016', (select id from leyes where slug = 'ley-58-2003'), '65.5', 'La presentación de una solicitud de aplazamiento o fraccionamiento en período voluntario:', array['Impedirá el inicio del período ejecutivo, pero no el devengo del interés de demora', 'Impedirá el inicio del período ejecutivo y el devengo del interés de demora', 'Impedirá el devengo del interés de demora, pero no el inicio del período ejecutivo', 'No impedirá el inicio del período ejecutivo ni el devengo del interés de demora']::text[], 0, 'El artículo 65.5 dispone que la solicitud en período voluntario «impedirá el inicio del período ejecutivo, pero no el devengo del interés de demora».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
