insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pgo-017', (select id from leyes where slug = 'ley-58-2003'), '65.5', 'Si se solicita un aplazamiento en período ejecutivo, mientras se tramita deberán suspenderse las actuaciones de:', array['Embargo de bienes y derechos', 'Iniciación del procedimiento de apremio', 'Liquidación de intereses de demora', 'Enajenación de los bienes embargados']::text[], 3, 'El artículo 65.5 indica que «deberán suspenderse las actuaciones de enajenación de los bienes embargados hasta la notificación de la resolución denegatoria del aplazamiento o fraccionamiento».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
