insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pgo-018', (select id from leyes where slug = 'rd-939-2005'), '33.1', 'Respecto al pago de una deuda, el tercero que la paga:', array['Queda subrogado en todos los derechos que corresponden al obligado al pago', 'Debe contar siempre con la aprobación expresa del obligado al pago', 'No está legitimado para ejercitar los derechos del obligado ante la Administración', 'Solo puede pagar si tiene interés en el cumplimiento de la obligación']::text[], 2, 'El artículo 33.1 señala que «El tercero que pague la deuda no estará legitimado para ejercitar ante la Administración los derechos que corresponden al obligado al pago».', 1, '2026-08-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'pgo-018', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 21 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pgo-019', (select id from leyes where slug = 'rd-939-2005'), '34.4', 'Si el pago se realiza a través de una entidad de crédito autorizada, la entrega al deudor del justificante de ingreso lo libera desde:', array['La fecha que consta en el justificante, por el importe que figure en él', 'La fecha en que la entidad ingresa el importe en el Tesoro público', 'El día siguiente al de la entrega del justificante al deudor', 'La fecha en que se comunique el pago al órgano de recaudación']::text[], 0, 'El artículo 34.4 dice que la entrega del justificante «liberará a este desde la fecha que se consigne en el justificante y por el importe que figure en él».', 2, '2026-08-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
