insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pgo-020', (select id from leyes where slug = 'rd-939-2005'), '34.5', 'Las órdenes de pago dadas por el deudor a las entidades de crédito autorizadas para recibir el pago:', array['Liberan al deudor desde la fecha en que se dan a la entidad', 'No surten por sí solas efectos frente a la Hacienda pública', 'Liberan al deudor desde el momento en que la entidad las acepta', 'Interrumpen el cómputo del plazo de pago en período voluntario']::text[], 1, 'El artículo 34.5 establece que las órdenes de pago «no surtirán por sí solas efectos frente a la Hacienda pública».', 3, '2026-08-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
