insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pgo-021', (select id from leyes where slug = 'rd-939-2005'), '38.3', 'Si el cargo en cuenta de una domiciliación no se realiza, o se realiza fuera de plazo, por causa no imputable al obligado, a este:', array['Se le exigirá solo el recargo de apremio reducido del 10 por ciento', 'Se le exigirán intereses de demora, pero no sanciones ni recargos', 'No se le exigirán recargos, intereses ni sanciones', 'Se le exigirán recargos, pero no intereses de demora ni sanciones']::text[], 2, 'El artículo 38.3 dispone que «no se exigirán a este recargos, intereses de demora ni sanciones».', 3, '2026-08-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
