insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pgo-023', (select id from leyes where slug = 'rd-939-2005'), '46.1.a', 'Una deuda resulta de una autoliquidación presentada fuera de plazo. La solicitud de aplazamiento se entenderá presentada en período voluntario solo si:', array['Se presenta antes de que se notifique la providencia de apremio', 'Se presenta dentro de los diez días siguientes a la autoliquidación', 'Se acompaña de garantía suficiente', 'Se presenta junto con la autoliquidación extemporánea']::text[], 3, 'El artículo 46.1.a) establece que «sólo se entenderá que la solicitud se presenta en periodo voluntario cuando la solicitud de aplazamiento o fraccionamiento se presente junto con la autoliquidación extemporánea».', 3, '2026-08-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'pgo-023', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 21 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pgo-024', (select id from leyes where slug = 'rd-939-2005'), '48.2', 'En periodo voluntario, la garantía de un aplazamiento cubrirá el importe de la deuda, los intereses de demora que genere el aplazamiento y un porcentaje de la suma de ambas partidas igual al:', array['5 por ciento', '25 por ciento', '10 por ciento', '20 por ciento']::text[], 1, 'El artículo 48.2 dispone que «La garantía cubrirá el importe de la deuda en periodo voluntario, de los intereses de demora que genere el aplazamiento y un 25 por ciento de la suma de ambas partidas».', 2, '2026-08-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
