insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pgo-025', (select id from leyes where slug = 'rd-939-2005'), '48.2', 'Cuando la deuda aplazada se encuentra en período ejecutivo, la garantía debe cubrir el importe aplazado con el recargo, los intereses de demora y, además, un porcentaje de la suma de ambas partidas igual al:', array['25 por ciento', '10 por ciento', '5 por ciento', '15 por ciento']::text[], 2, 'El artículo 48.2 señala que, en período ejecutivo, la garantía deberá cubrir «los intereses de demora que genere el aplazamiento, más un 5 por ciento de la suma de ambas partidas».', 3, '2026-08-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
