insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pgo-026', (select id from leyes where slug = 'rd-939-2005'), '48.5', 'La vigencia de la garantía constituida mediante aval o certificado de seguro de caución deberá exceder al menos al vencimiento del plazo o plazos garantizados en:', array['Tres meses', 'Seis meses', 'Un año', 'Dos meses']::text[], 1, 'El artículo 48.5 exige que «La vigencia de la garantía constituida mediante aval o certificado de seguro de caución deberá exceder al menos en seis meses al vencimiento del plazo o plazos garantizados».', 2, '2026-08-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
