insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pgo-027', (select id from leyes where slug = 'rd-939-2005'), '48.6', 'La garantía de un aplazamiento concedido deberá formalizarse en el plazo de dos meses contados desde:', array['El día siguiente al de la notificación del acuerdo de concesión', 'La fecha de presentación de la solicitud', 'El día siguiente al de vencimiento del plazo de ingreso en voluntario', 'La fecha de inicio del período ejecutivo']::text[], 0, 'El artículo 48.6 dispone que «La garantía deberá formalizarse en el plazo de dos meses contados a partir del día siguiente al de la notificación del acuerdo de concesión».', 1, '2026-08-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
