insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pgo-028', (select id from leyes where slug = 'rd-939-2005'), '52.1', 'Los vencimientos de los plazos de un aplazamiento o fraccionamiento concedido deberán coincidir con los días:', array['5 o 20 del mes', '1 o 15 del mes', '10 o 25 del mes', 'Último día del mes']::text[], 0, 'El artículo 52.1 dispone que «el vencimiento de los plazos deberá coincidir con los días 5 ó 20 del mes».', 1, '2026-08-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
