insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pgo-029', (select id from leyes where slug = 'rd-939-2005'), '52.6', 'La resolución de una solicitud de aplazamiento o fraccionamiento deberá notificarse en el plazo de:', array['Seis meses', 'Tres meses', 'Un mes', 'Doce meses']::text[], 0, 'El artículo 52.6 establece que «La resolución deberá notificarse en el plazo de seis meses».', 1, '2026-08-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
