insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pgo-030', (select id from leyes where slug = 'rd-939-2005'), '54.1.a', 'En un aplazamiento solicitado en período voluntario, si llegado el vencimiento del plazo concedido no se efectúa el pago, el período ejecutivo se iniciará:', array['El mismo día del vencimiento del plazo incumplido', 'Al día siguiente de notificarse el requerimiento de pago', 'Al día siguiente del vencimiento del plazo incumplido', 'Al día siguiente del vencimiento del plazo de ingreso en voluntario']::text[], 2, 'El artículo 54.1.a) dispone que «se iniciará el periodo ejecutivo al día siguiente del vencimiento del plazo incumplido, debiendo iniciarse el procedimiento de apremio».', 2, '2026-08-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
