insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ges-001', (select id from leyes where slug = 'ley-58-2003'), '123.1', 'Según la LGT, es un procedimiento de gestión tributaria:', array['El procedimiento de inspección', 'El procedimiento de apremio', 'El procedimiento de comprobación limitada', 'El procedimiento sancionador']::text[], 2, 'El artículo 123.1 enumera, entre los procedimientos de gestión, «e) El procedimiento de comprobación limitada.»', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
