insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ges-002', (select id from leyes where slug = 'ley-58-2003'), '124', 'El procedimiento de devolución se inicia mediante una autoliquidación de la que resulte cantidad a devolver, una solicitud de devolución o:', array['Una comunicación de datos', 'Un requerimiento de la Administración', 'Una propuesta de liquidación provisional', 'Una diligencia de la inspección']::text[], 0, 'Según el artículo 124, el procedimiento de devolución se iniciará mediante la presentación de una autoliquidación, de una solicitud de devolución «o mediante la presentación de una comunicación de datos».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
