insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ges-003', (select id from leyes where slug = 'ley-58-2003'), '125.2', 'Si una autoliquidación con cantidad a devolver se presenta fuera de plazo, el plazo para devolver se cuenta desde:', array['La finalización del plazo previsto para presentarla', 'El devengo del tributo', 'El día siguiente a la notificación de la Administración', 'La presentación de la autoliquidación extemporánea']::text[], 3, 'El artículo 125.2 dice que en la presentación fuera de plazo «el plazo al que se refiere el artículo 31 de esta ley para devolver se contará a partir de la presentación de la autoliquidación extemporánea».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
