insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ges-004', (select id from leyes where slug = 'ley-58-2003'), '127', 'El procedimiento de devolución termina, entre otras causas, por:', array['El pago voluntario de la deuda por el obligado tributario en periodo voluntario', 'El inicio de un procedimiento de verificación de datos, de comprobación limitada o de inspección', 'La interposición de un recurso de reposición contra la liquidación provisional', 'La declaración de responsabilidad solidaria de un tercero responsable']::text[], 1, 'El artículo 127 señala que terminará «por el inicio de un procedimiento de verificación de datos, de comprobación limitada o de inspección».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
