insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ges-005', (select id from leyes where slug = 'ley-58-2003'), '128.1', 'En el procedimiento iniciado mediante declaración, la Administración cuantifica la obligación tributaria mediante:', array['Una liquidación definitiva', 'Una liquidación provisional', 'Un acta de inspección', 'Una propuesta de sanción']::text[], 1, 'El artículo 128.1 indica que la declaración comunica los datos «para que la Administración cuantifique la obligación tributaria mediante la práctica de una liquidación provisional».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
