insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ges-006', (select id from leyes where slug = 'ley-58-2003'), '128.2', 'Si el procedimiento iniciado mediante declaración termina por caducidad, la Administración tributaria:', array['No puede volver a liquidar ese tributo', 'Solo puede iniciarlo de nuevo en los seis meses siguientes', 'Necesita autorización del obligado para reiniciarlo', 'Puede iniciarlo de nuevo dentro del plazo de prescripción']::text[], 3, 'El artículo 128.2 dispone que la Administración «podrá iniciar de nuevo este procedimiento para la liquidación del tributo dentro del plazo de prescripción».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
