insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ges-007', (select id from leyes where slug = 'ley-58-2003'), '129.1', 'Con carácter general, la liquidación del procedimiento iniciado mediante declaración debe notificarse en el plazo de:', array['Seis meses', 'Tres meses', 'Nueve meses', 'Doce meses']::text[], 0, 'El artículo 129.1 establece que la Administración «deberá notificar la liquidación en un plazo de seis meses desde el día siguiente a la finalización del plazo para presentar la declaración».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
