insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ges-008', (select id from leyes where slug = 'ley-58-2003'), '129.1', 'Si la declaración se presenta fuera de plazo, el plazo de seis meses para notificar la liquidación se cuenta desde:', array['El día siguiente a la finalización del plazo de presentación', 'La fecha del devengo del tributo', 'El día siguiente a la presentación de la declaración', 'El día siguiente a la notificación del requerimiento']::text[], 2, 'Según el artículo 129.1, «el plazo de seis meses para notificar la liquidación comenzará a contarse desde el día siguiente a la presentación de la declaración».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
