insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ges-009', (select id from leyes where slug = 'ley-58-2003'), '130', 'El procedimiento iniciado mediante declaración termina, entre otras causas, por:', array['Acta de conformidad firmada por el obligado', 'Resolución de un tribunal económico-administrativo', 'Pago voluntario de la deuda', 'Liquidación provisional practicada por la Administración tributaria']::text[], 3, 'El artículo 130.a) prevé la terminación «Por liquidación provisional practicada por la Administración tributaria».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
