insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ges-010', (select id from leyes where slug = 'ley-58-2003'), '131.a', 'Puede iniciarse el procedimiento de verificación de datos cuando la declaración o autoliquidación:', array['Oculte rentas no declaradas de actividades económicas', 'Adolezca de defectos formales o incurra en errores aritméticos', 'No haya sido presentada en el plazo reglamentario', 'Haya sido presentada por un representante sin poder']::text[], 1, 'El artículo 131.a) permite la verificación «Cuando la declaración o autoliquidación del obligado tributario adolezca de defectos formales o incurra en errores aritméticos».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
