insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ges-011', (select id from leyes where slug = 'ley-58-2003'), '131.c', 'Procede la verificación de datos por aplicación indebida de la normativa cuando esta resulte patente de:', array['Los requerimientos efectuados a terceros', 'Los libros y registros contables del obligado', 'La propia declaración o autoliquidación o de los justificantes aportados', 'Los datos de otros obligados tributarios']::text[], 2, 'El artículo 131.c) exige que la aplicación indebida «resulte patente de la propia declaración o autoliquidación presentada o de los justificantes aportados con la misma».', 3, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
