insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ges-012', (select id from leyes where slug = 'ley-58-2003'), '132.1', 'El procedimiento de verificación de datos puede iniciarse directamente mediante la notificación de la propuesta de liquidación cuando la Administración:', array['Cuente con datos suficientes para formularla', 'Haya practicado una comprobación de valores previa', 'Disponga de la conformidad expresa del obligado', 'Haya iniciado antes un procedimiento de inspección']::text[], 0, 'El artículo 132.1 prevé iniciarlo «mediante la notificación de la propuesta de liquidación cuando la Administración tributaria cuente con datos suficientes para formularla».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
