insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ges-013', (select id from leyes where slug = 'ley-58-2003'), '133.2', 'Terminada la verificación de datos, la Administración tributaria:', array['Puede comprobar posteriormente el objeto de la misma', 'No puede volver a comprobar el mismo objeto', 'Solo puede comprobarlo si descubre nuevos hechos', 'Solo puede comprobarlo mediante inspección']::text[], 0, 'El artículo 133.2 afirma: «La verificación de datos no impedirá la posterior comprobación del objeto de la misma.»', 3, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
