insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ges-014', (select id from leyes where slug = 'ley-58-2003'), '134.1', 'No procede la comprobación de valores si el obligado declaró utilizando:', array['Los valores publicados por cualquier Administración tributaria, sea o no la actuante', 'El valor fijado en la escritura pública otorgada ante notario por las partes', 'Los valores publicados por la propia Administración actuante en aplicación de alguno de los medios del artículo 57', 'El valor de tasación de un perito designado libremente por el propio obligado']::text[], 2, 'El artículo 134.1 admite la comprobación «salvo que el obligado tributario hubiera declarado utilizando los valores publicados por la propia Administración actuante en aplicación de alguno de los citados medios».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
