insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ges-015', (select id from leyes where slug = 'ley-58-2003'), '134.3', 'Contra la valoración efectuada en la comprobación de valores, los obligados tributarios:', array['Pueden interponer reclamación económico-administrativa independiente', 'No pueden interponer recurso o reclamación independiente', 'Pueden interponer recurso de reposición independiente', 'Solo pueden recurrir si la diferencia supera 120.000 euros']::text[], 1, 'El artículo 134.3 establece: «Los obligados tributarios no podrán interponer recurso o reclamación independiente contra la valoración, pero podrán promover la tasación pericial contradictoria».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
