insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ges-016', (select id from leyes where slug = 'ley-58-2003'), '135.1', 'La tasación pericial contradictoria se promueve dentro del plazo:', array['De diez días desde la notificación de la valoración', 'De un mes desde la propuesta de valoración', 'Del recurso de alzada ante el órgano superior', 'Del primer recurso o reclamación que proceda contra la liquidación']::text[], 3, 'El artículo 135.1 señala que se promoverá «dentro del plazo del primer recurso o reclamación que proceda contra la liquidación efectuada de acuerdo con los valores comprobados administrativamente».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
