insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ges-017', (select id from leyes where slug = 'ley-58-2003'), '135.1', 'La presentación de la solicitud de tasación pericial contradictoria determina:', array['La ejecutividad inmediata de la liquidación', 'La suspensión del plazo de pago pero no del de recurso', 'La suspensión de la ejecución de la liquidación y del plazo para recurrirla', 'La anulación de la liquidación impugnada']::text[], 2, 'Según el artículo 135.1, la solicitud «determinará la suspensión de la ejecución de la liquidación y del plazo para interponer recurso o reclamación contra la misma».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
