insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ges-018', (select id from leyes where slug = 'ley-58-2003'), '135.2', 'La tasación del perito del obligado servirá de base para la liquidación si su diferencia con la del perito de la Administración es igual o inferior a:', array['60.000 euros y al 10 por ciento de dicha tasación', '120.000 euros y al 20 por ciento de dicha tasación', '120.000 euros o al 5 por ciento de dicha tasación', '120.000 euros y al 10 por ciento de dicha tasación']::text[], 3, 'El artículo 135.2 dice que si la diferencia «es igual o inferior a 120.000 euros y al 10 por ciento de dicha tasación, esta última servirá de base para la liquidación».', 3, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
