insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ges-027', (select id from leyes where slug = 'rd-1065-2007'), '127.4', 'En la rectificación de autoliquidaciones, notificada la propuesta de resolución, el interesado puede alegar en el plazo de:', array['10 días', '1 mes', '5 días', '15 días']::text[], 3, 'El artículo 127.4 establece que se notificará la propuesta de resolución «para que en el plazo de 15 días, contados a partir del día siguiente al de la notificación de la propuesta, alegue lo que convenga a su derecho».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
