insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ges-028', (select id from leyes where slug = 'rd-1065-2007'), '155.3', 'Antes de la liquidación provisional o resolución en la verificación de datos, el obligado tiene para alegar tras la propuesta:', array['10 días', '15 días', '1 mes', '5 días']::text[], 0, 'El artículo 155.3 exige notificar la propuesta «para que en un plazo de 10 días, contados a partir del día siguiente al de la notificación de la propuesta, alegue lo que convenga a su derecho».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
