insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ges-029', (select id from leyes where slug = 'rd-1065-2007'), '164.4', '¿Qué plazo de alegaciones se concede al obligado, en la comprobación limitada, desde el día siguiente a la notificación de la propuesta?', array['20 días', '1 mes', '10 días', '15 días']::text[], 2, 'El artículo 164.4 exige notificar la propuesta «para que en un plazo de 10 días, contados a partir del día siguiente al de la notificación de la propuesta, alegue lo que convenga a su derecho».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
