insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ges-030', (select id from leyes where slug = 'rd-1065-2007'), '158.4', 'Para comprobar el valor de un bien por el precio declarado en otras transmisiones del mismo bien, estas deben haberse realizado dentro del plazo de:', array['Seis meses desde la fecha del devengo', 'Dos años desde la fecha del devengo', 'Tres meses desde la fecha de la escritura', 'Un año desde la fecha del devengo del impuesto']::text[], 3, 'El artículo 158.4 permite atender al valor declarado en otras transmisiones «realizadas dentro del plazo de un año desde la fecha del devengo del impuesto en el que surta efecto».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
