insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('isc-013', (select id from leyes where slug = 'ley-27-2014'), '12.1.c', '¿Cuál de los siguientes elementos NO puede acogerse a la amortización mediante el método de los números dígitos?', array['La maquinaria', 'Los elementos de transporte', 'El mobiliario y enseres', 'Los equipos para procesos de información']::text[], 2, 'El artículo 12.1.c) establece que «los edificios, mobiliario y enseres no podrán acogerse a la amortización mediante números dígitos».', 2, '2026-09-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'isc-013', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 29 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('isc-014', (select id from leyes where slug = 'ley-27-2014'), '12.3.e', 'Pueden amortizarse libremente los elementos nuevos del inmovilizado material cuyo valor unitario no exceda de:', array['300 euros, hasta el límite de 50.000 euros referido al período impositivo', '300 euros, hasta el límite de 25.000 euros referido al período impositivo', '600 euros, hasta el límite de 25.000 euros referido al período impositivo', '1.000 euros, hasta el límite de 10.000 euros referido al período impositivo']::text[], 1, 'El artículo 12.3.e) permite amortizar libremente «los elementos del inmovilizado material nuevos, cuyo valor unitario no exceda de 300 euros, hasta el límite de 25.000 euros referido al período impositivo».', 3, '2026-09-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'isc-014', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 29 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('isc-015', (select id from leyes where slug = 'ley-27-2014'), '13.1.a', 'Es deducible la pérdida por deterioro de un crédito por insolvencia del deudor cuando, en el momento del devengo, haya transcurrido desde el vencimiento de la obligación el plazo de:', array['3 meses', '12 meses', '2 años', '6 meses']::text[], 3, 'El artículo 13.1.a) exige «que haya transcurrido el plazo de 6 meses desde el vencimiento de la obligación».', 1, '2026-09-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'isc-015', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 29 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('isc-016', (select id from leyes where slug = 'ley-27-2014'), '13.1', '¿Cuál de las siguientes pérdidas por deterioro de créditos es fiscalmente deducible, con carácter general?', array['La derivada de una estimación global del riesgo de insolvencias de clientes', 'La de un crédito adeudado por una entidad de derecho público sin litigio sobre él', 'La de un crédito cuyo deudor está declarado en concurso', 'La de un crédito adeudado por una entidad vinculada que no esté en concurso']::text[], 2, 'Es deducible el deterioro cuando «el deudor esté declarado en situación de concurso» (art. 13.1.b), y no lo son «las correspondientes a estimaciones globales del riesgo de insolvencias de clientes y deudores».', 2, '2026-09-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'isc-016', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 29 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('isc-017', (select id from leyes where slug = 'ley-27-2014'), '15.c', 'No tienen la consideración de gastos fiscalmente deducibles:', array['Las multas y sanciones penales y administrativas', 'Los gastos por atenciones a clientes dentro del límite legal', 'Las retribuciones a administradores por funciones de alta dirección', 'Los gastos realizados para promocionar la venta de bienes']::text[], 0, 'El artículo 15.c) excluye «las multas y sanciones penales y administrativas, los recargos del período ejecutivo y el recargo por declaración extemporánea sin requerimiento previo».', 1, '2026-09-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'isc-017', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 29 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('isc-018', (select id from leyes where slug = 'ley-27-2014'), '15.e', 'Los gastos por atenciones a clientes o proveedores son deducibles con el límite del:', array['5 por ciento del importe neto de la cifra de negocios del período impositivo', '1 por ciento de la base imponible previa del período impositivo', '10 por ciento de los gastos de personal del período impositivo', '1 por ciento del importe neto de la cifra de negocios del período impositivo']::text[], 3, 'El artículo 15.e) dispone que «los gastos por atenciones a clientes o proveedores serán deducibles con el límite del 1 por ciento del importe neto de la cifra de negocios del período impositivo».', 2, '2026-09-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'isc-018', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 29 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('isc-019', (select id from leyes where slug = 'ley-27-2014'), '15.i', 'No son deducibles los gastos derivados de la extinción de la relación laboral que excedan, para cada perceptor, del mayor de dos importes. Uno de ellos es:', array['500.000 euros', '1 millón de euros', '2 millones de euros', '100.000 euros']::text[], 1, 'El artículo 15.i) no admite los gastos que «excedan, para cada perceptor, del mayor de los siguientes importes: 1.º 1 millón de euros»; el 2.º es el importe obligatorio según el Estatuto de los Trabajadores.', 3, '2026-09-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'isc-019', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 29 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('isc-020', (select id from leyes where slug = 'ley-27-2014'), '16.1', 'Los gastos financieros netos son deducibles con el límite del:', array['30 por ciento de la base imponible previa', '30 por ciento del beneficio operativo del ejercicio', '50 por ciento del beneficio operativo del ejercicio', '25 por ciento del importe neto de la cifra de negocios']::text[], 1, 'El artículo 16.1 establece que «los gastos financieros netos serán deducibles con el límite del 30 por ciento del beneficio operativo del ejercicio».', 2, '2026-09-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'isc-020', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 29 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('isc-021', (select id from leyes where slug = 'ley-27-2014'), '16.2', 'Si los gastos financieros netos del período no alcanzan el límite del artículo 16.1, la diferencia se adiciona al límite en los períodos impositivos que concluyan en los:', array['Tres años inmediatos y sucesivos', 'Diez años inmediatos y sucesivos', 'Dieciocho años inmediatos y sucesivos', 'Cinco años inmediatos y sucesivos']::text[], 3, 'Según el artículo 16.2, la diferencia se adicionará al límite «en los períodos impositivos que concluyan en los cinco años inmediatos y sucesivos, hasta que se deduzca dicha diferencia».', 3, '2026-09-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
