insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('isc-022', (select id from leyes where slug = 'ley-27-2014'), '18.1', 'Las operaciones efectuadas entre personas o entidades vinculadas se valorarán, a efectos del IS, por su:', array['Valor de mercado', 'Valor contable', 'Valor nominal', 'Valor catastral']::text[], 0, 'El artículo 18.1 dispone que «las operaciones efectuadas entre personas o entidades vinculadas se valorarán por su valor de mercado».', 1, '2026-09-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'isc-022', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 29 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('isc-023', (select id from leyes where slug = 'ley-27-2014'), '18.3', 'La documentación específica de operaciones vinculadas tiene un contenido simplificado para las personas o entidades cuyo importe neto de la cifra de negocios sea inferior a:', array['10 millones de euros', '25 millones de euros', '45 millones de euros', '100 millones de euros']::text[], 2, 'El artículo 18.3 establece que la documentación «tendrá un contenido simplificado» para vinculadas cuyo importe neto de la cifra de negocios «sea inferior a 45 millones de euros».', 3, '2026-09-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
