insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('isc-024', (select id from leyes where slug = 'ley-27-2014'), '25.1', 'Para aplicar la reducción por reserva de capitalización, el incremento de los fondos propios debe mantenerse, salvo pérdidas contables, durante un plazo de:', array['1 año desde el cierre del período impositivo', '5 años desde el cierre del período impositivo', '10 años desde el cierre del período impositivo', '3 años desde el cierre del período impositivo']::text[], 3, 'El artículo 25.1.a) exige «que el importe del incremento de los fondos propios de la entidad se mantenga durante un plazo de 3 años desde el cierre del período impositivo al que corresponda esta reducción».', 1, '2026-09-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
