insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('isc-026', (select id from leyes where slug = 'ley-27-2014'), '26.1', 'Con carácter general, la compensación de bases imponibles negativas está limitada al porcentaje de la base imponible previa que establece la Ley. Ese porcentaje es el:', array['50 por ciento', '60 por ciento', '70 por ciento', '80 por ciento']::text[], 2, 'El artículo 26.1 permite compensar las bases imponibles negativas «con el límite del 70 por ciento de la base imponible previa a la aplicación de la reserva de capitalización».', 2, '2026-09-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
