insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('isc-028', (select id from leyes where slug = 'ley-27-2014'), '27.3', 'El período impositivo del Impuesto sobre Sociedades no excederá de:', array['12 meses', '6 meses', '18 meses', '24 meses']::text[], 0, 'El artículo 27.3 establece que «el período impositivo no excederá de 12 meses».', 1, '2026-09-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
