insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('isc-029', (select id from leyes where slug = 'ley-27-2014'), '28', 'El Impuesto sobre Sociedades se devenga:', array['El primer día del período impositivo', 'El 31 de diciembre de cada año', 'El último día del período impositivo', 'El día de presentación de la declaración']::text[], 2, 'El artículo 28 dispone que «el impuesto se devengará el último día del período impositivo».', 1, '2026-09-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
