insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('isc-030', (select id from leyes where slug = 'ley-27-2014'), '29.1', 'El tipo general de gravamen del Impuesto sobre Sociedades es el:', array['20 por ciento', '25 por ciento', '30 por ciento', '23 por ciento']::text[], 1, 'El artículo 29.1 establece que «el tipo general de gravamen para los contribuyentes de este Impuesto será el 25 por ciento».', 1, '2026-09-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
