insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('isc-031', (select id from leyes where slug = 'ley-27-2014'), '29.1', 'Las entidades de nueva creación que realicen actividades económicas tributan, en el primer período impositivo en que la base imponible resulte positiva y en el siguiente, al tipo del:', array['17 por ciento', '10 por ciento', '20 por ciento', '15 por ciento']::text[], 3, 'Según el artículo 29.1, estas entidades «tributarán, en el primer período impositivo en que la base imponible resulte positiva y en el siguiente, al tipo del 15 por ciento».', 2, '2026-09-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
