insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('isc-032', (select id from leyes where slug = 'ley-27-2014'), '29.6', 'Las entidades de crédito tributan en el Impuesto sobre Sociedades al tipo del:', array['25 por ciento', '35 por ciento', '30 por ciento', '20 por ciento']::text[], 2, 'El artículo 29.6 dispone que «tributarán al tipo del 30 por ciento las entidades de crédito».', 1, '2026-09-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
