insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('isc-033', (select id from leyes where slug = 'ley-27-2014'), '29.2', 'Las sociedades cooperativas fiscalmente protegidas tributan, por sus resultados cooperativos, a los tipos del apartado 1 minorados en:', array['Tres puntos porcentuales, sin que el tipo resultante supere el 20 por ciento', 'Cinco puntos porcentuales, sin que el tipo resultante supere el 15 por ciento', 'Dos puntos porcentuales, sin que el tipo resultante supere el 25 por ciento', 'Tres puntos porcentuales, sin que el tipo resultante supere el 25 por ciento']::text[], 0, 'El artículo 29.2 señala que tributarán «a los tipos de gravamen resultantes de minorar en tres puntos porcentuales los tipos de gravamen previstos en el apartado anterior, siempre que el tipo resultante no supere el 20 por ciento».', 3, '2026-09-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
