insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('isc-034', (select id from leyes where slug = 'ley-27-2014'), '33.1', 'Las rentas obtenidas en Ceuta o Melilla por entidades que operen efectiva y materialmente en dichos territorios tienen una bonificación en la cuota íntegra del:', array['50 por ciento', '75 por ciento', '95 por ciento', '60 por ciento']::text[], 3, 'El artículo 33.1 establece «una bonificación del 60 por ciento, la parte de cuota íntegra que corresponda a las rentas obtenidas en Ceuta o Melilla».', 2, '2026-09-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
