insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('isc-035', (select id from leyes where slug = 'ley-27-2014'), '39.1', 'Las cantidades correspondientes a las deducciones del capítulo IV no deducidas en el período podrán aplicarse en los períodos impositivos que concluyan en los:', array['10 años inmediatos y sucesivos', '15 años inmediatos y sucesivos', '5 años inmediatos y sucesivos', '20 años inmediatos y sucesivos']::text[], 1, 'El artículo 39.1 dispone que «las cantidades correspondientes al período impositivo no deducidas podrán aplicarse en las liquidaciones de los periodos impositivos que concluyan en los 15 años inmediatos y sucesivos».', 3, '2026-09-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
