insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('isc-036', (select id from leyes where slug = 'ley-27-2014'), '40.1', 'Los pagos fraccionados del Impuesto sobre Sociedades se efectúan en los primeros 20 días naturales de los meses de:', array['Marzo, junio y septiembre', 'Abril, octubre y diciembre', 'Enero, abril y julio', 'Abril, julio y octubre']::text[], 1, 'El artículo 40.1 ordena que «en los primeros 20 días naturales de los meses de abril, octubre y diciembre, los contribuyentes deberán efectuar un pago fraccionado».', 1, '2026-09-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
