insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('isc-037', (select id from leyes where slug = 'ley-27-2014'), '101.1', 'Los incentivos fiscales para entidades de reducida dimensión se aplican si el importe neto de la cifra de negocios del período impositivo inmediato anterior fue inferior a:', array['1 millón de euros', '6 millones de euros', '20 millones de euros', '10 millones de euros']::text[], 3, 'El artículo 101.1 dispone que los incentivos se aplicarán «siempre que el importe neto de la cifra de negocios habida en el período impositivo inmediato anterior sea inferior a 10 millones de euros».', 1, '2026-09-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
