insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('isc-038', (select id from leyes where slug = 'ley-27-2014'), '105.1', 'Una entidad de reducida dimensión que aplica la reserva de nivelación puede minorar su base imponible positiva hasta el:', array['10 por ciento de su importe, sin superar 1 millón de euros', '20 por ciento de su importe, sin superar 1 millón de euros', '10 por ciento de su importe, sin superar 5 millones de euros', '25 por ciento de su importe, sin límite de cuantía']::text[], 0, 'El artículo 105.1 permite «minorar su base imponible positiva hasta el 10 por ciento de su importe» y añade que «la minoración no podrá superar el importe de 1 millón de euros».', 3, '2026-09-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
