insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('isc-039', (select id from leyes where slug = 'ley-27-2014'), '124.1', 'Una sociedad cuyo período impositivo coincide con el año natural debe presentar la declaración del IS en el plazo de los 25 días naturales siguientes a los 6 meses posteriores a la conclusión del período. ¿Hasta qué fecha puede presentarla?', array['El 25 de junio', 'El 30 de junio', 'El 25 de julio', 'El 25 de octubre']::text[], 2, 'El artículo 124.1 señala que «la declaración se presentará en el plazo de los 25 días naturales siguientes a los 6 meses posteriores a la conclusión del período impositivo»; si este termina el 31 de diciembre, los 6 meses acaban el 30 de junio.', 2, '2026-09-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
