insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('isc-040', (select id from leyes where slug = 'rd-634-2015'), '1.3', 'Una entidad que utiliza a efectos contables un criterio de imputación temporal distinto del devengo debe solicitar su eficacia fiscal con, al menos, la siguiente antelación a la conclusión del primer período impositivo en que quiera que surta efectos:', array['3 meses', '1 mes', '12 meses', '6 meses']::text[], 3, 'El artículo 1.3 del Reglamento establece que «la solicitud se presentará con, al menos, 6 meses de antelación a la conclusión del primer período impositivo respecto del que se pretenda que tenga efectos».', 2, '2026-05-29', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
