insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inf-031', (select id from leyes where slug = 'ley-58-2003'), '88.6', 'Según la LGT, la Administración debe contestar por escrito las consultas tributarias que reúnan los requisitos en el plazo de:', array['Seis meses desde su presentación', 'Tres meses desde su presentación', 'Un año desde su presentación', 'Diez días desde su presentación']::text[], 0, 'El artículo 88.6 obliga a contestar «en el plazo de seis meses desde su presentación».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'inf-031', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 17 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inf-032', (select id from leyes where slug = 'ley-58-2003'), '88.2', 'Las consultas tributarias escritas deben formularse:', array['Dentro de los seis meses siguientes a la finalización del plazo de declaración', 'En cualquier momento mientras no haya prescrito el derecho', 'Antes de que finalice el plazo para presentar la declaración o autoliquidación', 'Solo una vez notificada la liquidación correspondiente']::text[], 2, 'Según el artículo 88.2, «se formularán antes de la finalización del plazo establecido para el ejercicio de los derechos, la presentación de declaraciones o autoliquidaciones o el cumplimiento de otras obligaciones tributarias».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'inf-032', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 17 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inf-033', (select id from leyes where slug = 'ley-58-2003'), '89.4', 'Contra la contestación a una consulta tributaria escrita, el obligado tributario:', array['Puede interponer recurso de reposición en el plazo de un mes', 'Puede reclamar directamente ante el Tribunal Económico-Administrativo', 'Puede recurrir solo si la contestación es contraria a su criterio', 'No puede interponer recurso, pero sí contra los actos posteriores que la apliquen']::text[], 3, 'La contestación «tendrá carácter informativo y el obligado tributario no podrá entablar recurso alguno contra dicha contestación».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'inf-033', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 17 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inf-034', (select id from leyes where slug = 'ley-58-2003'), '89.3', 'La presentación y contestación de una consulta tributaria escrita, respecto de los plazos para cumplir obligaciones tributarias:', array['Los suspende hasta que se notifica la contestación', 'No interrumpe esos plazos', 'Los interrumpe durante un máximo de seis meses', 'Los amplía en un mes tras la contestación']::text[], 1, 'El artículo 89.3 dispone que «no interrumpirá los plazos establecidos en las normas tributarias para el cumplimiento de las obligaciones tributarias».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'inf-034', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 17 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inf-035', (select id from leyes where slug = 'ley-58-2003'), '89.2', 'No tiene efectos vinculantes para la Administración la contestación a una consulta presentada en plazo que plantee cuestiones relacionadas con:', array['La calificación tributaria de un contrato de arrendamiento', 'La aplicación de un beneficio fiscal a una entidad sin ánimo de lucro', 'El objeto de un procedimiento, recurso o reclamación iniciado con anterioridad', 'La tributación de operaciones realizadas en otro Estado']::text[], 2, 'Según el artículo 89.2, no tendrán efectos vinculantes las contestaciones que «planteen cuestiones relacionadas con el objeto o tramitación de un procedimiento, recurso o reclamación iniciado con anterioridad».', 3, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'inf-035', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 17 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inf-036', (select id from leyes where slug = 'ley-58-2003'), '88.3', 'Pueden formular consultas tributarias, cuando afecten a la generalidad de sus miembros o asociados, entre otros:', array['Los sindicatos', 'Los partidos políticos', 'Las comunidades de propietarios', 'Los ayuntamientos']::text[], 0, 'El artículo 88.3 cita a «los colegios profesionales, cámaras oficiales, organizaciones patronales, sindicatos, asociaciones de consumidores».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'inf-036', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 17 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inf-037', (select id from leyes where slug = 'ley-58-2003'), '88.4', 'Si una consulta tributaria no reúne los requisitos reglamentarios y no se subsana a requerimiento de la Administración, esta:', array['La inadmitirá sin necesidad de notificarlo', 'La archivará, con notificación al interesado', 'La contestará con carácter meramente informativo', 'La remitirá al órgano de inspección competente']::text[], 1, 'El artículo 88.4 establece que «archivará, con notificación al interesado, las consultas que no reúnan los requisitos» y no sean subsanadas.', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'inf-037', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 17 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inf-038', (select id from leyes where slug = 'rd-1065-2007'), '66.6', 'Si una consulta tributaria escrita no reúne los requisitos del reglamento, se requerirá su subsanación en el plazo de:', array['5 días, contados desde el día siguiente a la notificación del requerimiento', '15 días, contados desde el día siguiente a la notificación del requerimiento', 'Un mes, contado desde el día siguiente a la notificación del requerimiento', '10 días, contados desde el día siguiente a la notificación del requerimiento']::text[], 3, 'El artículo 66.6 exige subsanar «en un plazo de 10 días, contados a partir del día siguiente al de la notificación del requerimiento», so pena de tener al obligado «por desistido de la consulta».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
