insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inf-039', (select id from leyes where slug = 'ley-58-2003'), '92.3.e', '¿Cuál de estos aspectos de la colaboración social exige la previa autorización de los obligados tributarios?', array['Las campañas de información y difusión', 'La simplificación del cumplimiento de las obligaciones tributarias', 'La presentación y remisión de autoliquidaciones y declaraciones a la Administración', 'La realización de estudios o informes sobre disposiciones generales']::text[], 2, 'El artículo 92.3.e) incluye la «Presentación y remisión a la Administración tributaria de autoliquidaciones, declaraciones, comunicaciones o cualquier otro documento con trascendencia tributaria, previa autorización de los obligados tributarios».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
