insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inf-040', (select id from leyes where slug = 'ley-58-2003'), '93.3', 'Los requerimientos individualizados de información sobre movimientos de cuentas bancarias, en inspección o recaudación, requieren:', array['Previa autorización del órgano que reglamentariamente se determine', 'Autorización judicial previa, otorgada en todo caso por el juez', 'Consentimiento expreso del titular de la cuenta investigada', 'Comunicación previa al titular con diez días de antelación']::text[], 0, 'Según el artículo 93.3, pueden efectuarse «en el ejercicio de las funciones de inspección o recaudación, previa autorización del órgano de la Administración tributaria que reglamentariamente se determine».', 3, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
