insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inf-041', (select id from leyes where slug = 'ley-58-2003'), '93.4.a', 'Los funcionarios públicos deben suministrar a la Administración tributaria la información de que dispongan, salvo que sea aplicable:', array['El secreto bancario', 'El secreto del contenido de la correspondencia', 'El secreto de las deliberaciones del órgano', 'El secreto comercial']::text[], 1, 'El artículo 93.4 excluye, entre otros, «El secreto del contenido de la correspondencia».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
