insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inf-042', (select id from leyes where slug = 'rd-1065-2007'), '114.2', 'En las notificaciones en apartados postales del operador del servicio postal universal, la notificación se entiende practicada por el transcurso de:', array['5 días naturales desde el depósito del envío en la oficina', '10 días hábiles desde el depósito del envío en la oficina', '15 días naturales desde el depósito del envío en la oficina', '10 días naturales desde el depósito del envío en la oficina']::text[], 3, 'El artículo 114.2 dispone que «La notificación se entenderá practicada por el transcurso de 10 días naturales desde el depósito del envío en la oficina».', 3, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'inf-042', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 17 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inf-043', (select id from leyes where slug = 'ley-58-2003'), '95.1', 'Los datos obtenidos por la Administración tributaria tienen carácter reservado y solo podrán utilizarse para:', array['La aplicación de los tributos o recursos gestionados y la imposición de sanciones', 'Cualquier función de control económico que encomiende la ley a la Agencia', 'La elaboración de estadísticas y su cesión libre a otras Administraciones', 'La aplicación de los tributos y su comunicación a terceros interesados']::text[], 0, 'Según el artículo 95.1, «sólo podrán ser utilizados para la efectiva aplicación de los tributos o recursos cuya gestión tenga encomendada y para la imposición de las sanciones que procedan».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
