insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inf-044', (select id from leyes where slug = 'ley-58-2003'), '95.1.h', 'Para ceder datos tributarios a jueces y tribunales en la ejecución de resoluciones judiciales firmes, la resolución judicial debe motivar la necesidad por haberse agotado:', array['Los recursos contra la resolución judicial que se ejecuta', 'El procedimiento de apremio administrativo frente al deudor', 'Los demás medios de conocimiento de los bienes del deudor', 'Los plazos de requerimiento dirigidos al propio deudor']::text[], 2, 'El artículo 95.1.h) exige motivar la necesidad «por haberse agotado los demás medios o fuentes de conocimiento sobre la existencia de bienes y derechos del deudor».', 3, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
