insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inf-052', (select id from leyes where slug = 'ley-58-2003'), '104.5', 'Declarada la caducidad de un procedimiento tributario, las actuaciones realizadas en él:', array['Interrumpen el plazo de prescripción y conservan su validez probatoria', 'No interrumpen la prescripción y pierden todo valor probatorio', 'No interrumpen el plazo de prescripción, pero conservan su validez a efectos probatorios', 'Interrumpen la prescripción durante seis meses adicionales']::text[], 2, 'Las actuaciones de un procedimiento caducado «no interrumpirán el plazo de prescripción», pero «conservarán su validez y eficacia a efectos probatorios en otros procedimientos» (art. 104.5).', 3, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
