insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inf-053', (select id from leyes where slug = 'ley-58-2003'), '105.1', 'En los procedimientos de aplicación de los tributos, la carga de la prueba corresponde a:', array['La Administración tributaria en todo caso', 'Quien alegue hechos extintivos, con independencia de quién invoque el derecho', 'El obligado tributario, salvo en los procedimientos iniciados de oficio', 'Quien haga valer su derecho, que debe probar los hechos constitutivos del mismo']::text[], 3, 'Según el artículo 105.1, «quien haga valer su derecho deberá probar los hechos constitutivos del mismo».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
