insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inf-054', (select id from leyes where slug = 'ley-58-2003'), '112.2', 'La comparecencia para ser notificado por anuncio publicado en el Boletín Oficial del Estado debe producirse en el plazo de:', array['10 días naturales, contados desde el siguiente al de la publicación', '15 días naturales, contados desde el siguiente al de la publicación', '15 días hábiles, contados desde el siguiente al de la publicación', '20 días naturales, contados desde el siguiente al de la publicación']::text[], 1, 'El artículo 112.2 exige que «la comparecencia deberá producirse en el plazo de 15 días naturales, contados desde el siguiente al de la publicación del anuncio».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
