insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ins-001', (select id from leyes where slug = 'ley-58-2003'), '142.4', 'Según la LGT, los funcionarios que desempeñen funciones de inspección serán considerados:', array['Agentes de la autoridad', 'Autoridad judicial delegada', 'Agentes de la policía judicial', 'Representantes de la Administración tributaria']::text[], 0, 'El artículo 142.4 establece que «serán considerados agentes de la autoridad y deberán acreditar su condición, si son requeridos para ello, fuera de las oficinas públicas».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
