insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ins-024', (select id from leyes where slug = 'rd-1065-2007'), '170.7', 'Los planes de inspección y los sistemas de selección de los obligados tributarios que serán inspeccionados tienen carácter:', array['Reservado', 'Público', 'Público una vez aprobados anualmente', 'Comunicable a los obligados seleccionados']::text[], 0, 'El artículo 170.7 dispone que «tendrán carácter reservado, no serán objeto de publicidad o de comunicación ni se pondrán de manifiesto a los obligados tributarios ni a órganos ajenos a la aplicación de los tributos».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
