insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ins-030', (select id from leyes where slug = 'rd-1065-2007'), '184.1', 'Cada uno de los periodos que el obligado puede solicitar para que la inspección no actúe con él debe ser de un mínimo de:', array['7 días naturales', '3 días naturales', '10 días hábiles', '15 días naturales']::text[], 0, 'El artículo 184.1 dice que se podrán solicitar «uno o varios periodos a los que se refiere el apartado 4 del artículo 150 de la Ley 58/2003 […] de un mínimo de 7 días naturales cada uno».', 3, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
