insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir1-001', (select id from leyes where slug = 'ley-35-2006'), '1', 'El IRPF es un tributo de carácter:', array['Real e indirecto', 'Personal y directo', 'Personal e indirecto', 'Real y directo']::text[], 1, 'El artículo 1 define el IRPF como «un tributo de carácter personal y directo».', 1, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
