insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir1-002', (select id from leyes where slug = 'ley-35-2006'), '3.1', 'Según su ley reguladora, el IRPF es un impuesto:', array['Cedido totalmente a las Comunidades Autónomas', 'Propio de las Comunidades Autónomas', 'De titularidad exclusiva de las Entidades Locales', 'Cedido parcialmente a las Comunidades Autónomas']::text[], 3, 'El artículo 3.1 establece que «es un impuesto cedido parcialmente», en los términos de la LOFCA.', 1, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
