insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir1-004', (select id from leyes where slug = 'ley-35-2006'), '6.3', 'Para determinar la base imponible y calcular el impuesto, la renta del contribuyente se clasifica en:', array['Ordinaria y extraordinaria', 'Activa y pasiva', 'General y del ahorro', 'Regular e irregular']::text[], 2, 'El artículo 6.3 dispone que «la renta se clasificará en general y del ahorro».', 1, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'ir1-004', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 27 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir1-005', (select id from leyes where slug = 'ley-35-2006'), '6.4', 'No está sujeta al IRPF la renta que se encuentre sujeta al:', array['Impuesto sobre el Patrimonio', 'Impuesto sobre Sociedades', 'Impuesto sobre Transmisiones Patrimoniales', 'Impuesto sobre Sucesiones y Donaciones']::text[], 3, 'El artículo 6.4 señala: «No estará sujeta a este impuesto la renta que se encuentre sujeta al Impuesto sobre Sucesiones y Donaciones».', 1, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
