insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir1-006', (select id from leyes where slug = 'ley-35-2006'), '7.e', 'El importe de la indemnización por despido exenta en el IRPF tiene como límite la cantidad de:', array['100.000 euros', '180.000 euros', '120.000 euros', '240.000 euros']::text[], 1, 'El artículo 7.e) dispone que «tendrá como límite la cantidad de 180.000 euros».', 2, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'ir1-006', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 27 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir1-007', (select id from leyes where slug = 'ley-35-2006'), '7.e', '¿Qué indemnización por despido o cese del trabajador está exenta en el IRPF?', array['La pactada en convenio, pacto o contrato, cualquiera que sea su cuantía', 'La que acuerden libremente trabajador y empresa en el finiquito', 'La establecida con carácter obligatorio en el Estatuto de los Trabajadores o en su normativa de desarrollo', 'La fijada en el contrato de trabajo, aunque supere la legal']::text[], 2, 'Están exentas las indemnizaciones «en la cuantía establecida con carácter obligatorio en el texto refundido de la Ley del Estatuto de los Trabajadores», «sin que pueda considerarse como tal la establecida en virtud de convenio, pacto o contrato».', 2, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
