insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir1-008', (select id from leyes where slug = 'ley-35-2006'), '7.f', 'Está exenta en el IRPF la prestación reconocida por la Seguridad Social como consecuencia de:', array['Incapacidad permanente absoluta o gran invalidez', 'Jubilación ordinaria a la edad legal', 'Incapacidad permanente total para la profesión habitual', 'Viudedad del cónyuge supérstite']::text[], 0, 'El artículo 7.f) declara exentas las prestaciones de la Seguridad Social «como consecuencia de incapacidad permanente absoluta o gran invalidez».', 1, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'ir1-008', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 27 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir1-009', (select id from leyes where slug = 'ley-35-2006'), '7.k', '¿Cuál de estas rentas está exenta en el IRPF?', array['Las pensiones compensatorias recibidas del cónyuge', 'Las anualidades por alimentos percibidas de los padres en virtud de decisión judicial', 'Las retribuciones de los administradores de una sociedad', 'Las prestaciones por desempleo en pago periódico']::text[], 1, 'El artículo 7.k) establece: «Igualmente estarán exentas las anualidades por alimentos percibidas de los padres en virtud de decisión judicial en supuestos distintos a los establecidos en el párrafo anterior».', 2, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
