insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir1-010', (select id from leyes where slug = 'ley-35-2006'), '7.p', 'La exención por trabajos efectivamente realizados en el extranjero se aplica a las retribuciones de los días de estancia, con un límite anual de:', array['30.050 euros', '90.150 euros', '120.200 euros', '60.100 euros']::text[], 3, 'El artículo 7.p) aplica la exención a las retribuciones devengadas por los días de estancia en el extranjero, «con el límite máximo de 60.100 euros anuales».', 2, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
