insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir1-011', (select id from leyes where slug = 'ley-35-2006'), '7.w', 'Las prestaciones en forma de renta de personas con discapacidad por aportaciones del artículo 53 están exentas hasta un máximo anual de:', array['Tres veces el indicador público de renta de efectos múltiples', 'Dos veces el indicador público de renta de efectos múltiples', '1,5 veces el indicador público de renta de efectos múltiples', 'Cinco veces el indicador público de renta de efectos múltiples']::text[], 0, 'El artículo 7.w) las declara exentas «hasta un importe máximo anual de tres veces el indicador público de renta de efectos múltiples».', 3, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
