insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir1-013', (select id from leyes where slug = 'ley-35-2006'), '8.3', '¿Quién no tiene la consideración de contribuyente del IRPF?', array['Una persona física con residencia habitual en territorio español', 'Un español miembro de una misión diplomática española en el extranjero', 'Un funcionario español en activo con cargo oficial no diplomático en el extranjero', 'Una herencia yacente']::text[], 3, 'El artículo 8.3 dispone: «No tendrán la consideración de contribuyente las sociedades civiles no sujetas al Impuesto sobre Sociedades, herencias yacentes, comunidades de bienes».', 2, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
