insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir1-014', (select id from leyes where slug = 'ley-35-2006'), '9.1.a', 'Se considera que reside habitualmente en España quien permanezca en territorio español durante el año natural:', array['Más de 180 días', 'Más de 183 días', 'Al menos 150 días', 'Más de 200 días']::text[], 1, 'El artículo 9.1.a) exige «Que permanezca más de 183 días, durante el año natural, en territorio español».', 1, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'ir1-014', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 27 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir1-015', (select id from leyes where slug = 'ley-35-2006'), '9.1.a', 'Para calcular los días de permanencia en España, las ausencias esporádicas:', array['No se computan en ningún caso, aunque sean esporádicas', 'Se computan siempre, sin admitir excepción alguna', 'Se computan, salvo que se acredite la residencia fiscal en otro país', 'Se computan solo si no superan en total los 30 días']::text[], 2, 'El artículo 9.1.a) indica que «se computarán las ausencias esporádicas, salvo que el contribuyente acredite su residencia fiscal en otro país».', 2, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'ir1-015', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 27 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir1-016', (select id from leyes where slug = 'ley-35-2006'), '9.1', 'Se presume residente habitual en España, salvo prueba en contrario, a quien tenga en España:', array['Al cónyuge no separado legalmente y a los hijos menores de edad que dependan de él', 'A sus ascendientes mayores de 65 años que dependan de él', 'A cualquier hijo, sea mayor o menor de edad, y a su cónyuge', 'Solo al cónyuge, aunque esté separado legalmente de él']::text[], 0, 'Se presume la residencia cuando «resida habitualmente en España el cónyuge no separado legalmente y los hijos menores de edad que dependan de aquél».', 2, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
