insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir1-017', (select id from leyes where slug = 'ley-35-2006'), '10.1.b', 'Los españoles miembros de oficinas consulares en el extranjero son contribuyentes, con excepción de:', array['El jefe de la oficina consular', 'Los vicecónsules honorarios o agentes consulares honorarios y su personal dependiente', 'El funcionario adscrito a la oficina consular', 'El personal de servicios adscrito a la oficina consular']::text[], 1, 'El artículo 10.1.b) comprende a los miembros de las oficinas consulares «con excepción de los vicecónsules honorarios o agentes consulares honorarios y del personal dependiente de ellos».', 3, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
