insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir1-018', (select id from leyes where slug = 'ley-35-2006'), '11.2', 'Los rendimientos del trabajo se atribuyen exclusivamente a:', array['El cónyuge con menores ingresos', 'Quien figure como titular de la cuenta donde se ingresan', 'Ambos cónyuges por mitad, según su régimen económico', 'Quien haya generado el derecho a su percepción']::text[], 3, 'El artículo 11.2 establece: «Los rendimientos del trabajo se atribuirán exclusivamente a quien haya generado el derecho a su percepción».', 1, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
