insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir1-020', (select id from leyes where slug = 'ley-35-2006'), '12.2', 'El IRPF se devenga, con carácter general:', array['El 1 de enero de cada año', 'El último día del plazo de declaración', 'El 31 de diciembre de cada año', 'El 30 de junio de cada año']::text[], 2, 'El artículo 12.2 dispone: «El Impuesto se devengará el 31 de diciembre de cada año».', 1, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
