insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir1-021', (select id from leyes where slug = 'ley-35-2006'), '13', 'Si el contribuyente fallece el 15 de marzo, el período impositivo termina y el impuesto se devenga:', array['El 31 de diciembre de ese año', 'El día en que se acepte la herencia', 'El último día del plazo de declaración de ese año', 'El 15 de marzo, fecha del fallecimiento']::text[], 3, 'El artículo 13.2 establece que «el período impositivo terminará y se devengará el impuesto en la fecha del fallecimiento».', 1, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
