insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir1-022', (select id from leyes where slug = 'ley-35-2006'), '14.1.a', 'Los rendimientos del trabajo y del capital se imputan al período impositivo en que:', array['Se cobren efectivamente', 'Sean exigibles por su perceptor', 'Se presente la declaración', 'Se practiquen las retenciones']::text[], 1, 'El artículo 14.1.a) dispone: «Los rendimientos del trabajo y del capital se imputarán al período impositivo en que sean exigibles por su perceptor».', 2, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
