insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir1-023', (select id from leyes where slug = 'ley-35-2006'), '14.1.c', 'Las ganancias y pérdidas patrimoniales se imputan, con carácter general, al período impositivo en que:', array['Se cobre el precio de la operación', 'Se presente la declaración', 'Tenga lugar la alteración patrimonial', 'Se inscriba el bien en un registro público']::text[], 2, 'El artículo 14.1.c) establece que «Las ganancias y pérdidas patrimoniales se imputarán al período impositivo en que tenga lugar la alteración patrimonial».', 1, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
