insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir1-024', (select id from leyes where slug = 'ley-35-2006'), '14.2.a', 'Si una renta no se ha satisfecho por estar pendiente de resolución judicial el derecho a su percepción, el importe no satisfecho se imputa al período en que:', array['La resolución judicial adquiera firmeza', 'Se dicte la resolución en primera instancia', 'Se interponga la demanda', 'Se cobre efectivamente el importe']::text[], 0, 'El artículo 14.2.a) dice que «los importes no satisfechos se imputarán al período impositivo en que aquélla adquiera firmeza».', 2, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
