insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir1-025', (select id from leyes where slug = 'ley-35-2006'), '14.2.b', 'Si rendimientos del trabajo se perciben por causas justificadas en un período distinto al de su exigibilidad, la autoliquidación complementaria se presenta:', array['En el mes siguiente a la fecha de su percepción', 'Entre la fecha de su percepción y el final del inmediato siguiente plazo de declaraciones del impuesto', 'En el plazo de tres meses desde que sean exigibles', 'Durante el plazo de declaraciones del período en que fueron exigibles']::text[], 1, 'El artículo 14.2.b) señala: «La autoliquidación se presentará en el plazo que media entre la fecha en que se perciban y el final del inmediato siguiente plazo de declaraciones por el impuesto».', 3, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
