insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir1-026', (select id from leyes where slug = 'ley-35-2006'), '14.2.d', 'Se consideran operaciones a plazos o con precio aplazado las que se cobren con pagos sucesivos cuando entre la entrega y el vencimiento del último plazo transcurra un período:', array['Superior a seis meses', 'Superior a dos años', 'Igual o superior a tres años', 'Superior a un año']::text[], 3, 'Según el artículo 14.2.d), siempre que «el período transcurrido entre la entrega o la puesta a disposición y el vencimiento del último plazo sea superior al año».', 2, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
