insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir1-027', (select id from leyes where slug = 'ley-35-2006'), '14.2.g', 'Las ayudas por defectos estructurales de construcción de la vivienda habitual, destinadas a su reparación, pueden imputarse por cuartas partes en el período en que se obtengan y en:', array['Los tres siguientes', 'Los cuatro siguientes', 'Los dos siguientes', 'Los cinco siguientes']::text[], 0, 'El artículo 14.2.g) permite imputarlas «por cuartas partes, en el periodo impositivo en el que se obtengan y en los tres siguientes».', 3, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'ir1-027', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 27 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir1-028', (select id from leyes where slug = 'ley-35-2006'), '17.2.f', 'Las pensiones compensatorias recibidas del cónyuge tributan, en todo caso, como:', array['Rendimientos del capital mobiliario', 'Rendimientos de actividades económicas', 'Rendimientos del trabajo', 'Ganancias patrimoniales']::text[], 2, 'El artículo 17.2 dispone que «En todo caso, tendrán la consideración de rendimientos del trabajo» las «pensiones compensatorias recibidas del cónyuge y las anualidades por alimentos».', 1, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
