insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir1-030', (select id from leyes where slug = 'ley-35-2006'), '18.2', 'Los rendimientos del trabajo (salvo prestaciones del art. 17.2.a) con período de generación superior a dos años, imputados en un único período impositivo, se reducen en un:', array['20 por ciento', '30 por ciento', '40 por ciento', '50 por ciento']::text[], 1, 'El artículo 18.2 prevé «El 30 por ciento de reducción» para rendimientos «que tengan un período de generación superior a dos años».', 1, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
