insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir2-012', (select id from leyes where slug = 'ley-35-2006'), '46.b', 'Forman parte de la renta del ahorro:', array['Los rendimientos íntegros del trabajo por cuenta ajena', 'Las ganancias y pérdidas patrimoniales por transmisiones de elementos patrimoniales', 'Las imputaciones de renta de inmuebles urbanos del artículo 85', 'Los rendimientos íntegros de actividades económicas']::text[], 1, 'El artículo 46.b) incluye en la renta del ahorro «Las ganancias y pérdidas patrimoniales que se pongan de manifiesto con ocasión de transmisiones de elementos patrimoniales».', 1, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
