insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir2-013', (select id from leyes where slug = 'ley-35-2006'), '45', 'Las imputaciones de renta de los artículos 85, 91, 92 y 95 de la LIRPF forman parte de:', array['La renta general', 'La renta del ahorro', 'La renta del ahorro, salvo las del artículo 85', 'Ninguna de las dos clases de renta, pues tributan aparte']::text[], 0, 'El artículo 45 integra en la renta general «las imputaciones de renta a que se refieren los artículos 85, 91, 92 y 95 de esta Ley».', 1, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'ir2-013', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 28 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir2-014', (select id from leyes where slug = 'ley-35-2006'), '48', 'En la base imponible general, el saldo negativo de las ganancias y pérdidas patrimoniales se compensa con el saldo positivo de rendimientos e imputaciones de renta del mismo período con el límite de:', array['El 10 por ciento de dicho saldo positivo', 'El 50 por ciento de dicho saldo positivo', 'El 25 por ciento de dicho saldo positivo', 'El 30 por ciento de dicho saldo positivo']::text[], 2, 'El artículo 48 lo compensa con el saldo positivo de rendimientos e imputaciones «con el límite del 25 por ciento de dicho saldo positivo».', 2, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'ir2-014', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 28 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir2-015', (select id from leyes where slug = 'ley-35-2006'), '50.3', 'Si la base liquidable general resulta negativa, su importe puede compensarse con las bases liquidables generales positivas que se obtengan en:', array['El año siguiente', 'Los dos años siguientes', 'Los cinco años siguientes', 'Los cuatro años siguientes']::text[], 3, 'El artículo 50.3 permite compensarla «con los de las bases liquidables generales positivas que se obtengan en los cuatro años siguientes».', 1, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
