insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir2-016', (select id from leyes where slug = 'ley-35-2006'), '50.2', 'La base liquidable del ahorro se obtiene disminuyendo la base imponible del ahorro en el remanente, si lo hubiera, de:', array['La reducción por pensiones compensatorias y anualidades por alimentos', 'La reducción por aportaciones a planes de pensiones', 'La reducción por aportaciones a patrimonios protegidos de personas con discapacidad', 'La reducción por aportaciones a sistemas de previsión social de personas con discapacidad']::text[], 0, 'El artículo 50.2 la reduce en «el remanente, si lo hubiera, de la reducción prevista en el artículo 55», que se refiere a «Las pensiones compensatorias a favor del cónyuge y las anualidades por alimentos».', 3, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'ir2-016', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 28 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir2-017', (select id from leyes where slug = 'ley-35-2006'), '52.2', 'Las aportaciones a sistemas de previsión social que no hayan podido reducirse por insuficiencia de base o por el límite porcentual pueden reducirse en:', array['Los cuatro ejercicios siguientes', 'Los cinco ejercicios siguientes', 'Los tres ejercicios siguientes', 'El ejercicio siguiente']::text[], 1, 'El artículo 52.2 permite a los partícipes «reducir en los cinco ejercicios siguientes las cantidades aportadas» que no hubieran podido ser objeto de reducción.', 2, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
