insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir2-018', (select id from leyes where slug = 'ley-35-2006'), '55', '¿Cuál de los siguientes pagos puede ser objeto de reducción en la base imponible?', array['Las anualidades por alimentos fijadas en favor de los hijos del contribuyente', 'Las pensiones compensatorias pactadas en convenio privado sin decisión judicial', 'Las pensiones compensatorias a favor del cónyuge satisfechas por decisión judicial', 'Las cantidades entregadas voluntariamente a familiares sin ingresos']::text[], 2, 'Según el artículo 55 «Las pensiones compensatorias a favor del cónyuge y las anualidades por alimentos, con excepción de las fijadas en favor de los hijos del contribuyente, satisfechas ambas por decisión judicial, podrán ser objeto de reducción en la base imponible».', 2, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
