insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir2-019', (select id from leyes where slug = 'ley-35-2006'), '56.3', 'El mínimo personal y familiar es el resultado de sumar el mínimo del contribuyente y los mínimos por:', array['Cónyuge, descendientes y discapacidad', 'Descendientes, ascendientes y familia numerosa', 'Descendientes, ascendientes, discapacidad y vivienda habitual', 'Descendientes, ascendientes y discapacidad']::text[], 3, 'El artículo 56.3 señala que «El mínimo personal y familiar será el resultado de sumar el mínimo del contribuyente y los mínimos por descendientes, ascendientes y discapacidad».', 1, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'ir2-019', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 28 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir2-020', (select id from leyes where slug = 'ley-35-2006'), '58.1', 'El mínimo por descendientes exige, entre otros requisitos, que el descendiente conviva con el contribuyente y no tenga rentas anuales, excluidas las exentas, superiores a:', array['8.000 euros', '1.800 euros', '6.000 euros', '12.000 euros']::text[], 0, 'El artículo 58.1 lo aplica por cada descendiente «siempre que conviva con el contribuyente y no tenga rentas anuales, excluidas las exentas, superiores a 8.000 euros».', 2, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'ir2-020', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 28 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir2-021', (select id from leyes where slug = 'ley-35-2006'), '61.5', 'Para aplicar el mínimo por ascendientes, estos deben convivir con el contribuyente, al menos:', array['Tres meses del período impositivo', 'La mitad del período impositivo', 'Todo el período impositivo', 'Un tercio del período impositivo']::text[], 1, 'La regla 5.ª del artículo 61 exige «que éstos convivan con el contribuyente, al menos, la mitad del período impositivo».', 2, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'ir2-021', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 28 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir2-022', (select id from leyes where slug = 'ley-35-2006'), '61.1', 'Si dos o más contribuyentes con el mismo grado de parentesco tienen derecho al mínimo por descendientes respecto de los mismos descendientes, su importe:', array['Se aplica íntegramente al que tenga mayor renta', 'Se prorratea en proporción a sus bases liquidables', 'Se prorratea entre ellos por partes iguales', 'Se aplica íntegramente al contribuyente de mayor edad']::text[], 2, 'La regla 1.ª del artículo 61 establece que «su importe se prorrateará entre ellos por partes iguales».', 1, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'ir2-022', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 28 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir2-023', (select id from leyes where slug = 'ley-35-2006'), '60.3', 'Se considera acreditado un grado de discapacidad igual o superior al 65 por ciento cuando:', array['El contribuyente sea pensionista con pensión de incapacidad permanente total', 'El contribuyente perciba una pensión de jubilación del Régimen General', 'La persona tenga reconocida una situación de dependencia moderada', 'La incapacidad de la persona sea declarada judicialmente, aunque no alcance dicho grado']::text[], 3, 'El artículo 60.3 dice que se considerará acreditado ese grado «cuando se trate de personas cuya incapacidad sea declarada judicialmente, aunque no alcance dicho grado».', 3, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'ir2-023', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 28 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir2-024', (select id from leyes where slug = 'ley-35-2006'), '62', 'La cuota íntegra estatal es la suma de las cantidades resultantes de aplicar los tipos de gravamen:', array['A las bases liquidables general y del ahorro, respectivamente', 'A las bases imponibles general y del ahorro, respectivamente', 'A la base imponible total, una vez aplicadas las deducciones', 'A la base liquidable general, con tipo fijo para el ahorro']::text[], 0, 'El artículo 62 define la cuota íntegra estatal como la suma de aplicar los tipos de gravamen «a las bases liquidables general y del ahorro, respectivamente».', 1, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'ir2-024', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 28 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir2-025', (select id from leyes where slug = 'ley-35-2006'), '68.4', 'Los contribuyentes con residencia habitual y efectiva en Ceuta o Melilla se deducen, por las rentas obtenidas allí, el siguiente porcentaje de la parte de la suma de las cuotas íntegras estatal y autonómica:', array['El 50 por ciento', 'El 60 por ciento', 'El 40 por ciento', 'El 75 por ciento']::text[], 1, 'El artículo 68.4 dispone que «se deducirán el 60 por ciento de la parte de la suma de las cuotas íntegras estatal y autonómica que proporcionalmente corresponda a las rentas».', 1, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'ir2-025', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 28 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir2-026', (select id from leyes where slug = 'ley-35-2006'), '69.1', 'La base de las deducciones por donativos y por actuaciones de protección del Patrimonio Histórico no puede exceder, para cada una de ellas, de:', array['El 10 por ciento de la cuota íntegra', 'El 20 por ciento de la base liquidable del contribuyente', 'El 10 por ciento de la base liquidable del contribuyente', 'El 15 por ciento de la base imponible']::text[], 2, 'El artículo 69.1 establece que la base de esas deducciones «no podrá exceder para cada una de ellas del 10 por ciento de la base liquidable del contribuyente».', 3, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
