insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir2-027', (select id from leyes where slug = 'ley-35-2006'), '79', 'La cuota diferencial resulta de minorar la cuota líquida total en, entre otros importes:', array['Las reducciones por aportaciones a planes de pensiones', 'El mínimo personal y familiar', 'Las pensiones compensatorias satisfechas por decisión judicial', 'Las retenciones, los ingresos a cuenta y los pagos fraccionados']::text[], 3, 'Según el artículo 79, la cuota líquida total se minora en «Las retenciones, los ingresos a cuenta y los pagos fraccionados previstos en esta Ley y en sus normas reglamentarias de desarrollo».', 1, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'ir2-027', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 28 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir2-028', (select id from leyes where slug = 'ley-35-2006'), '80.1', 'La deducción por doble imposición internacional es la menor de dos cantidades: el impuesto efectivamente satisfecho en el extranjero y:', array['El resultado de aplicar el tipo medio efectivo de gravamen a la parte de base liquidable gravada en el extranjero', 'El resultado de aplicar el tipo máximo de la escala a la renta obtenida en el extranjero', 'El 50 por ciento de la cuota líquida total', 'El 10 por ciento de la base liquidable']::text[], 0, 'El artículo 80.1.b) fija como límite «El resultado de aplicar el tipo medio efectivo de gravamen a la parte de base liquidable gravada en el extranjero».', 3, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
