insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir2-029', (select id from leyes where slug = 'ley-35-2006'), '81.1', 'La deducción por maternidad permite minorar la cuota diferencial hasta en 1.200 euros anuales por cada hijo menor de:', array['Un año', 'Tres años', 'Cinco años', 'Seis años']::text[], 1, 'El artículo 81.1 permite minorar la cuota diferencial «hasta en 1.200 euros anuales por cada hijo menor de tres años».', 1, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
