insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir2-030', (select id from leyes where slug = 'ley-35-2006'), '82.3', 'Los miembros de la unidad familiar a efectos de la tributación conjunta se determinan atendiendo a la situación existente a:', array['1 de enero de cada año', '30 de junio de cada año', '31 de diciembre de cada año', 'La fecha de presentación de la declaración']::text[], 2, 'El artículo 82.3 señala que «La determinación de los miembros de la unidad familiar se realizará atendiendo a la situación existente a 31 de diciembre de cada año».', 1, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
