insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir2-031', (select id from leyes where slug = 'ley-35-2006'), '83.2', 'Si no se presenta declaración, los miembros de la unidad familiar tributan individualmente, salvo que manifiesten expresamente su opción por la conjunta en el plazo, a partir del requerimiento de la Administración, de:', array['5 días', '15 días', '30 días', '10 días']::text[], 3, 'El artículo 83.2 dice que «En caso de falta de declaración, los contribuyentes tributarán individualmente, salvo que manifiesten expresamente su opción en el plazo de 10 días a partir del requerimiento de la Administración tributaria».', 3, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'ir2-031', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 28 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir2-032', (select id from leyes where slug = 'ley-35-2006'), '84.2.4', 'En la modalidad de unidad familiar formada por el padre o la madre y los hijos, no se aplica la reducción de la base imponible cuando el contribuyente:', array['Conviva con el padre o la madre de alguno de los hijos de su unidad familiar', 'Tenga algún hijo mayor de edad que conviva con él en el domicilio familiar', 'Tenga más de dos hijos menores de edad que dependan de él', 'No obtenga ningún rendimiento íntegro del trabajo en el período']::text[], 0, 'El artículo 84.2.4.º establece: «No se aplicará esta reducción cuando el contribuyente conviva con el padre o la madre de alguno de los hijos que forman parte de su unidad familiar».', 3, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
