insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir2-033', (select id from leyes where slug = 'ley-35-2006'), '96.4', 'Están obligados a declarar por el IRPF en todo caso los contribuyentes que:', array['Obtengan solo rendimientos íntegros del trabajo dentro del límite legal de 22.000 euros', 'Tengan derecho a la deducción por doble imposición internacional', 'Obtengan solo ganancias patrimoniales sometidas a retención de hasta 1.600 euros', 'Obtengan solo rentas inmobiliarias imputadas de hasta 1.000 euros']::text[], 1, 'El artículo 96.4 dispone: «Estarán obligados a declarar en todo caso los contribuyentes que tengan derecho a deducción por doble imposición internacional».', 2, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
