insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir2-034', (select id from leyes where slug = 'ley-35-2006'), '98.2', 'No pueden suscribir ni confirmar el borrador de declaración, entre otros:', array['Los contribuyentes que solo obtengan rendimientos del trabajo', 'Los contribuyentes que obtengan imputación de rentas inmobiliarias', 'Los contribuyentes que compensen partidas negativas de ejercicios anteriores', 'Los contribuyentes con ganancias patrimoniales sometidas a retención']::text[], 2, 'El artículo 98.2 impide suscribir o confirmar el borrador a «Los contribuyentes que compensen partidas negativas de ejercicios anteriores».', 3, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
