insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir2-035', (select id from leyes where slug = 'ley-35-2006'), '99.5', 'El perceptor de rentas sobre las que deba retenerse a cuenta del IRPF computará aquellas por:', array['La contraprestación líquida efectivamente percibida', 'La contraprestación íntegra efectivamente cobrada', 'El valor normal de mercado de la renta', 'La contraprestación íntegra devengada']::text[], 3, 'El artículo 99.5 establece que «El perceptor de rentas sobre las que deba retenerse a cuenta de este impuesto computará aquéllas por la contraprestación íntegra devengada».', 2, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
