insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir2-036', (select id from leyes where slug = 'ley-35-2006'), '101.5.a', 'El porcentaje general de retención sobre los rendimientos de actividades profesionales establecidos en vía reglamentaria es del:', array['15 por ciento', '19 por ciento', '7 por ciento', '24 por ciento']::text[], 0, 'El artículo 101.5.a) fija «El 15 por ciento, en el caso de los rendimientos de actividades profesionales establecidos en vía reglamentaria».', 1, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
