insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir2-037', (select id from leyes where slug = 'ley-35-2006'), '101.11.a', 'El porcentaje del pago fraccionado de los contribuyentes con actividades económicas en estimación directa, en cualquiera de sus modalidades, es del:', array['15 por ciento', '20 por ciento', '4 por ciento', '2 por ciento']::text[], 1, 'El artículo 101.11.a) establece «El 20 por ciento, cuando se trate de actividades que determinen el rendimiento neto por el método de estimación directa, en cualquiera de sus modalidades».', 1, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'ir2-037', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 28 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir2-038', (select id from leyes where slug = 'ley-35-2006'), '103.1', 'Si las retenciones, ingresos a cuenta y pagos fraccionados superan la cuota autoliquidada, la Administración practicará, si procede, liquidación provisional dentro de:', array['Los tres meses siguientes al término del plazo establecido para presentar la declaración', 'Los doce meses siguientes al término del plazo establecido para presentar la declaración', 'Los seis meses siguientes al término del plazo establecido para presentar la declaración', 'Los seis meses siguientes a la fecha de presentación, aunque se hubiera presentado en plazo']::text[], 2, 'El artículo 103.1 prevé la liquidación provisional «dentro de los seis meses siguientes al término del plazo establecido para la presentación de la declaración».', 2, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
