insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir2-039', (select id from leyes where slug = 'ley-35-2006'), '85.1', '¿Cuál de los siguientes inmuebles urbanos no genera imputación de renta inmobiliaria?', array['Una segunda vivienda del contribuyente que permanece desocupada', 'Un local del contribuyente sin uso ni arrendamiento', 'Una plaza de garaje del contribuyente no arrendada ni afecta a actividad', 'La vivienda habitual del contribuyente']::text[], 3, 'El artículo 85.1 aplica la imputación a los inmuebles urbanos «no afectos en ambos casos a actividades económicas, ni generadores de rendimientos del capital, excluida la vivienda habitual y el suelo no edificado».', 1, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'ir2-039', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 28 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ir2-040', (select id from leyes where slug = 'ley-35-2006'), '29.1', 'Se consideran elementos patrimoniales afectos a una actividad económica:', array['Los bienes inmuebles en los que se desarrolla la actividad del contribuyente', 'Los bienes de esparcimiento y recreo del titular de la actividad', 'Los activos representativos de la participación en fondos propios de una entidad', 'Los bienes de uso particular del titular de la actividad']::text[], 0, 'El artículo 29.1.a) incluye «Los bienes inmuebles en los que se desarrolla la actividad del contribuyente»; en cambio, «No se consideran afectos los bienes de esparcimiento y recreo o, en general, de uso particular del titular de la actividad económica».', 2, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
