insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('iv1-001', (select id from leyes where slug = 'ley-37-1992'), '1', 'El Impuesto sobre el Valor Añadido es un tributo de naturaleza:', array['Directa que recae sobre la renta de los empresarios', 'Indirecta que recae sobre el consumo', 'Indirecta que recae sobre el patrimonio', 'Directa que recae sobre el consumo']::text[], 1, 'El artículo 1 dice que «El Impuesto sobre el Valor Añadido es un tributo de naturaleza indirecta que recae sobre el consumo».', 1, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
