insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('iv1-002', (select id from leyes where slug = 'ley-37-1992'), '1', 'Además de las entregas de bienes y prestaciones de servicios de empresarios o profesionales, el IVA grava las adquisiciones intracomunitarias de bienes y:', array['Las exportaciones de bienes', 'Las operaciones societarias', 'Las transmisiones patrimoniales onerosas', 'Las importaciones de bienes']::text[], 3, 'El artículo 1 enumera tres grupos de operaciones: las entregas y prestaciones de empresarios o profesionales, «Las adquisiciones intracomunitarias de bienes.» y «Las importaciones de bienes.»', 1, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
