insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('iv1-003', (select id from leyes where slug = 'ley-37-1992'), '3.Uno', 'El ámbito espacial del IVA comprende el territorio español, incluyendo el mar territorial hasta el límite de:', array['12 millas náuticas', '6 millas náuticas', '24 millas náuticas', '200 millas náuticas']::text[], 0, 'Según el artículo 3.Uno, el ámbito espacial incluye «el mar territorial hasta el límite de 12 millas náuticas».', 1, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'iv1-003', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 30 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('iv1-004', (select id from leyes where slug = 'ley-37-1992'), '3.Dos.1.º.a', 'Según la Ley del IVA, Ceuta y Melilla quedan excluidas del concepto de «interior del país» en cuanto territorios:', array['Excluidos de la armonización de los impuestos sobre el volumen de negocios', 'Sometidos al régimen de Concierto o Convenio', 'Con régimen fiscal especial por razón de insularidad', 'No comprendidos en la Unión Aduanera']::text[], 3, 'El artículo 3.Dos.1.º.a) excluye «en el Reino de España, Ceuta y Melilla y en la República Italiana, Livigno, en cuanto territorios no comprendidos en la Unión Aduanera».', 2, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'iv1-004', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 30 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('iv1-005', (select id from leyes where slug = 'ley-37-1992'), '3.Tres', 'A efectos del IVA, las operaciones efectuadas con el Principado de Mónaco tienen la misma consideración que las efectuadas con:', array['Italia', 'Chipre', 'El Reino Unido', 'Francia']::text[], 3, 'El artículo 3.Tres señala que las operaciones «con el Principado de Mónaco, con la Isla de Man y con las zonas de soberanía del Reino Unido en Akrotiri y Dhekelia tendrán la misma consideración que las efectuadas, respectivamente, con Francia, el Reino Unido y Chipre».', 2, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'iv1-005', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 30 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('iv1-006', (select id from leyes where slug = 'ley-37-1992'), '4.Tres', 'La sujeción al IVA de las operaciones realizadas en el desarrollo de una actividad empresarial o profesional se produce:', array['Solo si se persigue un fin de lucro', 'Solo si la operación resulta beneficiosa para el empresario', 'Con independencia de los fines o resultados perseguidos', 'Solo si la actividad se ejerce con carácter habitual']::text[], 2, 'El artículo 4.Tres establece que «La sujeción al impuesto se produce con independencia de los fines o resultados perseguidos en la actividad empresarial o profesional o en cada operación en particular.»', 1, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'iv1-006', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 30 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('iv1-007', (select id from leyes where slug = 'ley-37-1992'), '4.Dos.b', 'Un empresario cesa en su actividad y transmite a terceros bienes de su patrimonio empresarial. Según el artículo 4, esas transmisiones:', array['Quedan siempre fuera del IVA por haber cesado la actividad', 'Solo se sujetan si superan el valor contable de los bienes', 'Se entienden realizadas en el desarrollo de su actividad empresarial', 'Solo se sujetan si el adquirente es otro empresario']::text[], 2, 'El artículo 4.Dos.b) entiende realizadas en el desarrollo de una actividad empresarial las transmisiones «a terceros de la totalidad o parte de cualesquiera de los bienes o derechos que integren el patrimonio empresarial o profesional de los sujetos pasivos, incluso las efectuadas con ocasión del cese en el ejercicio de las actividades económicas».', 2, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'iv1-007', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 30 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('iv1-008', (select id from leyes where slug = 'ley-37-1992'), '5.Uno.a', 'No tienen la consideración de empresarios o profesionales a efectos del IVA, según el artículo 5.Uno.a):', array['Quienes exploten un bien para obtener ingresos continuados en el tiempo', 'Quienes realicen exclusivamente entregas de bienes o prestaciones de servicios a título gratuito', 'Quienes promuevan edificaciones destinadas a su venta, aunque sea ocasionalmente', 'Las sociedades mercantiles, aunque no realicen operaciones']::text[], 1, 'El artículo 5.Uno.a) dice que «no tendrán la consideración de empresarios o profesionales quienes realicen exclusivamente entregas de bienes o prestaciones de servicios a título gratuito».', 1, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'iv1-008', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 30 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('iv1-009', (select id from leyes where slug = 'ley-37-1992'), '5.Uno.b', 'Las sociedades mercantiles se reputan empresarios o profesionales a efectos del IVA:', array['Salvo prueba en contrario', 'En todo caso, sin admitir prueba en contrario', 'Solo si realizan operaciones con carácter habitual', 'Solo si están dadas de alta en el Impuesto sobre Actividades Económicas']::text[], 0, 'Según el artículo 5.Uno.b), se reputarán empresarios o profesionales «Las sociedades mercantiles, salvo prueba en contrario.»', 1, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'iv1-009', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 30 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('iv1-010', (select id from leyes where slug = 'ley-37-1992'), '5.Uno.e', 'Un particular vende ocasionalmente un coche nuevo, exento por el artículo 25.Uno, a un comprador de otro Estado miembro. Respecto de sus demás operaciones, ese particular:', array['Tiene la condición de empresario a efectos de todas sus operaciones', 'No tiene nunca la condición de empresario a efectos del IVA', 'Tiene la condición de empresario durante todo el año natural', 'Tiene la condición de empresario solo a efectos de las entregas de medios de transporte nuevos']::text[], 3, 'El artículo 5.Uno.e) añade que «Los empresarios o profesionales a que se refiere esta letra sólo tendrán dicha condición a los efectos de las entregas de los medios de transporte que en ella se comprenden.»', 3, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'iv1-010', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 30 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('iv1-011', (select id from leyes where slug = 'ley-37-1992'), '7.1.º', 'No se beneficia de la no sujeción prevista en el artículo 7.1.º para la transmisión de una unidad económica autónoma:', array['La transmisión a un adquirente que desarrolle una actividad distinta', 'La transmisión de elementos corporales e incorporales conjuntamente', 'La transmisión con mantenimiento de la afectación a una actividad', 'La mera cesión de bienes o de derechos']::text[], 3, 'El artículo 7.1.º excluye de la no sujeción, entre otras transmisiones, «La mera cesión de bienes o de derechos.»', 2, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'iv1-011', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 30 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('iv1-012', (select id from leyes where slug = 'ley-37-1992'), '7.4.º', 'Las entregas sin contraprestación de objetos de carácter publicitario quedan sujetas al IVA cuando el coste total de los suministros a un mismo destinatario durante el año natural exceda de:', array['200 euros', '100 euros', '300 euros', '500 euros']::text[], 0, 'El artículo 7.4.º dispone que quedarán sujetas «las entregas de objetos publicitarios cuando el coste total de los suministros a un mismo destinatario durante el año natural exceda de 200 euros».', 2, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'iv1-012', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 30 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('iv1-013', (select id from leyes where slug = 'ley-37-1992'), '7.8.º.B', 'A efectos de la no sujeción de las entregas y servicios de las Administraciones Públicas (artículo 7.8.º), NO tienen la consideración de Administración Pública:', array['Las entidades públicas empresariales estatales', 'Los organismos autónomos de la Administración', 'Las universidades de titularidad pública', 'Las agencias estatales de la Administración']::text[], 0, 'El artículo 7.8.º.B) precisa que «No tendrán la consideración de Administraciones Públicas las entidades públicas empresariales estatales y los organismos asimilados dependientes de las Comunidades Autónomas y Entidades locales.»', 2, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'iv1-013', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 30 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('iv1-014', (select id from leyes where slug = 'ley-37-1992'), '8.Dos.1.º', 'La ejecución de obra de construcción de una edificación es entrega de bienes cuando el empresario aporta parte de los materiales y su coste excede del siguiente porcentaje de la base imponible:', array['20 por 100', '30 por 100', '40 por 100', '50 por 100']::text[], 2, 'Según el artículo 8.Dos.1.º, es entrega de bienes la ejecución de obra cuando el empresario «aporte una parte de los materiales utilizados, siempre que el coste de los mismos exceda del 40 por 100 de la base imponible».', 1, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'iv1-014', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 30 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('iv1-015', (select id from leyes where slug = 'ley-37-1992'), '11.Dos.16.º', 'El suministro de productos informáticos tiene la consideración de prestación de servicios cuando se trata de productos:', array['Normalizados, entregados en cualquier soporte material', 'Que no precisan modificación sustancial para su uso por cualquier usuario', 'Confeccionados previo encargo de su destinatario conforme a sus especificaciones', 'Que se entregan en un soporte físico de uso estándar']::text[], 2, 'El artículo 11.Dos.16.º señala que se considerará prestación de servicios «el suministro de productos informáticos que hayan sido confeccionados previo encargo de su destinatario conforme a las especificaciones de éste».', 2, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'iv1-015', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 30 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('iv1-016', (select id from leyes where slug = 'ley-37-1992'), '14.Dos', 'La no sujeción de determinadas adquisiciones intracomunitarias solo se aplica si el importe total de las adquisiciones procedentes de otros Estados miembros no alcanzó en el año natural precedente la cifra de:', array['3.000 euros', '12.000 euros', '10.000 euros', '35.000 euros']::text[], 2, 'El artículo 14.Dos exige que el importe total de las adquisiciones «no haya alcanzado en el año natural precedente 10.000 euros».', 1, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
