insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('iv1-017', (select id from leyes where slug = 'ley-37-1992'), '13.2.ª.b', 'Un vehículo terrestre accionado a motor se considera nuevo, entre otros supuestos, si no ha recorrido más de:', array['3.000 kilómetros', '10.000 kilómetros', '6.000 kilómetros', '12.000 kilómetros']::text[], 2, 'El artículo 13.2.ª establece como circunstancia de novedad «Que los vehículos terrestres no hayan recorrido más de 6.000 kilómetros».', 2, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'iv1-017', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 30 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('iv1-018', (select id from leyes where slug = 'ley-37-1992'), '15.Uno.a', 'Constituye adquisición intracomunitaria la obtención del poder de disposición sobre bienes muebles corporales expedidos o transportados al territorio de aplicación del impuesto, con destino al adquirente, desde:', array['Cualquier territorio tercero', 'Canarias, Ceuta o Melilla', 'Cualquier punto del propio territorio de aplicación del impuesto', 'Otro Estado miembro']::text[], 3, 'Según el artículo 15.Uno.a), es la obtención del poder de disposición sobre bienes «expedidos o transportados al territorio de aplicación del Impuesto, con destino al adquirente, desde otro Estado miembro».', 1, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
