insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('iv1-019', (select id from leyes where slug = 'ley-37-1992'), '17', 'Las importaciones de bienes están sujetas al IVA:', array['Solo cuando el importador sea empresario o profesional', 'Solo cuando los bienes se destinen a la reventa', 'Solo cuando el importador tenga derecho a deducir', 'Cualquiera que sea el fin a que se destinen y la condición del importador']::text[], 3, 'El artículo 17 dispone que «Estarán sujetas al impuesto las importaciones de bienes, cualquiera que sea el fin a que se destinen y la condición del importador.»', 1, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
