insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('iv1-020', (select id from leyes where slug = 'ley-37-1992'), '18.Dos', 'Un bien procedente de un territorio tercero se coloca, desde su entrada, en situación de depósito temporal. La importación se produce:', array['Cuando cese la situación en el territorio de aplicación del impuesto', 'En el momento de su entrada en el interior del país', 'En el momento en que el bien se coloca en depósito', 'Cuando se presenta la declaración recapitulativa']::text[], 0, 'El artículo 18.Dos establece que «la importación de dicho bien se producirá cuando cesen las situaciones o se ultimen los regímenes indicados en el territorio de aplicación del impuesto».', 3, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
