insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('iv1-021', (select id from leyes where slug = 'ley-37-1992'), '20.Uno.2.º.a', 'La exención de las prestaciones de hospitalización o asistencia sanitaria no se extiende a:', array['Los servicios de quirófano prestados por clínicas', 'La entrega de medicamentos para ser consumidos fuera de los establecimientos', 'El alojamiento prestado a los acompañantes de los pacientes', 'El suministro de material sanitario a los pacientes hospitalizados']::text[], 1, 'El artículo 20.Uno.2.º excluye de la exención «La entrega de medicamentos para ser consumidos fuera de los establecimientos mencionados en el primer párrafo de este número.»', 2, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
