insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('iv1-022', (select id from leyes where slug = 'ley-37-1992'), '20.Uno.9.º.c', 'La exención de la enseñanza y la formación del artículo 20.Uno.9.º no comprende las operaciones efectuadas por:', array['Escuelas de conductores relativas a los permisos de las clases A y B', 'Centros de enseñanza de idiomas autorizados', 'Entidades de formación y reciclaje profesional autorizadas', 'Universidades por la enseñanza de postgraduados']::text[], 0, 'La exención no comprenderá «Las efectuadas por escuelas de conductores de vehículos relativas a los permisos de conducción de vehículos terrestres de las clases A y B» (artículo 20.Uno.9.º.c).', 2, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
