insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('iv1-023', (select id from leyes where slug = 'ley-37-1992'), '20.Uno.16.º', 'Están exentas del IVA en operaciones interiores las operaciones de:', array['Alquiler de cajas de seguridad', 'Gestión de cobro de créditos y recibos', 'Arrendamiento de maquinaria industrial', 'Seguro, reaseguro y capitalización']::text[], 3, 'El artículo 20.Uno.16.º declara exentas «Las operaciones de seguro, reaseguro y capitalización.»', 1, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
