insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('iv1-024', (select id from leyes where slug = 'ley-37-1992'), '20.Uno.18.º.j', 'Las operaciones de compra, venta o cambio de divisas, billetes y monedas que sean medios legales de pago están exentas, a excepción de:', array['Los billetes de banco emitidos por Estados no miembros', 'Las monedas de curso legal de otros Estados miembros', 'Las monedas y billetes de colección y las piezas de oro, plata y platino', 'Las divisas distintas del euro']::text[], 2, 'El artículo 20.Uno.18.º.j) exenta estas operaciones «a excepción de las monedas y billetes de colección y de las piezas de oro, plata y platino».', 3, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
