insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('iv1-025', (select id from leyes where slug = 'ley-37-1992'), '20.Uno.22.º.A', 'No tiene la consideración de primera entrega la realizada por el promotor después de la utilización ininterrumpida del inmueble por su propietario durante un plazo igual o superior a:', array['Un año', 'Dos años', 'Tres años', 'Cinco años']::text[], 1, 'Según el artículo 20.Uno.22.º.A), no es primera entrega la realizada por el promotor «después de la utilización ininterrumpida del inmueble por un plazo igual o superior a dos años».', 3, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
