insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('iv1-026', (select id from leyes where slug = 'ley-37-1992'), '20.Uno.23.º', 'La exención de los arrendamientos del artículo 20.Uno.23.º NO comprende:', array['Los arrendamientos de terrenos rústicos', 'Los arrendamientos de terrenos para estacionamientos de vehículos', 'Los arrendamientos de edificios destinados exclusivamente a viviendas', 'Los arrendamientos de garajes accesorios a las viviendas, arrendados conjuntamente con ellas']::text[], 1, 'La exención no comprenderá «Los arrendamientos de terrenos para estacionamientos de vehículos.» (artículo 20.Uno.23.º, letra a´).', 2, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
