insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('iv1-027', (select id from leyes where slug = 'ley-37-1992'), '20.Dos', 'Pueden ser objeto de renuncia por el sujeto pasivo las exenciones del artículo 20.Uno relativas a los números:', array['16.º y 18.º', '9.º y 10.º', '20.º y 22.º', '23.º y 24.º']::text[], 2, 'El artículo 20.Dos dispone que «Las exenciones relativas a los números 20.º y 22.º del apartado anterior podrán ser objeto de renuncia por el sujeto pasivo».', 2, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
