insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('iv1-028', (select id from leyes where slug = 'ley-37-1992'), '21.1.º', 'Están exentas como exportaciones las entregas de bienes expedidos o transportados fuera de la Comunidad por:', array['El adquirente establecido en el territorio de aplicación del impuesto', 'El transmitente o un tercero que actúe en su nombre y por su cuenta', 'Cualquier adquirente que no sea empresario o profesional', 'Un transportista que actúe en nombre del adquirente residente en España']::text[], 1, 'El artículo 21.1.º exime «Las entregas de bienes expedidos o transportados fuera de la Comunidad por el transmitente o por un tercero que actúe en nombre y por cuenta de éste.»', 1, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
