insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('iv1-029', (select id from leyes where slug = 'ley-37-1992'), '21.2.º.A.b', 'Para que sea exenta la entrega de bienes a un viajero, este debe tener su residencia habitual:', array['Fuera del territorio de aplicación del impuesto', 'Fuera del territorio de la Comunidad', 'En un Estado miembro distinto de España', 'En cualquier país con convenio con España']::text[], 1, 'El artículo 21.2.º.A) exige «Que los viajeros tengan su residencia habitual fuera del territorio de la Comunidad.»', 2, '2026-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
