insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('obg-017', (select id from leyes where slug = 'ley-58-2003'), '38.2', 'El obligado a soportar la repercusión de la cuota tributaria:', array['Está obligado al pago frente a la Administración como sustituto', 'Responde solidariamente con el sujeto pasivo ante la Administración', 'No debe pagar a la Administración, pero sí satisfacer al sujeto pasivo la cuota repercutida', 'No debe satisfacer cantidad alguna al sujeto pasivo']::text[], 2, 'Según el artículo 38.2, «El repercutido no está obligado al pago frente a la Administración tributaria pero debe satisfacer al sujeto pasivo el importe de la cuota repercutida».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
