insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('obg-020', (select id from leyes where slug = 'ley-58-2003'), '41.2', 'Salvo precepto legal expreso en contrario, la responsabilidad tributaria será:', array['Siempre solidaria', 'Siempre subsidiaria', 'Solidaria hasta el límite de los bienes embargables', 'Mancomunada con el deudor principal']::text[], 1, 'El artículo 41.2 establece: «Salvo precepto legal expreso en contrario, la responsabilidad será siempre subsidiaria».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'obg-020', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 16 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('obg-021', (select id from leyes where slug = 'ley-58-2003'), '41.5', 'La derivación de la acción administrativa a los responsables subsidiarios requiere la previa declaración de fallido de:', array['Solo el deudor principal', 'El deudor principal y los responsables solidarios', 'Solo los responsables solidarios', 'Los sucesores del deudor principal']::text[], 1, 'El artículo 41.5 señala: «La derivación de la acción administrativa a los responsables subsidiarios requerirá la previa declaración de fallido del deudor principal y de los responsables solidarios».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'obg-021', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 16 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('obg-022', (select id from leyes where slug = 'ley-58-2003'), '42.1.c', 'La responsabilidad solidaria de quien sucede en la titularidad de explotaciones económicas no es aplicable a:', array['Los supuestos de sucesión por causa de muerte', 'Quienes sucedan por cualquier concepto en el ejercicio de la actividad', 'Los adquirentes de elementos aislados que permitan continuar la explotación', 'Los adquirentes de explotaciones de un deudor concursado fuera del procedimiento concursal']::text[], 0, 'El artículo 42.1.c) indica que esta responsabilidad «no será aplicable a los supuestos de sucesión por causa de muerte, que se regirán por lo establecido en el artículo 39 de esta ley».', 3, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
