insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('obg-023', (select id from leyes where slug = 'ley-58-2003'), '43.1.f', 'El certificado de estar al corriente de obligaciones tributarias aportado por el contratista exime de responsabilidad al pagador si se emitió durante:', array['Los 3 meses anteriores al pago de cada factura', 'Los 6 meses anteriores al pago de cada factura', 'Los 24 meses anteriores al pago de cada factura', 'Los 12 meses anteriores al pago de cada factura']::text[], 3, 'El artículo 43.1.f) exige un certificado «emitido a estos efectos por la Administración tributaria durante los 12 meses anteriores al pago de cada factura correspondiente a la contratación o subcontratación».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
