insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('obg-025', (select id from leyes where slug = 'ley-58-2003'), '46.7', 'Si falta o es insuficiente el poder de representación, el órgano competente debe conceder un plazo de subsanación de:', array['5 días', '15 días', '30 días', '10 días']::text[], 3, 'El artículo 46.7 dispone que la falta de poder no impedirá el acto «siempre que se acompañe aquél o se subsane el defecto dentro del plazo de 10 días».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
