insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('obg-026', (select id from leyes where slug = 'ley-58-2003'), '48.3', '¿Cuándo produce efectos frente a la Administración tributaria el cambio de domicilio fiscal?', array['Desde que el obligado se traslada efectivamente al nuevo domicilio', 'Desde el día siguiente al empadronamiento en el nuevo municipio', 'Cuando el obligado cumple el deber de comunicarlo a la Administración', 'Desde el inicio del período impositivo siguiente']::text[], 2, 'El artículo 48.3 señala: «El cambio de domicilio fiscal no producirá efectos frente a la Administración tributaria hasta que se cumpla con dicho deber de comunicación».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
