insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('obg-027', (select id from leyes where slug = 'ley-58-2003'), '66', '¿En cuántos años prescribe el derecho de la Administración para exigir el pago de las deudas tributarias liquidadas y autoliquidadas?', array['Cuatro años', 'Tres años', 'Cinco años', 'Diez años']::text[], 0, 'El artículo 66 dice: «Prescribirán a los cuatro años los siguientes derechos», entre ellos «El derecho de la Administración para exigir el pago de las deudas tributarias liquidadas y autoliquidadas».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
