insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('rev-002', (select id from leyes where slug = 'ley-58-2003'), '216', 'Es un procedimiento especial de revisión en materia tributaria:', array['La declaración de lesividad de actos anulables', 'El recurso potestativo de reposición', 'La reclamación económico-administrativa en única instancia', 'El recurso de alzada ordinario ante el órgano superior']::text[], 0, 'El artículo 216 establece: «Son procedimientos especiales de revisión los de» […] «Declaración de lesividad de actos anulables».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'rev-002', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 26 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('rev-003', (select id from leyes where slug = 'ley-58-2003'), '217.6', 'El plazo máximo para notificar resolución expresa en el procedimiento de revisión de actos nulos de pleno derecho es de:', array['Seis meses', 'Tres meses', 'Dos años', 'Un año']::text[], 3, 'Según el artículo 217.6: «El plazo máximo para notificar resolución expresa será de un año desde que se presente la solicitud por el interesado o desde que se le notifique el acuerdo de iniciación de oficio del procedimiento».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'rev-003', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 26 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('rev-004', (select id from leyes where slug = 'ley-58-2003'), '217.6.b', 'Un contribuyente solicita la declaración de nulidad de pleno derecho de un acto. Vencido el plazo máximo sin resolución expresa, se produce:', array['La caducidad del procedimiento y el archivo de las actuaciones', 'La estimación por silencio administrativo de la solicitud', 'La desestimación por silencio administrativo de la solicitud', 'La inadmisión a trámite de la solicitud sin más trámite']::text[], 2, 'El artículo 217.6.b) prevé «La desestimación por silencio administrativo de la solicitud, si el procedimiento se hubiera iniciado a instancia del interesado»; la caducidad solo opera si se inició de oficio.', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
