insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('rev-005', (select id from leyes where slug = 'ley-58-2003'), '217.4', 'La declaración de nulidad de pleno derecho de un acto tributario requiere:', array['Informe favorable previo del Tribunal Económico-Administrativo Central', 'Dictamen favorable previo del Consejo de Estado u órgano equivalente de la comunidad autónoma', 'Informe previo del órgano con funciones de asesoramiento jurídico', 'Resolución previa del Tribunal Económico-Administrativo competente']::text[], 1, 'El artículo 217.4 dispone: «La declaración de nulidad requerirá dictamen favorable previo del Consejo de Estado u órgano equivalente de la respectiva comunidad autónoma, si lo hubiere».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
