insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('rev-006', (select id from leyes where slug = 'ley-58-2003'), '218.2', 'La declaración de lesividad de un acto favorable a los interesados no podrá adoptarse una vez transcurridos desde que se notificó el acto:', array['Cuatro años', 'Dos años', 'Un año', 'Seis años']::text[], 0, 'El artículo 218.2 señala: «La declaración de lesividad no podrá adoptarse una vez transcurridos cuatro años desde que se notificó el acto administrativo».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'rev-006', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 26 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('rev-007', (select id from leyes where slug = 'ley-58-2003'), '218.3', 'El procedimiento de declaración de lesividad caduca si, desde su iniciación, transcurren sin declararse la lesividad:', array['Un mes', 'Seis meses', 'Un año', 'Tres meses']::text[], 3, 'El artículo 218.3 establece: «Transcurrido el plazo de tres meses desde la iniciación del procedimiento sin que se hubiera declarado la lesividad se producirá la caducidad del mismo».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
