insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('rev-008', (select id from leyes where slug = 'ley-58-2003'), '219.3', 'El procedimiento de revocación de los actos de aplicación de los tributos se inicia:', array['Siempre a instancia del interesado', 'De oficio o a instancia del interesado', 'Siempre de oficio', 'Por acuerdo del Tribunal Económico-Administrativo competente']::text[], 2, 'El artículo 219.3 señala que «El procedimiento de revocación se iniciará siempre de oficio, y será competente para declararla el órgano que se determine reglamentariamente, que deberá ser distinto del órgano que dictó el acto».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
