insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('rev-029', (select id from leyes where slug = 'ley-58-2003'), '244.4', 'Es competente para resolver el recurso extraordinario de revisión:', array['El tribunal que dictó la resolución firme', 'El Tribunal Económico-Administrativo Central', 'La Sala Especial para la Unificación de Doctrina', 'El Tribunal Económico-Administrativo Regional del domicilio del recurrente']::text[], 1, 'El artículo 244.4 dispone: «Será competente para resolver el recurso extraordinario de revisión el Tribunal Económico-Administrativo Central».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
