insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('rev-030', (select id from leyes where slug = 'ley-58-2003'), '243.2', 'Es competente para resolver el recurso extraordinario para la unificación de doctrina:', array['La Sala Especial para la Unificación de Doctrina', 'El Pleno del Tribunal Económico-Administrativo Central', 'Una Sala del Tribunal Económico-Administrativo Central', 'El Tribunal Económico-Administrativo Regional que dictó la resolución']::text[], 0, 'El artículo 243.2 establece: «Será competente para resolver este recurso la Sala Especial para la Unificación de Doctrina».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
