insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('rev-031', (select id from leyes where slug = 'rd-520-2005'), '64', 'Las reclamaciones económico-administrativas se tramitan por el procedimiento abreviado cuando su cuantía es inferior a (salvo bases o valoraciones):', array['3.000 euros', '12.000 euros', '15.000 euros', '6.000 euros']::text[], 3, 'El artículo 64 del Reglamento dispone: «Las reclamaciones económico-administrativas se tramitarán por el procedimiento abreviado cuando sean de cuantía inferior a 6.000 euros o 72.000 euros si se trata de reclamaciones contra bases o valoraciones».', 1, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'rev-031', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 26 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('rev-032', (select id from leyes where slug = 'ley-58-2003'), '248', 'Contra las resoluciones dictadas en el procedimiento abreviado:', array['Cabe recurso de alzada ordinario ante el Tribunal Económico-Administrativo Central', 'Solo cabe recurso contencioso-administrativo', 'No cabe alzada ordinaria, pero sí los demás recursos de la sección anterior', 'No cabe ningún recurso en vía administrativa']::text[], 2, 'El artículo 248 señala que «no podrá interponerse recurso de alzada ordinario, pero podrán proceder, en su caso, los demás recursos regulados en la sección anterior».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'rev-032', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 26 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('rev-033', (select id from leyes where slug = 'rd-520-2005'), '36', 'Contra una liquidación tributaria, procede el recurso de alzada ordinario cuando la cuantía de la reclamación supera:', array['72.000 euros', '150.000 euros', '6.000 euros', '1.800.000 euros']::text[], 1, 'El artículo 36 del Reglamento dice que podrá interponerse «cuando la cuantía de la reclamación, calculada conforme a lo dispuesto en el artículo anterior, supere 150.000 euros, o 1.800.000 euros si se trata de reclamaciones contra bases o valoraciones».', 3, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'rev-033', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 26 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('rev-034', (select id from leyes where slug = 'rd-520-2005'), '41.1', 'Si la garantía de la suspensión es un depósito de dinero y la reclamación sigue el procedimiento general, los intereses de demora a cubrir son los de:', array['Un año', 'Seis meses', 'Dos años', 'Un mes']::text[], 0, 'El artículo 41.1 del Reglamento fija los intereses «de un año si el procedimiento de la reclamación es el general»; seis meses en el abreviado y dos años si cabe alzada ordinaria.', 3, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
