insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('rev-035', (select id from leyes where slug = 'ley-58-2003'), '241 ter.7', 'Contra los actos dictados en ejecución de una resolución económico-administrativa, el recurso contra la ejecución:', array['Exige haber interpuesto antes recurso de reposición', 'Exige solicitar antes la rectificación de errores', 'Exige haber agotado antes el recurso de alzada ordinario', 'No admite recurso de reposición previo']::text[], 3, 'El artículo 241 ter.7 dispone: «No cabrá la interposición de recurso de reposición con carácter previo al recurso contra la ejecución».', 3, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
