insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('san-011', (select id from leyes where slug = 'ley-58-2003'), '184.3.a', 'La llevanza incorrecta de libros mediante falsedad de asientos es anomalía sustancial (medio fraudulento) solo si su incidencia supera, sobre la base de la sanción:', array['El 10 por ciento', 'El 25 por ciento', 'El 50 por ciento', 'El 75 por ciento']::text[], 2, 'La apreciación de esta circunstancia «requerirá que la incidencia de la llevanza incorrecta de los libros o registros represente un porcentaje superior al 50 por ciento del importe de la base de la sanción».', 3, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'san-011', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 25 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('san-012', (select id from leyes where slug = 'ley-58-2003'), '186.1', 'A una persona se le impone una multa de 40.000 euros por infracción grave, con comisión repetida como criterio de graduación. ¿Cuánto puede durar la pérdida de subvenciones como sanción accesoria?', array['Seis meses', 'Dos años', 'Tres años', 'Un año']::text[], 3, 'Procede la pérdida de subvenciones «durante un plazo de un año si la infracción cometida hubiera sido grave o de dos años si hubiera sido muy grave».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'san-012', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 25 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('san-013', (select id from leyes where slug = 'ley-58-2003'), '186.2', 'Multa de 150.000 euros por infracción muy grave con comisión repetida. Plazo de la prohibición de contratar con la Administración que impuso la sanción:', array['Cuatro años', 'Dos años', 'Tres años', 'Cinco años']::text[], 0, 'La prohibición dura «tres, cuatro o cinco años, cuando el importe de la sanción impuesta hubiera sido igual o superior a 60.000, 150.000 ó 300.000 euros, respectivamente».', 3, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'san-013', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 25 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('san-014', (select id from leyes where slug = 'ley-58-2003'), '187.1.a', 'Hay comisión repetida de infracciones si el infractor fue sancionado por una de la misma naturaleza en resolución firme en vía administrativa dentro de los:', array['Dos años anteriores a la comisión de la infracción', 'Cuatro años anteriores a la comisión de la infracción', 'Tres años anteriores a la comisión de la infracción', 'Cinco años anteriores a la comisión de la infracción']::text[], 1, 'Se produce esta circunstancia cuando el sujeto infractor hubiera sido sancionado «en virtud de resolución firme en vía administrativa dentro de los cuatro años anteriores a la comisión de la infracción».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'san-014', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 25 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('san-015', (select id from leyes where slug = 'ley-58-2003'), '187.1.b', 'El perjuicio económico para la Hacienda es del 60 por ciento. ¿En cuántos puntos porcentuales se incrementa la sanción mínima por este criterio de graduación?', array['10 puntos', '15 puntos', '20 puntos', '25 puntos']::text[], 2, '«Cuando el perjuicio económico sea superior al 50 por ciento e inferior o igual al 75 por ciento, el incremento será de 20 puntos porcentuales».', 3, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
