insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('san-016', (select id from leyes where slug = 'ley-58-2003'), '188.1.a', 'La cuantía de las sanciones impuestas según los artículos 191 a 197 LGT se reduce en un porcentaje determinado en los supuestos de actas con acuerdo. ¿Cuál?', array['El 30 por ciento', 'El 40 por ciento', 'El 50 por ciento', 'El 65 por ciento']::text[], 3, 'El artículo 188.1 prevé una reducción de «Un 65 por ciento en los supuestos de actas con acuerdo previstos en el artículo 155 de esta Ley».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
