insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('san-018', (select id from leyes where slug = 'ley-58-2003'), '189.2', 'El plazo de prescripción para imponer sanciones tributarias es de:', array['Cuatro años desde que se notificó la liquidación', 'Cuatro años desde que se cometió la infracción', 'Cinco años desde que se cometió la infracción', 'Seis años desde que se cometió la infracción']::text[], 1, 'El plazo «será de cuatro años y comenzará a contarse desde el momento en que se cometieron las correspondientes infracciones».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'san-018', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 25 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('san-019', (select id from leyes where slug = 'ley-58-2003'), '189.4', '¿Cómo se aplica la prescripción del derecho a imponer sanciones tributarias?', array['Solo cuando la invoque el interesado en alegaciones', 'Solo a instancia del interesado en el recurso de reposición', 'De oficio, sin necesidad de que la invoque el interesado', 'De oficio, pero solo en el procedimiento de inspección']::text[], 2, 'El artículo 189.4 señala: «La prescripción se aplicará de oficio por la Administración tributaria, sin necesidad de que la invoque el interesado».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'san-019', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 25 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('san-020', (select id from leyes where slug = 'ley-58-2003'), '191.2', 'Se deja de ingresar una cuota de 2.500 euros en una autoliquidación, sin facturas falsas ni retenciones impagadas. ¿Calificación y sanción?', array['Leve, multa fija de 150 euros', 'Grave, multa proporcional del 50 al 100 por ciento', 'Leve, multa proporcional del 15 por ciento', 'Leve, multa proporcional del 50 por ciento']::text[], 3, 'La infracción será leve «cuando la base de la sanción sea inferior o igual a 3.000 euros» y «consistirá en multa pecuniaria proporcional del 50 por ciento».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'san-020', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 25 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('san-021', (select id from leyes where slug = 'ley-58-2003'), '191.3', 'Se dejan de ingresar 8.000 euros en una autoliquidación existiendo ocultación, sin medios fraudulentos. ¿Calificación y sanción?', array['Grave, multa proporcional del 50 al 100 por ciento', 'Leve, multa proporcional del 50 por ciento', 'Grave, multa proporcional del 100 al 150 por ciento', 'Muy grave, multa proporcional del 100 al 150 por ciento']::text[], 0, '«La infracción será grave cuando la base de la sanción sea superior a 3.000 euros y exista ocultación» y se sanciona con «multa pecuniaria proporcional del 50 al 100 por ciento».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'san-021', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 25 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('san-022', (select id from leyes where slug = 'ley-58-2003'), '191.4', 'Se deja de ingresar la deuda de una autoliquidación utilizando medios fraudulentos. La infracción es:', array['Muy grave, con multa proporcional del 75 al 100 por ciento', 'Muy grave, con multa proporcional del 100 al 150 por ciento', 'Grave, con multa proporcional del 100 al 150 por ciento', 'Grave, con multa proporcional del 50 al 100 por ciento']::text[], 1, '«La utilización de medios fraudulentos determinará que la infracción sea calificada en todo caso como muy grave» y la sanción «consistirá en multa pecuniaria proporcional del 100 al 150 por ciento».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
