insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('san-024', (select id from leyes where slug = 'ley-58-2003'), '195.2', 'Se determinan improcedentemente partidas a compensar en la base imponible de declaraciones futuras. La multa proporcional es del:', array['40 por ciento', '50 por ciento', '75 por ciento', '15 por ciento']::text[], 3, 'La sanción es «del 15 por ciento si se trata de partidas a compensar o deducir en la base imponible, o del 50 por ciento si se trata de partidas a deducir en la cuota».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'san-024', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 25 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('san-025', (select id from leyes where slug = 'ley-58-2003'), '198.2', 'Una autoliquidación sin perjuicio económico se presenta fuera de plazo sin requerimiento previo. La sanción general es de 200 euros; ¿qué multa corresponde?', array['100 euros', '50 euros', '150 euros', '200 euros']::text[], 0, 'Si se presentan fuera de plazo sin requerimiento previo, «la sanción y los límites mínimo y máximo serán la mitad de los previstos en el apartado anterior», que es «multa pecuniaria fija de 200 euros».', 3, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'san-025', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 25 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('san-026', (select id from leyes where slug = 'ley-58-2003'), '199.2', 'Se presenta una autoliquidación con datos inexactos, sin perjuicio económico para la Hacienda. ¿Calificación y sanción?', array['Leve, multa fija de 150 euros', 'Grave, multa fija de 150 euros', 'Grave, multa fija de 250 euros', 'Grave, multa fija de 300 euros']::text[], 1, 'Estas infracciones «serán graves» y, si se presentan de forma inexacta autoliquidaciones o declaraciones, «la sanción consistirá en multa pecuniaria fija de 150 euros».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
