insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('san-027', (select id from leyes where slug = 'ley-58-2003'), '201.2.b', 'Un empresario no expide facturas por operaciones cuyo importe se conoce. La infracción es grave y la multa proporcional es del:', array['Uno por ciento del importe de las operaciones', '75 por ciento del importe de las operaciones', 'Dos por ciento del importe de las operaciones', 'Cinco por ciento del importe de las operaciones']::text[], 2, 'En la falta de expedición de facturas «La sanción consistirá en multa pecuniaria proporcional del dos por ciento del importe del conjunto de las operaciones que hayan originado la infracción».', 3, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
