insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('san-028', (select id from leyes where slug = 'ley-58-2003'), '210.4', 'Notificada la propuesta de resolución en el procedimiento sancionador, ¿de qué plazo dispone el interesado para alegar y presentar pruebas?', array['10 días', '20 días', 'Un mes', '15 días']::text[], 3, 'La propuesta de resolución se notifica al interesado «concediéndole un plazo de 15 días para que alegue cuanto considere conveniente y presente los documentos, justificantes y pruebas que estime oportunos».', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
