insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('san-029', (select id from leyes where slug = 'ley-58-2003'), '211.4', '¿Qué efecto tiene la caducidad del procedimiento sancionador en materia tributaria?', array['Ordena archivar las actuaciones e impide iniciar un nuevo procedimiento sancionador', 'Permite iniciar un nuevo procedimiento en el plazo de seis meses', 'Interrumpe la prescripción y permite reabrir el expediente', 'Obliga a retrotraer las actuaciones al momento de la propuesta']::text[], 0, 'La declaración de caducidad «ordenará el archivo de las actuaciones. Dicha caducidad impedirá la iniciación de un nuevo procedimiento sancionador».', 1, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
