insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sfa-001', (select id from leyes where slug = 'constitucion'), '31.3', 'Según el artículo 31.3 de la Constitución, solo podrán establecerse prestaciones personales o patrimoniales de carácter público:', array['Mediante real decreto-ley únicamente', 'Con arreglo a la ley', 'Por reglamento aprobado por el Gobierno', 'Por decisión de la Administración competente']::text[], 1, 'El artículo 31.3 dispone: «Sólo podrán establecerse prestaciones personales o patrimoniales de carácter público con arreglo a la ley».', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
