insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sfa-002', (select id from leyes where slug = 'constitucion'), '133.2', 'Según el artículo 133.2 de la Constitución, las Comunidades Autónomas y las Corporaciones locales podrán:', array['Establecer tributos solo si el Estado los ha cedido antes', 'Exigir tributos, pero solo el Estado puede establecerlos', 'Establecer tributos con carácter originario y exclusivo', 'Establecer y exigir tributos, de acuerdo con la Constitución y las leyes']::text[], 3, 'El artículo 133.2 señala que «Las Comunidades Autónomas y las Corporaciones locales podrán establecer y exigir tributos, de acuerdo con la Constitución y las leyes».', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
