insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sfa-003', (select id from leyes where slug = 'constitucion'), '133.4', 'Las administraciones públicas solo podrán contraer obligaciones financieras y realizar gastos, según el artículo 133.4 de la Constitución:', array['De acuerdo con las leyes', 'Conforme a lo que fijen los reglamentos del Gobierno', 'Previa autorización del Tribunal de Cuentas', 'Con arreglo a la Ley de Presupuestos exclusivamente']::text[], 0, 'Según el artículo 133.4, «sólo podrán contraer obligaciones financieras y realizar gastos de acuerdo con las leyes».', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
