insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sfa-004', (select id from leyes where slug = 'constitucion'), '156.1', 'Según el artículo 156.1 de la Constitución, las Comunidades Autónomas gozan de autonomía financiera con arreglo a los principios de:', array['Suficiencia financiera y corresponsabilidad fiscal', 'Subsidiariedad y lealtad institucional', 'Coordinación con la Hacienda estatal y solidaridad entre todos los españoles', 'Autonomía plena y equilibrio territorial']::text[], 2, 'El artículo 156.1 establece que gozarán de autonomía financiera «con arreglo a los principios de coordinación con la Hacienda estatal y de solidaridad entre todos los españoles».', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
