insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sfa-005', (select id from leyes where slug = 'constitucion'), '156.2', 'Según la Constitución, las Comunidades Autónomas podrán actuar como delegados o colaboradores del Estado para:', array['La inspección y la sanción de los tributos locales', 'La recaudación, la gestión y la liquidación de los recursos tributarios del Estado', 'El establecimiento de los tributos estatales', 'La elaboración de los Presupuestos Generales del Estado']::text[], 1, 'El artículo 156.2 permite que actúen «como delegados o colaboradores del Estado para la recaudación, la gestión y la liquidación de los recursos tributarios de aquél».', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
