insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sfa-006', (select id from leyes where slug = 'constitucion'), '157.1.c', 'Entre los recursos de las Comunidades Autónomas, el artículo 157.1 de la Constitución incluye:', array['Participaciones en los tributos de las Corporaciones locales', 'Recargos sobre los impuestos de las Entidades Locales', 'Cuotas de la Seguridad Social recaudadas en su territorio', 'Transferencias de un Fondo de Compensación interterritorial']::text[], 3, 'El artículo 157.1.c) incluye entre los recursos autonómicos las «Transferencias de un Fondo de Compensación interterritorial y otras asignaciones con cargo a los Presupuestos Generales del Estado».', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
