insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sfa-007', (select id from leyes where slug = 'constitucion'), '157.2', 'Según el artículo 157.2 de la Constitución, las Comunidades Autónomas no podrán adoptar medidas tributarias que:', array['Supongan obstáculo para la libre circulación de mercancías o servicios', 'Graven los rendimientos de los residentes en su territorio', 'Establezcan recargos sobre impuestos estatales cedidos', 'Afecten a los tributos propios de otra Comunidad Autónoma']::text[], 0, 'El artículo 157.2 prohíbe «medidas tributarias sobre bienes situados fuera de su territorio o que supongan obstáculo para la libre circulación de mercancías o servicios».', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
