insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sfa-009', (select id from leyes where slug = 'lo-8-1980'), '6.2', 'Según el artículo 6 de la LOFCA, los tributos que establezcan las Comunidades Autónomas no podrán recaer sobre:', array['Hechos imponibles no gravados por el Estado', 'Hechos imponibles gravados por el Estado', 'Materias que ninguna ley haya regulado todavía', 'Bienes situados dentro de su propio territorio']::text[], 1, 'El artículo 6.2 LOFCA dispone: «Los tributos que establezcan las Comunidades Autónomas no podrán recaer sobre hechos imponibles gravados por el Estado».', 1, '2026-03-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
