insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sfa-011', (select id from leyes where slug = 'lo-8-1980'), '10.1', 'Según la LOFCA, son tributos cedidos los establecidos y regulados por el Estado:', array['Cuyo producto corresponda a la Comunidad Autónoma', 'Cuya gestión corresponda a la Comunidad Autónoma', 'Cuya recaudación se reparta a partes iguales con ella', 'Cuyo rendimiento se destine a los servicios transferidos']::text[], 0, 'El artículo 10.1 LOFCA define: «Son tributos cedidos los establecidos y regulados por el Estado, cuyo producto corresponda a la Comunidad Autónoma».', 2, '2026-03-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
