insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sfa-012', (select id from leyes where slug = 'lo-8-1980'), '10.4.a', 'Los tributos cedidos de naturaleza personal se atribuyen a una Comunidad por el domicilio fiscal del sujeto pasivo; en las adquisiciones por causa de muerte se atiende a:', array['El domicilio fiscal del heredero de mayor edad', 'El lugar donde radiquen los bienes heredados', 'El domicilio fiscal del causante', 'El lugar de fallecimiento del causante']::text[], 2, 'Según el artículo 10.4.a) LOFCA, la atribución se hará «en función del domicilio fiscal de los sujetos pasivos, salvo en el gravamen de adquisiciones por causa de muerte, en el que se atenderá al del causante».', 2, '2026-03-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
