insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sfa-013', (select id from leyes where slug = 'lo-8-1980'), '11.e', 'La LOFCA permite ceder a las Comunidades Autónomas el Impuesto sobre el Valor Añadido con carácter parcial y con el límite máximo del:', array['25 por ciento', '50 por ciento', '58 por ciento', '75 por ciento']::text[], 1, 'El artículo 11.e) LOFCA incluye el «Impuesto sobre el Valor Añadido, con carácter parcial con el límite máximo del 50 por ciento».', 2, '2026-03-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
