insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sfa-014', (select id from leyes where slug = 'lo-8-1980'), '11.f', 'Los Impuestos Especiales de Fabricación (salvo Electricidad e Hidrocarburos) pueden cederse a las Comunidades Autónomas con carácter parcial con el límite máximo del:', array['40 por ciento', '50 por ciento', '58 por ciento', '75 por ciento']::text[], 2, 'El artículo 11.f) LOFCA prevé «Los Impuestos Especiales de Fabricación, con carácter parcial con el límite máximo del 58 por ciento de cada uno de ellos, excepto el Impuesto sobre la Electricidad y el Impuesto sobre Hidrocarburos».', 3, '2026-03-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'sfa-014', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 13 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sfa-015', (select id from leyes where slug = 'lo-8-1980'), '12.1', 'Las Comunidades Autónomas podrán establecer recargos sobre los tributos del Estado susceptibles de cesión, con la excepción del:', array['Impuesto sobre el Valor Añadido', 'Impuesto sobre la Electricidad', 'Impuesto sobre Sucesiones y Donaciones', 'Impuesto sobre Hidrocarburos']::text[], 3, 'El artículo 12.1 LOFCA dice que podrán establecer recargos «sobre los tributos del Estado susceptibles de cesión, excepto en el Impuesto sobre Hidrocarburos».', 3, '2026-03-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
