insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sfa-016', (select id from leyes where slug = 'lo-8-1980'), '19.2.a', 'En el IRPF cedido, la LOFCA permite a las Comunidades asumir competencias normativas sobre el mínimo personal y familiar y sobre:', array['La tarifa y las deducciones de la cuota', 'Los rendimientos íntegros del trabajo', 'Los pagos fraccionados y las retenciones', 'El hecho imponible y el devengo']::text[], 0, 'Según el artículo 19.2.a) LOFCA, en el IRPF corresponde «la fijación de la cuantía del mínimo personal y familiar y la regulación de la tarifa y deducciones de la cuota».', 2, '2026-03-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
