insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sfa-017', (select id from leyes where slug = 'lo-8-1980'), '19.2', 'Las Comunidades Autónomas pueden asumir por delegación la aplicación, la potestad sancionadora y la revisión de los tributos cedidos, salvo en:', array['El Impuesto sobre Sucesiones y Donaciones', 'El Impuesto sobre el Valor Añadido', 'El Impuesto sobre el Patrimonio', 'Los Tributos sobre el Juego']::text[], 1, 'El artículo 19.2 LOFCA excluye esa delegación: «no será de aplicación en el Impuesto sobre la Renta de las Personas Físicas, en el Impuesto sobre el Valor Añadido ni en los Impuestos Especiales de Fabricación».', 3, '2026-03-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
