insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sfa-018', (select id from leyes where slug = 'lo-8-1980'), '3.2.f', 'Entre las materias de las que entiende el Consejo de Política Fiscal y Financiera de las Comunidades Autónomas figura:', array['La aprobación de los presupuestos autonómicos', 'La fijación de los tipos de gravamen de los tributos cedidos', 'La coordinación de la política de endeudamiento', 'La resolución de conflictos sobre puntos de conexión']::text[], 2, 'El artículo 3.2.f) LOFCA atribuye al Consejo «La coordinación de la política de endeudamiento».', 2, '2026-03-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
