insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sfa-019', (select id from leyes where slug = 'lo-8-1980'), '7.3', 'El rendimiento previsto para cada tasa autonómica por la prestación de servicios o realización de actividades:', array['Podrá superar el coste hasta un diez por ciento', 'Deberá igualar exactamente el coste del servicio', 'Se fijará libremente por la Comunidad Autónoma', 'No podrá sobrepasar el coste de dichos servicios o actividades']::text[], 3, 'El artículo 7.3 LOFCA establece: «El rendimiento previsto para cada tasa por la prestación de servicios o realización de actividades no podrá sobrepasar el coste de dichos servicios o actividades».', 1, '2026-03-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
