insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sfa-025', (select id from leyes where slug = 'ley-7-1985'), '106.2', 'Según la Ley 7/1985, la potestad reglamentaria de las entidades locales en materia tributaria se ejerce a través de:', array['Reglamentos orgánicos y bandos de la Alcaldía municipal', 'Normas forales de ámbito local aprobadas por el Pleno', 'Ordenanzas fiscales y Ordenanzas generales de gestión y recaudación', 'Decretos del Pleno aprobados por mayoría absoluta']::text[], 2, 'El artículo 106.2 dispone que se ejercerá «a través de Ordenanzas fiscales reguladoras de sus tributos propios y de Ordenanzas generales de gestión, recaudación e inspección».', 2, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
