insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sfa-026', (select id from leyes where slug = 'ley-31-1990'), '103.Uno.1', 'Según la Ley 31/1990, la Agencia Estatal de Administración Tributaria se crea como:', array['Organismo autónomo con personalidad jurídica propia y capacidad solo pública', 'Sociedad mercantil estatal con capital íntegramente público', 'Ente de Derecho Público con personalidad jurídica propia y plena capacidad pública y privada', 'Órgano administrativo sin personalidad jurídica propia']::text[], 2, 'El artículo 103.Uno.1 la configura como «un Ente de Derecho Público de los previstos en el artículo 6.5 de la Ley General Presupuestaria, con personalidad jurídica propia y plena capacidad pública y privada».', 1, '2025-12-17', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
