insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sfa-027', (select id from leyes where slug = 'ley-31-1990'), '103.Uno.2', 'La AEAT es la organización administrativa responsable, en nombre y por cuenta del Estado, de:', array['La aplicación efectiva del sistema tributario estatal y del aduanero', 'La elaboración de la normativa tributaria y aduanera', 'La resolución de las reclamaciones económico-administrativas', 'La fijación de los tipos de gravamen de los tributos']::text[], 0, 'El artículo 103.Uno.2 la define como «la organización administrativa responsable, en nombre y por cuenta del Estado, de la aplicación efectiva del sistema tributario estatal y del aduanero».', 1, '2025-12-17', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
