insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sfa-028', (select id from leyes where slug = 'ley-31-1990'), '103.Uno.4', 'Cuando la AEAT gestiona tributos cedidos a las Comunidades Autónomas, la recaudación obtenida se entrega:', array['Al Tesoro Público, que la distribuye anualmente', 'A la propia Agencia como financiación adicional', 'Al Fondo de Suficiencia Global de la Comunidad', 'A la Hacienda Autónoma titular del rendimiento de los tributos cedidos']::text[], 3, 'Según el artículo 103.Uno.4, «la recaudación obtenida se entregará a la Hacienda Autónoma titular del rendimiento de los tributos cedidos».', 2, '2025-12-17', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
