insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sfa-029', (select id from leyes where slug = 'ley-31-1990'), '103.Uno.6', 'Corresponde especialmente a la AEAT el auxilio, en la investigación y represión de delitos públicos, a:', array['El Tribunal de Cuentas y el Defensor del Pueblo', 'Los Juzgados y Tribunales de Justicia y el Ministerio Fiscal', 'Las Cortes Generales y sus Comisiones de investigación', 'El Consejo de Estado y el Consejo General del Poder Judicial']::text[], 1, 'El artículo 103.Uno.6 señala que le corresponde «el auxilio a los Juzgados y Tribunales de Justicia y al Ministerio Fiscal en la investigación, enjuiciamiento y represión de delitos públicos».', 2, '2025-12-17', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
