insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sfa-030', (select id from leyes where slug = 'ley-31-1990'), '103.Dos.2', 'Según la Ley 31/1990, la contratación de la AEAT se desarrolla en régimen de:', array['Derecho Administrativo, con sujeción plena a la ley de contratos', 'Derecho Público, previa fiscalización del Tribunal de Cuentas', 'Derecho Privado', 'Derecho Laboral y de la Seguridad Social']::text[], 2, 'El artículo 103.Dos.2 prevé que la contratación se ajustará a ciertos principios, «desarrollándose en régimen de Derecho Privado».', 1, '2025-12-17', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
