insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sfa-031', (select id from leyes where slug = 'ley-31-1990'), '103.Dos.4', 'Corresponde a la AEAT la resolución de los procedimientos de:', array['Responsabilidad patrimonial por daños causados a particulares por el funcionamiento de sus servicios', 'Declaración de lesividad de actos de los Tribunales Económico-Administrativos', 'Responsabilidad disciplinaria del personal de otras Administraciones', 'Expropiación forzosa de bienes afectos a sus servicios']::text[], 0, 'El artículo 103.Dos.4 dice: «Corresponde a la Agencia la resolución de los procedimientos de responsabilidad patrimonial, derivados de reclamaciones por los daños causados a los particulares como consecuencia del funcionamiento normal o anormal de sus servicios».', 2, '2025-12-17', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
