insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sfa-032', (select id from leyes where slug = 'ley-31-1990'), '103.Tres.1', 'Según la Ley 31/1990, los órganos rectores de la AEAT son:', array['El Consejo Rector y el Director General', 'El Presidente y el Director General', 'El Presidente y el Consejo de Administración', 'El Director General y el Secretario General']::text[], 1, 'El artículo 103.Tres.1 establece: «Los Organos rectores de la Agencia serán el Presidente y el Director General».', 1, '2025-12-17', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
