insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sfa-033', (select id from leyes where slug = 'ley-31-1990'), '103.Tres.2.a', 'Corresponde al Presidente de la AEAT aprobar:', array['La contratación del personal laboral dentro de los límites de la relación de puestos', 'El presupuesto definitivo de la Agencia dentro de los Presupuestos Generales', 'Los convenios colectivos del personal laboral', 'La relación de puestos de trabajo y la oferta de empleo de la Agencia']::text[], 3, 'El artículo 103.Tres.2.a) atribuye al Presidente «Aprobar la relación de puestos de trabajo y la oferta de empleo de la Agencia, así como sus modificaciones».', 2, '2025-12-17', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'sfa-033', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 14 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sfa-034', (select id from leyes where slug = 'ley-31-1990'), '103.Tres.3', 'Según la Ley 31/1990, el Director General de la AEAT dirige:', array['La ejecución del Plan de Actuaciones y el funcionamiento ordinario de los servicios', 'La estructura orgánica y los nombramientos del personal directivo', 'La superior dirección de la Agencia y su representación legal', 'La aprobación del Plan de Actuaciones para su elevación al Ministro']::text[], 0, 'El artículo 103.Tres.3 atribuye al Director General la dirección de «el funcionamiento ordinario de los servicios y actividades de ésta», mientras que la superior dirección y la representación legal corresponden al Presidente: «ejercer la superior dirección de la misma y ostentar su representación legal».', 2, '2025-12-17', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
