insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sfa-035', (select id from leyes where slug = 'ley-31-1990'), '103.Cuatro.1', 'El personal de la AEAT queda vinculado a ella por una relación sujeta a las normas de:', array['Derecho Administrativo exclusivamente', 'Derecho Mercantil y Civil', 'Derecho Laboral exclusivamente', 'Derecho Administrativo o Laboral que le sean de aplicación']::text[], 3, 'El artículo 103.Cuatro.1 dice: «El personal de la Agencia quedará vinculado a ésta por una relación sujeta a las normas de Derecho Administrativo o Laboral que le sean de aplicación».', 1, '2025-12-17', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
