insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sfa-036', (select id from leyes where slug = 'ley-31-1990'), '103.Cuatro.8', 'La infracción de los deberes de secreto y sigilo por el personal de la AEAT constituirá, según la Ley 31/1990:', array['Infracción administrativa muy grave', 'Infracción administrativa grave', 'Falta leve, salvo reincidencia', 'Delito en todo caso']::text[], 1, 'El artículo 103.Cuatro.8 establece que «La infracción de los deberes de secreto y sigilo constituirá infracción administrativa grave, sin perjuicio de que por su naturaleza la conducta pudiera ser constitutiva de delito».', 3, '2025-12-17', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
