insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sfa-037', (select id from leyes where slug = 'ley-31-1990'), '103.Cinco.b', 'El porcentaje de recaudación que financia los mayores gastos de funcionamiento e inversiones de la AEAT se fija:', array['Cada cinco años por el Consejo de Ministros', 'Cada año por el Presidente de la Agencia', 'Cada año en la Ley anual de Presupuestos', 'Una sola vez, en la ley de creación de la Agencia']::text[], 2, 'El artículo 103.Cinco.b) establece: «El porcentaje será fijado en cada año en la Ley anual de Presupuestos».', 2, '2025-12-17', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
