insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sfa-038', (select id from leyes where slug = 'ley-31-1990'), '103.Siete.1', 'El control financiero permanente de la AEAT corresponde de forma exclusiva a:', array['La Intervención General de la Administración del Estado', 'El Tribunal de Cuentas', 'El servicio de auditoría interna de la propia Agencia', 'El Consejo de Estado']::text[], 0, 'El artículo 103.Siete.1 dispone: «La Agencia estará sometida de forma exclusiva a control financiero permanente a cargo de la Intervención General de la Administración del Estado».', 2, '2025-12-17', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
