insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sfa-039', (select id from leyes where slug = 'ley-31-1990'), '103.Ocho', 'El servicio jurídico propio de la AEAT está integrado por:', array['Letrados de las Cortes Generales', 'Letrados de la Administración de Justicia', 'Abogados colegiados contratados por concurso', 'Abogados del Estado']::text[], 3, 'El artículo 103.Ocho establece que «La Agencia dispondrá de un servicio jurídico propio, integrado por Abogados del Estado».', 1, '2025-12-17', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
