insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sfa-040', (select id from leyes where slug = 'orden-pre-3581-2007'), '1.1', 'Según la Orden PRE/3581/2007, los Departamentos de la AEAT dependen directamente de la Dirección General de la Agencia y tienen rango de:', array['Subdirección general', 'Dirección general', 'Secretaría de Estado', 'Subsecretaría']::text[], 1, 'El artículo 1.1 integra los Departamentos «con dependencia directa de la Dirección General de la Agencia, los siguientes Departamentos, todos ellos con rango de dirección general».', 2, '2026-06-26', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
