insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sfa-042', (select id from leyes where slug = 'orden-pre-3581-2007'), '10', 'En caso de vacante, ausencia o enfermedad del titular de la Dirección General de la AEAT, sus funciones las desempeñan temporalmente:', array['El titular de la Presidencia de la Agencia, con carácter automático', 'El titular del Departamento que tenga más antigüedad en el cargo', 'El Subdirector General que designe el Presidente de la Agencia', 'Los titulares de los Departamentos, por el orden del artículo 1']::text[], 3, 'El artículo 10 dispone que sus funciones «serán desempeñadas temporalmente por los titulares de los Departamentos por el orden en el que se mencionan en el artículo 1».', 3, '2026-06-26', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
