insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('age-002', (select id from leyes where slug = 'ley-40-2015'), '55 bis', 'En cada departamento ministerial, los nombramientos de Secretarías de Estado y órganos directivos respetarán que las personas de cada sexo:', array['No superen el setenta por ciento ni sean menos del treinta por ciento', 'No superen el sesenta por ciento ni sean menos del cuarenta por ciento', 'No superen el cincuenta y cinco por ciento ni sean menos del cuarenta y cinco', 'Representen exactamente el cincuenta por ciento']::text[], 1, 'El artículo 55 bis exige que «las personas de cada sexo no superen el sesenta por ciento ni sean menos del cuarenta por ciento en el ámbito de cada departamento ministerial».', 1, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
