insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('age-003', (select id from leyes where slug = 'ley-40-2015'), '55.9', 'Corresponde a los órganos superiores establecer los planes de actuación. ¿Qué corresponde a los órganos directivos?', array['Su aprobación definitiva', 'Su evaluación y control de eficacia', 'Su desarrollo y ejecución', 'Su financiación presupuestaria']::text[], 2, 'Según el artículo 55.9, «corresponde a los órganos superiores establecer los planes de actuación de la organización situada bajo su responsabilidad y a los órganos directivos su desarrollo y ejecución».', 1, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
