insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('age-005', (select id from leyes where slug = 'ley-40-2015'), '59.2', 'Los órganos de nivel inferior a Subdirección General se crean, modifican y suprimen:', array['Por Real Decreto del Consejo de Ministros', 'Por orden del Ministro respectivo', 'Por resolución del Subsecretario', 'Mediante las relaciones de puestos de trabajo']::text[], 1, 'El artículo 59.2 dispone que «los órganos de nivel inferior a Subdirección General se crean, modifican y suprimen por orden del Ministro respectivo, previa autorización del Ministro de Hacienda y Administraciones Públicas».', 2, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
