insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('age-008', (select id from leyes where slug = 'ley-40-2015'), '61.s', '¿A quién corresponde imponer la sanción de separación del servicio por faltas muy graves?', array['Al Subsecretario', 'Al Secretario de Estado', 'Al Ministro', 'Al Secretario general técnico']::text[], 2, 'Entre las funciones de los Ministros, el artículo 61.s) incluye «imponer la sanción de separación del servicio por faltas muy graves». El Subsecretario ejerce la potestad disciplinaria «salvo la separación del servicio» (artículo 63.1.ñ).', 2, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
