insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('age-012', (select id from leyes where slug = 'ley-40-2015'), '65.1', 'Los Secretarios generales técnicos tendrán, en todo caso, las competencias relativas a:', array['Gestión financiera, estadística y publicaciones', 'Producción normativa, asistencia jurídica y publicaciones', 'Recursos humanos, asistencia jurídica e inspección de servicios', 'Producción normativa, presupuestación y sistemas de información']::text[], 1, 'Según el artículo 65.1, los Secretarios generales técnicos tienen las competencias sobre servicios comunes que les atribuya el Real Decreto de estructura «y, en todo caso, las relativas a producción normativa, asistencia jurídica y publicaciones».', 2, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
