insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('age-015', (select id from leyes where slug = 'ley-40-2015'), '68.3', 'La gestión compartida de algunos de los servicios comunes de los Ministerios podrá preverse mediante:', array['Orden del Ministro del Departamento', 'Real Decreto', 'Resolución del Subsecretario', 'Instrucción de la Secretaría General Técnica']::text[], 1, 'El artículo 68.3 dispone que «mediante Real Decreto podrá preverse la gestión compartida de algunos de los servicios comunes».', 3, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
