insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('age-020', (select id from leyes where slug = 'ley-40-2015'), '73.1.b', 'El informe del Delegado del Gobierno sobre el funcionamiento de los servicios públicos estatales en el ámbito autonómico se eleva al Gobierno con carácter:', array['Semestral', 'Bienal', 'Anual', 'Trimestral']::text[], 2, 'El artículo 73.1.b).4.º atribuye al Delegado «elevar al Gobierno, con carácter anual, a través del titular del Ministerio de Hacienda y Administraciones Públicas, un informe sobre el funcionamiento de los servicios públicos estatales en el ámbito autonómico».', 2, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
