insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('at-004', (select id from leyes where slug = 'ley-39-2015'), '4.3', 'Si la condición de interesado deriva de una relación jurídica transmisible, el derecho-habiente le sucede:', array['Solo si aún no se ha iniciado la instrucción', 'Solo hasta que se abra el trámite de audiencia', 'Solo si lo autoriza el órgano instructor', 'Cualquiera que sea el estado del procedimiento']::text[], 3, 'El artículo 4.3 dice que «el derecho-habiente sucederá en tal condición cualquiera que sea el estado del procedimiento».', 3, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
