insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('at-006', (select id from leyes where slug = 'ley-39-2015'), '5.2', 'Las personas jurídicas pueden actuar en representación de otras ante las Administraciones:', array['Cuando estén inscritas en el registro de apoderamientos', 'Nunca: solo pueden representar las personas físicas', 'Siempre que ello esté previsto en sus Estatutos', 'Solo ante la Administración de su domicilio social']::text[], 2, 'El artículo 5.2 permite actuar en representación de otras a «las personas jurídicas, siempre que ello esté previsto en sus Estatutos».', 2, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
