insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('at-007', (select id from leyes where slug = 'ley-39-2015'), '5.3', 'Para los actos y gestiones de mero trámite en nombre de otra persona, la representación:', array['Debe acreditarse siempre por escrito', 'Debe acreditarse con poder notarial', 'Solo vale si consta en el registro', 'Se presume, sin tener que acreditarla']::text[], 3, 'El artículo 5.3 establece: «Para los actos y gestiones de mero trámite se presumirá aquella representación».', 1, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
