insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('at-009', (select id from leyes where slug = 'ley-39-2015'), '6.6', 'Los poderes inscritos en el registro electrónico de apoderamientos tienen una validez máxima de:', array['Dos años desde la fecha de inscripción', 'Tres años desde la fecha de inscripción', 'Cinco años desde la fecha de inscripción', 'Diez años desde la fecha de inscripción']::text[], 2, 'El artículo 6.6 dice: «Los poderes inscritos en el registro tendrán una validez determinada máxima de cinco años a contar desde la fecha de inscripción».', 2, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
