insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('at-013', (select id from leyes where slug = 'ley-39-2015'), '12.2', 'Las Administraciones asisten en el uso de medios electrónicos a:', array['Los interesados no obligados a relacionarse electrónicamente que lo soliciten', 'Solo las personas jurídicas que lo soliciten por escrito', 'Todos los interesados, aunque no lo hayan solicitado', 'Solo los interesados obligados a relacionarse electrónicamente']::text[], 0, 'El artículo 12.2 dice: «Las Administraciones Públicas asistirán en el uso de medios electrónicos a los interesados no incluidos en los apartados 2 y 3 del artículo 14 que así lo soliciten».', 3, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
