insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('at-018', (select id from leyes where slug = 'ley-39-2015'), '53.2.b', 'En un procedimiento sancionador, el presunto responsable tiene derecho:', array['A elegir al instructor del procedimiento', 'A que la sanción la confirme antes un juez', 'A la presunción de no existencia de responsabilidad', 'A que se archive si no se resuelve en un mes']::text[], 2, 'El artículo 53.2.b) reconoce el derecho «A la presunción de no existencia de responsabilidad administrativa mientras no se demuestre lo contrario».', 1, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
