insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('at-019', (select id from leyes where slug = 'ley-39-2015'), '53.1.d', 'Los interesados tienen derecho a no presentar los documentos:', array['Que ya estén en poder de las Administraciones o los hayan elaborado ellas', 'Cuyo coste de obtención supere el importe de la tasa del procedimiento', 'Que tengan una antigüedad superior a cinco años desde su expedición', 'Que no estén redactados en castellano ni en otra lengua cooficial']::text[], 0, 'El artículo 53.1.d) reconoce el derecho a no presentar datos y documentos «que ya se encuentren en poder de las Administraciones Públicas o que hayan sido elaborados por éstas».', 1, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
