insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('at-021', (select id from leyes where slug = 'ley-39-2015'), '66.3', 'De las solicitudes que presenten, los interesados pueden exigir un recibo que acredite:', array['La fecha y hora de presentación', 'El órgano que va a resolver', 'El plazo máximo para resolver', 'El número de expediente asignado']::text[], 0, 'El artículo 66.3 permite exigir «el correspondiente recibo que acredite la fecha y hora de presentación».', 1, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
