insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('at-022', (select id from leyes where slug = 'ley-39-2015'), '68.2', 'El plazo para subsanar la solicitud puede ampliarse prudencialmente hasta cinco días, salvo en los procedimientos:', array['Sancionadores o de reintegro', 'Selectivos o de concurrencia competitiva', 'De responsabilidad patrimonial', 'Iniciados de oficio por la Administración']::text[], 1, 'El artículo 68.2 dice: «Siempre que no se trate de procedimientos selectivos o de concurrencia competitiva, este plazo podrá ser ampliado prudencialmente, hasta cinco días».', 3, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
