insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('at-023', (select id from leyes where slug = 'ley-39-2015'), '68.4', 'Si un obligado a relacionarse electrónicamente presenta su solicitud en papel y luego la subsana, se toma como fecha de presentación:', array['La de la presentación presencial', 'La del requerimiento de subsanación', 'La de la subsanación electrónica', 'La de su llegada al órgano competente']::text[], 2, 'El artículo 68.4 dice: «se considerará como fecha de presentación de la solicitud aquella en la que haya sido realizada la subsanación».', 3, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
