insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('der-001', (select id from leyes where slug = 'constitucion'), '10.2', 'Las normas relativas a los derechos fundamentales que la Constitución reconoce se interpretarán de conformidad con:', array['La Declaración Universal de Derechos Humanos y los tratados ratificados por España', 'La jurisprudencia del Tribunal Supremo y las leyes orgánicas que las desarrollen', 'El Convenio Europeo de Derechos Humanos exclusivamente', 'Los principios generales del Derecho y la costumbre internacional']::text[], 0, 'El artículo 10.2 dispone que esas normas «se interpretarán de conformidad con la Declaración Universal de Derechos Humanos y los tratados y acuerdos internacionales sobre las mismas materias ratificados por España».', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
