insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('der-003', (select id from leyes where slug = 'constitucion'), '11.3', 'El Estado podrá concertar tratados de doble nacionalidad con:', array['Los Estados miembros de la Unión Europea y Andorra', 'Los países iberoamericanos o con particular vinculación con España', 'Cualquier país que reconozca un derecho recíproco', 'Solo los países de lengua oficial española']::text[], 1, 'Según el artículo 11.3, «El Estado podrá concertar tratados de doble nacionalidad con los países iberoamericanos o con aquellos que hayan tenido o tengan una particular vinculación con España.»', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
