insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('der-008', (select id from leyes where slug = 'constitucion'), '18.2', 'Sin consentimiento del titular ni resolución judicial, solo puede entrarse en un domicilio:', array['Por orden de la autoridad gubernativa', 'En caso de flagrante delito', 'Cuando lo acuerde el Ministerio Fiscal', 'Durante la vigencia del estado de alarma']::text[], 1, 'El artículo 18.2 dispone: «Ninguna entrada o registro podrá hacerse en él sin consentimiento del titular o resolución judicial, salvo en caso de flagrante delito.»', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
