insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('der-027', (select id from leyes where slug = 'constitucion'), '50', 'Durante la tercera edad, los poderes públicos garantizarán la suficiencia económica de los ciudadanos mediante:', array['Un sistema de ahorro privado obligatorio', 'Prestaciones asistenciales de las familias', 'Pensiones adecuadas y periódicamente actualizadas', 'Pensiones mínimas fijadas cada cinco años']::text[], 2, 'El artículo 50 dispone que los poderes públicos garantizarán, «mediante pensiones adecuadas y periódicamente actualizadas, la suficiencia económica a los ciudadanos durante la tercera edad».', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
