insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('der-029', (select id from leyes where slug = 'constitucion'), '53.3', 'Los principios rectores del Capítulo tercero del Título I:', array['Solo podrán alegarse ante la Jurisdicción ordinaria según las leyes que los desarrollen', 'Pueden alegarse directamente en recurso de amparo', 'Se tutelan por un procedimiento de preferencia y sumariedad', 'No vinculan a los poderes públicos']::text[], 0, 'El artículo 53.3 dispone que los principios del Capítulo tercero «Sólo podrán ser alegados ante la Jurisdicción ordinaria de acuerdo con lo que dispongan las leyes que los desarrollen».', 3, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
