insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('der-030', (select id from leyes where slug = 'constitucion'), '55.1', '¿Qué apartado del artículo 17 no puede suspenderse cuando se declara el estado de excepción?', array['El apartado 1', 'El apartado 2', 'El apartado 4', 'El apartado 3']::text[], 3, 'El artículo 55.1 señala: «Se exceptúa de lo establecido anteriormente el apartado 3 del artículo 17 para el supuesto de declaración de estado de excepción.»', 3, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
