insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dlg-001', (select id from leyes where slug = 'ley-39-2006'), '1.1', 'Según la Ley 39/2006, la promoción de la autonomía personal y la atención a las personas en situación de dependencia es un derecho:', array['Graciable y de carácter asistencial', 'Derivado de la cotización a la Seguridad Social', 'Subjetivo de ciudadanía', 'De configuración exclusivamente autonómica']::text[], 2, 'El artículo 1.1 se refiere a la igualdad «en el ejercicio del derecho subjetivo de ciudadanía a la promoción de la autonomía personal y atención a las personas en situación de dependencia».', 1, '2026-10-06', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
