insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dlg-002', (select id from leyes where slug = 'ley-39-2006'), '2.1', 'La capacidad de controlar, afrontar y tomar, por propia iniciativa, decisiones personales acerca de cómo vivir es, según la Ley 39/2006:', array['La autonomía', 'La vida independiente', 'El proyecto de vida', 'La asistencia personal']::text[], 0, 'El artículo 2.1 define la autonomía como «la capacidad de controlar, afrontar y tomar, por propia iniciativa, decisiones personales acerca de cómo vivir de acuerdo con las normas y preferencias propias».', 1, '2026-10-06', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
