insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dlg-003', (select id from leyes where slug = 'ley-39-2006'), '2.2', 'La Ley 39/2006 define la situación de dependencia como un estado de carácter:', array['Temporal', 'Transitorio y revisable', 'Ocasional', 'Permanente']::text[], 3, 'El artículo 2.2 define la situación de dependencia como «el estado de carácter permanente en el que las personas, debido a dificultades que afectan a su autonomía, precisan de cuidados y apoyos de otra u otras personas».', 1, '2026-10-06', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
