insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dlg-004', (select id from leyes where slug = 'ley-39-2006'), '2.5', 'La atención prestada en su domicilio a una persona en situación de dependencia por familiares no vinculados a un servicio profesionalizado se denomina:', array['Asistencia personal', 'Cuidados no profesionales', 'Cuidados profesionales', 'Prestaciones de base comunitaria']::text[], 1, 'El artículo 2.5 define los cuidados no profesionales como «la atención prestada a personas en situación de dependencia en su domicilio, por personas de la familia o de su entorno, no vinculadas a un servicio de atención profesionalizada».', 1, '2026-10-06', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
