insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dlg-005', (select id from leyes where slug = 'ley-39-2006'), '3.r', 'Entre los principios de la Ley 39/2006, ¿qué personas serán atendidas de manera preferente?', array['Las menores de seis años', 'Las que están en situación de gran dependencia', 'Las que viven solas en su domicilio', 'Las que carecen de cuidados no profesionales']::text[], 1, 'El artículo 3.r) establece que «Las personas en situación de gran dependencia serán atendidas de manera preferente».', 2, '2026-10-06', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
