insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dlg-006', (select id from leyes where slug = 'ley-39-2006'), '5.1.c', 'Para ser titular de los derechos de la Ley 39/2006 hay que haber residido en territorio español durante:', array['Dos años, inmediatamente anteriores a la solicitud', 'Cinco años, uno de ellos inmediatamente anterior a la solicitud', 'Diez años, dos de ellos inmediatamente anteriores a la solicitud', 'Cinco años, dos de ellos inmediatamente anteriores a la solicitud']::text[], 3, 'El artículo 5.1.c) exige «Residir en territorio español y haberlo hecho durante cinco años, de los cuales dos deberán ser inmediatamente anteriores a la fecha de presentación de la solicitud».', 2, '2026-10-06', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
