insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dlg-007', (select id from leyes where slug = 'ley-39-2006'), '6.2', 'El Sistema para la Autonomía y Atención a la Dependencia se configura como:', array['Una red de utilización pública que integra centros y servicios públicos y privados', 'Un organismo autónomo adscrito a la Administración General del Estado', 'Una red formada solo por centros públicos de las comunidades autónomas', 'Una entidad gestora de la Seguridad Social']::text[], 0, 'El artículo 6.2 dice: «El Sistema se configura como una red de utilización pública que integra, de forma coordinada, centros y servicios, públicos y privados».', 2, '2026-10-06', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
