insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dlg-008', (select id from leyes where slug = 'ley-39-2006'), '7', '¿Quién establece el nivel de protección mínimo del Sistema para la Autonomía y Atención a la Dependencia?', array['Cada comunidad autónoma', 'El Consejo Territorial, por mayoría', 'La Administración General del Estado', 'Las entidades locales']::text[], 2, 'El artículo 7 recoge como primer nivel «El nivel de protección mínimo establecido por la Administración General del Estado».', 2, '2026-10-06', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
