insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dlg-009', (select id from leyes where slug = 'ley-39-2006'), '8.1', 'En la composición del Consejo Territorial de Servicios Sociales y del Sistema para la Autonomía y Atención a la Dependencia tienen mayoría:', array['Los representantes de la Administración General del Estado', 'Los representantes de las entidades locales', 'Las organizaciones sindicales y empresariales', 'Los representantes de las comunidades autónomas']::text[], 3, 'El artículo 8.1 dispone: «En la composición del Consejo Territorial tendrán mayoría los representantes de las comunidades autónomas».', 3, '2026-10-06', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
