insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dlg-010', (select id from leyes where slug = 'ley-39-2006'), '14.4', 'Según la Ley 39/2006, a igual grado de dependencia, la prioridad en el acceso a los servicios se determina por:', array['La capacidad económica de la persona solicitante', 'El tiempo de espera transcurrido desde la solicitud', 'La edad de la persona solicitante', 'La falta de cuidados en el entorno familiar']::text[], 1, 'El artículo 14.4 dice que la prioridad «vendrá determinada por el grado de dependencia y, a igual grado, por el tiempo de espera transcurrido, desde la fecha de solicitud». La capacidad económica solo opera «a igual grado y tiempo de espera».', 3, '2026-10-06', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
