insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dlg-011', (select id from leyes where slug = 'ley-39-2006'), '15.1.c', '¿Cuál de estos servicios forma parte del Catálogo de servicios de la Ley 39/2006?', array['El servicio de teleasistencia', 'El servicio de transporte adaptado', 'El servicio de orientación jurídica gratuita', 'El servicio de comedor social']::text[], 0, 'El artículo 15.1 incluye en el Catálogo, entre otros, el «Servicio de teleasistencia».', 1, '2026-10-06', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
