insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dlg-012', (select id from leyes where slug = 'ley-39-2006'), '20', 'La cuantía de las prestaciones económicas de la Ley 39/2006 se acuerda por el Consejo Territorial y se aprueba después:', array['Por cada comunidad autónoma mediante ley', 'Por las Cortes Generales en la Ley de Presupuestos', 'Por el Gobierno mediante real decreto', 'Por orden de la persona titular del Ministerio competente']::text[], 2, 'El artículo 20 dispone que la cuantía «se acordará por el Consejo Territorial del Sistema para la Autonomía y Atención a la Dependencia, para su aprobación posterior por el Gobierno mediante Real Decreto».', 2, '2026-10-06', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
