insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dlg-013', (select id from leyes where slug = 'ley-39-2006'), '26.1.b', 'Si una persona necesita ayuda para varias actividades de la vida diaria dos o tres veces al día, sin requerir el apoyo permanente de una persona cuidadora, tiene:', array['Grado I. Dependencia moderada', 'Grado III. Gran dependencia', 'Grado II. Dependencia severa', 'Grado II. Dependencia moderada']::text[], 2, 'El artículo 26.1.b) define el «Grado II. Dependencia severa: cuando la persona necesita ayuda para realizar varias actividades de la vida diaria dos o tres veces al día, pero no requiere el apoyo permanente de una persona cuidadora».', 2, '2026-10-06', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
