insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dlg-014', (select id from leyes where slug = 'ley-39-2006'), '28.1', '¿Cuál es el plazo máximo para resolver el procedimiento de reconocimiento de la situación de dependencia?', array['Tres meses', 'Seis meses', 'Un mes', 'Dos meses']::text[], 0, 'El artículo 28.1 establece que el procedimiento se inicia a instancia de la persona interesada o de su representante, «estableciéndose un plazo máximo de 3 meses para su resolución».', 2, '2026-10-06', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
