insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dlg-015', (select id from leyes where slug = 'ley-39-2006'), '29.1', 'Según la Ley 39/2006, el Programa Individual de Atención lo establecen:', array['Los órganos de valoración, en el mismo dictamen que fija el grado', 'Los servicios sociales del sistema público, de acuerdo con la persona y a propuesta de esta', 'El Consejo Territorial, a propuesta de la comunidad autónoma', 'La persona cuidadora principal, con el visto bueno de los servicios sociales']::text[], 1, 'El artículo 29.1 dice que «los servicios sociales competentes del sistema público de acuerdo con la persona en situación de dependencia y, a propuesta de esta, establecerán un Programa Individual de Atención».', 3, '2026-10-06', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
