insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dlg-016', (select id from leyes where slug = 'ley-4-2023'), '1.1', 'La Ley 4/2023 tiene por finalidad garantizar y promover el derecho a la igualdad real y efectiva de las personas LGTBI y:', array['De las asociaciones que las representan', 'De las personas con discapacidad', 'De las personas menores de edad tuteladas', 'De sus familias']::text[], 3, 'El artículo 1.1 fija como finalidad «garantizar y promover el derecho a la igualdad real y efectiva de las personas lesbianas, gais, trans, bisexuales e intersexuales (en adelante, LGTBI), así como de sus familias».', 1, '2025-12-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
