insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dlg-017', (select id from leyes where slug = 'ley-4-2023'), '2', 'La Ley 4/2023 se aplica a toda persona física o jurídica, pública o privada, que:', array['Tenga nacionalidad española', 'Resida, se encuentre o actúe en territorio español', 'Resida legalmente en España desde hace al menos un año', 'Esté inscrita en el Registro Civil español']::text[], 1, 'El artículo 2 dispone que la ley se aplica a toda persona física o jurídica «que resida, se encuentre o actúe en territorio español, cualquiera que fuera su nacionalidad».', 1, '2025-12-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
