insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dlg-018', (select id from leyes where slug = 'ley-4-2023'), '3.i', 'La vivencia interna e individual del sexo tal y como cada persona la siente y autodefine es, según la Ley 4/2023:', array['La expresión de género', 'La orientación sexual', 'La intersexualidad', 'La identidad sexual']::text[], 3, 'El artículo 3.i) define la identidad sexual como la «Vivencia interna e individual del sexo tal y como cada persona la siente y autodefine, pudiendo o no corresponder con el sexo asignado al nacer».', 1, '2025-12-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
