insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dlg-019', (select id from leyes where slug = 'ley-4-2023'), '3.e', 'La discriminación que se funda en una apreciación incorrecta sobre las características de la persona discriminada es la discriminación:', array['Por error', 'Por asociación', 'Indirecta', 'Interseccional']::text[], 0, 'El artículo 3.e) dice: «La discriminación por error es aquella que se funda en una apreciación incorrecta acerca de las características de la persona o personas discriminadas».', 2, '2025-12-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
