insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dlg-020', (select id from leyes where slug = 'ley-4-2023'), '3.c', 'Cuando concurren o interactúan diversas causas de discriminación generando una forma específica de discriminación, la Ley 4/2023 habla de discriminación:', array['Múltiple', 'Por asociación', 'Interseccional', 'Directa']::text[], 2, 'El artículo 3.c) dispone: «Se produce discriminación interseccional cuando concurren o interactúan diversas causas comprendidas en el apartado anterior, generando una forma específica de discriminación».', 3, '2025-12-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
