insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dlg-021', (select id from leyes where slug = 'ley-4-2023'), '5.2', 'Según el artículo 5 de la Ley 4/2023, los poderes públicos fomentarán:', array['El reconocimiento institucional y la participación en los actos conmemorativos', 'La creación de un registro estatal de personas LGTBI', 'La reserva de plazas para personas LGTBI en el empleo público', 'La exención de tasas en los procedimientos registrales']::text[], 0, 'El artículo 5.2 dice: «Los poderes públicos fomentarán el reconocimiento institucional y la participación en los actos conmemorativos de la lucha por la igualdad real y efectiva de las personas LGTBI».', 2, '2025-12-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
