insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dlg-022', (select id from leyes where slug = 'ley-4-2023'), '11', 'Las medidas de igualdad de las personas LGTBI en el acceso al empleo público y la carrera profesional se implantan:', array['Previo informe del Consejo de Participación de las Personas LGTBI', 'Previo dictamen del Consejo de Estado', 'Previa negociación con las organizaciones sindicales', 'Mediante acuerdo del Consejo de Ministros']::text[], 2, 'El artículo 11 dice que las Administraciones públicas «implantarán medidas para la promoción y defensa de la igualdad de trato y no discriminación de las personas LGTBI en el acceso al empleo público y carrera profesional, previa negociación con las organizaciones sindicales».', 2, '2025-12-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
