insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dlg-023', (select id from leyes where slug = 'ley-4-2023'), '12.2', 'Según la Ley 4/2023, en los programas de las pruebas selectivas de acceso al empleo público se incluirán:', array['Una entrevista personal sobre diversidad familiar', 'Conocimientos sobre igualdad de trato y no discriminación de las personas LGTBI', 'Un cupo de plazas reservado a personas trans', 'Una prueba práctica de atención a víctimas de discriminación']::text[], 1, 'El artículo 12.2 dispone que las Administraciones públicas «incluirán en los programas de las pruebas selectivas de acceso al empleo público formación y conocimientos sobre igualdad de trato y no discriminación de las personas LGTBI».', 1, '2025-12-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
