insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dlg-024', (select id from leyes where slug = 'ley-4-2023'), '43.1', '¿Desde qué edad puede una persona de nacionalidad española solicitar por sí misma la rectificación de la mención registral relativa al sexo?', array['Desde que es mayor de dieciocho años', 'Desde que es mayor de catorce años', 'Desde que es mayor de doce años', 'Desde que es mayor de dieciséis años']::text[], 3, 'El artículo 43.1 dice: «Toda persona de nacionalidad española mayor de dieciséis años podrá solicitar por sí misma ante el Registro Civil la rectificación de la mención registral relativa al sexo».', 1, '2025-12-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
