insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dlg-025', (select id from leyes where slug = 'ley-4-2023'), '43.2', 'Las personas menores de dieciséis años y mayores de catorce pueden solicitar la rectificación registral de la mención relativa al sexo:', array['Solo a través de sus representantes legales', 'Solo con autorización judicial previa', 'Por sí mismas, sin necesidad de asistencia', 'Por sí mismas, asistidas por sus representantes legales']::text[], 3, 'El artículo 43.2 dispone que estas personas «podrán presentar la solicitud por sí mismas, asistidas en el procedimiento por sus representantes legales».', 2, '2025-12-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
