insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dlg-026', (select id from leyes where slug = 'ley-4-2023'), '43.4', 'Para modificar la mención registral del sexo, las personas menores de catorce años y mayores de doce pueden:', array['Presentar la solicitud por sí mismas ante el Registro Civil', 'Solicitar la autorización judicial', 'Presentarla asistidas por sus representantes legales', 'Pedirla a través del Ministerio Fiscal']::text[], 1, 'El artículo 43.4 dice que estas personas «podrán solicitar la autorización judicial para la modificación de la mención registral del sexo en los términos del capítulo I bis del título II de la Ley 15/2015».', 3, '2025-12-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
