insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dlg-027', (select id from leyes where slug = 'ley-4-2023'), '44.3', 'Según la Ley 4/2023, el derecho a la rectificación registral de la mención relativa al sexo:', array['Exige un informe médico que acredite la disconformidad con el sexo registrado', 'Exige acreditar un tratamiento médico previo de al menos dos años', 'No puede condicionarse a la previa exhibición de un informe médico o psicológico', 'Requiere un informe psicológico emitido por un servicio público de salud']::text[], 2, 'El artículo 44.3 establece que este derecho «en ningún caso podrá estar condicionado a la previa exhibición de informe médico o psicológico relativo a la disconformidad con el sexo mencionado en la inscripción de nacimiento».', 1, '2025-12-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
