insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dlg-029', (select id from leyes where slug = 'ley-4-2023'), '46.1', 'La resolución que acuerda la rectificación de la mención registral del sexo tiene efectos:', array['Declarativos desde la fecha de la solicitud', 'Constitutivos a partir de su inscripción en el Registro Civil', 'Retroactivos desde la fecha de nacimiento', 'Constitutivos desde la segunda comparecencia']::text[], 1, 'El artículo 46.1 dispone que la resolución «tendrá efectos constitutivos a partir de su inscripción en el Registro Civil».', 2, '2025-12-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
