insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dlg-030', (select id from leyes where slug = 'ley-4-2023'), '79.4.d', 'Según la Ley 4/2023, la promoción o la práctica de terapias de conversión de la orientación sexual o la identidad sexual es una infracción:', array['Muy grave', 'Grave', 'Leve', 'Grave o leve, según haya consentimiento']::text[], 0, 'El artículo 79.4 califica como infracción muy grave «La promoción o la práctica de métodos, programas o terapias de aversión, conversión o contracondicionamiento […] con independencia del consentimiento que pudieran haber prestado las mismas o sus representantes legales».', 1, '2025-12-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
