insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dag-001', (select id from leyes where slug = 'constitucion'), '82.2', 'La delegación legislativa en el Gobierno para formar textos articulados debe otorgarse mediante:', array['Una ley ordinaria', 'Una ley de bases', 'Una ley orgánica', 'Una resolución del Congreso']::text[], 1, 'El artículo 82.2 de la Constitución dispone que la delegación legislativa «deberá otorgarse mediante una ley de bases cuando su objeto sea la formación de textos articulados o por una ley ordinaria cuando se trate de refundir varios textos legales en uno solo».', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
