insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dag-002', (select id from leyes where slug = 'constitucion'), '82.3', 'Según el artículo 82.3 de la Constitución, la delegación legislativa se agota:', array['Al cumplirse un año desde la aprobación de la ley de delegación', 'Cuando el Congreso convalida el texto aprobado por el Gobierno', 'Por su uso por el Gobierno mediante la publicación de la norma', 'Con la aprobación del texto en el Consejo de Ministros']::text[], 2, 'El artículo 82.3 de la Constitución establece: «La delegación se agota por el uso que de ella haga el Gobierno mediante la publicación de la norma correspondiente».', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
