insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dag-003', (select id from leyes where slug = 'constitucion'), '83.b', 'Según la Constitución, las leyes de bases no podrán en ningún caso:', array['Fijar el plazo para el ejercicio de la delegación', 'Facultar para dictar normas con carácter retroactivo', 'Establecer fórmulas adicionales de control', 'Fijar los principios y criterios de la delegación']::text[], 1, 'El artículo 83 dispone: «Las leyes de bases no podrán en ningún caso» […] «Facultar para dictar normas con carácter retroactivo».', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
