insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dag-005', (select id from leyes where slug = 'constitucion'), '86.3', 'Durante el plazo de convalidación, las Cortes pueden tramitar los decretos-leyes como proyectos de ley por el procedimiento:', array['Ordinario', 'De lectura única', 'Especial y sumario', 'De urgencia']::text[], 3, 'El artículo 86.3 de la Constitución establece que durante ese plazo «las Cortes podrán tramitarlos como proyectos de ley por el procedimiento de urgencia».', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
