insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dag-007', (select id from leyes where slug = 'ley-50-1997'), '26.2', 'En la consulta pública previa a la elaboración de una norma del Gobierno, el tiempo para opinar no será inferior a:', array['Quince días hábiles', 'Quince días naturales', 'Diez días hábiles', 'Siete días hábiles']::text[], 1, 'El artículo 26.2 de la Ley 50/1997 exige que se proporcione «un tiempo suficiente, que en ningún caso será inferior a quince días naturales».', 3, '2025-04-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
