insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dag-009', (select id from leyes where slug = 'ley-39-2015'), '129.1', '¿Cuál de los siguientes NO es un principio de buena regulación según la Ley 39/2015?', array['Proporcionalidad', 'Seguridad jurídica', 'Eficiencia', 'Descentralización']::text[], 3, 'Según el artículo 129.1, las Administraciones Públicas «actuarán de acuerdo con los principios de necesidad, eficacia, proporcionalidad, seguridad jurídica, transparencia, y eficiencia».', 1, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
