insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dag-010', (select id from leyes where slug = 'ley-39-2015'), '131', 'Para que las normas con rango de ley y los reglamentos entren en vigor y produzcan efectos jurídicos, deben:', array['Publicarse en la sede electrónica del órgano autor', 'Notificarse a los interesados conocidos', 'Comunicarse a las Cortes Generales', 'Publicarse en el diario oficial correspondiente']::text[], 3, 'El artículo 131 de la Ley 39/2015 dispone que las normas con rango de ley, los reglamentos y disposiciones administrativas «habrán de publicarse en el diario oficial correspondiente para que entren en vigor y produzcan efectos jurídicos».', 1, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
