insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dag-011', (select id from leyes where slug = 'ley-39-2015'), '35.1.c', 'Deben motivarse, con sucinta referencia de hechos y fundamentos de derecho:', array['Los actos que se separen del dictamen de órganos consultivos', 'Los actos que sigan el criterio de actuaciones precedentes', 'Los actos que acuerden la tramitación ordinaria', 'Los actos que admitan las pruebas propuestas']::text[], 0, 'El artículo 35.1.c) incluye entre los actos que serán motivados «Los actos que se separen del criterio seguido en actuaciones precedentes o del dictamen de órganos consultivos».', 2, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
