insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dag-012', (select id from leyes where slug = 'ley-39-2015'), '36.1', 'Salvo que su naturaleza exija otra forma, los actos administrativos se producirán:', array['Por escrito en soporte papel', 'De forma verbal, con constancia escrita', 'Por escrito a través de medios electrónicos', 'En la forma que elija el interesado']::text[], 2, 'El artículo 36.1 dispone: «Los actos administrativos se producirán por escrito a través de medios electrónicos, a menos que su naturaleza exija otra forma más adecuada de expresión y constancia».', 1, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
