insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'dag-012', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 9 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dag-013', (select id from leyes where slug = 'ley-39-2015'), '37.1', 'Una resolución administrativa de carácter particular no puede vulnerar una disposición de carácter general:', array['Salvo que proceda de un órgano de superior jerarquía', 'Salvo que la dicte el órgano que aprobó la disposición', 'Salvo que se motive en razones de interés público', 'Aunque proceda de un órgano de igual o superior jerarquía']::text[], 3, 'El artículo 37.1 establece que las resoluciones de carácter particular no podrán vulnerar lo establecido en una disposición de carácter general, «aunque aquéllas procedan de un órgano de igual o superior jerarquía al que dictó la disposición general».', 2, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
