insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'dag-014', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 9 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dag-015', (select id from leyes where slug = 'ley-39-2015'), '39.5', 'Si una Administración requiere a otra para que anule un acto ilegal en el que debe basarse el suyo, el procedimiento para dictar resolución:', array['Continúa su tramitación', 'Se archiva por caducidad', 'Queda suspendido', 'Se declara concluso']::text[], 2, 'El artículo 39.5 prevé que la Administración podrá requerir previamente a la otra para que anule o revise el acto y añade: «En estos casos, quedará suspendido el procedimiento para dictar resolución».', 3, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
