insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dag-017', (select id from leyes where slug = 'ley-39-2015'), '47.1.b', 'Es nulo de pleno derecho el acto dictado por un órgano manifiestamente incompetente por razón de:', array['La jerarquía o la cuantía', 'La materia o la jerarquía', 'La materia o el territorio', 'El territorio o el tiempo']::text[], 2, 'El artículo 47.1.b) declara nulos de pleno derecho «Los dictados por órgano manifiestamente incompetente por razón de la materia o del territorio».', 1, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
