insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dag-019', (select id from leyes where slug = 'ley-39-2015'), '50', 'Los actos nulos o anulables que contengan los elementos constitutivos de otro distinto:', array['Deberán revisarse de oficio', 'Producirán los efectos de este', 'Carecerán de todo efecto', 'Solo surtirán efecto si se convalidan']::text[], 1, 'El artículo 50 establece: «Los actos nulos o anulables que, sin embargo, contengan los elementos constitutivos de otro distinto producirán los efectos de éste».', 1, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
