insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dag-021', (select id from leyes where slug = 'ley-40-2015'), '25.1', 'La potestad sancionadora de las Administraciones se ejerce cuando ha sido expresamente reconocida por:', array['Una norma con rango de Ley', 'Un reglamento del Gobierno', 'Una orden ministerial', 'Una ley o un reglamento']::text[], 0, 'El artículo 25.1 de la Ley 40/2015 dispone que la potestad sancionadora «se ejercerá cuando haya sido expresamente reconocida por una norma con rango de Ley».', 1, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
