insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dag-022', (select id from leyes where slug = 'ley-40-2015'), '25.4', 'Las normas de la Ley 40/2015 sobre potestad sancionadora NO se aplican a quienes se vinculan a la Administración por relaciones reguladas por:', array['El régimen jurídico de los funcionarios', 'La legislación laboral de su personal', 'Las ordenanzas municipales', 'La legislación de contratos del sector público']::text[], 3, 'El artículo 25.4 excluye la potestad sancionadora «respecto de quienes estén vinculados a ellas por relaciones reguladas por la legislación de contratos del sector público o por la legislación patrimonial de las Administraciones Públicas».', 3, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
