insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dag-024', (select id from leyes where slug = 'ley-40-2015'), '27.4', 'Según la Ley 40/2015, las normas definidoras de infracciones y sanciones:', array['Admiten la analogía si favorece al interesado', 'Pueden crearse por norma reglamentaria', 'Admiten la analogía en el ámbito local', 'No son susceptibles de aplicación analógica']::text[], 3, 'El artículo 27.4 establece: «Las normas definidoras de infracciones y sanciones no serán susceptibles de aplicación analógica».', 1, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'dag-024', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 20 where o.slug = 'admin-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('dag-025', (select id from leyes where slug = 'ley-40-2015'), '30.2', 'La prescripción de la infracción se reinicia si el expediente sancionador está paralizado, por causa no imputable al presunto responsable, más de:', array['Un mes', 'Dos meses', 'Tres meses', 'Seis meses']::text[], 0, 'El artículo 30.2 dispone que se reinicia el plazo de prescripción «si el expediente sancionador estuviera paralizado durante más de un mes por causa no imputable al presunto responsable».', 2, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
