insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('hac-003', (select id from leyes where slug = 'constitucion'), '134.2', 'Los Presupuestos Generales del Estado tendrán carácter:', array['Bienal', 'Plurianual, por legislatura', 'Anual', 'Semestral']::text[], 2, 'El artículo 134.2 establece que «Los Presupuestos Generales del Estado tendrán carácter anual».', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
