insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('hac-004', (select id from leyes where slug = 'constitucion'), '134.2', 'Además de la totalidad de los gastos e ingresos del sector público estatal, en los Presupuestos Generales del Estado se consignará:', array['El volumen máximo de deuda pública de las Comunidades Autónomas', 'El informe anual del Tribunal de Cuentas sobre el ejercicio anterior', 'El déficit estructural máximo de las Entidades Locales', 'El importe de los beneficios fiscales que afecten a los tributos del Estado']::text[], 3, 'El artículo 134.2 dice que los Presupuestos incluirán la totalidad de los gastos e ingresos del sector público estatal «y en ellos se consignará el importe de los beneficios fiscales que afecten a los tributos del Estado».', 3, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
