insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('hac-009', (select id from leyes where slug = 'constitucion'), '134.6', 'Toda proposición o enmienda que suponga aumento de los créditos o disminución de los ingresos presupuestarios requiere para su tramitación:', array['La mayoría absoluta del Congreso', 'El informe del Tribunal de Cuentas', 'La conformidad del Senado', 'La conformidad del Gobierno']::text[], 3, 'El artículo 134.6 establece que toda proposición o enmienda de ese tipo «requerirá la conformidad del Gobierno para su tramitación».', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
