insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('xls-014', null, 'Sintaxis', 'En BUSCARX, ¿qué hace el valor -1 en el argumento modo_de_búsqueda?', array['Busca empezando por el primer elemento', 'Busca de forma inversa empezando por el último elemento', 'Hace una búsqueda binaria en orden descendente', 'Devuelve el siguiente elemento más pequeño']::text[], 1, 'Para modo_de_búsqueda la página indica: «-1: realizar una búsqueda inversa empezando por el último elemento». El valor 1, predeterminado, empieza por el primer elemento.', 3, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
