insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('xls-017', null, 'Procedimientos recomendados para usar CONTAR.SI en Excel', '¿La fórmula =CONTAR.SI(A2:A5;"manzanas") cuenta también las celdas que contienen MANZANAS?', array['No, porque los criterios distinguen mayúsculas', 'Solo si se activa Distinguir mayúsculas', 'Solo si el criterio se escribe sin comillas', 'Sí, porque los criterios no distinguen mayúsculas']::text[], 3, 'La página indica: «Los criterios no distinguen mayúsculas de minúsculas. En otras palabras, la cadena "manzanas" y la cadena "MANZANAS" coinciden con las mismas celdas».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
