insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('xls-018', null, 'Procedimientos recomendados para usar CONTAR.SI en Excel', 'En los criterios de CONTAR.SI, ¿qué hace el signo de interrogación (?)?', array['Reemplaza cualquier carácter individual', 'Reemplaza cualquier secuencia de caracteres', 'Indica que el carácter siguiente es literal', 'Cuenta solo las celdas que están en blanco']::text[], 0, 'Según la página: «El signo de interrogación reemplaza cualquier carácter individual. El asterisco reemplaza cualquier secuencia de caracteres».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
