insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('xls-020', null, 'Inmovilizar filas o columnas', 'Para inmovilizar las dos primeras columnas, antes de elegir Inmovilizar paneles hay que seleccionar:', array['La segunda columna', 'La primera columna', 'La celda A1', 'La tercera columna']::text[], 3, 'La página explica que «Inmovilizar paneles inmoviliza las filas superiores y las columnas a la izquierda de la celda seleccionada». Para las dos primeras columnas: «Seleccione la tercera columna».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
