insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('fps-001', (select id from leyes where slug = 'trebep'), '70.1', 'La Oferta de empleo público comporta la obligación de convocar los procesos selectivos para las plazas comprometidas y hasta:', array['Un cinco por cien adicional', 'Un diez por cien adicional', 'Un quince por cien adicional', 'Un veinte por cien adicional']::text[], 1, 'El artículo 70.1 del TREBEP establece «la obligación de convocar los correspondientes procesos selectivos para las plazas comprometidas y hasta un diez por cien adicional».', 2, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
