insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('fps-002', (select id from leyes where slug = 'trebep'), '70.1', 'La ejecución de la Oferta de empleo público deberá desarrollarse dentro del plazo improrrogable de:', array['Dos años', 'Un año', 'Cuatro años', 'Tres años']::text[], 3, 'El artículo 70.1 del TREBEP dispone que «la ejecución de la oferta de empleo público o instrumento similar deberá desarrollarse dentro del plazo improrrogable de tres años».', 1, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
