insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('fps-004', (select id from leyes where slug = 'rd-364-1995'), '11', 'Los Tribunales de selección están constituidos por un número impar de miembros, funcionarios de carrera:', array['No inferior a tres', 'No inferior a nueve', 'No inferior a cinco', 'No inferior a siete']::text[], 2, 'El artículo 11 establece que los Tribunales «estarán constituidos por un número impar de miembros, funcionarios de carrera, no inferior a cinco».', 1, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
