insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('fps-005', (select id from leyes where slug = 'rd-364-1995'), '13.2', 'No pueden formar parte de los órganos de selección los funcionarios que hayan preparado aspirantes a pruebas selectivas en los:', array['Dos años anteriores a la publicación de la convocatoria', 'Tres años anteriores a la publicación de la convocatoria', 'Cinco años anteriores a la publicación de la convocatoria', 'Cuatro años anteriores a la publicación de la convocatoria']::text[], 2, 'El artículo 13.2 excluye a quienes «hubiesen realizado tareas de preparación de aspirantes a pruebas selectivas en los cinco años anteriores a la publicación de la correspondiente convocatoria».', 2, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
