insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('fps-006', (select id from leyes where slug = 'rd-364-1995'), '16.j', 'Desde la total conclusión de un ejercicio hasta el comienzo del siguiente debe transcurrir un plazo:', array['Mínimo de setenta y dos horas y máximo de cuarenta y cinco días naturales', 'Mínimo de cuarenta y ocho horas y máximo de treinta días naturales', 'Mínimo de veinticuatro horas y máximo de cuarenta y cinco días hábiles', 'Mínimo de setenta y dos horas y máximo de dos meses']::text[], 0, 'El artículo 16.j) dispone: «Desde la total conclusión de un ejercicio o prueba hasta el comienzo del siguiente deberá transcurrir un plazo mínimo de setenta y dos horas y máximo de cuarenta y cinco días naturales».', 3, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
