insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('fps-007', (select id from leyes where slug = 'rd-364-1995'), '18.1', 'La solicitud para participar en los procedimientos de ingreso se presenta, desde el día siguiente al de publicación de la convocatoria en el BOE, en el plazo de:', array['Quince días hábiles', 'Diez días hábiles', 'Treinta días naturales', 'Veinte días naturales']::text[], 3, 'Según el artículo 18.1, la solicitud «deberá presentarse en el plazo de veinte días naturales a partir del siguiente al de publicación de la convocatoria respectiva».', 1, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
