insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('fps-008', (select id from leyes where slug = 'rd-364-1995'), '22.3', 'El número de aprobados en las pruebas selectivas puede ser superior al de plazas convocadas cuando el proceso incluya:', array['Un período de prácticas', 'Un curso selectivo', 'Una fase de concurso', 'Una entrevista personal']::text[], 1, 'El artículo 22.3 dice: «El proceso selectivo podrá comprender, además de las pruebas selectivas, un curso selectivo o un período de prácticas. Sólo en el primer caso el número de aprobados en las pruebas selectivas podrá ser superior al de plazas convocadas».', 2, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
