insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('fps-009', (select id from leyes where slug = 'trebep'), '10.1.b', 'Si se nombra a un funcionario interino para la sustitución transitoria de los titulares, el nombramiento dura:', array['El tiempo estrictamente necesario', 'Un máximo de tres años', 'Un máximo de nueve meses', 'Un máximo de dieciocho meses']::text[], 0, 'El artículo 10.1.b) del TREBEP prevé «La sustitución transitoria de los titulares, durante el tiempo estrictamente necesario».', 1, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
