insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('fps-010', (select id from leyes where slug = 'trebep'), '10.2', 'Además de igualdad, mérito, capacidad y publicidad, la selección del personal funcionario interino se rige por el principio de:', array['Especialidad', 'Libre concurrencia', 'Celeridad', 'Discrecionalidad técnica']::text[], 2, 'El artículo 10.2 del TREBEP dice que estos procedimientos serán públicos, «rigiéndose en todo caso por los principios de igualdad, mérito, capacidad, publicidad y celeridad».', 2, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
