insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('fps-013', (select id from leyes where slug = 'rd-364-1995'), '41.2', 'Como regla general, para participar en los concursos de provisión hay que permanecer en cada puesto de destino definitivo un mínimo de:', array['Un año', 'Tres años', 'Seis meses', 'Dos años']::text[], 3, 'El artículo 41.2 dice: «Los funcionarios deberán permanecer en cada puesto de trabajo de destino definitivo un mínimo de dos años para poder participar en los concursos de provisión».', 1, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
