insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('fps-014', (select id from leyes where slug = 'rd-364-1995'), '42.2', 'El plazo de presentación de instancias en los concursos de provisión de puestos de trabajo es de:', array['Veinte días naturales', 'Quince días hábiles', 'Diez días hábiles', 'Un mes']::text[], 1, 'El artículo 42.2 dispone: «El plazo de presentación de instancias será de quince días hábiles, contados a partir del siguiente al de la publicación de la convocatoria».', 2, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
