insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('fps-015', (select id from leyes where slug = 'rd-364-1995'), '48.1', 'Si el destino obtenido por concurso comporta cambio de residencia, el plazo para tomar posesión es de:', array['Tres días hábiles', 'Quince días hábiles', 'Un mes', 'Ocho días naturales']::text[], 2, 'El artículo 48.1 dice: «El plazo para tomar posesión será de tres días hábiles si no implica cambio de residencia del funcionario, o de un mes si comporta cambio de residencia o el reingreso al servicio activo».', 2, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
