insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('fps-016', (select id from leyes where slug = 'rd-364-1995'), '64.3', 'Según el Reglamento General de Ingreso, las comisiones de servicios tienen una duración máxima de:', array['Un año, prorrogable por otro', 'Seis meses, prorrogables por otros seis', 'Dos años, sin prórroga posible', 'Un año, sin prórroga posible']::text[], 0, 'El artículo 64.3 establece que las comisiones de servicios «tendrán una duración máxima de un año prorrogable por otro en caso de no haberse cubierto el puesto con carácter definitivo».', 1, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
