insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('fps-018', (select id from leyes where slug = 'rd-364-1995'), '58.2', 'El funcionario cesado en un puesto de libre designación queda adscrito provisionalmente a un puesto de su Cuerpo o Escala:', array['No inferior en más de dos niveles al de su grado personal', 'No inferior en más de un nivel al de su grado personal', 'De igual nivel que el puesto del que ha sido cesado', 'No inferior en más de tres niveles al de su grado personal']::text[], 0, 'El artículo 58.2 dice que serán adscritos a un puesto de su Cuerpo o Escala «no inferior en más de dos niveles al de su grado personal en el mismo municipio».', 3, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
