insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('fps-019', (select id from leyes where slug = 'rd-364-1995'), '74.2', 'En la promoción interna por concurso-oposición, la puntuación obtenida en la fase de concurso:', array['Se suma a la de cada ejercicio para superarlo', 'Puede compensar un ejercicio no superado', 'Determina por sí sola el orden de prelación', 'No puede aplicarse para superar los ejercicios de la oposición']::text[], 3, 'El artículo 74.2 dispone: «En ningún caso la puntuación obtenida en la fase de concurso podrá aplicarse para superar los ejercicios de la fase de oposición».', 2, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
