insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('fps-020', (select id from leyes where slug = 'trebep'), '16.3.d', 'Según el TREBEP, el acceso a cuerpos o escalas del mismo Subgrupo profesional se denomina:', array['Promoción interna vertical', 'Carrera horizontal', 'Promoción interna horizontal', 'Carrera vertical']::text[], 2, 'El artículo 16.3.d) del TREBEP define la «Promoción interna horizontal, que consiste en el acceso a cuerpos o escalas del mismo Subgrupo profesional».', 1, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
