insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('fps-021', (select id from leyes where slug = 'ley-53-1984'), '12.1.d', 'El personal incluido en la Ley 53/1984 no puede tener en el capital de empresas contratistas del sector público una participación superior al:', array['5 por 100', '25 por 100', '10 por 100', '50 por 100']::text[], 2, 'El artículo 12.1.d) prohíbe «La participación superior al 10 por 100 en el capital de las Empresas o Sociedades a que se refiere el párrafo anterior» (concesionarias, contratistas, etc.).', 2, '2025-12-16', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
