insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('fps-022', (select id from leyes where slug = 'ley-53-1984'), '12.1.a', 'No pueden ejercerse actividades privadas en los asuntos en que el empleado público esté interviniendo o haya intervenido en:', array['El último año', 'Los cinco últimos años', 'Los tres últimos años', 'Los dos últimos años']::text[], 3, 'El artículo 12.1.a) prohíbe esas actividades «en los asuntos en que esté interviniendo, haya intervenido en los dos últimos años o tenga que intervenir por razón del puesto público».', 2, '2025-12-16', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
