insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('fps-023', (select id from leyes where slug = 'ley-53-1984'), '19.b', 'Queda fuera del régimen de incompatibilidades dar cursos en centros oficiales de formación de funcionarios si no es habitual ni supone más de:', array['Setenta y cinco horas al año', 'Cincuenta horas al año', 'Cien horas al año', 'Setenta y cinco horas al semestre']::text[], 0, 'El artículo 19.b) exceptúa esas actividades «cuando no tenga carácter permanente o habitual ni supongan más de setenta y cinco horas al año».', 3, '2025-12-16', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
