insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('fps-024', (select id from leyes where slug = 'ley-53-1984'), '14', 'La resolución que reconoce la compatibilidad para actividades privadas, o declara la incompatibilidad, se dicta en el plazo de:', array['Un mes', 'Dos meses', 'Tres meses', 'Seis meses']::text[], 1, 'El artículo 14 se refiere a «La resolución motivada reconociendo la compatibilidad o declarando la incompatibilidad, que se dictará en el plazo de dos meses».', 2, '2025-12-16', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
