insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('fps-025', (select id from leyes where slug = 'ley-53-1984'), '10', 'Si quien accede a un nuevo puesto público incompatible no opta en el plazo de toma de posesión, se entiende que:', array['Opta por el nuevo puesto y pasa a excedencia voluntaria en el anterior', 'Opta por el puesto que venía desempeñando hasta entonces', 'Renuncia a ambos puestos y queda sin destino', 'Opta por el nuevo puesto y queda en servicios especiales en el anterior']::text[], 0, 'El artículo 10 dice: «A falta de opción en el plazo señalado se entenderá que optan por el nuevo puesto, pasando a la situación de excedencia voluntaria en los que vinieran desempeñando».', 1, '2025-12-16', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
