insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('fps-026', (select id from leyes where slug = 'ley-53-1984'), '16.4', 'Cabe reconocer compatibilidad para actividades privadas a quien cobra complemento específico si este no supera, sobre su retribución básica sin antigüedad, el:', array['10 por 100', '30 por 100', '25 por 100', '50 por 100']::text[], 1, 'El artículo 16.4 lo permite cuando el complemento específico tenga una cuantía que «no supere el 30 por 100 de su retribución básica, excluidos los conceptos que tengan su origen en la antigüedad».', 3, '2025-12-16', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
