insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('fps-027', (select id from leyes where slug = 'ley-53-1984'), '5.1.b', 'Se puede compatibilizar el puesto público con el de miembro de una Corporación local, salvo que:', array['Se perciban dietas o asistencias por acudir a sus sesiones', 'Se forme parte de un grupo municipal de la oposición', 'Se desempeñe en ella un cargo retribuido en dedicación exclusiva', 'Se desempeñe en ella un cargo en dedicación parcial']::text[], 2, 'El artículo 5.1.b) admite la compatibilidad como «Miembros de las Corporaciones locales, salvo que desempeñen en las mismas cargos retribuidos en régimen de dedicación exclusiva».', 1, '2025-12-16', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
