insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('fps-028', (select id from leyes where slug = 'rd-33-1986'), '7.1.l', 'El incumplimiento injustificado de la jornada de trabajo es falta grave cuando, acumulado, supone un mínimo de:', array['Cinco horas al mes', 'Quince horas al mes', 'Diez horas al trimestre', 'Diez horas al mes']::text[], 3, 'El artículo 7.1.l) tipifica como falta grave «El incumplimiento injustificado de la jornada de trabajo que acumulado suponga un mínimo de diez horas al mes».', 2, '2025-12-17', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
