insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('fps-029', (select id from leyes where slug = 'rd-33-1986'), '8.b', 'Según el Reglamento de Régimen Disciplinario, la falta de asistencia injustificada de un día es una falta:', array['Grave', 'Muy grave', 'Grave si es la segunda en un mes', 'Leve']::text[], 3, 'El artículo 8 dice: «Son faltas leves: […] b) La falta de asistencia injustificada de un día».', 1, '2025-12-17', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
