insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('fps-030', (select id from leyes where slug = 'rd-33-1986'), '16', 'Quien es sancionado por falta grave con traslado con cambio de residencia no puede obtener destino en la localidad de la que fue trasladado durante:', array['Tres años', 'Seis meses', 'Un año', 'Dos años']::text[], 2, 'El artículo 16 fija esa prohibición «durante tres años, cuando hubiere sido impuesta por falta muy grave, y durante uno cuando hubiere correspondido a la comisión de una falta grave».', 3, '2025-12-17', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
