insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('fps-031', (select id from leyes where slug = 'rd-33-1986'), '30', 'El Instructor del expediente disciplinario debe ser un funcionario público perteneciente a un cuerpo o escala:', array['Del mismo cuerpo o escala que el inculpado', 'De igual o superior grupo al del inculpado', 'De grupo necesariamente superior al del inculpado', 'De cualquier grupo, si es funcionario de carrera']::text[], 1, 'El artículo 30 exige que el Instructor sea «un funcionario público perteneciente a un cuerpo o escala de igual o superior grupo al del inculpado».', 1, '2025-12-17', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
