insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('fps-032', (select id from leyes where slug = 'rd-33-1986'), '35.1', 'Desde la incoación del procedimiento disciplinario, el Instructor debe formular el pliego de cargos en un plazo no superior a:', array['Un mes', 'Diez días', 'Quince días', 'Dos meses']::text[], 0, 'El artículo 35.1 dispone que, «en un plazo no superior a un mes, contados a partir de la incoación del procedimiento, el Instructor formulará el correspondiente pliego de cargos».', 2, '2025-12-17', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
