insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('fps-033', (select id from leyes where slug = 'rd-33-1986'), '47.1', 'Según el Reglamento de Régimen Disciplinario, el órgano competente para imponer la sanción de separación del servicio es:', array['El Subsecretario del Departamento', 'El Ministro del Departamento', 'El Consejo de Ministros', 'El Director general del funcionario']::text[], 2, 'El artículo 47.1 atribuye esa competencia a «El Consejo de Ministros, a propuesta del Ministro de la Presidencia, quien con carácter previo oirá a la Comisión Superior de Personal, para imponer la separación del servicio».', 1, '2025-12-17', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
