insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('fps-034', (select id from leyes where slug = 'trebep'), '98.3', 'Durante la suspensión provisional, el funcionario tiene derecho a percibir:', array['Todas sus retribuciones básicas y complementarias', 'Las retribuciones básicas y, en su caso, las prestaciones por hijo a cargo', 'El setenta y cinco por ciento de sus retribuciones', 'Las retribuciones complementarias, pero no las básicas']::text[], 1, 'El artículo 98.3 del TREBEP dice: «El funcionario suspenso provisional tendrá derecho a percibir durante la suspensión las retribuciones básicas y, en su caso, las prestaciones familiares por hijo a cargo».', 2, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
