insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gfi-001', (select id from leyes where slug = 'ley-47-2003'), '27.1', 'La gestión del sector público estatal está sometida al régimen de presupuesto:', array['Bienal aprobado por el Gobierno', 'Trienal aprobado por las Cortes Generales', 'Anual aprobado por las Cortes Generales', 'Anual aprobado por el Consejo de Ministros']::text[], 2, 'El artículo 27.1 dice que la gestión del sector público estatal «está sometida al régimen de presupuesto anual aprobado por las Cortes Generales y enmarcado en los límites de un escenario plurianual».', 1, '2026-09-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
