insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gfi-002', (select id from leyes where slug = 'ley-47-2003'), '27.4', 'Los derechos liquidados y las obligaciones reconocidas se aplicarán a los presupuestos:', array['Por su importe íntegro', 'Por su importe neto, ya compensados', 'Por la diferencia entre unos y otras', 'Por el importe que fije cada ministerio']::text[], 0, 'El artículo 27.4 establece: «Los derechos liquidados y las obligaciones reconocidas se aplicarán a los presupuestos por su importe íntegro, sin que puedan atenderse obligaciones mediante minoración de los derechos a liquidar o ya ingresados».', 1, '2026-09-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
