insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gfi-003', (select id from leyes where slug = 'ley-47-2003'), '28.4', 'Los escenarios presupuestarios plurianuales estarán integrados por:', array['Un escenario económico y un escenario social', 'Un escenario estatal y un escenario autonómico', 'Un escenario de inversiones y uno de personal', 'Un escenario de ingresos y un escenario de gastos']::text[], 3, 'El artículo 28.4 dice: «Los escenarios presupuestarios plurianuales estarán integrados por un escenario de ingresos y un escenario de gastos».', 1, '2026-09-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
