insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gfi-004', (select id from leyes where slug = 'ley-47-2003'), '29.3', 'El programa plurianual de cada ministerio, con los programas de sus centros gestores, se aprobará por:', array['El Consejo de Ministros', 'El Ministro', 'La Comisión de Políticas de Gasto', 'El Subsecretario del departamento']::text[], 1, 'Según el artículo 29.3, «El programa plurianual de cada ministerio contendrá los programas de todos los centros gestores que de él dependan y se aprobará por el Ministro».', 2, '2026-09-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
