insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gfi-005', (select id from leyes where slug = 'ley-47-2003'), '31.2', 'Las asignaciones presupuestarias a los centros gestores de gasto se efectuarán tomando en cuenta, entre otras circunstancias:', array['El número de efectivos de personal de cada centro', 'El crédito no comprometido en el ejercicio anterior', 'El nivel de cumplimiento de los objetivos anteriores', 'La propuesta de la Intervención Delegada']::text[], 2, 'El artículo 31.2 dice: «Las asignaciones presupuestarias a los centros gestores de gasto se efectuarán tomando en cuenta, entre otras circunstancias, el nivel de cumplimiento de los objetivos en ejercicios anteriores».', 2, '2026-09-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
