insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gfi-006', (select id from leyes where slug = 'ley-47-2003'), '34.4', 'Imputar a presupuesto obligaciones de ejercicios anteriores no comprendidas en los supuestos legales previstos requiere:', array['Una norma con rango de ley que lo autorice', 'Un acuerdo del Consejo de Ministros', 'Un informe favorable de la Intervención General', 'Una orden del ministro del departamento']::text[], 0, 'El artículo 34.4 dispone que, para obligaciones de ejercicios anteriores no comprendidas en los apartados anteriores, «la imputación requerirá norma con rango de ley que la autorice».', 3, '2026-09-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
