insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gfi-007', (select id from leyes where slug = 'ley-47-2003'), '43.1', 'En el presupuesto del Estado, los créditos destinados a inversiones reales se especifican a nivel de:', array['Concepto', 'Subconcepto', 'Artículo', 'Capítulo']::text[], 3, 'El artículo 43.1 dice que los créditos se especifican a nivel de concepto, salvo los de personal y gastos corrientes en bienes y servicios, «que se especificarán a nivel de artículo y las inversiones reales a nivel de capítulo».', 2, '2026-09-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
