insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gfi-008', (select id from leyes where slug = 'ley-47-2003'), '46', 'Los actos administrativos que adquieran compromisos de gasto por cuantía superior a los créditos autorizados son:', array['Anulables', 'Nulos de pleno derecho', 'Válidos si se convalidan después', 'Irregulares no invalidantes']::text[], 1, 'El artículo 46 dice: «Los créditos para gastos son limitativos. No podrán adquirirse compromisos de gasto ni adquirirse obligaciones por cuantía superior al importe de los créditos autorizados en los estados de gastos, siendo nulos de pleno derecho los actos administrativos […]».', 1, '2026-09-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
