insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gfi-009', (select id from leyes where slug = 'ley-47-2003'), '47.2', 'Con carácter general, el número de ejercicios a que pueden aplicarse los gastos plurianuales no será superior a:', array['Cuatro', 'Tres', 'Cinco', 'Seis']::text[], 0, 'El artículo 47.2 dice: «El número de ejercicios a que pueden aplicarse los gastos no será superior a cuatro».', 1, '2026-09-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
