insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gfi-010', (select id from leyes where slug = 'ley-47-2003'), '47.2', 'En los compromisos de gasto plurianuales, el gasto imputado al ejercicio inmediato siguiente no podrá exceder del:', array['50 % del crédito inicial', '60 % del crédito inicial', '70 % del crédito inicial', '80 % del crédito inicial']::text[], 2, 'El artículo 47.2 fija estos porcentajes sobre el crédito inicial: «en el ejercicio inmediato siguiente, el 70 por ciento, en el segundo ejercicio, el 60 por ciento, y en los ejercicios tercero y cuarto, el 50 por ciento».', 2, '2026-09-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
