insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gfi-011', (select id from leyes where slug = 'ley-47-2003'), '47.2', 'En los contratos de obra plurianuales, salvo los de abono total del precio, al adjudicar se hace una retención adicional de crédito del:', array['5 % del importe de adjudicación', '10 % del importe de adjudicación', '15 % del importe de adjudicación', '20 % del importe de adjudicación']::text[], 1, 'El artículo 47.2 dice que en estos contratos «se efectuará una retención adicional de crédito del 10 por ciento del importe de adjudicación, en el momento en que ésta se realice».', 3, '2026-09-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
