insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gfi-013', (select id from leyes where slug = 'ley-47-2003'), '49.2', 'Los créditos para gastos que el último día del ejercicio no estén afectados al cumplimiento de obligaciones ya reconocidas:', array['Quedarán anulados de pleno derecho', 'Se incorporan sin más al ejercicio siguiente', 'Pasan a dotar el Fondo de Contingencia', 'Se prorrogan durante el primer trimestre']::text[], 0, 'El artículo 49.2 dice que estos créditos «quedarán anulados de pleno derecho, sin perjuicio de lo establecido en el artículo 58 de esta ley».', 1, '2026-09-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
