insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gfi-014', (select id from leyes where slug = 'ley-47-2003'), '63.1', 'Los titulares de los ministerios pueden autorizar las modificaciones presupuestarias de su competencia previo informe favorable de:', array['La Dirección General de Presupuestos', 'El Consejo de Estado', 'La Intervención Delegada competente', 'El Tribunal de Cuentas']::text[], 2, 'El artículo 63.1 dice: «Los titulares de los distintos ministerios podrán autorizar, previo informe favorable de la Intervención Delegada competente en el ministerio […] las siguientes modificaciones presupuestarias».', 2, '2026-09-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
