insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gfi-015', (select id from leyes where slug = 'ley-47-2003'), '73.3', '¿Qué fase del gasto es un acto con relevancia jurídica para con terceros que vincula a la Hacienda Pública a realizar el gasto?', array['La aprobación del gasto', 'La ordenación del pago', 'El pago material', 'El compromiso de gasto']::text[], 3, 'El artículo 73.3 dice: «El compromiso es un acto con relevancia jurídica para con terceros, vinculando a la Hacienda Pública estatal o a la Seguridad Social a la realización del gasto».', 1, '2026-09-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
