insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gfi-016', (select id from leyes where slug = 'ley-47-2003'), '73.7', 'Cuando la naturaleza de la operación o gasto así lo determine, las fases de ejecución precisas:', array['Se tramitarán por el procedimiento de urgencia', 'Se acumularán en un solo acto', 'Podrán omitirse con informe de la Intervención', 'Se sustituirán por un pago a justificar']::text[], 1, 'El artículo 73.7 dice: «Cuando la naturaleza de la operación o gasto así lo determinen, se acumularán en un solo acto las fases de ejecución precisas».', 2, '2026-09-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
