insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gfi-017', (select id from leyes where slug = 'ley-47-2003'), '74.1', 'Los Ministros pueden fijar los límites por debajo de los cuales sus competencias de gestión de gastos corresponderán a:', array['Los Directores y Subdirectores Generales', 'Los Delegados del Gobierno', 'Los Secretarios de Estado y Subsecretario', 'Los Interventores Delegados']::text[], 2, 'El artículo 74.1 dice que corresponderá a los Ministros «fijar los límites por debajo de los cuales las citadas competencias corresponderán, en su ámbito respectivo, a los Secretarios de Estado y Subsecretario del departamento».', 3, '2026-09-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
