insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gfi-018', (select id from leyes where slug = 'ley-47-2003'), '75.1', 'Las funciones de Ordenador General de pagos del Estado competen:', array['Al Director General del Tesoro y Política Financiera', 'Al Interventor General de la Administración del Estado', 'Al Director General de Presupuestos', 'Al Subsecretario de cada departamento']::text[], 0, 'El artículo 75.1 dice que «competen al Director General del Tesoro y Política Financiera las funciones de Ordenador General de pagos del Estado».', 2, '2026-09-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
