insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gfi-019', (select id from leyes where slug = 'ley-47-2003'), '140.2', 'El control interno de la gestión económica y financiera del sector público estatal lo ejerce:', array['El Tribunal de Cuentas', 'La Dirección General de Presupuestos', 'La Oficina Presupuestaria de las Cortes', 'La Intervención General de la Administración del Estado']::text[], 3, 'El artículo 140.2 dice: «La Intervención General de la Administración del Estado ejercerá en los términos previstos en esta ley el control interno de la gestión económica y financiera del sector público estatal».', 1, '2026-09-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
