insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gfi-020', (select id from leyes where slug = 'ley-47-2003'), '142.2', 'Según la Ley General Presupuestaria, el control interno se realiza mediante:', array['La fiscalización previa, la censura de cuentas y la inspección', 'La función interventora, el control financiero permanente y la auditoría pública', 'El enjuiciamiento contable, la auditoría privada y la inspección', 'El control parlamentario, el control judicial y la auditoría']::text[], 1, 'El artículo 142.2 dice: «El control se realizará mediante el ejercicio de la función interventora, el control financiero permanente y la auditoría pública».', 1, '2026-09-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
