insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gfi-021', (select id from leyes where slug = 'ley-47-2003'), '144.1', 'La Intervención General de la Administración del Estado ejerce sus funciones de control conforme a los principios de:', array['Autonomía, ejercicio desconcentrado y jerarquía interna', 'Dependencia, centralización y coordinación', 'Eficacia, descentralización y jerarquía externa', 'Independencia, unidad de caja y especialidad']::text[], 0, 'El artículo 144.1 dice que la Intervención General «ejercerá sus funciones de control conforme a los principios de autonomía, ejercicio desconcentrado y jerarquía interna».', 3, '2026-09-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
