insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gfi-022', (select id from leyes where slug = 'lo-2-1982'), '2.a', 'Según su Ley Orgánica, la fiscalización del Tribunal de Cuentas sobre la actividad económico-financiera del sector público es:', array['Interna, previa y selectiva', 'Externa, ocasional y preventiva', 'Externa, permanente y consuntiva', 'Interna, permanente y concomitante']::text[], 2, 'El artículo segundo, a), atribuye al Tribunal de Cuentas «La fiscalización externa, permanente y consuntiva de la actividad económico-financiera del sector público».', 2, '2025-12-16', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
