insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gfi-023', (select id from leyes where slug = 'lo-2-1982'), '21.1', 'El Pleno del Tribunal de Cuentas está integrado por:', array['Nueve Consejeros de Cuentas y el Fiscal', 'Doce Consejeros de Cuentas y el Secretario General', 'Quince Consejeros, uno de ellos el Presidente', 'Doce Consejeros, uno de ellos el Presidente, y el Fiscal']::text[], 3, 'El artículo veintiuno, uno, dice: «El Tribunal en Pleno estará integrado por doce Consejeros de Cuentas, uno de los cuales será el Presidente, y el Fiscal».', 1, '2025-12-16', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
