insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gfi-024', (select id from leyes where slug = 'lo-2-1982'), '30.1', 'Los Consejeros de Cuentas son designados por las Cortes Generales por un período de:', array['Seis años', 'Nueve años', 'Cinco años', 'Doce años']::text[], 1, 'El artículo treinta, uno, dice que los Consejeros son designados «mediante votación por mayoría de tres quintos de cada una de las Cámaras, por un período de nueve años».', 1, '2025-12-16', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
