insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gfi-025', (select id from leyes where slug = 'lo-2-1982'), '29', 'El Presidente del Tribunal de Cuentas es nombrado por el Rey, a propuesta del Pleno, por un período de:', array['Cinco años', 'Nueve años', 'Tres años', 'Cuatro años']::text[], 2, 'El artículo veintinueve dice: «El Presidente del Tribunal de Cuentas será nombrado de entre sus miembros por el Rey, a propuesta del mismo Tribunal en Pleno y por un período de tres años».', 2, '2025-12-16', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
