insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gfi-026', (select id from leyes where slug = 'lo-2-1982'), '17.1', 'Según la Ley Orgánica del Tribunal de Cuentas, la jurisdicción contable es:', array['Necesaria e improrrogable, exclusiva y plena', 'Voluntaria y prorrogable, exclusiva y plena', 'Necesaria e improrrogable, compartida y limitada', 'Voluntaria, compartida y subsidiaria de la penal']::text[], 0, 'El artículo diecisiete, uno, dice: «La jurisdicción contable es necesaria e improrrogable, exclusiva y plena».', 3, '2025-12-16', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
