insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gfi-027', (select id from leyes where slug = 'ley-47-2003'), '78.1', 'Los anticipos de caja fija son provisiones de fondos de carácter:', array['Presupuestario y temporal', 'Extrapresupuestario y permanente', 'Presupuestario y permanente', 'Extrapresupuestario y ocasional']::text[], 1, 'El artículo 78.1 dice: «Se entienden por anticipos de caja fija las provisiones de fondos de carácter extrapresupuestario y permanente que se realicen a pagadurías, cajas y habilitaciones».', 1, '2026-09-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'gfi-027', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 36 where o.slug = 'admin-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gfi-028', (select id from leyes where slug = 'ley-47-2003'), '78.3', 'Con carácter general, la cuantía global de los anticipos de caja fija de cada ministerio u organismo autónomo no podrá superar:', array['El 3 % de los créditos del capítulo de gastos de personal', 'El 10 % de los créditos del capítulo de inversiones reales', 'El 14 % de los créditos de gastos corrientes en bienes y servicios', 'El 7 % de los créditos de gastos corrientes en bienes y servicios']::text[], 3, 'El artículo 78.3 dice que la cuantía global «no podrá superar para cada ministerio u organismo autónomo el siete por ciento del total de créditos del capítulo destinado a gastos corrientes en bienes y servicios».', 2, '2026-09-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'gfi-028', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 36 where o.slug = 'admin-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gfi-029', (select id from leyes where slug = 'rd-725-1989'), '2.3', 'Con cargo al anticipo de caja fija no pueden hacerse pagos individualizados de más de 5.000 euros, salvo los destinados a:', array['Teléfono, energía eléctrica, combustibles o indemnizaciones por razón del servicio', 'Material no inventariable, conservación y reparación de edificios', 'Material de oficina, atenciones protocolarias y reuniones', 'Arrendamientos de inmuebles, publicidad y propaganda']::text[], 0, 'El artículo 2.3 dice que no podrán realizarse con cargo al anticipo «pagos individualizados superiores a 5.000 euros […] excepto los destinados a gastos de teléfono, energía eléctrica, combustibles o indemnizaciones por razón del servicio».', 3, '2026-10-08', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'gfi-029', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 36 where o.slug = 'admin-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gfi-030', (select id from leyes where slug = 'rd-725-1989'), '7.1', 'Los Cajeros pagadores rinden cuentas de los gastos atendidos con anticipos de caja fija según sus necesidades de tesorería y, necesariamente:', array['Al final de cada trimestre', 'En el mes de enero de cada año', 'En el mes de diciembre de cada año', 'Cuando se agote la mitad del anticipo']::text[], 2, 'El artículo 7.1 dice que los Cajeros pagadores rendirán cuentas «a medida que sus necesidades de tesorería aconsejen la reposición de los fondos utilizados y, necesariamente, en el mes de diciembre de cada año».', 2, '2026-10-08', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'gfi-030', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 36 where o.slug = 'admin-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gfi-031', (select id from leyes where slug = 'rd-725-1989'), '6.1', 'Las disposiciones de fondos de las cuentas de anticipos de caja fija, por cheque o transferencia, se autorizan con:', array['Firma única del Cajero pagador', 'Firma única del Interventor Delegado', 'Firmas mancomunadas del Cajero y del Interventor', 'Firmas mancomunadas del Cajero y de un funcionario designado']::text[], 3, 'El artículo 6.1 exige que se autoricen «con las firmas mancomunadas del Cajero pagador y del funcionario que designe el Jefe de la Unidad Administrativa a la que esté adscrita la Caja pagadora».', 2, '2026-10-08', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'gfi-031', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 36 where o.slug = 'admin-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gfi-032', (select id from leyes where slug = 'ley-47-2003'), '79.1', 'Pueden librarse fondos con el carácter de "a justificar" cuando, excepcionalmente:', array['Los gastos sean periódicos o repetitivos', 'No pueda aportarse a tiempo la documentación justificativa', 'El crédito sea insuficiente y no ampliable', 'El gasto no supere el importe de un contrato menor']::text[], 1, 'El artículo 79.1 dice: «Cuando, excepcionalmente, no pueda aportarse la documentación justificativa de las obligaciones en el momento previsto en el apartado 4 del artículo 73, podrán tramitarse propuestas de pagos presupuestarios y librarse fondos con el carácter de a justificar».', 1, '2026-09-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
