insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gfi-033', (select id from leyes where slug = 'ley-47-2003'), '79.4', 'Salvo expropiaciones y pagos en el extranjero, el plazo para rendir la cuenta de los pagos a justificar es de:', array['Tres meses', 'Seis meses', 'Un mes', 'Doce meses']::text[], 0, 'El artículo 79.4 dice: «El plazo de rendición de las cuentas será de tres meses, excepto las correspondientes a pagos de expropiaciones y pagos en el extranjero que podrán ser rendidas en el plazo de seis meses».', 1, '2026-09-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
