insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gfi-034', (select id from leyes where slug = 'rd-725-1989'), '9.1', 'Los estados de situación de Tesorería de las Cajas pagadoras se formulan, como mínimo, en las primeras quincenas de:', array['Cada mes del año', 'Enero y julio', 'Enero, abril, julio y octubre', 'Marzo, junio, septiembre y diciembre']::text[], 2, 'El artículo 9.1 dice que, como mínimo, «en las primeras quincenas de los meses de enero, abril, julio y octubre y referidos al último día del trimestre inmediato anterior se formularán estados de situación de Tesorería».', 3, '2026-10-08', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
