insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gab-001', null, 'Preámbulo', '¿Cuántos Objetivos de Desarrollo Sostenible y metas recoge la Agenda 2030?', array['17 Objetivos y 169 metas', '17 Objetivos y 196 metas', '15 Objetivos y 169 metas', '19 Objetivos y 159 metas']::text[], 0, 'El preámbulo de la Resolución 70/1 dice: «Los 17 Objetivos de Desarrollo Sostenible y las 169 metas que anunciamos hoy demuestran la magnitud de esta ambiciosa nueva Agenda universal».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
