insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gab-017', null, '¿Qué es el Gobierno Abierto?', 'La definición de Gobierno Abierto que recoge el Portal de la Transparencia procede de una Recomendación del Consejo de:', array['La Unión Europea, de 14 de diciembre de 2017', 'Europa, de 25 de septiembre de 2015', 'La OCDE, de 9 de diciembre de 2013', 'La OCDE, de 14 de diciembre de 2017']::text[], 3, 'La página remite a la «definición recogida en la Recomendación del Consejo de la OCDE sobre Gobierno Abierto de 14 de diciembre de 2017».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
