insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gab-018', null, '¿Qué es el Gobierno Abierto?', 'Según la definición de la OCDE, el Gobierno Abierto promueve los principios de:', array['Transparencia, integridad, rendición de cuentas y participación', 'Transparencia, eficacia, legalidad y participación', 'Publicidad, integridad, eficiencia y colaboración', 'Transparencia, neutralidad, jerarquía y participación']::text[], 0, 'El Gobierno Abierto es «una cultura de gobernanza que promueve los principios de transparencia, integridad, rendición de cuentas y participación de las partes interesadas en apoyo de la democracia y el crecimiento inclusivo».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
