insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gab-021', null, 'Organización de las Naciones Unidas (ONU) y los ODS', 'En el Plan de Acción para la Agenda 2030, los Planes de Gobierno Abierto son política palanca por su contribución al:', array['ODS 10 (reducción de las desigualdades)', 'ODS 17 (alianzas para lograr los objetivos)', 'ODS 4 (educación de calidad)', 'ODS 16 (paz, justicia e instituciones sólidas)']::text[], 3, 'La página dice que los Planes de Gobierno Abierto se consideran política palanca «por su contribución al cumplimiento del ODS 16 (paz, justicia e instituciones sólidas)».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
