insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gab-022', null, 'El Gobierno Abierto en España', 'En España, ¿cómo se distribuye la competencia en materia de Gobierno Abierto?', array['Es exclusiva de cada Administración, salvo en transparencia', 'Es exclusiva del Estado en todos sus aspectos', 'Es compartida entre el Estado y las comunidades', 'Es exclusiva de cada Administración, salvo en participación']::text[], 0, 'La página dice: «Cada Administración pública tiene competencia exclusiva en materia de Gobierno Abierto, excepto en lo relativo a la transparencia», donde la Ley 19/2013 fija obligaciones comunes.', 3, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
