insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gab-023', null, 'El Gobierno Abierto en España', '¿Qué órgano es el espacio de coordinación, colaboración y debate entre las Administraciones públicas estatal, autonómicas y locales en gobierno abierto?', array['El Foro de Gobierno Abierto', 'La Comisión Sectorial de Gobierno Abierto', 'El grupo interministerial de Gobierno Abierto', 'El Consejo de Transparencia y Buen Gobierno']::text[], 1, 'Según la página, «La Comisión Sectorial de Gobierno Abierto es un espacio de coordinación, colaboración y debate entre las Administraciones públicas españolas (estatal, autonómicas y locales)». El Foro incluye además a la sociedad civil.', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
