insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gb-003', (select id from leyes where slug = 'ley-50-1997'), '15.1', 'Los Secretarios de Estado son nombrados y separados:', array['Por Real Decreto del Consejo de Ministros', 'Por Real Decreto del Presidente del Gobierno', 'Por Orden del Ministro del Departamento', 'Por el Rey, a propuesta del Congreso']::text[], 0, 'El artículo 15.1 establece que «Los Secretarios de Estado son nombrados y separados por Real Decreto del Consejo de Ministros, aprobado a propuesta del Presidente del Gobierno o del miembro del Gobierno a cuyo Departamento pertenezcan».', 2, '2025-04-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
