insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gb-011', (select id from leyes where slug = 'ley-50-1997'), '10.1', 'Según la Ley del Gobierno, los miembros de los Gabinetes:', array['Pueden dictar resoluciones por delegación del Ministro', 'Son órganos superiores de la Administración', 'Sustituyen al Ministro en caso de ausencia', 'Realizan tareas de confianza y asesoramiento especial']::text[], 3, 'El artículo 10.1 dice que «Los miembros de los Gabinetes realizan tareas de confianza y asesoramiento especial sin que en ningún caso puedan adoptar actos o resoluciones que correspondan legalmente a los órganos de la Administración General del Estado».', 1, '2025-04-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
