insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gb-013', (select id from leyes where slug = 'ley-50-1997'), '16.3', 'Cuando cesa el titular del cargo del que dependen, los Directores de los Gabinetes:', array['Continúan tres meses en funciones', 'Cesan automáticamente', 'Pasan a depender del Subsecretario', 'Siguen en el cargo hasta que el sucesor los cese']::text[], 1, 'Según el artículo 16.3, «Los Directores de los Gabinetes cesarán automáticamente cuando cese el titular del cargo del que dependen». Si el Gobierno está en funciones, siguen hasta que se forma el nuevo.', 1, '2025-04-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
