insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gb-015', (select id from leyes where slug = 'ley-50-1997'), '12.2', 'Según la Ley del Gobierno, la separación de los Ministros sin cartera:', array['Obliga a nombrar otro Ministro sin cartera', 'Requiere acuerdo del Consejo de Ministros', 'Lleva aparejada la extinción de dichos órganos', 'Debe comunicarse al Congreso de los Diputados']::text[], 2, 'El artículo 12.2 dispone que «La separación de los Ministros sin cartera llevará aparejada la extinción de dichos órganos».', 3, '2025-04-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
