insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gb-016', (select id from leyes where slug = 'ley-50-1997'), '13.2', 'La suplencia de los Ministros para el despacho ordinario de los asuntos de su competencia se determina:', array['Por acuerdo del Consejo de Ministros', 'Por Orden del propio Ministro', 'Por Real Decreto acordado en Consejo de Ministros', 'Por Real Decreto del Presidente del Gobierno']::text[], 3, 'El artículo 13.2 dice que esta suplencia «será determinada por Real Decreto del Presidente del Gobierno, debiendo recaer, en todo caso, en otro miembro del Gobierno».', 2, '2025-04-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
