insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gb-017', (select id from leyes where slug = 'ley-50-1997'), '18.4', '¿Qué de lo siguiente NO figura en el acta de las sesiones del Consejo de Ministros?', array['Las opiniones expresadas por cada Ministro', 'La relación de asistentes', 'Los informes presentados', 'El tiempo y lugar de su celebración']::text[], 0, 'Según el artículo 18.4, en el acta figurarán «exclusivamente, las circunstancias relativas al tiempo y lugar de su celebración, la relación de asistentes, los acuerdos adoptados y los informes presentados».', 2, '2025-04-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
