insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gb-019', (select id from leyes where slug = 'ley-50-1997'), '21.5', '¿Cuál de estas facultades NO puede ejercer el Gobierno en funciones?', array['El despacho ordinario de los asuntos públicos', 'Presentar proyectos de ley al Congreso de los Diputados', 'Facilitar el traspaso de poderes al nuevo Gobierno', 'Adoptar medidas en casos de urgencia debidamente acreditados']::text[], 1, 'El artículo 21.5 dispone que «El Gobierno en funciones no podrá ejercer las siguientes facultades» y cita, junto al proyecto de Presupuestos, «Presentar proyectos de ley al Congreso de los Diputados o, en su caso, al Senado».', 1, '2025-04-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
