insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gb-020', (select id from leyes where slug = 'ley-50-1997'), '21.6', '¿Qué ocurre con las delegaciones legislativas otorgadas por las Cortes cuando el Gobierno está en funciones tras unas elecciones generales?', array['Se extinguen de forma automática', 'Las ejerce el Gobierno solo en casos urgentes', 'Se prorrogan hasta la investidura', 'Quedan en suspenso durante todo ese tiempo']::text[], 3, 'El artículo 21.6 señala que «Las delegaciones legislativas otorgadas por las Cortes Generales quedarán en suspenso durante todo el tiempo que el Gobierno esté en funciones como consecuencia de la celebración de elecciones generales».', 3, '2025-04-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
