insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gb-021', (select id from leyes where slug = 'ley-50-1997'), '23', 'Los reglamentos del Gobierno que impongan nuevas obligaciones a quienes ejercen una actividad económica o profesional entran en vigor:', array['El 2 de enero o el 1 de julio siguientes a su aprobación', 'A los veinte días de su publicación en el BOE', 'El 1 de enero o el 1 de julio siguientes a su publicación', 'Al día siguiente de su publicación en el BOE']::text[], 0, 'El artículo 23 indica que esas disposiciones «preverán el comienzo de su vigencia el 2 de enero o el 1 de julio siguientes a su aprobación».', 2, '2025-04-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
