insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gb-023', (select id from leyes where slug = 'constitucion'), '116.4', 'El estado de sitio se declara:', array['Por el Gobierno, previa autorización del Congreso', 'Por la mayoría absoluta del Congreso, a propuesta exclusiva del Gobierno', 'Por el Gobierno, dando cuenta al Congreso', 'Por las Cortes Generales, a propuesta del Rey']::text[], 1, 'El artículo 116.4 establece que «El estado de sitio será declarado por la mayoría absoluta del Congreso de los Diputados, a propuesta exclusiva del Gobierno».', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
