insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gb-024', (select id from leyes where slug = 'constitucion'), '116.5', 'Mientras esté declarado el estado de alarma, de excepción o de sitio:', array['El Congreso puede disolverse con autorización del Senado', 'Se suspenden los periodos de sesiones de las Cámaras', 'El Gobierno queda exento de responsabilidad', 'No puede procederse a la disolución del Congreso']::text[], 3, 'Según el artículo 116.5, «No podrá procederse a la disolución del Congreso mientras estén declarados algunos de los estados comprendidos en el presente artículo».', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
