insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inf-001', (select id from leyes where slug = 'rd-208-1996'), '2.2', 'Según el RD 208/1996, la información administrativa general se facilitará a los ciudadanos:', array['Solo si acreditan la condición de interesados', 'Previa solicitud escrita y motivada', 'Obligatoriamente, sin exigir acreditación de legitimación alguna', 'Solo a través de sus representantes legales']::text[], 2, 'El artículo 2.2 dispone: «La información general se facilitará obligatoriamente a los ciudadanos, sin exigir para ello la acreditación de legitimación alguna».', 1, '2026-09-14', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
