insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inf-003', (select id from leyes where slug = 'rd-208-1996'), '2.1', '¿Cuál de estas informaciones es información general según el RD 208/1996?', array['La concerniente al estado de un procedimiento en tramitación', 'La relativa a la localización de organismos y unidades administrativas', 'La identificación del personal que tramita un procedimiento concreto', 'La referida a datos personales que afectan a la intimidad']::text[], 1, 'El artículo 2.1 define la información general como la «relativa a la identificación, fines, competencia, estructura, funcionamiento y localización de organismos y unidades administrativas».', 2, '2026-09-14', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
