insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inf-007', (select id from leyes where slug = 'rd-208-1996'), '4.f', 'El RD 208/1996 incluye la asistencia en el ejercicio del derecho de petición, reconocido por los artículos de la Constitución:', array['23 y 77', '29 y 77', '29 y 105', '24 y 29']::text[], 1, 'El artículo 4.f) se refiere a la asistencia «en el ejercicio del derecho de petición, reconocido por los artículos 29 y 77 de la Constitución».', 3, '2026-09-14', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
