insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inf-008', (select id from leyes where slug = 'rd-208-1996'), '4.f', 'Si una unidad de información recibe una petición en la que no figura el destinatario, debe:', array['Elevarla a los órganos competentes', 'Devolverla al peticionario para que la subsane', 'Archivarla sin más trámite', 'Remitirla al Defensor del Pueblo']::text[], 0, 'Según el artículo 4.f), «estas unidades deberán elevar a los órganos competentes las peticiones que reciban, en las que no figure el destinatario o conste erróneamente».', 2, '2026-09-14', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
