insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inf-009', (select id from leyes where slug = 'rd-208-1996'), '4.c', 'La función de gestión incluye la resolución de las cuestiones cuya:', array['Cuantía no supere el límite fijado reglamentariamente', 'Urgencia y simplicidad demanden una respuesta inmediata', 'Complejidad aconseje una atención personalizada', 'Naturaleza no requiera un informe jurídico previo']::text[], 1, 'El artículo 4.c) incluye «las actuaciones de trámite y resolución de las cuestiones cuya urgencia y simplicidad demanden una respuesta inmediata».', 2, '2026-09-14', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
