insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inf-010', (select id from leyes where slug = 'rd-208-1996'), '4.d', 'Según el RD 208/1996, las iniciativas o sugerencias para mejorar la calidad de los servicios pueden formularlas:', array['Solo los ciudadanos', 'Los ciudadanos y los propios empleados públicos', 'Solo los interesados en un procedimiento', 'Solo los empleados públicos']::text[], 1, 'El artículo 4.d) habla de las «iniciativas o sugerencias formuladas por los ciudadanos, o por los propios empleados públicos para mejorar la calidad de los servicios».', 1, '2026-09-14', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
