insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inf-011', (select id from leyes where slug = 'rd-208-1996'), '5.1', '¿Quién ostenta la jefatura de la unidad departamental de información administrativa de cada Ministerio?', array['El Subsecretario del Departamento', 'El Secretario General Técnico', 'El Inspector General de Servicios', 'El titular de la Subdirección General competente']::text[], 3, 'El artículo 5.1 dispone que «el titular de la Subdirección General que tenga encomendada la competencia sobre la información administrativa ostentará la jefatura de la unidad departamental de información administrativa».', 3, '2026-09-14', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
