insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inf-021', (select id from leyes where slug = 'rd-951-2005'), '11.2', 'La resolución que aprueba una carta de servicios:', array['Se notifica solo a las unidades afectadas', 'Se publica únicamente en la sede electrónica', 'Se publica en el «Boletín Oficial del Estado»', 'No requiere publicación']::text[], 2, 'Según el artículo 11.2, la resolución se publicará en el Boletín Oficial del Estado, «lo que dará cuenta de la aprobación de la carta y de su disponibilidad para el público».', 1, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
