insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inf-023', (select id from leyes where slug = 'rd-951-2005'), '12.2', 'El informe sobre el grado de cumplimiento de los compromisos de las cartas de servicios se remite:', array['En el primer trimestre de cada año', 'Dentro del primer semestre de cada año', 'En el mes de enero de cada año', 'En el último trimestre de cada año']::text[], 0, 'El artículo 12.2 dispone que los órganos y organismos remitirán, «en el primer trimestre de cada año, un informe sobre el grado de cumplimiento de los compromisos en el año anterior».', 3, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
