insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inf-025', (select id from leyes where slug = 'rd-951-2005'), '16.1', 'Recibida una queja o sugerencia, la unidad responsable informará al interesado de las actuaciones realizadas en el plazo de:', array['20 días hábiles', '10 días hábiles', '15 días hábiles', 'Un mes']::text[], 0, 'El artículo 16.1 fija que la unidad «informará al interesado de las actuaciones realizadas en el plazo de 20 días hábiles».', 1, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
