insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inf-027', (select id from leyes where slug = 'rd-951-2005'), '16.3', 'Si el ciudadano no recibe respuesta a su queja en el plazo establecido, podrá dirigirse a:', array['El Defensor del Pueblo, como trámite previo obligatorio', 'El Subsecretario, mediante recurso de alzada', 'La Inspección General de Servicios del departamento', 'El órgano que dictó el acto, mediante recurso de reposición']::text[], 2, 'El artículo 16.3 dispone que «el ciudadano podrá dirigirse a la Inspección General de Servicios del departamento correspondiente para conocer los motivos de la falta de contestación».', 2, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
