insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inb-009', null, 'Preguntas más frecuentes (P+F)', '¿Cómo viene configurado de forma predeterminada el Sensor de almacenamiento?', array['Activado en todos los equipos', 'Activado solo en los portátiles', 'Activado tras la primera actualización', 'Desactivado de forma predeterminada']::text[], 3, 'La página responde que «el Sensor de almacenamiento está desactivado de forma predeterminada», aunque Windows puede activarlo si el PC se queda sin espacio en disco.', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
