insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inb-013', null, 'Paso 2: Hacer una copia de seguridad de las carpetas', '¿Cuál de estas carpetas de usuario NO figura entre las que Copias de seguridad de Windows copia en OneDrive?', array['Documentos', 'Imágenes', 'Música', 'Descargas']::text[], 3, 'La página indica: «Puede hacer una copia de seguridad de las carpetas Escritorio , Documentos , Imágenes , Vídeos y Música activando el conmutador de cada carpeta». Descargas no aparece en la lista.', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
