insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inb-015', null, 'Paso 1: iniciar sesión con una cuenta de Microsoft', '¿Con qué tipo de cuenta funciona actualmente la aplicación Copias de seguridad de Windows?', array['Con una cuenta profesional o educativa de Microsoft', 'Con una cuenta local sin conexión a Internet', 'Con una cuenta personal de Microsoft', 'Con la cuenta de administrador del equipo']::text[], 2, 'La aplicación «se centra en dispositivos de consumidor», que usan una «cuenta personal de Microsoft (MSA)». La página advierte: «Las cuentas profesionales o educativas de Microsoft no funcionarán».', 3, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
