insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inb-017', null, 'Realice un examen rápido', 'Si sospechas que hay un virus, ¿en qué sección de Seguridad de Windows se lanza un examen rápido?', array['Firewall y protección de red', 'Control de aplicaciones y navegador', 'Rendimiento y estado del dispositivo', 'Protección contra virus y amenazas']::text[], 3, 'Si sospechas que hay malware, «debes ejecutar inmediatamente un análisis rápido»: en Seguridad de Windows, se selecciona «Protección contra virus & amenazas > Examen rápido».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
