insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inb-018', null, 'Activar o desactivar la protección en tiempo real del Antivirus de Defender', '¿Qué ocurre si desactivas la protección en tiempo real del Antivirus de Microsoft Defender?', array['Se desinstala el antivirus hasta que lo reinstales', 'Al poco tiempo se vuelve a activar sola', 'Se desactiva también el Firewall de Windows', 'Queda desactivada hasta el siguiente mes']::text[], 1, 'Mientras está desactivada, «no se analizarán en busca de amenazas los archivos que abras ni los que descargues». Pero «la protección en tiempo real pronto se activará automáticamente para proteger el dispositivo».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
