insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inb-019', null, 'Configurar Firewall de Windows con Seguridad de Windows', '¿Cuál de estos NO es un perfil de red del Firewall de Windows en Seguridad de Windows?', array['Red de dominio', 'Red privada', 'Red de invitados', 'Red pública']::text[], 2, 'Seguridad de Windows pide: «Selecciona un perfil de red: Red de dominio , Red privada , o Red pública». No existe un perfil de red de invitados.', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
