insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inb-021', null, 'Configurar Firewall de Windows con Seguridad de Windows', '¿Qué hace la casilla «Bloquea todas las conexiones entrantes, incluidas las de la lista de aplicaciones permitidas»?', array['Desactiva el Firewall de Windows en las redes públicas', 'Bloquea solo las aplicaciones que no son de Microsoft Store', 'Restaura el firewall a los valores predeterminados', 'Hace que el firewall ignore la lista de permitidas y bloquee todo']::text[], 3, 'Esa casilla indica «al Firewall de Windows que ignore la lista de aplicaciones permitidas y bloquee todo». «Activar esta opción aumenta la seguridad, pero puede que algunas aplicaciones dejen de funcionar».', 3, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
