insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inb-022', null, 'Protéjase del fraude en línea', '¿Qué es el phishing o suplantación de identidad?', array['Un malware que cifra tus archivos y pide un rescate', 'Un ataque que busca que reveles datos personales en sitios falsos', 'Un programa que muestra anuncios no deseados en el navegador', 'Un fallo del firewall que deja pasar conexiones entrantes']::text[], 1, '«El phishing es un ataque que intenta robar su dinero o su identidad, haciendo que divulgue información personal [...] en sitios web que fingen ser sitios legítimos».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
