insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('inb-023', null, 'Obtenga información sobre cómo detectar un mensaje de phishing', '¿Cuál de estas es una señal de un correo electrónico de phishing?', array['Que te llame por tu nombre y apellidos', 'Que venga del dominio oficial de la empresa', 'Que empiece con «Estimado señor o señora»', 'Que no incluya vínculos ni datos adjuntos']::text[], 2, 'Sobre los saludos genéricos, la página explica: «Si el correo electrónico empieza con un mensaje genérico, como "Estimado señor o señora", es un signo de que puede que no sea realmente su banco o sitio de compras».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
