insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('net-001', null, 'Métodos abreviados de teclado (Windows)', 'En Microsoft Edge para Windows, ¿qué combinación de teclas abre una nueva ventana InPrivate?', array['Ctrl + Mayús + N', 'Ctrl + N', 'Ctrl + Mayús + T', 'Ctrl + Mayús + O']::text[], 0, 'La tabla de Windows asigna a Ctrl + Mayús + N la acción «Abrir una nueva ventana de InPrivate». Ctrl + N abre una ventana normal y Ctrl + Mayús + O abre Favoritos.', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
