insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('net-002', null, 'Métodos abreviados de teclado (Windows)', 'En Microsoft Edge, ¿qué hace la combinación Ctrl + H?', array['Abrir Descargas', 'Abrir historial', 'Abrir Favoritos', 'Abrir Colecciones']::text[], 1, 'Según la tabla de Windows, Ctrl + H sirve para «Abrir historial». Descargas se abre con Ctrl + J y Favoritos con Ctrl + Mayús + O.', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
