insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('net-003', null, 'Métodos abreviados de teclado (Windows)', 'En Microsoft Edge, ¿qué combinación de teclas abre Descargas?', array['Ctrl + H', 'Ctrl + K', 'Ctrl + J', 'Ctrl + U']::text[], 2, 'La tabla indica que Ctrl + J sirve para «Abrir Descargas». Ctrl + H abre el historial y Ctrl + U muestra el origen («Ver origen»).', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
