insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('net-014', null, 'Datos de navegación que puedes eliminar en Microsoft Edge', 'En Microsoft Edge, ¿qué son los «archivos e imágenes en memoria caché»?', array['Copias de páginas e imágenes para cargarlas más rápido', 'Datos que guardan los sitios para recordar preferencias', 'Las direcciones de los sitios visitados con fecha y hora', 'Información escrita en formularios, como la dirección']::text[], 0, 'Son «Copias de páginas, imágenes y otro contenido multimedia almacenado en el dispositivo». El explorador las usa «para cargar el contenido con mayor rapidez la próxima vez que visites esos sitios».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
