insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('net-020', null, 'Eliminar cookies cada vez que se cierra el explorador', 'En Microsoft Edge, ¿qué opción permite eliminar las cookies automáticamente cada vez que se cierra el navegador?', array['Bloquear cookies de terceros', 'Ver todas las cookies y datos del sitio', 'Elegir lo que se debe borrar cada vez que se cierra el explorador', 'Precargar páginas para una exploración más rápida']::text[], 2, 'Hay que seleccionar Borrar datos de exploración y elegir «Elegir lo que se debe borrar cada vez que se cierra el explorador». Luego se activa «Cookies y otros datos del sitio».', 3, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
