insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('net-021', null, '¿De qué manera puede ser útil SmartScreen para protegerme en Microsoft Edge?', 'En Microsoft Edge, ¿para qué sirve SmartScreen de Microsoft Defender?', array['Protege frente a sitios de suplantación de identidad y malware', 'Bloquea la mayor parte de los elementos emergentes', 'Elimina las cookies al cerrar el navegador', 'Impide que se guarde el historial de exploración']::text[], 0, 'SmartScreen de Microsoft Defender «ayuda a proteger su seguridad frente a sitios y software de suplantación de identidad y malware». El bloqueador de elementos emergentes es una función distinta.', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
