insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('net-023', null, '¿Cómo guardo u olvido contraseñas en Microsoft Edge?', 'Si desactivas en Microsoft Edge la opción «Preguntar para guardar contraseñas y claves de paso», ¿qué pasa con las contraseñas ya guardadas?', array['Se eliminan todas automáticamente', 'Se mantienen: no se eliminan', 'Se trasladan a la nube de Microsoft', 'Se eliminan al cerrar el navegador']::text[], 1, 'La página aclara: «Esto no elimina las contraseñas guardadas anteriormente». Para borrarlas hay que ir a Borrar datos de exploración, activar Contraseñas y seleccionar Borrar ahora.', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
