insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('net-024', null, '¿Qué es el sistema de nombres de dominio (DNS)?', '¿Qué función cumple el protocolo DNS?', array['Asigna nombres de dominio a direcciones IP', 'Cifra la comunicación entre navegador y servidor', 'Asigna direcciones IP a los equipos de la red', 'Transfiere páginas web al navegador']::text[], 0, '«DNS es un protocolo estándar del sector que asigna nombres de dominio a direcciones IP, lo que permite la resolución de nombres para computadoras y usuarios».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
