insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('net-025', null, 'Uso de DNS en Windows y Windows Server', '¿En qué capa del modelo de referencia TCP/IP se sitúa el protocolo DNS?', array['Capa de transporte', 'Capa de Internet', 'Capa de acceso a la red', 'Capa de aplicación']::text[], 3, 'La página indica que «DNS forma parte de la capa de aplicación del modelo de referencia TCP/IP».', 3, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
