insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lcsp-003', (select id from leyes where slug = 'ley-9-2017'), '13.3', 'Como regla general, los contratos de obras se referirán a:', array['Una fase independiente de la obra', 'Una obra completa', 'Cada uno de los lotes de la obra', 'El proyecto y la dirección de la obra']::text[], 1, 'El artículo 13.3 dispone: «Los contratos de obras se referirán a una obra completa, entendiendo por esta la susceptible de ser entregada al uso general o al servicio correspondiente».', 1, '2026-10-06', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
