insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lcsp-004', (select id from leyes where slug = 'ley-9-2017'), '14.4', 'En la concesión de obras, el derecho de explotación de las obras debe implicar la transferencia al concesionario de:', array['La titularidad de la obra pública', 'El riesgo de construcción únicamente', 'La potestad de fijar las tarifas', 'Un riesgo operacional en la explotación']::text[], 3, 'El artículo 14.4 establece que el derecho de explotación «deberá implicar la transferencia al concesionario de un riesgo operacional en la explotación de dichas obras abarcando el riesgo de demanda o el de suministro, o ambos».', 2, '2026-10-06', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'lcsp-004', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 19 where o.slug = 'admin-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lcsp-005', (select id from leyes where slug = 'ley-9-2017'), '15.1', 'En el contrato de concesión de servicios, los poderes adjudicadores encomiendan a título oneroso:', array['La ejecución de una obra con derecho a explotarla', 'La gestión de un servicio cuya prestación sea de su titularidad o competencia', 'La adquisición o el arrendamiento de bienes muebles', 'El ejercicio de la autoridad inherente a los poderes públicos']::text[], 1, 'El artículo 15.1 define este contrato como aquel en que poderes adjudicadores encomiendan «a título oneroso a una o varias personas, naturales o jurídicas, la gestión de un servicio cuya prestación sea de su titularidad o competencia».', 1, '2026-10-06', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'lcsp-005', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 19 where o.slug = 'admin-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lcsp-006', (select id from leyes where slug = 'ley-9-2017'), '16.1', 'Son contratos de suministro los que tienen por objeto la adquisición, el arrendamiento financiero o el arrendamiento, con o sin opción de compra, de:', array['Productos o bienes muebles', 'Bienes inmuebles', 'Valores negociables', 'Propiedades incorporales']::text[], 0, 'El artículo 16.1 dice: «Son contratos de suministro los que tienen por objeto la adquisición, el arrendamiento financiero, o el arrendamiento, con o sin opción de compra, de productos o bienes muebles».', 1, '2026-10-06', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
