insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lcse-008', (select id from leyes where slug = 'ley-9-2017'), '45.1', 'El Tribunal Administrativo Central de Recursos Contractuales está compuesto por un Presidente y:', array['Un mínimo de cinco vocales', 'Un máximo de cinco vocales', 'Un mínimo de tres vocales', 'Un mínimo de siete vocales']::text[], 0, 'El artículo 45.1 dispone que el Tribunal «estará compuesto por un Presidente y un mínimo de cinco vocales», cuyo número podrá incrementarse mediante Real Decreto.', 2, '2026-10-06', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
