insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lcse-009', (select id from leyes where slug = 'ley-9-2017'), '49.2', 'El órgano competente debe decidir sobre las medidas cautelares solicitadas antes del recurso especial dentro de:', array['Los dos días hábiles siguientes a la solicitud', 'Los cinco días hábiles siguientes a la solicitud', 'Los diez días hábiles siguientes a la solicitud', 'Los quince días hábiles siguientes a la solicitud']::text[], 1, 'El artículo 49.2 obliga a adoptar decisión motivada sobre las medidas cautelares «dentro de los cinco días hábiles siguientes a la presentación del escrito en que se soliciten». Los dos días hábiles son el plazo de alegaciones del órgano de contratación.', 3, '2026-10-06', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
