insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lcse-025', (select id from leyes where slug = 'ley-9-2017'), '107.1', 'Con carácter general, la garantía definitiva en los contratos de las Administraciones Públicas es del:', array['3 % del presupuesto base de licitación, IVA excluido', '10 % del precio final ofertado, IVA incluido', '5 % del precio final ofertado, IVA excluido', '5 % del valor estimado del contrato']::text[], 2, 'El artículo 107.1 exige constituir «una garantía de un 5 por 100 del precio final ofertado por aquellos, excluido el Impuesto sobre el Valor Añadido».', 1, '2026-10-06', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'lcse-025', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 37 where o.slug = 'admin-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lcse-026', (select id from leyes where slug = 'ley-9-2017'), '107.2', 'En casos especiales puede exigirse una garantía complementaria, de modo que la garantía total pueda alcanzar el:', array['8 % del precio final ofertado', '10 % del precio final ofertado', '15 % del precio final ofertado', '20 % del precio final ofertado']::text[], 1, 'El artículo 107.2 permite una garantía complementaria «de hasta un 5 por 100 del precio final ofertado […] pudiendo alcanzar la garantía total un 10 por 100 del citado precio».', 2, '2026-10-06', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
