insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ljca-001', (select id from leyes where slug = 'ley-29-1998'), '1.1', 'Los Juzgados y Tribunales contencioso-administrativos conocen de las pretensiones relativas a los Decretos legislativos:', array['Cuando excedan los límites de la delegación', 'En todo caso, por tener rango de ley', 'Solo cuando lo solicite el Congreso de los Diputados', 'Cuando vulneren derechos fundamentales']::text[], 0, 'El artículo 1.1 incluye las pretensiones que se deduzcan «con los Decretos legislativos cuando excedan los límites de la delegación».', 1, '2026-03-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
