insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ljca-002', (select id from leyes where slug = 'ley-29-1998'), '1.2.d', 'A efectos de la LJCA, se entienden por Administraciones públicas, entre otras:', array['Las sociedades mercantiles de capital público', 'Las fundaciones del sector público', 'Las Entidades de Derecho público vinculadas a las Comunidades Autónomas', 'Las asociaciones declaradas de utilidad pública']::text[], 2, 'El artículo 1.2.d) incluye «Las Entidades de Derecho público que sean dependientes o estén vinculadas al Estado, las Comunidades Autónomas o las Entidades locales».', 2, '2026-03-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
