insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ljca-003', (select id from leyes where slug = 'ley-29-1998'), '2.a', 'Respecto de los actos del Gobierno, cualquiera que sea su naturaleza, el orden contencioso-administrativo conoce:', array['Solo de los elementos reglados y de la competencia del órgano que dictó el acto', 'Solo de las indemnizaciones que procedan por los daños derivados de su ejecución', 'De su oportunidad política, de sus elementos reglados y de las indemnizaciones', 'De la tutela de los derechos fundamentales, los elementos reglados y las indemnizaciones']::text[], 3, 'El artículo 2.a) atribuye «La protección jurisdiccional de los derechos fundamentales, los elementos reglados y la determinación de las indemnizaciones que fueran procedentes, todo ello en relación con los actos del Gobierno».', 3, '2026-03-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
