insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ljca-004', (select id from leyes where slug = 'ley-29-1998'), '2.e', 'Por responsabilidad patrimonial, las Administraciones públicas no pueden ser demandadas ante los órdenes jurisdiccionales:', array['Penal o social', 'Civil o social', 'Civil o militar', 'Penal o civil']::text[], 1, 'El artículo 2.e) dispone que las Administraciones no pueden «ser demandadas aquellas por este motivo ante los órdenes jurisdiccionales civil o social, aun cuando en la producción del daño concurran con particulares o cuenten con un seguro de responsabilidad».', 2, '2026-03-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
