insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ljca-005', (select id from leyes where slug = 'ley-29-1998'), '3.b', 'No corresponde al orden jurisdiccional contencioso-administrativo:', array['Los contratos administrativos', 'La responsabilidad patrimonial de las Administraciones públicas', 'El recurso contencioso-disciplinario militar', 'Los actos de las Corporaciones de Derecho público en ejercicio de funciones públicas']::text[], 2, 'Según el artículo 3, «No corresponden al orden jurisdiccional contencioso-administrativo» […] «El recurso contencioso-disciplinario militar».', 1, '2026-03-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
