insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ljca-006', (select id from leyes where slug = 'ley-29-1998'), '21.4', 'Si el demandante funda sus pretensiones en la ilegalidad de una disposición general, se considera también parte demandada:', array['A la Administración autora de la disposición, aunque no proceda de ella la actuación recurrida', 'Al Ministerio Fiscal, en defensa de la legalidad de la disposición', 'Solo a la Administración autora de la actuación recurrida', 'Al Consejo de Estado, si informó el proyecto de disposición']::text[], 0, 'El artículo 21.4 dice que, en ese caso, «se considerará también parte demandada a la Administración autora de la misma, aunque no proceda de ella la actuación recurrida».', 3, '2026-03-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
