insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ljca-007', (select id from leyes where slug = 'ley-29-1998'), '11.1.a', 'Los recursos contra las disposiciones generales de los Ministros y Secretarios de Estado corresponden, en única instancia, a:', array['La Sala de lo Contencioso-administrativo del Tribunal Supremo', 'Los Juzgados Centrales de lo Contencioso-administrativo', 'La Sala de lo Contencioso-administrativo del TSJ de Madrid', 'La Sala de lo Contencioso-administrativo de la Audiencia Nacional']::text[], 3, 'Según el artículo 11.1, «La Sala de lo Contencioso-administrativo de la Audiencia Nacional conocerá en única instancia» de los recursos «en relación con las disposiciones generales y los actos de los Ministros».', 2, '2026-03-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
