insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ljca-008', (select id from leyes where slug = 'ley-29-1998'), '13.c', 'Salvo disposición expresa en contrario, al aplicar las reglas de distribución de competencia entre órganos jurisdiccionales:', array['Prevalece la atribución por razón del órgano autor del acto', 'Prevalece la atribución por razón de la materia', 'Prevalece el domicilio del demandante', 'Prevalece la cuantía del asunto']::text[], 1, 'El artículo 13.c) establece que «la atribución de competencia por razón de la materia prevalece sobre la efectuada en razón del órgano administrativo autor del acto».', 3, '2026-03-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
