insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ljca-010', (select id from leyes where slug = 'ley-29-1998'), '19.1.a', 'Están legitimados ante el orden contencioso-administrativo las personas físicas o jurídicas que ostenten:', array['Un derecho subjetivo, exclusivamente', 'Un interés directo y personal', 'La condición de interesado en el procedimiento', 'Un derecho o interés legítimo']::text[], 3, 'El artículo 19.1.a) legitima a «Las personas físicas o jurídicas que ostenten un derecho o interés legítimo».', 1, '2026-03-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
