insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ljca-011', (select id from leyes where slug = 'ley-29-1998'), '19.1.h', 'Cualquier ciudadano puede ejercer la acción popular ante el orden contencioso-administrativo:', array['Siempre que acredite un interés legítimo', 'En cualquier materia, sin limitación', 'En los casos expresamente previstos por las Leyes', 'Solo cuando lo autorice el Ministerio Fiscal']::text[], 2, 'El artículo 19.1.h) legitima a «Cualquier ciudadano, en ejercicio de la acción popular, en los casos expresamente previstos por las Leyes».', 1, '2026-03-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
