insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ljca-012', (select id from leyes where slug = 'ley-29-1998'), '19.2', 'La Administración autora de un acto puede impugnarlo ante el orden contencioso-administrativo:', array['En ningún caso', 'Previa su declaración de lesividad para el interés público', 'Previo dictamen favorable del Consejo de Estado', 'Solo si el acto es nulo de pleno derecho']::text[], 1, 'El artículo 19.2 dice: «La Administración autora de un acto está legitimada para impugnarlo ante este orden jurisdiccional, previa su declaración de lesividad para el interés público en los términos establecidos por la Ley».', 1, '2026-03-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
