insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ljca-013', (select id from leyes where slug = 'ley-29-1998'), '19.1.k', 'Los sindicatos pueden actuar en defensa de los derechos individuales del personal funcionario y estatutario afiliado:', array['Sin necesidad de autorización del afiliado', 'Solo en procesos sobre separación del servicio', 'Solo si el afiliado forma parte de un órgano de representación', 'Si el afiliado lo autoriza, recayendo sobre él los efectos de la actuación']::text[], 3, 'El artículo 19.1.k) legitima a los sindicatos para actuar en interés «del personal funcionario y estatutario afiliado a ellos que así lo autorice, en defensa de sus derechos individuales, recayendo sobre dichos afiliados los efectos de aquella actuación».', 2, '2026-03-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
