insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ljca-014', (select id from leyes where slug = 'ley-29-1998'), '20.a', 'Los miembros de los órganos colegiados de una Administración pueden recurrir contra la actividad de esta:', array['Solo si una Ley lo autoriza expresamente', 'En ningún caso', 'Siempre que ostenten un interés legítimo', 'Solo previa declaración de lesividad']::text[], 0, 'El artículo 20.a) excluye a «Los órganos de la misma y los miembros de sus órganos colegiados, salvo que una Ley lo autorice expresamente».', 2, '2026-03-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
