insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ljca-015', (select id from leyes where slug = 'ley-29-1998'), '23.1', 'En sus actuaciones ante órganos unipersonales, las partes:', array['Deben conferir su representación a un Procurador y ser asistidas por Abogado', 'Pueden comparecer por sí mismas sin Abogado ni Procurador', 'Podrán conferir su representación a un Procurador y serán asistidas, en todo caso, por Abogado', 'Deben ser representadas por Procurador, y la asistencia de Abogado es potestativa']::text[], 2, 'El artículo 23.1 dice: «En sus actuaciones ante órganos unipersonales, las partes podrán conferir su representación a un Procurador y serán asistidas, en todo caso, por Abogado».', 2, '2026-03-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
