insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ljca-016', (select id from leyes where slug = 'ley-29-1998'), '23.2', 'Ante los órganos jurisdiccionales colegiados, las partes:', array['Pueden elegir entre ser representadas por Procurador o por Abogado', 'Deben conferir su representación a un Procurador y ser asistidas por Abogado', 'Solo necesitan ser asistidas por Abogado, sin necesidad de Procurador', 'Pueden comparecer siempre por sí mismas, sin Procurador ni Abogado']::text[], 1, 'El artículo 23.2 dice: «En sus actuaciones ante órganos colegiados, las partes deberán conferir su representación a un Procurador y ser asistidas por Abogado».', 1, '2026-03-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
