insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ljca-017', (select id from leyes where slug = 'ley-29-1998'), '23.3', 'Los funcionarios públicos pueden comparecer por sí mismos en defensa de sus derechos estatutarios cuando:', array['Se trate de cuestiones de personal que no impliquen separación de empleados públicos inamovibles', 'El asunto se tramite ante un órgano jurisdiccional colegiado', 'La cuantía del asunto no supere 30.050 euros', 'Lo autorice el órgano del que dependen']::text[], 0, 'El artículo 23.3 permite comparecer por sí mismos a los funcionarios «cuando se refieran a cuestiones de personal que no impliquen separación de empleados públicos inamovibles».', 2, '2026-03-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
