insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ljca-019', (select id from leyes where slug = 'ley-29-1998'), '26.2', 'La falta de impugnación directa de una disposición general:', array['Impide impugnar después sus actos de aplicación', 'Convierte en firmes los actos dictados en su aplicación', 'No impide impugnar sus actos de aplicación alegando que la disposición no es conforme a Derecho', 'Solo permite impugnar sus actos de aplicación por vicios propios']::text[], 2, 'El artículo 26.2 dice: «La falta de impugnación directa de una disposición general o la desestimación del recurso que frente a ella se hubiera interpuesto no impiden la impugnación de los actos de aplicación».', 3, '2026-03-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
