insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ljca-020', (select id from leyes where slug = 'ley-29-1998'), '28', 'No es admisible el recurso contencioso-administrativo respecto de:', array['Los actos presuntos de la Administración que pongan fin a la vía administrativa', 'Los actos confirmatorios de actos consentidos por no haber sido recurridos en tiempo y forma', 'Los actos de trámite que producen indefensión a los interesados', 'La inactividad de la Administración obligada a una prestación concreta']::text[], 1, 'El artículo 28 excluye «los actos que sean reproducción de otros anteriores definitivos y firmes y los confirmatorios de actos consentidos por no haber sido recurridos en tiempo y forma».', 1, '2026-03-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
