insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ljca-021', (select id from leyes where slug = 'ley-29-1998'), '29.1', 'Si la Administración no cumple la prestación concreta a que está obligada, cabe recurrir por inactividad si no la cumple, desde la reclamación, en:', array['Un mes', 'Seis meses', 'Dos meses', 'Tres meses']::text[], 3, 'El artículo 29.1 dice: «Si en el plazo de tres meses desde la fecha de la reclamación, la Administración no hubiera dado cumplimiento a lo solicitado», los interesados pueden recurrir.', 1, '2026-03-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
