insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ljca-022', (select id from leyes where slug = 'ley-29-1998'), '29.2', 'Si la Administración no ejecuta sus actos firmes, los afectados pueden recurrir si la ejecución no se produce, desde su petición, en el plazo de:', array['Un mes', 'Tres meses', 'Diez días', 'Dos meses']::text[], 0, 'El artículo 29.2 permite recurrir a los afectados si la ejecución «no se produce en el plazo de un mes desde tal petición».', 2, '2026-03-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
