insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ljca-023', (select id from leyes where slug = 'ley-29-1998'), '30', 'En caso de vía de hecho, puede recurrirse directamente si el requerimiento de cesación no es atendido dentro de:', array['Los cinco días siguientes a su presentación', 'El mes siguiente a su presentación', 'Los diez días siguientes a su presentación', 'Los veinte días siguientes a su presentación']::text[], 2, 'El artículo 30 permite recurrir si la intimación «no fuere atendida dentro de los diez días siguientes a la presentación del requerimiento».', 1, '2026-03-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
