insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ljca-025', (select id from leyes where slug = 'ley-29-1998'), '46.1', 'Si el acto que se recurre no es expreso, el plazo para interponer el recurso contencioso-administrativo es de:', array['Dos meses', 'Tres meses', 'Un año', 'Seis meses']::text[], 3, 'El artículo 46.1 añade, para el acto no expreso: «Si no lo fuera, el plazo será de seis meses».', 2, '2026-03-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
