insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ljca-026', (select id from leyes where slug = 'ley-29-1998'), '46.3', 'Si no hubo requerimiento previo, el plazo para recurrir una actuación en vía de hecho es de:', array['Veinte días desde que se inició la actuación', 'Diez días desde que se inició la actuación', 'Dos meses desde que se inició la actuación', 'Un mes desde que cesó la actuación']::text[], 0, 'El artículo 46.3 dice: «Si no hubiere requerimiento, el plazo será de veinte días desde el día en que se inició la actuación administrativa en vía de hecho».', 3, '2026-03-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
