insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ljca-027', (select id from leyes where slug = 'ley-29-1998'), '45.3', 'Si con el escrito de interposición no se acompañan los documentos exigidos, se requerirá su subsanación en un plazo de:', array['Cinco días', 'Quince días', 'Diez días', 'Veinte días']::text[], 2, 'El artículo 45.3 indica que se «requerirá inmediatamente la subsanación de los mismos, señalando un plazo de diez días para que el recurrente pueda llevarla a efecto».', 2, '2026-03-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
