insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ljca-028', (select id from leyes where slug = 'ley-29-1998'), '69.e', 'La sentencia declarará la inadmisibilidad del recurso cuando:', array['El acto impugnado incurra en desviación de poder', 'El escrito inicial se haya presentado fuera del plazo establecido', 'El acto impugnado sea conforme a Derecho', 'La Administración no haya remitido el expediente']::text[], 1, 'El artículo 69.e) prevé la inadmisibilidad «Que se hubiera presentado el escrito inicial del recurso fuera del plazo establecido».', 1, '2026-03-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
