insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ljca-029', (select id from leyes where slug = 'ley-29-1998'), '70.2', 'Según la LJCA, se entiende por desviación de poder:', array['El ejercicio de potestades por un órgano manifiestamente incompetente', 'La omisión total del procedimiento legalmente establecido', 'La falta de motivación de los actos discrecionales', 'El ejercicio de potestades administrativas para fines distintos de los fijados por el ordenamiento']::text[], 3, 'El artículo 70.2 dice: «Se entiende por desviación de poder el ejercicio de potestades administrativas para fines distintos de los fijados por el ordenamiento jurídico».', 1, '2026-03-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
