insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pdd-002', (select id from leyes where slug = 'lo-3-2018'), '12.4', 'La prueba del cumplimiento del deber de responder a la solicitud de ejercicio de derechos del afectado recae sobre:', array['El encargado del tratamiento', 'El responsable del tratamiento', 'El delegado de protección de datos', 'El propio afectado']::text[], 1, 'El artículo 12.4 establece que la prueba del cumplimiento del deber de responder a la solicitud «recaerá sobre el responsable».', 1, '2025-12-28', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
