insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pdd-003', (select id from leyes where slug = 'lo-3-2018'), '12.3', 'El encargado puede tramitar, por cuenta del responsable, las solicitudes de ejercicio de derechos de los afectados:', array['Solo si lo autoriza la Agencia Española de Protección de Datos', 'Siempre que lo solicite el propio afectado', 'Si así se establece en el contrato o acto jurídico que les vincule', 'Únicamente cuando el responsable no haya designado delegado']::text[], 2, 'El artículo 12.3 dice que el encargado podrá tramitar las solicitudes «si así se estableciere en el contrato o acto jurídico que les vincule».', 2, '2025-12-28', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
