insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pdd-009', (select id from leyes where slug = 'lo-3-2018'), '34.3', 'Las designaciones, nombramientos y ceses de los delegados de protección de datos se comunican a la autoridad de protección de datos en el plazo de:', array['Diez días', 'Un mes', 'Quince días', 'Cinco días']::text[], 0, 'El artículo 34.3 dispone que los responsables y encargados «comunicarán en el plazo de diez días a la Agencia Española de Protección de Datos […] las designaciones, nombramientos y ceses de los delegados de protección de datos».', 1, '2025-12-28', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
