insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pdd-014', (select id from leyes where slug = 'lo-3-2018'), '46.2', 'La Presidencia de la Agencia Española de Protección de Datos puede autorizar modificaciones presupuestarias que impliquen hasta un:', array['Uno por ciento de su presupuesto total de gastos', 'Tres por ciento de la cifra inicial de su presupuesto total de gastos', 'Cinco por ciento de la cifra inicial de su presupuesto total de gastos', 'Diez por ciento de su presupuesto total de gastos']::text[], 1, 'El artículo 46.2 atribuye a la Presidencia «autorizar las modificaciones presupuestarias que impliquen hasta un tres por ciento de la cifra inicial de su presupuesto total de gastos, siempre que no se incrementen los créditos para gastos de personal».', 3, '2025-12-28', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
