insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pdd-015', (select id from leyes where slug = 'lo-3-2018'), '48.6', 'Los actos y disposiciones de la Presidencia de la Agencia Española de Protección de Datos son recurribles directamente ante:', array['El Tribunal Supremo', 'El Consejo de Ministros', 'La Sala de lo Contencioso-administrativo de la Audiencia Nacional', 'Los Juzgados Centrales de lo Contencioso-administrativo']::text[], 2, 'El artículo 48.6 dice que estos actos «ponen fin a la vía administrativa, siendo recurribles, directamente, ante la Sala de lo Contencioso-administrativo de la Audiencia Nacional».', 1, '2025-12-28', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
