insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pdd-016', (select id from leyes where slug = 'lo-3-2018'), '48.3', 'La propuesta de Presidencia y Adjunto de la Agencia debe ser ratificada por la Comisión de Justicia del Congreso, en primera votación, por mayoría de:', array['Dos tercios de sus miembros', 'Absoluta de sus miembros', 'Simple de los presentes', 'Tres quintos de sus miembros']::text[], 3, 'El artículo 48.3 exige la ratificación por la Comisión de Justicia «en votación pública por mayoría de tres quintos de sus miembros en primera votación o, de no alcanzarse ésta, por mayoría absoluta en segunda votación».', 3, '2025-12-28', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
