insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pdd-017', (select id from leyes where slug = 'lo-3-2018'), '49.4', 'El Consejo Consultivo de la Agencia Española de Protección de Datos se reúne, en todo caso:', array['Una vez al semestre', 'Una vez al trimestre', 'Una vez al año', 'Una vez al mes']::text[], 0, 'El artículo 49.4 establece que el Consejo Consultivo se reunirá cuando lo disponga la Presidencia «y, en todo caso, una vez al semestre».', 1, '2025-12-28', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
