insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pdd-022', (select id from leyes where slug = 'lo-3-2018'), '76.4', 'Se publica en el BOE la identidad del infractor sancionado por la AEPD cuando sea persona jurídica y la sanción supere:', array['Trescientos mil euros', 'Un millón de euros', 'Quinientos mil euros', 'Veinte millones de euros']::text[], 1, 'El artículo 76.4 prevé esa publicación cuando la autoridad competente sea la Agencia, «la sanción fuese superior a un millón de euros y el infractor sea una persona jurídica».', 3, '2025-12-28', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
