insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pdd-025', (select id from leyes where slug = 'lo-3-2018'), '89.2', '¿En qué lugares no se admite en ningún caso la instalación de sistemas de videovigilancia o grabación de sonidos en el trabajo?', array['En los destinados al descanso o esparcimiento, como vestuarios, aseos o comedores', 'En los accesos y zonas de entrada al centro de trabajo', 'En las oficinas de atención al público', 'En los almacenes y zonas de carga']::text[], 0, 'El artículo 89.2 dispone que «en ningún caso se admitirá la instalación de sistemas de grabación de sonidos ni de videovigilancia en lugares destinados al descanso o esparcimiento de los trabajadores o los empleados públicos, tales como vestuarios, aseos, comedores y análogos».', 1, '2025-12-28', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
