insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pd-019', (select id from leyes where slug = 'lo-3-2018'), '12.1', 'Los derechos de los artículos 15 a 22 del Reglamento (UE) 2016/679 pueden ejercerse:', array['Solo directamente por el afectado', 'Solo a través de abogado', 'Solo a través de la Agencia Española de Protección de Datos', 'Directamente o por medio de representante legal o voluntario']::text[], 3, 'El artículo 12.1 dice que estos derechos «podrán ejercerse directamente o por medio de representante legal o voluntario».', 1, '2025-12-28', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
