insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pd-020', (select id from leyes where slug = 'lo-3-2018'), '12.7', 'Las actuaciones del responsable para atender las solicitudes de ejercicio de derechos son, como regla general:', array['De pago según tarifa oficial', 'Gratuitas solo para menores de edad', 'Gratuitas', 'Gratuitas solo la primera vez cada año']::text[], 2, 'El artículo 12.7 dice: «Serán gratuitas las actuaciones llevadas a cabo por el responsable del tratamiento para atender las solicitudes de ejercicio de estos derechos», sin perjuicio de lo previsto en el Reglamento.', 2, '2025-12-28', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
