insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('mf-001', (select id from leyes where slug = 'ley-50-1981'), '2.1', 'Según el Estatuto Orgánico del Ministerio Fiscal, este está integrado con autonomía funcional en:', array['El Poder Judicial', 'El Gobierno de la Nación', 'Las Cortes Generales', 'El Consejo General del Poder Judicial']::text[], 0, 'El artículo 2.1 dice que el Ministerio Fiscal es «un órgano de relevancia constitucional con personalidad jurídica propia, integrado con autonomía funcional en el Poder Judicial».', 1, '2026-07-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
