insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('mf-008', (select id from leyes where slug = 'ley-50-1981'), '14.1', 'En la elección de los Vocales del Consejo Fiscal, cada uno de los sexos debe suponer como mínimo:', array['El cincuenta por ciento de los Vocales electos', 'El treinta por ciento de los Vocales electos', 'El treinta y tres por ciento de los Vocales electos', 'El cuarenta por ciento de los Vocales electos']::text[], 3, 'El artículo 14.1 exige atender al principio de presencia equilibrada, «de forma que cada uno de los sexos suponga como mínimo el cuarenta por ciento de los Vocales electos».', 3, '2026-07-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
