insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('mf-012', (select id from leyes where slug = 'ley-50-1981'), '29.1', 'El Fiscal General del Estado se elige entre juristas españoles de reconocido prestigio con:', array['Más de diez años de ejercicio efectivo de su profesión', 'Más de veinte años de ejercicio efectivo de su profesión', 'Más de doce años de ejercicio efectivo de su profesión', 'Más de quince años de ejercicio efectivo de su profesión']::text[], 3, 'El artículo 29.1 dice que se elige «entre juristas españoles de reconocido prestigio con más de quince años de ejercicio efectivo de su profesión».', 1, '2026-07-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
