insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('mf-013', (select id from leyes where slug = 'ley-50-1981'), '29.1', 'No puede ser propuesto Fiscal General del Estado quien haya sido titular de un Ministerio:', array['En los cinco años anteriores', 'En los dos años anteriores', 'En los tres años anteriores', 'En los cuatro años anteriores']::text[], 0, 'El artículo 29.1 dice: «No podrá ser propuesto para el cargo quien en los cinco años anteriores haya sido nombrado titular de un Ministerio […]».', 2, '2026-07-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
