insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('mf-018', (select id from leyes where slug = 'ley-50-1981'), '31.3', '¿Quién aprecia que concurre una causa de cese del Fiscal General del Estado, como la incapacidad o el incumplimiento grave de funciones?', array['El Consejo General del Poder Judicial', 'El Consejo de Ministros', 'El Consejo Fiscal', 'El Pleno del Tribunal Supremo']::text[], 1, 'El artículo 31.3 dice: «La existencia de las causas de cese mencionadas en los apartados a), b), c) y d) del número anterior será apreciada por el Consejo de Ministros».', 2, '2026-07-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
