insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('mf-019', (select id from leyes where slug = 'ley-50-1981'), '30', 'En los actos oficiales, el Fiscal General del Estado ocupa el lugar inmediato siguiente al de:', array['El Ministro de Justicia', 'El Presidente del Consejo de Estado', 'El Presidente del Tribunal Supremo', 'El Presidente del Tribunal Constitucional']::text[], 2, 'El artículo 30 dice: «En los actos oficiales ocupará el lugar inmediato siguiente al del Presidente del Tribunal Supremo».', 1, '2026-07-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
