insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('mf-020', (select id from leyes where slug = 'ley-50-1981'), '13.2', '¿A quién corresponde ejercer la inspección ordinaria de las Fiscalías del ámbito territorial de una Comunidad Autónoma?', array['Al Fiscal Jefe Inspector', 'Al Consejo Fiscal', 'A la Junta de Fiscales de Sala', 'Al Fiscal Superior de la Comunidad Autónoma']::text[], 3, 'El artículo 13.2 dice: «En todo caso, corresponde al Fiscal Superior de la Comunidad Autónoma ejercer la inspección ordinaria de las Fiscalías de su ámbito territorial».', 2, '2026-07-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
