insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('muf-001', (select id from leyes where slug = 'rdleg-4-2000'), '2.1', 'El Régimen especial de Seguridad Social de los Funcionarios Civiles del Estado queda integrado por los mecanismos de cobertura de:', array['El Régimen General de la Seguridad Social y MUFACE', 'El Régimen de Clases Pasivas y el Mutualismo Administrativo', 'El Régimen de Clases Pasivas y el Régimen General', 'El Mutualismo Administrativo y la asistencia social']::text[], 1, 'El artículo 2.1 lo integra por «a) El Régimen de Clases Pasivas del Estado, de acuerdo con sus normas específicas. b) El Régimen del Mutualismo Administrativo que se regula en la presente Ley».', 1, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
