insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('muf-002', (select id from leyes where slug = 'rdleg-4-2000'), '2.2', 'Los funcionarios de carrera de la Administración Civil del Estado ingresados a partir del 1 de enero de 2011 quedan integrados en el Régimen General de la Seguridad Social:', array['A todos los efectos, incluida la asistencia sanitaria', 'Solo a efectos de incapacidad temporal', 'A efectos de asistencia sanitaria y pensiones', 'A los exclusivos efectos de pensiones']::text[], 3, 'Según el artículo 2.2, los que «hayan ingresado a partir del 1 de enero de 2011, quedarán integrados en el Régimen General de la Seguridad Social a los exclusivos efectos de pensiones».', 2, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
