insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('muf-003', (select id from leyes where slug = 'rdleg-4-2000'), '3.2.a', 'Queda excluido del Régimen especial de Seguridad Social de los Funcionarios Civiles del Estado:', array['El funcionario de la Administración Local', 'El funcionario de carrera de la Administración Civil del Estado', 'El funcionario en prácticas que aspira a un Cuerpo civil del Estado', 'El funcionario interino del Decreto-ley 10/1965']::text[], 0, 'El artículo 3.2 dispone: «Quedan excluidos de este Régimen especial y se regirán por sus normas específicas: a) Los funcionarios de la Administración Local».', 2, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
