insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('muf-004', (select id from leyes where slug = 'rdleg-4-2000'), '5.1', 'MUFACE se rige por las previsiones de la Ley de Organización y Funcionamiento de la Administración General del Estado relativas a:', array['Las entidades públicas empresariales', 'Las agencias estatales', 'Los organismos autónomos', 'Las sociedades mercantiles estatales']::text[], 2, 'El artículo 5.1 dice que MUFACE «se regirá por las previsiones de la Ley 6/1997, de 14 de abril, de Organización y Funcionamiento de la Administración General del Estado, relativas a los organismos autónomos».', 2, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
