insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('muf-005', (select id from leyes where slug = 'rdleg-4-2000'), '7.1', 'Los funcionarios de carrera de la Administración Civil del Estado se incorporan obligatoriamente como mutualistas a MUFACE:', array['En el momento de la toma de posesión de su cargo', 'En la fecha de su nombramiento como funcionarios', 'Al superar el proceso selectivo', 'Al publicarse su nombramiento en el BOE']::text[], 0, 'Según el artículo 7.1, se incorporan obligatoriamente como mutualistas a MUFACE «en el momento de la toma de posesión de su cargo».', 1, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
