insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('muf-006', (select id from leyes where slug = 'rdleg-4-2000'), '7.1.d', 'Conserva la condición de mutualista, con los mismos derechos y obligaciones que en servicio activo, el funcionario que pasa a:', array['Excedencia voluntaria por interés particular', 'Excedencia forzosa', 'Excedencia voluntaria por agrupación familiar', 'Excedencia voluntaria incentivada']::text[], 1, 'El artículo 7.1 mantiene la condición de mutualista en, entre otras, la situación de «d) Excedencia forzosa». El artículo 8.1.a) da de baja a los que pasen a «excedencia voluntaria, en cualquiera de sus modalidades».', 2, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
