insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('muf-007', (select id from leyes where slug = 'rdleg-4-2000'), '7.3', 'El funcionario que, por promoción interna, queda incluido en el Régimen General y desea seguir siendo mutualista debe optar en el plazo de:', array['Un mes desde la toma de posesión', 'Diez días desde el nombramiento', 'Tres meses desde el nombramiento', 'Quince días desde la toma de posesión']::text[], 3, 'El artículo 7.3 indica que «deberán ejercitar esta opción, por una sola vez, en el plazo de quince días desde la toma de posesión en el nuevo Cuerpo o Escala».', 3, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
