insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('muf-008', (select id from leyes where slug = 'rdleg-4-2000'), '8.2', 'Quienes mantienen facultativamente el alta en MUFACE como mutualistas voluntarios deben abonar:', array['Solo la cuota del funcionario', 'La cuota del funcionario y la mitad de la del Estado', 'A su cargo las cuotas del funcionario y del Estado', 'Ninguna cuota mientras dure la excedencia']::text[], 2, 'Según el artículo 8.2, pueden mantener el alta «siempre que abonen exclusivamente a su cargo las cuotas correspondientes al funcionario y al Estado».', 2, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
