insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('muf-009', (select id from leyes where slug = 'rdleg-4-2000'), '10.1', 'No están obligados a cotizar a MUFACE:', array['Los mutualistas en expectativa de destino', 'Los mutualistas en suspensión provisional de funciones', 'Los mutualistas en excedencia forzosa', 'Los mutualistas jubilados']::text[], 3, 'El artículo 10.1 establece que la cotización es obligatoria para todos los mutualistas, «con excepción de los mutualistas jubilados y de quienes se encuentren en la situación de excedencia voluntaria para atender al cuidado de hijos o familiares».', 2, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
