insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('muf-010', (select id from leyes where slug = 'rdleg-4-2000'), '15.3', 'MUFACE presta asistencia sanitaria al recién nacido de madre mutualista, aunque no tenga reconocida la condición de beneficiario, durante:', array['El primer mes desde el parto', 'Los primeros quince días desde el parto', 'Los primeros diez días desde el parto', 'Los tres primeros meses desde el parto']::text[], 1, 'El artículo 15.3 lo admite «en el caso del recién nacido cuando la madre sea mutualista o beneficiaria […] durante los primeros quince días desde el momento del parto».', 3, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
