insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('muf-011', (select id from leyes where slug = 'rdleg-4-2000'), '17.1', 'Los conciertos de MUFACE para facilitar la asistencia sanitaria se establecerán preferentemente con:', array['Instituciones de la Seguridad Social', 'Entidades de seguro privadas', 'Hospitales de la Administración militar', 'Colegios oficiales de médicos']::text[], 0, 'El artículo 17.1 dice que la asistencia se facilita directamente o por concierto y que «Estos conciertos se establecerán preferentemente con instituciones de la Seguridad Social».', 1, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
