insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('muf-012', (select id from leyes where slug = 'rdleg-4-2000'), '21.1.b', 'En incapacidad temporal, el mutualista empieza a percibir el subsidio a cargo de MUFACE:', array['Desde el primer día de licencia', 'Desde el segundo mes', 'Desde el cuarto mes', 'Desde el séptimo mes']::text[], 2, 'El artículo 21.1.b) dice: «Desde el cuarto mes percibirá las retribuciones básicas, la prestación por hijo a cargo, en su caso, y un subsidio por incapacidad temporal a cargo de la Mutualidad». Los tres primeros meses cobra la totalidad de sus retribuciones.', 1, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
