insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('muf-013', (select id from leyes where slug = 'rdleg-4-2000'), '21.1.b', 'El subsidio de MUFACE por incapacidad temporal es la mayor de dos cantidades: el 80 % de las retribuciones básicas del tercer mes de licencia y:', array['El 75 % de las retribuciones complementarias del tercer mes de licencia', 'El 80 % de las retribuciones complementarias del tercer mes de licencia', 'El 100 % de las retribuciones complementarias del tercer mes de licencia', 'El 75 % de las retribuciones complementarias del primer mes de licencia']::text[], 0, 'El artículo 21.1.b) fija como segunda cantidad «2.ª El 75 por ciento de las retribuciones complementarias devengadas en el tercer mes de licencia».', 3, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
