insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('muf-014', (select id from leyes where slug = 'rdleg-4-2000'), '22.1', 'Las situaciones de riesgo durante el embarazo o la lactancia natural tienen la misma consideración que la incapacidad temporal derivada de:', array['Enfermedad común', 'Accidente no laboral', 'Accidente en acto de servicio', 'Enfermedad profesional']::text[], 3, 'El artículo 22.1 dice que estas situaciones «tendrán la misma consideración que la situación de incapacidad temporal derivada de enfermedad profesional, por lo que no requerirán de periodo de carencia».', 2, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
