insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('muf-016', (select id from leyes where slug = 'rdleg-4-2000'), '26', 'La gran invalidez da derecho a una cantidad mensual, para remunerar a la persona que asiste al funcionario, equivalente al:', array['25 % de su pensión de jubilación de Clases Pasivas', '50 % de su haber regulador', '50 % de su pensión de jubilación de Clases Pasivas', '100 % de su pensión de jubilación de Clases Pasivas']::text[], 2, 'El artículo 26 reconoce «una cantidad mensual equivalente al 50 por 100 de la pensión de jubilación que le corresponda con arreglo al Régimen de Clases Pasivas, destinada a remunerar a la persona encargada de su asistencia».', 2, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
