insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('muf-017', (select id from leyes where slug = 'rdleg-4-2000'), '35.2', 'La cuantía de las aportaciones del Estado a MUFACE se fija:', array['Anualmente en la Ley de Presupuestos Generales del Estado', 'Por acuerdo del Consejo de Ministros cada tres años', 'Por acuerdo del Consejo General de MUFACE', 'Por real decreto con vigencia indefinida']::text[], 0, 'El artículo 35.2 dice: «La cuantía de las aportaciones estatales se fijará anualmente en la Ley de Presupuestos Generales del Estado, mediante el establecimiento de un porcentaje aplicable sobre los haberes reguladores».', 1, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
