insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('muf-018', (select id from leyes where slug = 'rdleg-4-2000'), '37.1', 'Con carácter general, los actos y resoluciones del Director general de MUFACE:', array['Ponen fin a la vía administrativa y cabe reposición potestativa', 'Solo pueden recurrirse ante la jurisdicción social', 'Se recurren en alzada ante el Consejo General de MUFACE', 'No ponen fin a la vía administrativa y cabe recurso de alzada']::text[], 3, 'El artículo 37.1 dice que esos actos «no ponen fin a la vía administrativa, pudiéndose recurrir en alzada ante el Ministro».', 3, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
