insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('muf-019', (select id from leyes where slug = 'rdleg-670-1987'), '1.1', 'A través del Régimen de Clases Pasivas, el Estado protege a su personal frente a los riesgos de:', array['Enfermedad, maternidad y desempleo', 'Vejez, desempleo e incapacidad temporal', 'Vejez, incapacidad y muerte y supervivencia', 'Asistencia sanitaria, incapacidad y cargas familiares']::text[], 2, 'El artículo 1.1 dice que el Estado garantiza a ese personal «la protección frente a los riesgos de vejez, incapacidad y muerte y supervivencia».', 1, '2026-03-26', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
