insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('muf-020', (select id from leyes where slug = 'rdleg-670-1987'), '2.2', 'El ámbito personal de cobertura del Régimen de Clases Pasivas solo podrá ampliarse o restringirse:', array['Por real decreto', 'Por ley', 'Por acuerdo del Consejo de Ministros', 'Por orden ministerial']::text[], 1, 'El artículo 2.2 dice: «Este ámbito personal de cobertura del Régimen de Clases sólo podrá ser ampliado o restringido por Ley».', 1, '2026-03-26', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
