insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('muf-021', (select id from leyes where slug = 'rdleg-670-1987'), '18.2', 'Las prestaciones de Clases Pasivas se concretan en pensiones de jubilación o retiro, de viudedad, de orfandad y:', array['En favor de los hermanos', 'En favor de los nietos', 'Por incapacidad temporal', 'En favor de los padres']::text[], 3, 'El artículo 18.2 dice que se concretan «en las pensiones de jubilación o retiro, de viudedad, de orfandad y en favor de los padres que se regulan en este texto».', 2, '2026-03-26', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
