insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('muf-023', (select id from leyes where slug = 'rdleg-670-1987'), '28.2.b', 'La jubilación voluntaria se declara a instancia de parte siempre que el interesado tenga cumplidos:', array['60 años de edad y 30 años de servicios efectivos al Estado', '65 años de edad y 15 años de servicios efectivos al Estado', '60 años de edad y 15 años de servicios efectivos al Estado', '61 años de edad y 35 años de servicios efectivos al Estado']::text[], 0, 'El artículo 28.2.b) exige que el interesado «tenga cumplidos los sesenta años de edad y reconocidos treinta años de servicios efectivos al Estado».', 1, '2026-03-26', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
