insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('muf-024', (select id from leyes where slug = 'rdleg-670-1987'), '29', 'Para causar derecho a pensión ordinaria de jubilación, el funcionario debe haber completado un período de servicios efectivos al Estado de:', array['Diez años', 'Quince años', 'Veinte años', 'Treinta y cinco años']::text[], 1, 'El artículo 29 exige «haber completado quince años de servicios efectivos al Estado».', 1, '2026-03-26', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
