insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('muf-025', (select id from leyes where slug = 'rdleg-670-1987'), '28.2.a', 'Al cumplir la edad de jubilación forzosa, puede pedir prórroga en el servicio activo el funcionario que tenga reconocidos:', array['Diez años de servicios y no haya completado quince', 'Quince años de servicios y no haya completado treinta', 'Doce años de servicios y no haya completado quince', 'Doce años de servicios y no haya completado veinte']::text[], 2, 'Según el artículo 28.2.a), si al cumplir la edad «tuviera reconocidos doce años de servicios efectivos al Estado y no hubiera completado los quince […] podrá solicitar prorroga en el servicio activo».', 3, '2026-03-26', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
