insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('muf-026', (select id from leyes where slug = 'rdleg-670-1987'), '28.2.c', 'La jubilación por incapacidad permanente para el servicio se declara:', array['Solo a instancia del interesado', 'Solo de oficio, a propuesta de MUFACE', 'De forma automática al cumplir la edad legal', 'De oficio o a instancia de parte']::text[], 3, 'El artículo 28.2.c) dice que la jubilación por incapacidad permanente para el servicio o inutilidad «se declarará de oficio o a instancia de parte».', 2, '2026-03-26', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
