insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('muf-027', (select id from leyes where slug = 'rdleg-670-1987'), '30.1', 'Los haberes reguladores para calcular las pensiones de jubilación de Clases Pasivas se establecen:', array['En el propio texto refundido, con carácter permanente', 'Por real decreto cada cinco años', 'En la Ley de Presupuestos Generales del Estado de cada ejercicio', 'Por resolución anual de MUFACE']::text[], 2, 'El artículo 30.1 dice que los haberes reguladores «se establecerán en la Ley de Presupuestos Generales del Estado para cada ejercicio económico».', 2, '2026-03-26', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
