insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('muf-028', (select id from leyes where slug = 'rdleg-670-1987'), '38.1', 'Si la muerte deriva de enfermedad común no sobrevenida tras el matrimonio, la viudedad exige, en general, que este se celebrara con una antelación mínima de:', array['Un año', 'Seis meses', 'Dos años', 'Cinco años']::text[], 0, 'El artículo 38.1 requiere «que el matrimonio se hubiera celebrado con un año de antelación como mínimo a la fecha del fallecimiento», salvo hijos comunes o convivencia previa que sume más de dos años.', 2, '2026-03-26', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
