insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('terr-023', (select id from leyes where slug = 'constitucion'), '151.1', 'En la vía del artículo 151.1, además de las Diputaciones, la iniciativa debe acordarse por los municipios de cada provincia en proporción de:', array['Tres cuartas partes', 'Dos terceras partes', 'Tres quintas partes', 'La mayoría absoluta']::text[], 0, 'El artículo 151.1 exige que la iniciativa se acuerde, además de por las Diputaciones, «por las tres cuartas partes de los municipios de cada una de las provincias afectadas».', 3, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
