insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('terr-024', (select id from leyes where slug = 'constitucion'), '151.2', 'En el procedimiento del artículo 151.2, la Comisión Constitucional del Congreso examina el proyecto de Estatuto en el plazo de:', array['Un mes', 'Tres meses', 'Dos meses', 'Seis meses']::text[], 2, 'El artículo 151.2.2.º dice que el proyecto se remitirá a la Comisión Constitucional del Congreso, «la cual, dentro del plazo de dos meses, lo examinará».', 3, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
