insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('out-005', null, 'Crear un mensaje de correo electrónico en el nuevo Outlook', 'En el nuevo Outlook, al seleccionar el botón Para, CC o CCO de un mensaje, ¿qué ventana se abre?', array['Agregar destinatarios', 'Libreta de contactos', 'Seleccionar remitentes', 'Contactos sugeridos']::text[], 0, 'La página indica: «Al seleccionar el botón Para , CC o CCO , se abrirá la ventana Agregar destinatarios». Allí se selecciona + junto a cada nombre y después Guardar.', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
