insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('out-006', null, 'Mostrar, ocultar y ver el campo CCO (copia carbón oculta)', '¿Qué ocurre cuando escribe el nombre de un destinatario en el campo CCO de un correo?', array['Recibe una copia y su nombre es visible para todos los destinatarios', 'Recibe una copia sin que su nombre sea visible para los demás destinatarios', 'Solo recibe el mensaje si alguien selecciona Responder a todos', 'Recibe un aviso de lectura, pero no el texto del mensaje']::text[], 1, 'Con el campo CCO (copia carbón oculta), «ese destinatario recibe una copia del correo electrónico sin que el nombre sea visible para los demás destinatarios».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
