insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('out-008', null, 'Desactivar CCO', 'En Outlook clásico, ¿qué indica un fondo oscuro en el botón CCO?', array['Que hay destinatarios ocultos en el mensaje', 'Que el mensaje se ha marcado como no deseado', 'Que el campo CCO está desactivado', 'Que el campo CCO está activado']::text[], 3, 'Según Microsoft, el color de fondo distingue el estado del botón: «Un fondo oscuro significa que está activado y un fondo claro significa que está desactivado».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
