insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('out-013', null, 'Crear una regla a partir de una plantilla en Outlook clásico para Windows', 'En Outlook clásico, ¿qué ruta permite crear una regla a partir de una plantilla?', array['Archivo > Administrar reglas y alertas > Nueva regla', 'Archivo > Opciones > Correo > Nueva regla', 'Vista > Configuración de vista > Nueva regla', 'Insertar > Elemento de Outlook > Nueva regla']::text[], 0, 'Para crear una regla a partir de una plantilla en Outlook clásico se elige Archivo > «Administrar reglas & Alertas» > nueva regla y, después, «Seleccione una plantilla».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
