insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('out-018', null, 'Resumen', '¿Qué hacen las respuestas automáticas de fuera de la oficina en Outlook?', array['Reenvían los mensajes recibidos a otra dirección de correo', 'Envían un mensaje personalizado una vez a cada persona que le escribe', 'Responden a cada mensaje recibido, aunque sea de la misma persona', 'Mueven los mensajes recibidos a una carpeta de ausencias']::text[], 1, 'Según Microsoft, esta función «envía automáticamente un mensaje personalizado una vez a cada persona que le envíe un correo electrónico durante su ausencia».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
