insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('out-019', null, 'Determinar el tipo de cuenta de correo electrónico', 'En Outlook clásico, ¿dónde se encuentra el botón Respuestas automáticas?', array['En la pestaña Inicio, grupo Mover', 'En la pestaña Vista, grupo Diseño', 'En la pestaña Archivo', 'En la pestaña Enviar y recibir']::text[], 2, 'Para comprobarlo hay que seleccionar Archivo: «Seleccione Archivo en el extremo izquierdo de la cinta de opciones». Si aparece el botón Respuestas automáticas, se configuran desde ahí.', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
