insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('out-030', null, 'Adjuntar una tarjeta de presentación, un calendario o un correo electrónico a un mensaje de correo electrónico en Outlook clásico', 'En Outlook clásico, en Adjuntar archivo > Adjuntar elemento, ¿qué opción permite incluir una tarjeta electrónica de su lista de contactos?', array['Calendario', 'Tarjeta de presentación', 'Elemento de Outlook', 'Firma']::text[], 1, 'Al seleccionar Adjuntar archivo > Adjuntar elemento, la opción Tarjeta de presentación permite: «Elija una tarjeta de presentación electrónica de su lista de contactos».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
