insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lab-002', (select id from leyes where slug = 'trebep'), '7', 'En materia de permisos de nacimiento, adopción, lactancia y parental, el personal laboral de las Administraciones públicas se rige por:', array['El Estatuto de los Trabajadores, como regla general', 'El convenio colectivo aplicable en cada caso', 'Lo previsto en el propio TREBEP', 'El régimen de la Seguridad Social que le corresponda']::text[], 2, 'Según el artículo 7, en esas materias «el personal laboral al servicio de las Administraciones públicas se regirá por lo previsto en el presente Estatuto», sin que se apliquen las previsiones del Estatuto de los Trabajadores sobre suspensión del contrato.', 3, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'lab-002', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 30 where o.slug = 'admin-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lab-003', (select id from leyes where slug = 'trebep'), '11.1', 'En función de la duración del contrato, el personal laboral de las Administraciones Públicas puede ser:', array['Fijo, interino o eventual', 'Fijo, por tiempo indefinido o temporal', 'Indefinido, de carrera o temporal', 'Fijo, discontinuo o en prácticas']::text[], 1, 'El artículo 11.1 señala: «En función de la duración del contrato éste podrá ser fijo, por tiempo indefinido o temporal».', 1, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
