insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lab-004', (select id from leyes where slug = 'trebep'), '11.3', 'Además de por los de igualdad, mérito y capacidad, la selección del personal laboral temporal se rige por el principio de:', array['Celeridad', 'Antigüedad', 'Oralidad', 'Proximidad']::text[], 0, 'El artículo 11.3 añade: «En el caso del personal laboral temporal se regirá igualmente por el principio de celeridad, teniendo por finalidad atender razones expresamente justificadas de necesidad y urgencia».', 2, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
