insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lab-005', (select id from leyes where slug = 'trebep'), '55.2', 'Los principios de publicidad, transparencia y agilidad del artículo 55.2 del TREBEP rigen la selección de:', array['Solo el personal funcionario de carrera', 'Solo el personal laboral temporal', 'El personal funcionario y el personal eventual', 'El personal funcionario y el personal laboral']::text[], 3, 'El artículo 55.2 dispone que las Administraciones «seleccionarán a su personal funcionario y laboral mediante procedimientos» que garanticen esos principios.', 1, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
