insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lab-012', (select id from leyes where slug = 'ley-53-1984'), '2.2', 'En el ámbito de aplicación de la Ley 53/1984, de Incompatibilidades, se entiende incluido:', array['Solo el personal funcionario', 'El personal con más de un año de servicio', 'Todo el personal, sea cual sea su relación de empleo', 'Solo el personal con relación estatutaria']::text[], 2, 'El artículo 2.2 dispone: «En el ámbito delimitado en el apartado anterior se entenderá incluido todo el personal, cualquiera que sea la naturaleza jurídica de la relación de empleo». Por tanto, también el personal laboral.', 2, '2025-12-16', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
