insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lab-013', null, '1.1', 'Según su artículo 1.1, el IV Convenio único se aplica al personal laboral de:', array['La AGE y sus organismos autónomos', 'Todas las Administraciones Públicas', 'La AGE y las comunidades autónomas', 'Todo el sector público estatal']::text[], 0, 'El artículo 1.1 dispone: «El presente Convenio colectivo será de aplicación al personal laboral de la Administración General del Estado y sus organismos autónomos».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
