insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lab-014', null, '1.2', '¿Cuál de los siguientes colectivos está incluido en el ámbito del IV Convenio único?', array['El personal laboral que presta servicios en el exterior', 'El personal laboral del Consejo de Seguridad Nuclear', 'El profesorado de religión', 'El personal de alta dirección']::text[], 1, 'El artículo 1.2 incluye al personal laboral que preste servicios en «El Consejo de Seguridad Nuclear». Los otros tres colectivos figuran entre los excluidos del artículo 2.', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
