insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lab-015', null, '1.2.a', 'El IV Convenio único incluye al personal laboral que presta servicios en la Administración de Justicia:', array['De todas las comunidades autónomas', 'Solo en los órganos centrales', 'Solo en el Tribunal Supremo', 'No transferida']::text[], 3, 'El artículo 1.2 incluye al personal laboral que preste servicios en «La Administración de Justicia no transferida».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
