insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lab-016', null, '2.a', '¿Qué personal queda excluido del ámbito del IV Convenio único?', array['El que presta servicios en el exterior', 'El de la Agencia Española de Protección de Datos', 'El del Museo Nacional Centro de Arte Reina Sofía', 'El de Trabajo Penitenciario y Formación para el Empleo']::text[], 0, 'El artículo 2 excluye a «El personal laboral que presta servicios en el exterior». Los otros tres están incluidos expresamente en el artículo 1.2.', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
