insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lab-017', null, '2.c', 'El personal de alta dirección del artículo 2.1.a) del Estatuto de los Trabajadores, respecto al IV Convenio único:', array['Está incluido solo si presta servicios en la AGE', 'Está incluido si lo acuerda la Comisión Paritaria', 'Queda excluido de su ámbito de aplicación', 'Se rige por él en lo no previsto en su contrato']::text[], 2, 'El artículo 2 excluye a «El personal de alta dirección contemplado en el artículo 2.1.a) del texto refundido de la Ley del Estatuto de los Trabajadores».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
