insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lab-018', null, '2.f', 'Las contrataciones de personal laboral formalizadas expresamente fuera del IV Convenio único se harán:', array['De forma excepcional, informando a la Comisión Paritaria', 'Solo con informe favorable de la Comisión Negociadora', 'Previa autorización de la Subcomisión Paritaria', 'Solo para puestos con funciones de alta dirección']::text[], 0, 'Según el artículo 2.f), «Estas contrataciones se realizarán de forma excepcional, e informando a la Comisión Paritaria, en aquellos ámbitos en los que exista personal laboral del ámbito del Convenio que realice idénticas funciones».', 3, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
