insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lab-019', null, '1.3', '¿Qué exige el IV Convenio único para incluir en su ámbito a nuevo personal tras su entrada en vigor?', array['La aprobación unánime de la Comisión Negociadora', 'Que la mayoría del colectivo afectado esté conforme', 'Un informe favorable de la Abogacía del Estado', 'Que el colectivo supere un proceso de encuadramiento']::text[], 1, 'El artículo 1.3 dispone que la inclusión de nuevo personal «exigirá que la mayoría del colectivo afectado manifieste su conformidad a la integración, individualmente o a través de los representantes legítimos en su ámbito».', 3, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
