insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lab-020', null, '3.3', 'Si el IV Convenio único no se denuncia expresamente al terminar su vigencia:', array['Pierde su vigencia de forma automática', 'Se prorroga por un único período de dos años', 'Se prorroga automáticamente por períodos anuales', 'Se aplica de nuevo el III Convenio único']::text[], 2, 'El artículo 3.3 señala: «De no efectuarse denuncia expresa, el Convenio se prorrogará automáticamente por períodos anuales».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
