insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lab-021', null, '7.1', 'El sistema de clasificación del IV Convenio único se estructura en:', array['Cuerpos, escalas y especialidades', 'Grupos, subgrupos y niveles retributivos', 'Categorías, niveles y puestos tipo', 'Grupos profesionales, familias profesionales y/o especialidades']::text[], 3, 'El artículo 7.1 indica que el sistema de clasificación «se estructura en grupos profesionales, familias profesionales y/o especialidades».', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
