insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lab-022', null, '8.1', '¿Cuántos grupos profesionales establece el artículo 8 del IV Convenio único?', array['Seis', 'Cinco', 'Cuatro', 'Siete']::text[], 0, 'El artículo 8.1 establece seis grupos profesionales, de «Grupo profesional M3» a «Grupo profesional E0»: M3, M2, M1, E2, E1 y E0.', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
