insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lab-023', null, '8.1.d', 'Según el IV Convenio único, ¿qué titulación se exige para el ingreso en el grupo profesional E2?', array['Título de Graduado en ESO o Título Profesional Básico', 'Título de Bachiller o Técnico', 'Título de Técnico Superior', 'Ninguna titulación del sistema educativo']::text[], 1, 'El artículo 8.1 dispone: «Grupo profesional E2: Título de Bachiller o Técnico o equivalentes».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
