insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lab-024', null, '8.1.c', 'El título clasificado en el Nivel 1 del Marco Español de Cualificaciones para la Educación Superior (MECES) da acceso al grupo profesional:', array['M3', 'M2', 'M1', 'E2']::text[], 2, 'El artículo 8.1 señala: «Grupo profesional M1: Título clasificado en el Nivel 1 del Marco Español de Cualificaciones para la Educación Superior o equivalentes».', 3, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
