insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lab-025', null, '7.5', 'En el IV Convenio único, ¿qué determina el contenido concreto de la prestación laboral y el perfil profesional de cada puesto?', array['El grupo profesional', 'La familia profesional', 'La relación de puestos de trabajo', 'La especialidad']::text[], 3, 'El artículo 7.5 dispone: «La especialidad determina el contenido concreto de la prestación laboral y establece el perfil profesional de cada puesto». Además, según el artículo 10.1, «Todos los puestos de trabajo tendrán asignada una especialidad».', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
