insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pj-002', (select id from leyes where slug = 'constitucion'), '117.1', 'Los Jueces y Magistrados integrantes del poder judicial están sometidos únicamente:', array['Al imperio de la ley', 'A la Constitución y al CGPJ', 'A la doctrina del Tribunal Supremo', 'A la ley y a la jurisprudencia']::text[], 0, 'El artículo 117.1 los define como «independientes, inamovibles, responsables y sometidos únicamente al imperio de la ley».', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
