insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pj-004', (select id from leyes where slug = 'constitucion'), '117.3', 'La potestad jurisdiccional, juzgando y haciendo ejecutar lo juzgado, corresponde exclusivamente:', array['Al Consejo General del Poder Judicial', 'A los Jueces, Magistrados y Fiscales', 'Al Tribunal Supremo y al Tribunal Constitucional', 'A los Juzgados y Tribunales determinados por las leyes']::text[], 3, 'El artículo 117.3 dice que el ejercicio de la potestad jurisdiccional «corresponde exclusivamente a los Juzgados y Tribunales determinados por las leyes».', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
