insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pj-005', (select id from leyes where slug = 'constitucion'), '117.4', 'Además de la potestad jurisdiccional, los Juzgados y Tribunales ejercerán las funciones que la ley les atribuya expresamente:', array['En defensa del interés público', 'En garantía del orden constitucional', 'En materia de gobierno judicial', 'En garantía de cualquier derecho']::text[], 3, 'El artículo 117.4 dice que no ejercerán más funciones que las jurisdiccionales «y las que expresamente les sean atribuidas por ley en garantía de cualquier derecho».', 3, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
