insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lopj-005', (select id from leyes where slug = 'lo-6-1985'), '26', '¿Cuál de estos órganos NO figura en la relación de Tribunales del artículo 26 de la LOPJ?', array['Tribunales de Instancia', 'Tribunal Central de Instancia', 'Audiencias Provinciales', 'Juzgados de Primera Instancia e Instrucción']::text[], 3, 'El artículo 26 enumera, entre otros, los «Tribunales de Instancia», las «Audiencias Provinciales» y el «Tribunal Central de Instancia»; no menciona los Juzgados de Primera Instancia e Instrucción.', 2, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
