insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lopj-030', (select id from leyes where slug = 'lo-6-1985'), '561.2', 'Si no se indica urgencia, el CGPJ debe emitir su informe sobre anteproyectos de ley en el plazo de:', array['Quince días', 'Diez días', 'Treinta días', 'Dos meses']::text[], 2, 'El artículo 561.2 dice: «El Consejo General del Poder Judicial emitirá su informe en el plazo improrrogable de treinta días. Si en la orden de remisión se hiciere constar la urgencia del informe, el plazo será de quince días».', 3, '2026-10-09', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
