insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgp-002', (select id from leyes where slug = 'ley-47-2003'), '28.1', 'Los escenarios presupuestarios plurianuales determinan los límites que debe respetar la acción de gobierno, referidos a:', array['Los dos ejercicios siguientes', 'Los cuatro ejercicios siguientes', 'Los tres ejercicios siguientes', 'Los cinco ejercicios siguientes']::text[], 2, 'El artículo 28.1 establece que los escenarios presupuestarios plurianuales «determinarán los límites, referidos a los tres ejercicios siguientes, que la acción de gobierno debe respetar».', 1, '2026-09-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
