insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgp-003', (select id from leyes where slug = 'ley-47-2003'), '32', 'Los Presupuestos Generales del Estado constituyen la expresión cifrada, conjunta y sistemática de:', array['Los ingresos y gastos previstos para los tres ejercicios siguientes', 'Los derechos y obligaciones a liquidar durante el ejercicio', 'Los objetivos de estabilidad de todas las Administraciones públicas', 'Las operaciones financieras de las entidades del sector empresarial']::text[], 1, 'Según el artículo 32, los Presupuestos Generales del Estado constituyen «la expresión cifrada, conjunta y sistemática de los derechos y obligaciones a liquidar durante el ejercicio».', 1, '2026-09-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
