insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgp-005', (select id from leyes where slug = 'ley-47-2003'), '36.2', 'Para determinar las directrices de distribución del gasto en la elaboración de los Presupuestos se constituirá:', array['El Consejo de Política Fiscal y Financiera', 'La Comisión General de Secretarios de Estado y Subsecretarios', 'La Comisión de Políticas de Gasto', 'La Comisión de Presupuestos del Congreso']::text[], 2, 'El artículo 36.2, norma primera, tras regular las directrices para la distribución del gasto, añade: «Con este fin, se constituirá la Comisión de Políticas de Gasto».', 2, '2026-09-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
