insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgp-009', (select id from leyes where slug = 'ley-47-2003'), '38.2', 'La prórroga de los Presupuestos Generales del Estado no afectará a los créditos para gastos correspondientes a:', array['Gastos de personal de la Administración General del Estado', 'Programas o actuaciones que terminen en el ejercicio cuyos presupuestos se prorrogan', 'Intereses y amortización de la Deuda Pública', 'Pensiones de Clases Pasivas del Estado']::text[], 1, 'El artículo 38.2 dispone que «La prórroga no afectará a los créditos para gastos correspondientes a programas o actuaciones que terminen en el ejercicio cuyos presupuestos se prorrogan o para obligaciones que se extingan en el mismo».', 2, '2026-09-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
