insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgp-013', (select id from leyes where slug = 'ley-47-2003'), '40.1.c', 'En la clasificación económica de los gastos, dentro de los créditos para operaciones de capital se distinguen:', array['Los gastos de personal y las inversiones reales', 'Los activos financieros y los pasivos financieros', 'Los gastos financieros y las transferencias de capital', 'Las inversiones reales y las transferencias de capital']::text[], 3, 'El artículo 40.1.c) señala: «En los créditos para operaciones de capital se distinguirán las inversiones reales y las transferencias de capital».', 2, '2026-09-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
