insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgp-017', (select id from leyes where slug = 'ley-47-2003'), '52.1.a', 'Las transferencias de crédito NO podrán realizarse:', array['Desde créditos para operaciones corrientes a créditos para operaciones de capital', 'Entre créditos de una misma sección presupuestaria', 'Desde créditos para operaciones de capital a créditos para operaciones corrientes', 'Con la creación de créditos nuevos']::text[], 2, 'El artículo 52.1 permite las transferencias «incluso con la creación de créditos nuevos», pero «No podrán realizarse desde créditos para operaciones financieras al resto de los créditos, ni desde créditos para operaciones de capital a créditos para operaciones corrientes».', 2, '2026-09-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
