insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgp-018', (select id from leyes where slug = 'ley-47-2003'), '52.1.c', 'Con carácter general, las transferencias de crédito no podrán minorar:', array['Créditos destinados a gastos de personal', 'Créditos para operaciones corrientes en bienes y servicios', 'Créditos incluidos en el programa de imprevistos', 'Créditos extraordinarios o que se hayan suplementado o ampliado en el ejercicio']::text[], 3, 'El artículo 52.1.c) establece que las transferencias «No minorarán créditos extraordinarios o créditos que se hayan suplementado o ampliado en el ejercicio».', 2, '2026-09-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
