insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgp-019', (select id from leyes where slug = 'ley-47-2003'), '53.1', 'Las generaciones de crédito son modificaciones que incrementan los créditos como consecuencia de:', array['Ingresos no previstos o superiores a los contemplados en el presupuesto inicial', 'La incorporación de remanentes de crédito del ejercicio anterior', 'El traspaso de dotaciones entre créditos de distintos programas', 'Obligaciones derivadas de normas con rango de ley']::text[], 0, 'Según el artículo 53.1, «Las generaciones son modificaciones que incrementan los créditos como consecuencia de la realización de determinados ingresos no previstos o superiores a los contemplados en el presupuesto inicial».', 1, '2026-09-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
