insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgp-020', (select id from leyes where slug = 'ley-47-2003'), '53.5', 'Con carácter excepcional, pueden generar crédito en el presupuesto del ejercicio los ingresos realizados en:', array['El último mes del ejercicio anterior', 'El último trimestre del ejercicio anterior', 'El último semestre del ejercicio anterior', 'El primer trimestre del ejercicio siguiente']::text[], 1, 'El artículo 53.5 dispone: «Con carácter excepcional podrán generar crédito en el Presupuesto del ejercicio los ingresos realizados en el último trimestre del ejercicio anterior».', 3, '2026-09-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
