insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgp-024', (select id from leyes where slug = 'ley-47-2003'), '58.d', 'Pueden incorporarse los remanentes de créditos extraordinarios y suplementos concedidos mediante norma con rango de ley en:', array['El último mes del ejercicio presupuestario anterior', 'El último trimestre del ejercicio presupuestario anterior', 'El último semestre del ejercicio presupuestario anterior', 'Los dos últimos meses del ejercicio presupuestario anterior']::text[], 0, 'El artículo 58.d) permite incorporar los remanentes que «resulten de créditos extraordinarios y suplementos de crédito que hayan sido concedidos mediante norma con rango de ley en el último mes del ejercicio presupuestario anterior».', 3, '2026-09-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
