insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgp-026', (select id from leyes where slug = 'ley-47-2003'), '73.1', 'En la gestión del presupuesto de gastos, la fase que sigue inmediatamente al compromiso de gasto es:', array['El reconocimiento de la obligación', 'La aprobación del gasto', 'La ordenación del pago', 'El pago material']::text[], 0, 'El artículo 73.1 enumera las fases en este orden: «a) Aprobación del gasto. b) Compromiso de gasto. c) Reconocimiento de la obligación. d) Ordenación del pago. e) Pago material.»', 1, '2026-09-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
