insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgp-029', (select id from leyes where slug = 'ley-47-2003'), '74.1', 'Salvo los casos reservados al Consejo de Ministros, aprobar y comprometer los gastos propios del presupuesto de un ministerio corresponde:', array['Al Ministro', 'Al Ordenador general de pagos del Estado', 'Al Interventor Delegado del ministerio', 'Al Consejo de Ministros en todo caso']::text[], 0, 'El artículo 74.1 dispone que «Corresponde a los Ministros y a los titulares de los demás órganos del Estado con dotaciones diferenciadas […] aprobar y comprometer los gastos propios de sus presupuestos».', 1, '2026-09-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
