insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgp-030', (select id from leyes where slug = 'ley-47-2003'), '74.5', 'Los órganos competentes para suscribir convenios necesitarán autorización del Consejo de Ministros cuando el gasto derivado sea superior a:', array['Seis millones de euros', 'Diez millones de euros', 'Doce millones de euros', 'Quince millones de euros']::text[], 2, 'El artículo 74.5 exige autorización del Consejo de Ministros «cuando el importe del gasto que de aquellos se derive sea superior a doce millones de euros».', 2, '2026-09-30', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
