insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('psa-002', (select id from leyes where slug = 'psicotecnico'), 'Ordenación alfabética', 'Se ordenan alfabéticamente los apellidos Pascual, Pastor, Prieto y Peña. ¿Cuál queda en tercer lugar?', array['Prieto', 'Peña', 'Pascual', 'Pastor']::text[], 1, 'Se compara letra a letra, sin tener en cuenta las tildes. Ordenados quedan: Pascual, Pastor, Peña, Prieto. El tercero es Peña.', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
