insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('psa-003', (select id from leyes where slug = 'psicotecnico'), 'Ordenación alfabética', 'Se ordenan alfabéticamente los apellidos Campos, Castro, Cabrera y Crespo. ¿Cuál queda en segundo lugar?', array['Campos', 'Crespo', 'Castro', 'Cabrera']::text[], 0, 'Se compara letra a letra, sin tener en cuenta las tildes. Ordenados quedan: Cabrera, Campos, Castro, Crespo. El segundo es Campos.', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
