insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('psa-004', (select id from leyes where slug = 'psicotecnico'), 'Plazos administrativos', 'Una resolución se notifica el jueves 12 de marzo de 2026. Para recurrir hay 10 días hábiles. Si no hay festivos en ese periodo, ¿cuándo termina el plazo?', array['miércoles 25 de marzo', 'domingo 22 de marzo', 'jueves 26 de marzo', 'viernes 27 de marzo']::text[], 2, 'Según el artículo 30 de la Ley 39/2015, los plazos en días hábiles se cuentan desde el día siguiente a la notificación y excluyen sábados, domingos y festivos. Contando 10 días hábiles desde el jueves 12 de marzo, el plazo termina el jueves 26 de marzo.', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
