insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('psa-005', (select id from leyes where slug = 'psicotecnico'), 'Ordenación alfabética', 'Se ordenan alfabéticamente los apellidos Sanz, Sánchez, Soler y Suárez. ¿Cuál queda en segundo lugar?', array['Suárez', 'Sánchez', 'Soler', 'Sanz']::text[], 3, 'Se compara letra a letra, sin tener en cuenta las tildes. Ordenados quedan: Sánchez, Sanz, Soler, Suárez. El segundo es Sanz.', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
