insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('psa-006', (select id from leyes where slug = 'psicotecnico'), 'Plazos administrativos', 'Un acto se notifica el lunes 28 de septiembre de 2026 y el plazo para recurrirlo es de dos meses. Si no hay festivos, ¿cuándo termina el plazo?', array['viernes 27 de noviembre', 'martes 1 de diciembre', 'lunes 30 de noviembre', 'domingo 29 de noviembre']::text[], 2, 'Según el artículo 30 de la Ley 39/2015, los plazos en meses se cuentan de fecha a fecha: terminan el mismo día del mes de vencimiento (sábado 28 de noviembre). Como ese día es sábado o domingo, el plazo se prorroga al primer día hábil siguiente. Termina el lunes 30 de noviembre.', 3, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'psa-006', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 31 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('psa-007', (select id from leyes where slug = 'psicotecnico'), 'Plazos administrativos', 'Una resolución se notifica el jueves 3 de septiembre de 2026. Para recurrir hay 12 días hábiles. Si no hay festivos en ese periodo, ¿cuándo termina el plazo?', array['lunes 21 de septiembre', 'viernes 18 de septiembre', 'martes 15 de septiembre', 'martes 22 de septiembre']::text[], 0, 'Según el artículo 30 de la Ley 39/2015, los plazos en días hábiles se cuentan desde el día siguiente a la notificación y excluyen sábados, domingos y festivos. Contando 12 días hábiles desde el jueves 3 de septiembre, el plazo termina el lunes 21 de septiembre.', 3, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
