insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('psa-011', (select id from leyes where slug = 'psicotecnico'), 'Horarios y jornadas', 'Si la jornada semanal es de 37,5 horas, repartidas en 5 días iguales, ¿cuánto dura cada jornada diaria?', array['8 h', '7 h', '7 h 45 min', '7 h 30 min']::text[], 3, '37,5 horas ÷ 5 días = 7,5 horas al día, es decir, 7 h 30 min.', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
