insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('psa-022', (select id from leyes where slug = 'psicotecnico'), 'Horarios y jornadas', 'Las citas duran 30 minutos y se dan seguidas, sin pausas, desde las 9:00 hasta las 18:00. ¿Cuántas citas se pueden dar?', array['19', '18', '17', '20']::text[], 1, 'De 9:00 a 18:00 hay 9 h, es decir, 540 minutos. 540 ÷ 30 = 18 citas.', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
