insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('psa-024', (select id from leyes where slug = 'psicotecnico'), 'Comprobación de datos', 'La letra del DNI se obtiene dividiendo el número entre 23 y buscando el resto en esta tabla: 0 T, 1 R, 2 W, 3 A, 4 G, 5 M, 6 Y, 7 F, 8 P, 9 D, 10 X, 11 B, 12 N, 13 J, 14 Z, 15 S, 16 Q, 17 V, 18 H, 19 L, 20 C, 21 K, 22 E. ¿Qué letra corresponde al DNI 11893315?', array['V', 'Q', 'Z', 'S']::text[], 3, 'Al dividir 11893315 entre 23 el resto es 15. En la tabla, el resto 15 corresponde a la letra S.', 3, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
