insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('psa-027', (select id from leyes where slug = 'psicotecnico'), 'Ordenación numérica', 'Se ordenan de menor a mayor estos números de registro: 20250331, 20241532, 20241444 y 20231395. ¿Cuál queda en último lugar?', array['20241532', '20241444', '20231395', '20250331']::text[], 3, 'Ordenados de menor a mayor: 20231395, 20241444, 20241532, 20250331. El último es 20250331.', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
