insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('psa-028', (select id from leyes where slug = 'psicotecnico'), 'Ordenación alfabética', 'Se ordenan alfabéticamente los apellidos Cortés, Cruz, Crespo y Carrasco. ¿Cuál queda en último lugar?', array['Cruz', 'Carrasco', 'Crespo', 'Cortés']::text[], 0, 'Se compara letra a letra, sin tener en cuenta las tildes. Ordenados quedan: Carrasco, Cortés, Crespo, Cruz. El último es Cruz.', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
