insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('psa-030', (select id from leyes where slug = 'psicotecnico'), 'Comparación de códigos', '¿En cuál de las siguientes parejas los dos códigos son exactamente iguales?', array['UP-132709 / UV-132709', 'FP-908253 / FP-901253', 'MJ-457086 / MJ-4570866', 'UE-135126 / UE-135126']::text[], 3, 'En UE-135126 / UE-135126 los dos códigos coinciden carácter a carácter. En las otras parejas hay una diferencia: dos cifras cambiadas de sitio, una cifra distinta, una letra distinta o una cifra de más.', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
