insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('psa-033', (select id from leyes where slug = 'psicotecnico'), 'Horarios y jornadas', 'Clasificar 48 expedientes lleva 4 horas. A ese ritmo, ¿cuánto se tardará en clasificar 72?', array['5 h 30 min', '6 h 30 min', '6 h', '7 h']::text[], 2, 'El ritmo es 48 ÷ 4 = 12 expedientes por hora. Para 72 hacen falta 72 ÷ 12 = 6 horas, es decir, 6 h.', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
