insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('psa-039', (select id from leyes where slug = 'psicotecnico'), 'Comparación de códigos', '¿En cuál de las siguientes parejas los dos códigos son exactamente iguales?', array['MX-47098 / MC-47098', 'VF-35347 / VF-35437', 'XA-97590 / XA-97590', 'NT-13552 / NT-135522']::text[], 2, 'En XA-97590 / XA-97590 los dos códigos coinciden carácter a carácter. En las otras parejas hay una diferencia: dos cifras cambiadas de sitio, una cifra distinta, una letra distinta o una cifra de más.', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
