insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('psa-040', (select id from leyes where slug = 'psicotecnico'), 'Horarios y jornadas', 'Una ventanilla atiende a 12 personas por hora. ¿Cuántas atenderá en una mañana de 5 horas y 30 minutos?', array['72', '67', '66', '60']::text[], 2, '5 h 30 min son 5,5 horas, y 12 personas por hora × 5,5 horas = 66 personas.', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
