insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('psl-001', (select id from leyes where slug = 'psicotecnico'), 'Orden y posiciones', 'Cuatro personas terminan a horas distintas. Raúl terminó después de Luis. Sara terminó antes que Jorge. Jorge terminó antes que Luis. ¿Quién terminó en tercer lugar?', array['Sara', 'Jorge', 'Luis', 'Raúl']::text[], 2, 'Ordenadas, Sara, Jorge, Luis y Raúl terminan en ese orden. El tercero es Luis.', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
