insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('psl-002', (select id from leyes where slug = 'psicotecnico'), 'Orden y posiciones', 'Cuatro personas llegan a horas distintas. Jorge llegó antes que Elena. Álvaro llegó después de Diego. Jorge llegó después de Álvaro. ¿Quién llegó en segundo lugar?', array['Diego', 'Jorge', 'Elena', 'Álvaro']::text[], 3, 'Ordenadas, Diego, Álvaro, Jorge y Elena llegan en ese orden. El segundo es Álvaro.', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
