insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('psl-003', (select id from leyes where slug = 'psicotecnico'), 'Series de letras', 'Alfabeto español de 27 letras (de la A a la Z, con la Ñ): ¿qué letra continúa la serie O, Q, S, U, W, …?', array['Y', 'X', 'W', 'Z']::text[], 0, 'Cada letra está 2 lugares después de la anterior. La letra que sigue es la Y.', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
