insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('psl-007', (select id from leyes where slug = 'psicotecnico'), 'Codificación', 'En un código cada letra se sustituye por la siguiente del alfabeto español de 27 letras (A → B, B → C, … N → Ñ, Ñ → O…). ¿Cómo se escribe «LEY»?', array['ZFM', 'KDX', 'MFZ', 'NGA']::text[], 2, 'Cada letra se cambia por la siguiente: L → M, E → F, Y → Z. Se escribe MFZ.', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
