insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('psl-010', (select id from leyes where slug = 'psicotecnico'), 'Reloj', '¿Qué ángulo forman las agujas de un reloj a las 6:30?', array['30°', '45°', '15°', '0°']::text[], 2, 'A las 6:30 la aguja de las horas está a 195° (6 × 30° más 30 × 0,5°) y la de los minutos a 180° (30 × 6°). La diferencia es 15°.', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
