insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('psl-011', (select id from leyes where slug = 'psicotecnico'), 'Calendario', 'En 2026, el 17 de julio cae en viernes. ¿En qué día de la semana cae el 11 de agosto?', array['martes', 'miércoles', 'lunes', 'jueves']::text[], 0, 'Del 17 de julio al 11 de agosto hay 25 días: 3 semanas completas y 4 días más. Desde el viernes se avanza hasta el martes.', 3, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
