insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('psl-012', (select id from leyes where slug = 'psicotecnico'), 'Silogismos', 'Todos los M son N. Todos los N son P. ¿Qué conclusión se deduce con seguridad?', array['Algunos P no son N', 'Ningún M es P', 'Todos los P son M', 'Todos los M son P']::text[], 3, 'Si todos los M son N y todos los N son P, entonces todos los M son P. Lo contrario (todos los P son M) no se deduce.', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
