insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('psl-013', (select id from leyes where slug = 'psicotecnico'), 'Orden y posiciones', 'Cuatro personas terminan a horas distintas. Diego terminó después de Carlos. Álvaro terminó después de Pedro. Diego terminó antes que Pedro. ¿Quién terminó en primer lugar?', array['Carlos', 'Diego', 'Pedro', 'Álvaro']::text[], 0, 'Ordenadas, Carlos, Diego, Pedro y Álvaro terminan en ese orden. El primero es Carlos.', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
