insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('psl-014', (select id from leyes where slug = 'psicotecnico'), 'Orden y posiciones', 'Cuatro personas terminan a horas distintas. Ana terminó después de Nuria. Nuria terminó después de Irene. Ana terminó antes que Álvaro. ¿Quién terminó en tercer lugar?', array['Ana', 'Nuria', 'Irene', 'Álvaro']::text[], 0, 'Ordenadas, Irene, Nuria, Ana y Álvaro terminan en ese orden. El tercero es Ana.', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
