insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('psl-015', (select id from leyes where slug = 'psicotecnico'), 'Codificación', 'En un código cada letra se sustituye por la siguiente del alfabeto español de 27 letras (A → B, B → C, … N → Ñ, Ñ → O…). ¿Cómo se escribe «EXPEDIENTE»?', array['GZRGFKGOVG', 'FYQFEJFÑUF', 'DWODCHDMSD', 'FUÑFJEFQYF']::text[], 1, 'Cada letra se cambia por la siguiente: E → F, X → Y, P → Q, E → F, D → E, I → J, E → F, N → Ñ, T → U, E → F. Se escribe FYQFEJFÑUF.', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
