insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('psl-016', (select id from leyes where slug = 'psicotecnico'), 'Problemas de lógica', 'Un número aumentado en 8 da lo mismo que su doble disminuido en 7. ¿Cuál es el número?', array['10', '15', '16', '20']::text[], 1, 'Con 15: 15 + 8 = 23 y 2 × 15 − 7 = 23. Los dos resultados coinciden.', 3, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
