insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('psl-017', (select id from leyes where slug = 'psicotecnico'), 'Codificación', '¿Qué letra ocupa el lugar 19 en el alfabeto español de 27 letras (A, B, C… con la Ñ entre la N y la O)?', array['Q', 'T', 'S', 'R']::text[], 3, 'Contando desde la A, que es la 1.ª, el lugar 19 corresponde a la R. (Con la Ñ en el lugar 15, la O es la 16.ª y la Z, la 27.ª.)', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
