insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('psl-020', (select id from leyes where slug = 'psicotecnico'), 'Calendario', 'Si hoy es martes, ¿qué día de la semana fue hace 89 días?', array['sábado', 'jueves', 'miércoles', 'viernes']::text[], 1, '89 días son 12 semanas completas y 5 días. Las semanas no cambian el día; retrocediendo 5 desde el martes se llega al jueves.', 3, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
