insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('psl-021', (select id from leyes where slug = 'psicotecnico'), 'Problemas de lógica', 'En un servicio trabajan 15 personas y los hombres son el doble que las mujeres. ¿Cuántas mujeres hay?', array['6', '10', '5', '13']::text[], 2, 'Las mujeres son una parte y los hombres dos, así que hay 3 partes en total. Cada parte vale 15 ÷ 3 = 5: hay 5 mujeres.', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
