insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('psl-035', (select id from leyes where slug = 'psicotecnico'), 'Calendario', 'Si hoy es miércoles, ¿qué día de la semana será dentro de 33 días?', array['miércoles', 'martes', 'lunes', 'domingo']::text[], 2, '33 días son 4 semanas completas y 5 días. Las semanas no cambian el día; avanzando 5 desde el miércoles se llega al lunes.', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
