insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('psl-036', (select id from leyes where slug = 'psicotecnico'), 'Silogismos', 'Todos los A son B. Ningún C es B. ¿Qué conclusión se deduce con seguridad?', array['Algunos C son A', 'Ningún C es A', 'Todos los A son C', 'Todos los C son A']::text[], 1, 'Todo A es B y ningún C es B; luego ningún C puede ser A.', 3, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
