insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('psl-038', (select id from leyes where slug = 'psicotecnico'), 'Problemas de lógica', 'Si a la mitad de un número se le suman 8, se obtiene 40. ¿Cuál es el número?', array['64', '48', '80', '32']::text[], 0, 'La mitad del número es 40 − 8 = 32, así que el número es el doble: 64.', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
