insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('psl-039', (select id from leyes where slug = 'psicotecnico'), 'Codificación', 'Si cada letra vale su posición en el alfabeto español de 27 letras (A = 1, B = 2, … N = 14, Ñ = 15, O = 16…), ¿cuánto suman las letras de «SELLO»?', array['66', '65', '63', '64']::text[], 1, 'S = 20, E = 5, L = 12, L = 12, O = 16. La suma es 65.', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
