insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('psl-040', (select id from leyes where slug = 'psicotecnico'), 'Orden y posiciones', 'Cuatro personas llegan a horas distintas. Laura llegó después de Diego. Pedro llegó después de Laura. Pedro llegó antes que Ana. ¿Quién llegó en primer lugar?', array['Pedro', 'Laura', 'Diego', 'Ana']::text[], 2, 'Ordenadas, Diego, Laura, Pedro y Ana llegan en ese orden. El primero es Diego.', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
