insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('psl-041', (select id from leyes where slug = 'psicotecnico'), 'Silogismos', 'Algunos M son N. Todos los N son P. ¿Qué conclusión se deduce con seguridad?', array['Algunos M son P', 'Todos los P son N', 'Ningún M es P', 'Todos los M son P']::text[], 0, 'Los M que son N son también P, así que algunos M son P. No se puede afirmar que todos lo sean.', 3, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
