insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('psl-042', (select id from leyes where slug = 'psicotecnico'), 'Silogismos', 'Todos los X son Y. Pablo es X. ¿Qué conclusión se deduce con seguridad?', array['Pablo no es Y', 'Todos los Y son X', 'Pablo es X pero no Y', 'Pablo es Y']::text[], 3, 'Pablo pertenece a X, y todo X es Y; por tanto Pablo es Y. Que todos los Y sean X no se deduce.', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
