insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('psl-043', (select id from leyes where slug = 'psicotecnico'), 'Problemas de lógica', 'Elena tiene el triple de edad que Pablo, y entre los dos suman 36 años. ¿Cuántos años tiene Pablo?', array['10', '27', '18', '9']::text[], 3, 'Si Pablo tiene una parte, Elena tiene 3 y juntos 4 partes. Cada parte vale 36 ÷ 4 = 9, así que Pablo tiene 9 años.', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
