insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('psl-045', (select id from leyes where slug = 'psicotecnico'), 'Orden y posiciones', 'Cuatro personas terminan a horas distintas. Marta terminó después de Álvaro. Álvaro terminó después de Irene. Elena terminó antes que Irene. ¿Quién terminó en segundo lugar?', array['Elena', 'Irene', 'Álvaro', 'Marta']::text[], 1, 'Ordenadas, Elena, Irene, Álvaro y Marta terminan en ese orden. El segundo es Irene.', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
