insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('psl-046', (select id from leyes where slug = 'psicotecnico'), 'Problemas de lógica', 'Un autobús recorre 120 km en 2 horas. A la misma velocidad, ¿cuántos kilómetros recorrerá en 3 horas?', array['360 km', '180 km', '240 km', '150 km']::text[], 1, 'La velocidad es 120 km ÷ 2 h = 60 km/h. En 3 horas recorre 60 × 3 = 180 km.', 2, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
