insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('psl-047', (select id from leyes where slug = 'psicotecnico'), 'Reloj', '¿Qué ángulo forman las agujas de un reloj a las 2:00?', array['45°', '90°', '75°', '60°']::text[], 3, 'A las 2:00 la aguja de las horas está a 60° (2 × 30° más 0 × 0,5°) y la de los minutos a 0° (0 × 6°). La diferencia es 60°.', 1, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
