insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('psl-048', (select id from leyes where slug = 'psicotecnico'), 'Calendario', 'Si pasado mañana es jueves, ¿qué día de la semana fue ayer?', array['lunes', 'miércoles', 'martes', 'domingo']::text[], 0, 'Si pasado mañana es jueves, hoy es martes. Desde ahí, ayer fue lunes.', 3, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
