insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('psn-001', (select id from leyes where slug = 'psicotecnico'), 'Series numéricas', '¿Qué número continúa la serie 1, 2, 6, 24, 120, …?', array['480', '720', '216', '820']::text[], 1, 'Cada término es el anterior multiplicado por 2, 3, 4… (son factoriales): el siguiente es ×6, es decir, 720. El siguiente término es 720.', 3, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
