insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('psn-003', (select id from leyes where slug = 'psicotecnico'), 'Series numéricas', '¿Qué número continúa la serie 4, 6, 18, 20, 60, 62, …?', array['64', '65', '186', '187']::text[], 2, 'Se alternan dos operaciones: sumar 2 y multiplicar por 3. 4 +2 = 6, ×3 = 18, +2 = 20…. El siguiente término es 186.', 3, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
