insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('psn-046', (select id from leyes where slug = 'psicotecnico'), 'Reparto proporcional', 'Se reparten 550 € entre 3 personas en partes proporcionales a 2, 3 y 5. ¿Cuánto recibe la que menos recibe?', array['275 €', '110 €', '111 €', '165 €']::text[], 1, 'En total hay 2 + 3 + 5 = 10 partes, y cada una vale 550 € ÷ 10 = 55 €. La que menos recibe tiene 2 partes: 110 €.', 3, null, 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
