insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('loc-017', (select id from leyes where slug = 'ley-7-1985'), '21.3', '¿Cuál de estas atribuciones del Alcalde no puede delegar?', array['El otorgamiento de las licencias', 'Aprobar la oferta de empleo público', 'Dictar bandos', 'Sancionar las faltas por infracción de las ordenanzas']::text[], 2, 'El artículo 21.3 excluye de la delegación, entre otras, «las enunciadas en los párrafos a), e), j), k), l) y m) del apartado 1», y el párrafo e) es «Dictar bandos».', 3, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
