insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('loc-019', (select id from leyes where slug = 'ley-7-1985'), '23.1', 'La Junta de Gobierno Local la integran el Alcalde y un número de Concejales no superior:', array['Al tercio del número legal de los mismos', 'A la mitad del número legal de los mismos', 'A la cuarta parte del número legal de los mismos', 'A los dos tercios del número legal de los mismos']::text[], 0, 'El artículo 23.1 dice que la integran «el Alcalde y un número de Concejales no superior al tercio del número legal de los mismos».', 1, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
