insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('reg-004', (select id from leyes where slug = 'ley-39-2015'), '16.2', 'Los asientos en el registro se anotarán respetando:', array['El orden alfabético de los interesados', 'El orden de prioridad que fije el órgano destinatario', 'El orden temporal de recepción o salida de los documentos', 'El orden de urgencia del asunto tramitado']::text[], 2, 'El artículo 16.2 dispone: «Los asientos se anotarán respetando el orden temporal de recepción o salida de los documentos, e indicarán la fecha del día en que se produzcan».', 1, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
