insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('reg-005', (select id from leyes where slug = 'ley-39-2015'), '16.2', 'Concluido el trámite de registro, los documentos serán cursados a sus destinatarios:', array['Sin dilación', 'En el plazo de tres días', 'En el plazo de diez días', 'Dentro de las veinticuatro horas siguientes']::text[], 0, 'Según el artículo 16.2, «Concluido el trámite de registro, los documentos serán cursados sin dilación a sus destinatarios y a las unidades administrativas correspondientes […]».', 2, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
