insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('reg-006', (select id from leyes where slug = 'ley-39-2015'), '16.3', 'El recibo que emite automáticamente el registro electrónico consiste en:', array['Un justificante de entrega, sin valor de copia, con la fecha de presentación', 'Una copia simple del documento, sin indicación de hora', 'Una copia autenticada del documento, con fecha, hora y número de entrada', 'Un certificado de presentación expedido por el responsable del registro']::text[], 2, 'El artículo 16.3 prevé que «se emitirá automáticamente un recibo consistente en una copia autenticada del documento de que se trate, incluyendo la fecha y hora de presentación y el número de entrada de registro».', 2, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
