insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('reg-011', (select id from leyes where slug = 'ley-39-2015'), '16.8', 'Según el artículo 16.8, no se tendrán por presentados en el registro:', array['Los documentos presentados en un día inhábil', 'Los documentos presentados en las oficinas de Correos', 'Los documentos que no vayan acompañados de copia', 'Los documentos cuyo régimen especial establezca otra forma de presentación']::text[], 3, 'El artículo 16.8 dispone: «No se tendrán por presentados en el registro aquellos documentos e información cuyo régimen especial establezca otra forma de presentación».', 3, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
