insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('reg-012', (select id from leyes where slug = 'ley-39-2015'), '17.1', 'El archivo electrónico único de cada Administración guarda los documentos electrónicos de:', array['Procedimientos en tramitación', 'Procedimientos finalizados', 'Procedimientos iniciados en los últimos cinco años', 'Procedimientos sancionadores, exclusivamente']::text[], 1, 'El artículo 17.1 establece: «Cada Administración deberá mantener un archivo electrónico único de los documentos electrónicos que correspondan a procedimientos finalizados […]».', 1, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
