insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('reg-013', (select id from leyes where slug = 'ley-39-2015'), '17.2', 'La eliminación de los documentos electrónicos archivados:', array['Es automática al finalizar el procedimiento', 'La decide libremente el órgano que los custodia', 'Debe ser autorizada conforme a la normativa aplicable', 'Está prohibida en todo caso']::text[], 2, 'Según el artículo 17.2, «La eliminación de dichos documentos deberá ser autorizada de acuerdo a lo dispuesto en la normativa aplicable».', 2, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
