insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('reg-014', (select id from leyes where slug = 'ley-39-2015'), '26.1', 'Según la Ley 39/2015, son documentos públicos administrativos:', array['Los válidamente emitidos por los órganos de las Administraciones Públicas', 'Los presentados por los interesados en cualquier registro público', 'Los que constan en un archivo público, sea cual sea su origen', 'Los autorizados por notario o por funcionario habilitado']::text[], 0, 'El artículo 26.1 dispone: «Se entiende por documentos públicos administrativos los válidamente emitidos por los órganos de las Administraciones Públicas».', 1, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
