insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('reg-015', (select id from leyes where slug = 'ley-39-2015'), '26.2', '¿Cuál de estos NO es un requisito de validez de los documentos electrónicos administrativos?', array['Incorporar una referencia temporal del momento de su emisión', 'Haber sido notificados al interesado por comparecencia en la sede', 'Incorporar los metadatos mínimos exigidos', 'Disponer de datos de identificación que permitan su individualización']::text[], 1, 'El artículo 26.2 exige, entre otros requisitos, «Incorporar una referencia temporal del momento en que han sido emitidos» e «Incorporar los metadatos mínimos exigidos». La notificación no figura entre ellos.', 2, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
