insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('reg-016', (select id from leyes where slug = 'ley-39-2015'), '26.3', 'No requerirán de firma electrónica los documentos electrónicos emitidos por las Administraciones que:', array['Pongan fin al procedimiento administrativo', 'Sean actos de trámite cualificados', 'Sean copias auténticas de documentos en papel', 'Se publiquen con carácter meramente informativo']::text[], 3, 'El artículo 26.3 dispone: «No requerirán de firma electrónica, los documentos electrónicos emitidos por las Administraciones Públicas que se publiquen con carácter meramente informativo, así como aquellos que no formen parte de un expediente administrativo».', 1, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
