insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('reg-017', (select id from leyes where slug = 'ley-39-2015'), '27.1', 'Las copias auténticas de documentos privados surten:', array['Únicamente efectos administrativos', 'Plenos efectos civiles y mercantiles', 'Efectos solo ante el órgano que las expidió', 'Los mismos efectos que una escritura pública']::text[], 0, 'El artículo 27.1 establece: «Las copias auténticas de documentos privados surten únicamente efectos administrativos».', 2, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
