insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('reg-019', (select id from leyes where slug = 'ley-39-2015'), '27.2', 'Las copias auténticas tienen, respecto de los documentos originales:', array['Validez, pero solo eficacia probatoria', 'La misma validez y eficacia', 'Menor eficacia, salvo que se cotejen', 'Eficacia solo dentro del procedimiento']::text[], 1, 'El artículo 27.2 dispone: «Las copias auténticas tendrán la misma validez y eficacia que los documentos originales».', 1, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
