insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('reg-024', (select id from leyes where slug = 'ley-39-2015'), '31.2.a', 'El registro electrónico permitirá la presentación de documentos:', array['Solo los días hábiles, durante las veinticuatro horas', 'Todos los días del año, de 8 a 20 horas', 'Solo en el horario de las oficinas de asistencia', 'Todos los días del año durante las veinticuatro horas']::text[], 3, 'El artículo 31.2.a) dispone que el registro electrónico «Permitirá la presentación de documentos todos los días del año durante las veinticuatro horas».', 1, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
