insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('reg-025', (select id from leyes where slug = 'ley-39-2015'), '31.2.b', 'Con carácter general, a efectos de plazos en días hábiles, la presentación electrónica en día inhábil se entiende hecha:', array['En la primera hora del primer día hábil siguiente', 'A las doce horas del primer día hábil siguiente', 'En la misma fecha y hora en que se presentó', 'En la última hora del primer día hábil siguiente']::text[], 0, 'Según el artículo 31.2.b), «la presentación en un día inhábil se entenderá realizada en la primera hora del primer día hábil siguiente salvo que una norma permita expresamente la recepción en día inhábil».', 2, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
