insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('rme-002', (select id from leyes where slug = 'rd-203-2021'), '4.c', '¿Cuál de estos canales cita expresamente el Reglamento para prestar asistencia en el acceso a los servicios electrónicos?', array['El correo postal certificado', 'La videollamada concertada', 'Las redes sociales', 'El servicio de fax']::text[], 2, 'El artículo 4 enumera como canales de asistencia el presencial, los portales y sedes, «c) Redes sociales», el telefónico y el correo electrónico.', 2, '2026-10-13', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
