insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('rme-006', (select id from leyes where slug = 'rd-203-2021'), '10.2', 'El acto de creación de la sede electrónica de una entidad local se publica en:', array['El boletín oficial de la provincia a la que pertenezca la entidad', 'El Boletín Oficial del Estado', 'El boletín oficial de la comunidad autónoma', 'El tablón de edictos de la propia entidad']::text[], 0, 'El artículo 10.2 indica que «en el caso de las entidades locales, el boletín oficial será el de la provincia al que pertenezca la entidad».', 1, '2026-10-13', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
