insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('rme-007', (select id from leyes where slug = 'rd-203-2021'), '11.2.i', 'Entre los servicios mínimos de toda sede electrónica figura un directorio geográfico de:', array['Funcionarios habilitados para expedir copias', 'Puntos de expedición del DNI electrónico', 'Prestadores cualificados de servicios de confianza', 'Oficinas de asistencia en materia de registros']::text[], 3, 'El artículo 11.2.i) incluye «un servicio de consulta del directorio geográfico de oficinas de asistencia en materia de registros, que permita al interesado identificar la más próxima a su dirección de consulta».', 1, '2026-10-13', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
