insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('rme-008', (select id from leyes where slug = 'rd-203-2021'), '12.2', 'Si una sede electrónica contiene un enlace a otra sede, ¿quién responde de la información que figura en esta última?', array['El titular de la sede que contiene el enlace', 'El titular de la sede enlazada', 'Ambos titulares, de forma solidaria', 'El gestor del Punto de Acceso General']::text[], 1, 'El artículo 12.2 dispone que en ese caso «será el titular de esta última el responsable de la integridad, veracidad y actualización de la información o procedimientos que figuren en la misma».', 3, '2026-10-13', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
