insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('rme-010', (select id from leyes where slug = 'rd-203-2021'), '14.1', 'Si un obligado a relacionarse electrónicamente presenta en papel una solicitud de iniciación y luego subsana, se considera fecha de presentación:', array['La fecha de la presentación en papel', 'La fecha del requerimiento de subsanación', 'La fecha de recepción en el órgano competente', 'La fecha de la subsanación']::text[], 3, 'El artículo 14.1 señala que, en una solicitud de iniciación, «la fecha de la subsanación se considerará a estos efectos como fecha de presentación de la solicitud».', 2, '2026-10-13', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
