insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('rme-011', (select id from leyes where slug = 'rd-203-2021'), '26.2', 'Las Administraciones deben garantizar que, en todo procedimiento, sea posible identificarse mediante:', array['Sistemas basados en certificados cualificados de firma o de sello electrónico', 'Sistemas de clave concertada con registro previo como usuario', 'Personal funcionario público habilitado para ello', 'Cualquier sistema que la Administración considere válido']::text[], 0, 'El artículo 26.2 dispone que las Administraciones «deberán garantizar que la utilización de uno de los sistemas previstos en las letras a) y b) sea posible para todo procedimiento», que son los basados en certificados cualificados de firma y de sello.', 2, '2026-10-13', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
