insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('rme-015', (select id from leyes where slug = 'rd-203-2021'), '43.1', 'La falta de práctica del aviso de puesta a disposición de una notificación:', array['Determina la nulidad de pleno derecho de la notificación', 'Hace anulable la notificación a instancia del interesado', 'No impide que la notificación se considere plenamente válida', 'Obliga a repetir la notificación en papel']::text[], 2, 'El artículo 43.1 señala que «la falta de práctica de este aviso, de carácter meramente informativo, no impedirá que la notificación sea considerada plenamente válida».', 1, '2026-10-13', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
