insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('rme-018', (select id from leyes where slug = 'rd-203-2021'), '38.2', 'Las anotaciones en el Registro General de la Administración General del Estado tienen plena eficacia y validez:', array['Solo para la Administración General del Estado', 'Solo para el sector público estatal', 'Para todas las Administraciones Públicas', 'Solo para el órgano destinatario']::text[], 2, 'El artículo 38.2 dice: «Las anotaciones en el Registro General de la Administración General del Estado tendrán plena eficacia y validez para todas las Administraciones Públicas».', 1, '2026-10-13', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
