insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('rme-019', (select id from leyes where slug = 'rd-203-2021'), '39.2', 'Si se detecta código malicioso que puede afectar a la seguridad del sistema en documentos ya registrados:', array['Se tienen por no presentados sin más trámite', 'Se destruyen y se archiva la solicitud', 'Se remiten al órgano destinatario tal como llegaron', 'Se requiere su subsanación al interesado que los aportó']::text[], 3, 'El artículo 39.2 prevé que en ese caso «se requerirá su subsanación al interesado que los haya aportado de acuerdo con lo previsto en el artículo 14.3 de este Reglamento».', 2, '2026-10-13', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
