insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('rme-026', (select id from leyes where slug = 'rd-203-2021'), '50.1.b', 'Los sellos electrónicos de tiempo no cualificados son asimilables a todos los efectos a:', array['Los sellos cualificados de tiempo', 'Las marcas de tiempo', 'Los códigos seguros de verificación', 'Las firmas electrónicas avanzadas']::text[], 1, 'El artículo 50.1.b) establece que «los sellos electrónicos de tiempo no cualificados serán asimilables a todos los efectos a las marcas de tiempo».', 3, '2026-10-13', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
