insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('rme-029', (select id from leyes where slug = 'rd-203-2021'), '53.1', 'Los documentos en papel que no pueden devolverse al interesado al presentarlos se conservan a su disposición, una vez digitalizados, durante:', array['Tres meses, salvo que se establezca un plazo mayor', 'Seis meses, salvo que se establezca un plazo mayor', 'Un año, salvo que se establezca un plazo mayor', 'Un mes, salvo que se establezca un plazo mayor']::text[], 1, 'El artículo 53.1 dispone que, una vez digitalizados, «serán conservados a su disposición durante seis meses para que pueda recogerlos».', 1, '2026-10-13', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
