insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('rme-030', (select id from leyes where slug = 'rd-203-2021'), '55.2', 'Los plazos en que los expedientes del sector público estatal son accesibles en su archivo electrónico único los determina:', array['El órgano que tramitó el procedimiento', 'La Comisión Ministerial de Administración Digital', 'El Consejo de Ministros mediante acuerdo', 'La Comisión Superior Calificadora de Documentos Administrativos']::text[], 3, 'El artículo 55.2 dice que serán accesibles una vez finalizados los procedimientos y «en los plazos determinados por la Comisión Superior Calificadora de Documentos Administrativos».', 3, '2026-10-13', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
