insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgss-001', (select id from leyes where slug = 'rdleg-8-2015'), '2.1', 'El sistema de la Seguridad Social se fundamenta en los principios de:', array['Universalidad, eficacia, solidaridad y suficiencia', 'Unidad, contributividad, equidad y suficiencia', 'Universalidad, unidad, solidaridad e igualdad', 'Generalidad, unidad, solidaridad y proporcionalidad']::text[], 2, 'El artículo 2.1 dice que el sistema de la Seguridad Social «se fundamenta en los principios de universalidad, unidad, solidaridad e igualdad».', 1, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
