insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgss-002', (select id from leyes where slug = 'rdleg-8-2015'), '7.1.b', 'A efectos de las prestaciones contributivas, se incluyen en el sistema los trabajadores autónomos que sean:', array['Mayores de dieciséis años', 'Mayores de dieciocho años', 'Mayores de veintiún años', 'Menores de sesenta y siete años']::text[], 1, 'El artículo 7.1.b) comprende a los «Trabajadores por cuenta propia o autónomos, sean o no titulares de empresas individuales o familiares, mayores de dieciocho años».', 2, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
