insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgss-003', (select id from leyes where slug = 'rdleg-8-2015'), '7.2', 'A efectos de las prestaciones no contributivas, están comprendidos en el campo de aplicación del sistema:', array['Todos los españoles residentes en territorio español', 'Los españoles con al menos quince años cotizados', 'Los españoles mayores de sesenta y cinco años', 'Los españoles que residan en cualquier Estado de la UE']::text[], 0, 'El artículo 7.2 incluye en el campo de aplicación del sistema, «a efectos de las prestaciones no contributivas, todos los españoles residentes en territorio español».', 1, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
