insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgss-004', (select id from leyes where slug = 'rdleg-8-2015'), '9.1', 'Según la LGSS, el sistema de la Seguridad Social está integrado por:', array['Los niveles contributivo, asistencial y complementario', 'El Régimen General y el Régimen de Clases Pasivas', 'El Régimen General y los sistemas especiales agrarios', 'El Régimen General y los regímenes especiales']::text[], 3, 'El artículo 9.1 dispone: «El sistema de la Seguridad Social viene integrado por los siguientes regímenes: a) El Régimen General […] b) Los regímenes especiales».', 1, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
