insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgss-005', (select id from leyes where slug = 'rdleg-8-2015'), '10.3', 'Se rigen por las leyes específicas que se dicten al efecto los regímenes especiales de:', array['Trabajadores autónomos y estudiantes', 'Trabajadores del mar y funcionarios públicos, civiles y militares', 'Funcionarios públicos y trabajadores autónomos', 'Trabajadores del mar y estudiantes']::text[], 1, 'Según el artículo 10.3, los regímenes de las letras b) («Trabajadores del mar») y c) («Funcionarios públicos, civiles y militares») del apartado 2 «se regirán por las leyes específicas que se dicten al efecto».', 3, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
