insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgss-006', (select id from leyes where slug = 'rdleg-8-2015'), '15', 'La afiliación a la Seguridad Social es obligatoria y:', array['Única para toda la vida y para todo el sistema', 'Distinta para cada régimen en que se trabaje', 'Renovable cada vez que se cambia de empresa', 'Única para cada empresa y para cada régimen']::text[], 0, 'El artículo 15 dice: «La afiliación a la Seguridad Social es obligatoria para las personas a que se refiere el artículo 7.1 y única para toda su vida y para todo el sistema».', 1, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'lgss-006', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 31 where o.slug = 'admin-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgss-007', (select id from leyes where slug = 'rdleg-8-2015'), '16.5', 'Si una afiliación o un alta no es conforme con la ley, la Administración de la Seguridad Social puede revisarla de oficio:', array['En el plazo de cuatro años', 'Solo en el año siguiente al alta', 'Solo antes de que el acto sea firme', 'En cualquier momento']::text[], 3, 'El artículo 16.5 establece que los organismos de la Administración de la Seguridad Social «podrán revisar de oficio, en cualquier momento, sus actos dictados en las citadas materias».', 2, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
