insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgss-008', (select id from leyes where slug = 'rdleg-8-2015'), '18.2', 'La obligación de cotizar a la Seguridad Social nace:', array['Desde la afiliación del trabajador', 'Al mes siguiente del alta en el régimen', 'Desde el momento de iniciación de la actividad', 'Desde la firma del contrato de trabajo']::text[], 2, 'El artículo 18.2 dice: «La obligación de cotizar nacerá desde el momento de iniciación de la actividad correspondiente».', 1, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'lgss-008', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 31 where o.slug = 'admin-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgss-009', (select id from leyes where slug = 'rdleg-8-2015'), '19.2', 'Salvo disposición expresa en contrario, el tope mínimo de las bases de cotización es el salario mínimo interprofesional vigente:', array['Incrementado en un sexto', 'Incrementado en un quinto', 'Incrementado en un tercio', 'Sin incremento alguno']::text[], 0, 'El artículo 19.2 fija «como tope mínimo las cuantías del salario mínimo interprofesional vigente en cada momento, incrementadas en un sexto, salvo disposición expresa en contrario».', 3, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
