insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgss-010', (select id from leyes where slug = 'rdleg-8-2015'), '42.2', 'Como complemento de las prestaciones de la acción protectora del sistema, podrán otorgarse los beneficios de:', array['La previsión social empresarial', 'Los planes de pensiones individuales', 'Los seguros privados de salud', 'La asistencia social']::text[], 3, 'El artículo 42.2 dice: «como complemento de las prestaciones comprendidas en el apartado anterior, podrán otorgarse los beneficios de la asistencia social».', 2, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
