insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgss-011', (select id from leyes where slug = 'rdleg-8-2015'), '136.2.k', 'El personal civil no funcionario de las administraciones públicas está incluido en el Régimen General:', array['Solo si tiene un contrato de duración indefinida', 'Salvo que una ley especial lo incluya en otro régimen obligatorio', 'Solo a efectos de las prestaciones por desempleo', 'Únicamente si presta servicios a tiempo completo']::text[], 1, 'El artículo 136.2.k) incluye a «El personal civil no funcionario de las administraciones públicas […] siempre que no estén incluidos en virtud de una ley especial en otro régimen obligatorio de previsión social».', 2, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'lgss-011', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 31 where o.slug = 'admin-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgss-012', (select id from leyes where slug = 'rdleg-8-2015'), '137.a', 'No dan lugar a inclusión en el Régimen General los trabajos ejecutados ocasionalmente mediante servicios:', array['Retribuidos en especie', 'Prestados en días festivos', 'Amistosos, benévolos o de buena vecindad', 'De duración inferior a una jornada']::text[], 2, 'El artículo 137.a) excluye «Los que se ejecuten ocasionalmente mediante los llamados servicios amistosos, benévolos o de buena vecindad».', 1, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'lgss-012', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 31 where o.slug = 'admin-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgss-013', (select id from leyes where slug = 'rdleg-8-2015'), '140.2', 'La afiliación y las altas solicitadas fuera de plazo por el empresario o el trabajador:', array['No tienen efecto retroactivo alguno', 'Tienen efectos desde el inicio de la actividad', 'Tienen efectos desde el mes anterior a la solicitud', 'Son nulas y deben solicitarse de nuevo']::text[], 0, 'El artículo 140.2 dice: «La afiliación y altas sucesivas solicitadas fuera de plazo por el empresario o el trabajador no tendrán efecto retroactivo alguno».', 2, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'lgss-013', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 31 where o.slug = 'admin-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgss-014', (select id from leyes where slug = 'rdleg-8-2015'), '156.3', 'Se presume, salvo prueba en contrario, que son accidente de trabajo las lesiones que el trabajador sufra:', array['En las veinticuatro horas siguientes a la jornada', 'Durante las vacaciones anuales retribuidas', 'Durante el tiempo y en el lugar del trabajo', 'En cualquier lugar, si es trabajador fijo']::text[], 2, 'El artículo 156.3 dice: «Se presumirá, salvo prueba en contrario, que son constitutivas de accidente de trabajo las lesiones que sufra el trabajador durante el tiempo y en el lugar del trabajo».', 1, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'lgss-014', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 31 where o.slug = 'admin-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgss-015', (select id from leyes where slug = 'rdleg-8-2015'), '156.4.b', 'No tiene la consideración de accidente de trabajo el debido a:', array['La imprudencia profesional nacida de la confianza en el trabajo', 'Una insolación sufrida mientras se trabaja', 'La culpa civil de un compañero de trabajo', 'Dolo o imprudencia temeraria del trabajador accidentado']::text[], 3, 'El artículo 156.4.b) excluye «Los que sean debidos a dolo o a imprudencia temeraria del trabajador accidentado». En cambio, «En ningún caso se considerará fuerza mayor extraña al trabajo la insolación».', 2, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'lgss-015', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 31 where o.slug = 'admin-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgss-016', (select id from leyes where slug = 'rdleg-8-2015'), '157', 'Es enfermedad profesional la contraída por el trabajo por cuenta ajena en las actividades que especifique:', array['El convenio colectivo del sector correspondiente', 'El cuadro aprobado por las normas de desarrollo de la ley', 'La evaluación de riesgos laborales de la empresa', 'El parte médico de baja de la mutua colaboradora']::text[], 1, 'El artículo 157 la define como «la contraída a consecuencia del trabajo ejecutado por cuenta ajena en las actividades que se especifiquen en el cuadro que se apruebe por las disposiciones de aplicación y desarrollo de esta ley».', 2, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'lgss-016', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 31 where o.slug = 'admin-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgss-017', (select id from leyes where slug = 'rdleg-8-2015'), '169.1.a', 'La incapacidad temporal por enfermedad o accidente tiene una duración máxima de:', array['Ciento ochenta días, prorrogables por otros ciento ochenta', 'Trescientos sesenta y cinco días, sin prórroga posible', 'Quinientos cuarenta y cinco días, prorrogables por noventa', 'Trescientos sesenta y cinco días, prorrogables por otros ciento ochenta']::text[], 3, 'El artículo 169.1.a) fija «una duración máxima de trescientos sesenta y cinco días, prorrogables por otros ciento ochenta días cuando se presuma que durante ellos puede el trabajador ser dado de alta médica por curación».', 1, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'lgss-017', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 31 where o.slug = 'admin-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgss-018', (select id from leyes where slug = 'rdleg-8-2015'), '169.2', 'Hay recaída en un mismo proceso de IT si la nueva baja por la misma o similar patología se produce dentro de los:', array['Ciento ochenta días naturales siguientes al alta anterior', 'Noventa días naturales siguientes al alta anterior', 'Trescientos sesenta y cinco días siguientes al alta anterior', 'Treinta días hábiles siguientes al alta anterior']::text[], 0, 'El artículo 169.2 dice que existe recaída «cuando se produzca una nueva baja médica por la misma o similar patología dentro de los ciento ochenta días naturales siguientes a la fecha de efectos de alta médica anterior».', 3, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'lgss-018', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 31 where o.slug = 'admin-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgss-019', (select id from leyes where slug = 'rdleg-8-2015'), '172.a', 'Para el subsidio de incapacidad temporal por enfermedad común se exige haber cotizado:', array['Noventa días en los dos años anteriores al hecho causante', 'Trescientos sesenta días en los seis años anteriores', 'Ciento ochenta días en los cinco años anteriores al hecho causante', 'Quinientos días en los siete años anteriores']::text[], 2, 'El artículo 172.a) exige, «En caso de enfermedad común, ciento ochenta días dentro de los cinco años inmediatamente anteriores al hecho causante».', 2, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'lgss-019', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 31 where o.slug = 'admin-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgss-020', (select id from leyes where slug = 'rdleg-8-2015'), '173.1', 'En IT por enfermedad común, el subsidio desde el día cuarto al decimoquinto de baja, ambos inclusive, corre a cargo:', array['De la entidad gestora', 'Del empresario', 'De la mutua colaboradora', 'Del Servicio Público de Salud']::text[], 1, 'El artículo 173.1 dice que el subsidio se abona «a partir del cuarto día de baja en el trabajo, si bien desde el día cuarto al decimoquinto de baja, ambos inclusive, el subsidio estará a cargo del empresario».', 1, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
