insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgss-021', (select id from leyes where slug = 'rdleg-8-2015'), '174.1', 'El subsidio por incapacidad temporal se extingue por el transcurso, desde la baja médica, de un plazo máximo de:', array['Quinientos cuarenta y cinco días naturales', 'Trescientos sesenta y cinco días naturales', 'Setecientos treinta días naturales', 'Cuatrocientos cincuenta días naturales']::text[], 0, 'El artículo 174.1 dice: «El derecho al subsidio se extinguirá por el transcurso del plazo máximo de quinientos cuarenta y cinco días naturales desde la baja médica».', 1, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
