insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgss-022', (select id from leyes where slug = 'rdleg-8-2015'), '178.1.a', 'El subsidio por nacimiento y cuidado de menor no exige período mínimo de cotización si la persona trabajadora tiene:', array['Menos de dieciocho años', 'Menos de veintiséis años', 'Menos de treinta años', 'Menos de veintiún años']::text[], 3, 'El artículo 178.1.a) dice: «Si la persona trabajadora tiene menos de veintiún años de edad en la fecha del nacimiento […] no se exigirá período mínimo de cotización».', 2, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
