insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgss-023', (select id from leyes where slug = 'rdleg-8-2015'), '194.1', '¿Cuál de los siguientes NO es un grado de incapacidad permanente según la LGSS?', array['Incapacidad permanente parcial', 'Gran incapacidad', 'Incapacidad permanente severa', 'Incapacidad permanente absoluta']::text[], 2, 'El artículo 194.1 enumera los grados: «a) Incapacidad permanente parcial. b) Incapacidad permanente total. c) Incapacidad permanente absoluta. d) Gran incapacidad».', 1, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
