insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgss-024', (select id from leyes where slug = 'rdleg-8-2015'), '205.1.a', 'La pensión de jubilación exige haber cumplido sesenta y siete años, o sesenta y cinco si se acreditan:', array['Treinta y cinco años de cotización', 'Treinta y ocho años y seis meses de cotización', 'Cuarenta años de cotización', 'Treinta y seis años y seis meses de cotización']::text[], 1, 'El artículo 205.1.a) exige «Haber cumplido sesenta y siete años de edad, o sesenta y cinco años cuando se acrediten treinta y ocho años y seis meses de cotización».', 2, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'lgss-024', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 31 where o.slug = 'admin-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgss-025', (select id from leyes where slug = 'rdleg-8-2015'), '213.4', 'La pensión de jubilación es compatible con trabajos por cuenta propia cuyos ingresos anuales totales no superen:', array['El salario mínimo interprofesional, en cómputo anual', 'El doble del IPREM en cómputo anual', 'La base mínima de cotización anual', 'El importe anual de la propia pensión']::text[], 0, 'El artículo 213.4 dice: «El percibo de la pensión de jubilación será compatible con la realización de trabajos por cuenta propia cuyos ingresos anuales totales no superen el salario mínimo interprofesional, en cómputo anual».', 2, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
