insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgss-026', (select id from leyes where slug = 'rdleg-8-2015'), '216.2', 'En caso de muerte causada por accidente de trabajo o enfermedad profesional se reconoce, además:', array['Un subsidio temporal de viudedad', 'Una indemnización a tanto alzado', 'Una pensión vitalicia en favor de familiares', 'Un doble auxilio por defunción']::text[], 1, 'El artículo 216.2 dice: «En caso de muerte causada por accidente de trabajo o enfermedad profesional se reconocerá, además, una indemnización a tanto alzado».', 2, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'lgss-026', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 31 where o.slug = 'admin-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgss-027', (select id from leyes where slug = 'rdleg-8-2015'), '219.1', 'Si el causante estaba en alta al fallecer por enfermedad común, la pensión de viudedad exige que haya cotizado:', array['Quince años a lo largo de su vida laboral', 'Ciento ochenta días en los cinco años anteriores', 'Trescientos sesenta días en los siete años anteriores', 'Quinientos días en los cinco años anteriores']::text[], 3, 'El artículo 219.1 exige, si el causante estaba en alta, que «hubiera completado un período de cotización de quinientos días, dentro de los cinco años inmediatamente anteriores a la fecha del hecho causante de la pensión». Los quince años se piden si no estaba en alta.', 3, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'lgss-027', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 31 where o.slug = 'admin-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgss-028', (select id from leyes where slug = 'rdleg-8-2015'), '263.1', 'La protección por desempleo se estructura en:', array['Un nivel contributivo y un nivel complementario libre', 'Un nivel básico, uno asistencial y uno complementario', 'Un nivel contributivo y un nivel asistencial', 'Un único nivel contributivo y obligatorio']::text[], 2, 'El artículo 263.1 dice: «La protección por desempleo se estructura en un nivel contributivo y en un nivel asistencial, ambos de carácter público y obligatorio».', 1, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
