insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgss-029', (select id from leyes where slug = 'rdleg-8-2015'), '266.b', 'Para la prestación contributiva por desempleo, el período mínimo de cotización debe cubrirse dentro de los:', array['Seis años anteriores a la situación legal de desempleo', 'Cuatro años anteriores a la situación legal de desempleo', 'Cinco años anteriores a la situación legal de desempleo', 'Diez años anteriores a la situación legal de desempleo']::text[], 0, 'El artículo 266.b) exige «Tener cubierto el período mínimo de cotización a que se refiere el artículo 269.1, dentro de los seis años anteriores a la situación legal de desempleo».', 3, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
