insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgss-030', (select id from leyes where slug = 'rdleg-8-2015'), '262.3', 'El desempleo es parcial cuando la jornada diaria ordinaria se reduce temporalmente, con análoga reducción del salario, entre un:', array['5 y un 50 por ciento', '10 y un 50 por ciento', '20 y un 70 por ciento', '10 y un 70 por ciento']::text[], 3, 'El artículo 262.3 dice que el desempleo es parcial cuando la jornada diaria ordinaria se reduce temporalmente «entre un mínimo de un 10 y un máximo de un 70 por ciento, siempre que el salario sea objeto de análoga reducción».', 3, '2026-10-05', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
