insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sre-001', (select id from leyes where slug = 'trebep'), '64.3', 'La renuncia a la condición de funcionario de carrera:', array['Inhabilita para ingresar de nuevo en la Administración durante cinco años', 'No inhabilita para ingresar de nuevo a través del procedimiento de selección', 'Inhabilita definitivamente para ingresar en el mismo cuerpo o escala', 'Solo permite volver a ingresar mediante la rehabilitación del interesado']::text[], 1, 'El artículo 64.3 dispone que «La renuncia a la condición de funcionario no inhabilita para ingresar de nuevo en la Administración Pública a través del procedimiento de selección establecido».', 1, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
