insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'sre-001', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 7 where o.slug = 'agente-aeat' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sre-002', (select id from leyes where slug = 'trebep'), '65', 'La pérdida de la nacionalidad tenida en cuenta para el nombramiento no determina la pérdida de la condición de funcionario si:', array['El funcionario lleva más de cinco años en servicio activo', 'Lo autoriza expresamente el órgano que efectuó el nombramiento', 'El funcionario se encuentra en situación de servicios especiales', 'Simultáneamente se adquiere la nacionalidad de alguno de los Estados previstos']::text[], 3, 'El artículo 65 establece que la pérdida de la nacionalidad «determinará la pérdida de la condición de funcionario salvo que simultáneamente se adquiera la nacionalidad de alguno de dichos Estados».', 2, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
