insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sre-005', (select id from leyes where slug = 'trebep'), '87.2', 'Los funcionarios en situación de servicios especiales perciben:', array['Las retribuciones de funcionario de carrera, más las del cargo', 'Las retribuciones del puesto o cargo, sin perjuicio de sus trienios', 'Solo las retribuciones básicas como funcionarios de carrera', 'El 50 por 100 de sus retribuciones como funcionarios de carrera']::text[], 1, 'Según el artículo 87.2, «percibirán las retribuciones del puesto o cargo que desempeñen y no las que les correspondan como funcionarios de carrera, sin perjuicio del derecho a percibir los trienios que tengan reconocidos en cada momento».', 1, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
