insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sre-006', (select id from leyes where slug = 'trebep'), '88.3', 'El tiempo de servicio en otra Administración a la que el funcionario llegó por un sistema de provisión de puestos:', array['No se computa a ningún efecto en su Administración de origen', 'Se computa únicamente a efectos de reconocimiento de trienios', 'Se computa solo si reingresa en su Administración antes de dos años', 'Se le computa como de servicio activo en su cuerpo o escala de origen']::text[], 3, 'El artículo 88.3 dispone: «El tiempo de servicio en la Administración Pública en la que estén destinados se les computará como de servicio activo en su cuerpo o escala de origen».', 2, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
