insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sre-007', (select id from leyes where slug = 'trebep'), '89.3', 'Para conceder la excedencia voluntaria por agrupación familiar, el TREBEP:', array['No exige haber prestado servicios efectivos durante un periodo previo', 'Exige cinco años de servicios efectivos inmediatamente anteriores', 'Exige tres años de servicios efectivos en cualquier Administración', 'Exige un año de servicios efectivos en el mismo cuerpo o escala']::text[], 0, 'Según el artículo 89.3, la excedencia por agrupación familiar puede concederse «sin el requisito de haber prestado servicios efectivos en cualquiera de las Administraciones Públicas durante el periodo establecido».', 2, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
