insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sre-008', (select id from leyes where slug = 'trebep'), '89.4', 'La excedencia para cuidar a un familiar a cargo que no pueda valerse por sí mismo alcanza a familiares hasta el:', array['Primer grado de consanguinidad o afinidad', 'Tercer grado de consanguinidad y segundo de afinidad', 'Segundo grado inclusive de consanguinidad o afinidad', 'Cuarto grado de consanguinidad o afinidad']::text[], 2, 'El artículo 89.4 reconoce la excedencia «para atender al cuidado de un familiar que se encuentre a su cargo, hasta el segundo grado inclusive de consanguinidad o afinidad».', 1, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
