insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sre-010', (select id from leyes where slug = 'trebep'), '90.2', 'La suspensión firme de funciones impuesta por sanción disciplinaria no puede exceder de:', array['Seis años', 'Seis meses', 'Tres años', 'Cuatro años']::text[], 0, 'El artículo 90.2 establece: «La suspensión firme por sanción disciplinaria no podrá exceder de seis años».', 1, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
