insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sre-012', (select id from leyes where slug = 'rd-365-1995'), '22.3', 'El funcionario que perdió su puesto de trabajo por una suspensión firme debe solicitar el reingreso al servicio activo:', array['En el mes siguiente a la finalización de la suspensión', 'Con tres meses de antelación al fin de la suspensión', 'Con un mes de antelación a la finalización de la suspensión', 'En cualquier momento tras cumplir la mitad de la sanción']::text[], 2, 'Según el artículo 22.3, el funcionario «deberá solicitar el reingreso al servicio activo con un mes de antelación a la finalización del período de duración de la suspensión».', 3, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
