insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sre-013', (select id from leyes where slug = 'rd-365-1995'), '12.2', 'Según el RD 365/1995, ¿cuál es el periodo máximo de permanencia en la situación de expectativa de destino?', array['Seis meses', 'Dos años', 'Dieciocho meses', 'Un año']::text[], 3, 'El artículo 12.2 establece: «Los funcionarios permanecerán en esta situación un período máximo de un año, transcurrido el cual pasarán a la situación de excedencia forzosa».', 1, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
