insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sre-014', (select id from leyes where slug = 'rd-365-1995'), '23.1', 'Según el RD 365/1995, los cambios de situaciones administrativas deben comunicarse siempre:', array['Al Registro Central de Personal', 'A la Intervención General de la Administración del Estado', 'Al Tribunal de Cuentas', 'A la Comisión Superior de Personal']::text[], 0, 'El artículo 23.1 dispone que «Los cambios de situaciones administrativas deberán ser siempre comunicados al Registro Central de Personal».', 1, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
