insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sre-016', (select id from leyes where slug = 'trebep'), '22.5', 'Según el TREBEP, la participación o premio en multas impuestas como contraprestación de un servicio:', array['Se permite si está atribuida normativamente a los servicios', 'Se permite hasta el 10 por 100 del importe de la multa', 'No podrá percibirse, aunque esté atribuida normativamente', 'Solo se permite como parte del complemento de productividad']::text[], 2, 'El artículo 22.5 dispone que no podrá percibirse «participación o premio en multas impuestas, aun cuando estuviesen normativamente atribuidas a los servicios».', 2, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
