insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sre-017', (select id from leyes where slug = 'trebep'), '24', 'Según el TREBEP, la cuantía y estructura de las retribuciones complementarias de los funcionarios se establecen por:', array['Las mesas generales de negociación de cada Administración', 'Los convenios colectivos de cada Administración Pública', 'Real decreto aprobado por el Consejo de Ministros', 'Las correspondientes leyes de cada Administración Pública']::text[], 3, 'El artículo 24 dispone: «La cuantía y estructura de las retribuciones complementarias de los funcionarios se establecerán por las correspondientes leyes de cada Administración Pública».', 1, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
