insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sre-018', (select id from leyes where slug = 'trebep'), '25.1', 'Los funcionarios interinos perciben las retribuciones complementarias correspondientes a:', array['La categoría de entrada en el cuerpo o escala en que se les nombre', 'La categoría consolidada por el funcionario de carrera sustituido', 'El nivel máximo del intervalo asignado a su cuerpo o escala', 'El grado personal que tendría un funcionario con su antigüedad']::text[], 0, 'El artículo 25.1 dispone que percibirán las complementarias de los apartados b), c) y d) del artículo 24 «y las correspondientes a la categoría de entrada en el cuerpo o escala en el que se le nombre».', 2, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
