insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sre-019', (select id from leyes where slug = 'trebep'), '26', 'Las retribuciones de los funcionarios en prácticas se corresponderán, como mínimo, con:', array['Las retribuciones básicas y complementarias del puesto', 'El sueldo del Subgrupo o Grupo en que aspiren a ingresar', 'El 50 por 100 del sueldo del Subgrupo de ingreso', 'El salario mínimo interprofesional vigente']::text[], 1, 'Según el artículo 26, las retribuciones de los funcionarios en prácticas, «como mínimo, se corresponderán a las del sueldo del Subgrupo o Grupo, en el supuesto de que éste no tenga Subgrupo, en que aspiren a ingresar».', 1, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
