insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sre-020', (select id from leyes where slug = 'trebep'), '29', 'Las cantidades destinadas a financiar aportaciones a planes de pensiones de empleo tienen la consideración de:', array['Retribución complementaria', 'Indemnización por razón del servicio', 'Retribución diferida', 'Prestación de acción social']::text[], 2, 'El artículo 29 establece que las cantidades destinadas a financiar aportaciones a planes de pensiones o contratos de seguros «tendrán a todos los efectos la consideración de retribución diferida».', 2, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
