insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sre-021', (select id from leyes where slug = 'trebep'), '30.1', 'La deducción proporcional de haberes por la parte de jornada no realizada:', array['Tiene carácter de sanción disciplinaria leve', 'Sustituye a cualquier sanción disciplinaria', 'Requiere la previa instrucción de un expediente', 'No tiene carácter sancionador']::text[], 3, 'El artículo 30.1 dispone: «Sin perjuicio de la sanción disciplinaria que pueda corresponder, la parte de jornada no realizada dará lugar a la deducción proporcional de haberes, que no tendrá carácter sancionador».', 1, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
