insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sre-023', (select id from leyes where slug = 'trebep'), '22.2', 'Las retribuciones básicas retribuyen al funcionario según la adscripción de su cuerpo o escala a un Subgrupo o Grupo y:', array['Por el nivel del puesto que desempeña', 'Por su antigüedad en el mismo', 'Por el rendimiento obtenido', 'Por la dificultad técnica del puesto']::text[], 1, 'Según el artículo 22.2, las retribuciones básicas retribuyen al funcionario según la adscripción de su cuerpo o escala a un Subgrupo o Grupo «y por su antigüedad en el mismo».', 1, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
