insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sre-024', (select id from leyes where slug = 'ley-30-1984'), '23.3.b', 'Según la Ley 30/1984, ¿cuántos complementos específicos pueden asignarse a cada puesto de trabajo?', array['Uno como máximo', 'Dos como máximo', 'Tantos como factores concurran', 'Uno por cada factor de penosidad']::text[], 0, 'El artículo 23.3.b) dispone: «En ningún caso podrá asignarse más de un complemento específico a cada puesto de trabajo».', 1, '2026-02-23', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
