insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sre-025', (select id from leyes where slug = 'ley-30-1984'), '23.3.c', 'Según la Ley 30/1984, las cantidades que percibe cada funcionario por complemento de productividad:', array['Son reservadas y solo las conoce el propio funcionario interesado', 'Solo se comunican a la Intervención Delegada del departamento', 'Son de conocimiento público de los funcionarios y representantes sindicales', 'Se publican cada trimestre en el Boletín Oficial del Estado']::text[], 2, 'El artículo 23.3.c) dispone que «las cantidades que perciba cada funcionario por este concepto serán de conocimiento público de los demás funcionarios del Departamento u Organismo interesado así como de los representantes sindicales».', 2, '2026-02-23', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
