insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sre-026', (select id from leyes where slug = 'ley-30-1984'), '23.3.d', 'Según la Ley 30/1984, las gratificaciones por servicios extraordinarios fuera de la jornada normal:', array['Son fijas en su cuantía y periódicas en su devengo', 'Se devengan mensualmente junto con el sueldo', 'Se integran en el complemento específico del puesto', 'Nunca pueden ser fijas en cuantía y periódicas en devengo']::text[], 3, 'El artículo 23.3.d) se refiere a «Las gratificaciones por servicios extraordinarios, fuera de la jornada normal, que en ningún caso podrán ser fijas en su cuantía y periódicas en su devengo».', 1, '2026-02-23', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
