insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sre-027', (select id from leyes where slug = 'ley-30-1984'), '23.2.b', 'Según la Ley 30/1984, si un funcionario cambia de grupo antes de completar un trienio, la fracción de tiempo transcurrido:', array['Se pierde a efectos de trienios', 'Se considera tiempo de servicios prestados en el nuevo grupo', 'Se computa en el grupo anterior solo si supera un año', 'Se abona como parte proporcional del trienio']::text[], 1, 'El artículo 23.2.b) dispone: «Cuando un funcionario cambie de adscripción a grupo antes de completar un trienio, la fracción de tiempo transcurrido se considerará como tiempo de servicios prestados en el nuevo grupo».', 3, '2026-02-23', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
