insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sre-028', (select id from leyes where slug = 'rd-462-2002'), '5.1', 'Salvo casos excepcionales, una comisión de servicio con derecho a indemnización en territorio nacional no durará más de:', array['Quince días', 'Tres meses', 'Un mes', 'Seis meses']::text[], 2, 'El artículo 5.1 dispone: «Toda comisión con derecho a indemnización, salvo casos excepcionales, no durará más de un mes en territorio nacional y de tres en el extranjero».', 1, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
