insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sre-029', (select id from leyes where slug = 'rd-462-2002'), '6.2', 'Según el RD 462/2002, la duración de la residencia eventual no podrá exceder, salvo prórroga, de:', array['Un año', 'Seis meses', 'Tres meses', 'Dos años']::text[], 0, 'El artículo 6.2 dispone: «La duración de la residencia eventual no podrá exceder de un año, salvo que se prorrogue por el tiempo estrictamente indispensable».', 2, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
