insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sre-031', (select id from leyes where slug = 'rd-462-2002'), '16.1', 'La indemnización por residencia eventual la fija la autoridad que confiere la comisión con un límite máximo, sin justificación documental, del:', array['50 por 100 de las dietas enteras', '60 por 100 de las dietas enteras', '100 por 100 de las dietas enteras', '80 por 100 de las dietas enteras']::text[], 3, 'El artículo 16.1 dispone que la cuantía se fijará «dentro del límite máximo, sin que se necesite justificación documental, del 80 por 100 del importe de las dietas enteras».', 2, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
