insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('sre-032', (select id from leyes where slug = 'rd-462-2002'), '32', 'Lo percibido al año por asistencias a tribunales y órganos de selección no puede superar, de las retribuciones anuales del puesto principal, el:', array['40 por 100', '50 por 100', '20 por 100', '25 por 100']::text[], 2, 'El artículo 32 impide percibir por estas asistencias «un importe total por año natural superior al 20 por 100 de las retribuciones anuales, excluidas las de carácter personal derivadas de la antigüedad, que correspondan por el puesto de trabajo principal».', 3, '2025-12-18', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
