insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgs-001', (select id from leyes where slug = 'ley-38-2003'), '2.1.a', 'Para que una disposición dineraria sea subvención, la entrega debe realizarse:', array['Sin contraprestación directa de los beneficiarios', 'Con una contraprestación equivalente del beneficiario', 'Siempre en régimen de concurrencia competitiva', 'Solo a favor de personas jurídicas privadas']::text[], 0, 'El artículo 2.1.a) exige «Que la entrega se realice sin contraprestación directa de los beneficiarios».', 1, '2026-10-14', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
