insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgs-002', (select id from leyes where slug = 'ley-38-2003'), '2.4.g', 'Según el artículo 2.4 de la Ley General de Subvenciones, no tienen carácter de subvención:', array['Las subvenciones nominativas de los Presupuestos Generales del Estado', 'Las ayudas otorgadas en régimen de concurrencia competitiva', 'Los beneficios fiscales y en la cotización a la Seguridad Social', 'Las entregas sin contraprestación para fomentar el interés social']::text[], 2, 'El artículo 2.4 dice que «No tienen carácter de subvenciones los siguientes supuestos» e incluye en la letra g) «Los beneficios fiscales y beneficios en la cotización a la Seguridad Social».', 2, '2026-10-14', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
