insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgs-003', (select id from leyes where slug = 'ley-38-2003'), '3.2', 'Los organismos de derecho público vinculados a una Administración ajustan sus subvenciones a la Ley 38/2003:', array['Solo cuando se financien con fondos de la Unión Europea', 'En la medida en que sean consecuencia del ejercicio de potestades administrativas', 'Únicamente si su cuantía supera los 12 millones de euros', 'Solo cuando se concedan de forma directa']::text[], 1, 'El artículo 3.2 dispone que se ajustarán a esta ley «en la medida en que las subvenciones que otorguen sean consecuencia del ejercicio de potestades administrativas».', 2, '2026-10-14', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
