insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgs-004', (select id from leyes where slug = 'ley-38-2003'), '8.1', 'Antes de establecer subvenciones, los órganos que las propongan deben concretar sus objetivos y efectos en:', array['El plan anual normativo', 'Una memoria de impacto económico', 'Un informe de la Intervención General', 'Un plan estratégico de subvenciones']::text[], 3, 'El artículo 8.1 obliga a que, «con carácter previo, deberán concretar en un plan estratégico de subvenciones los objetivos y efectos que se pretenden con su aplicación».', 1, '2026-10-14', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
