insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgs-005', (select id from leyes where slug = 'ley-38-2003'), '8.3.c', 'Entre los principios de gestión de las subvenciones, la eficiencia se refiere a:', array['La asignación y utilización de los recursos públicos', 'El cumplimiento de los objetivos fijados por la Administración otorgante', 'La comparación de las solicitudes presentadas', 'La corrección de fallos del mercado claramente identificados']::text[], 0, 'El artículo 8.3 recoge en la letra c) la «Eficiencia en la asignación y utilización de los recursos públicos».', 2, '2026-10-14', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
