insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgs-007', (select id from leyes where slug = 'ley-38-2003'), '10.1', 'En la Administración General del Estado, son órganos competentes para conceder subvenciones:', array['Solo el Consejo de Ministros', 'Los Ministros y los Secretarios de Estado', 'Los Subsecretarios y los Directores generales', 'Los Delegados del Gobierno']::text[], 1, 'El artículo 10.1 establece que «Los Ministros y los Secretarios de Estado en la Administración General del Estado» son «los órganos competentes para conceder subvenciones».', 1, '2026-10-14', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
