insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgs-008', (select id from leyes where slug = 'ley-38-2003'), '10.2', 'Requiere la previa autorización del Consejo de Ministros la concesión de subvenciones de cuantía superior a:', array['6 millones de euros', '30 millones de euros', '12 millones de euros', '3 millones de euros']::text[], 2, 'El artículo 10.2 dice que «la concesión de subvenciones de cuantía superior a 12 millones de euros requerirá la previa autorización del Consejo de Ministros».', 2, '2026-10-14', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
