insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgs-009', (select id from leyes where slug = 'ley-38-2003'), '11.3', 'Una agrupación sin personalidad jurídica que sea beneficiaria de una subvención no podrá disolverse hasta que:', array['Se haya aprobado la justificación de la subvención', 'Se haya realizado el pago total de la subvención', 'Haya transcurrido el plazo de prescripción de los artículos 39 y 65', 'Haya transcurrido un año desde la concesión']::text[], 2, 'El artículo 11.3 dispone: «No podrá disolverse la agrupación hasta que haya transcurrido el plazo de prescripción previsto en los artículos 39 y 65 de esta ley».', 3, '2026-10-14', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
