insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgs-010', (select id from leyes where slug = 'ley-38-2003'), '12.1', 'Los fondos públicos que recibe una entidad colaboradora para entregarlos a los beneficiarios:', array['En ningún caso se consideran integrantes de su patrimonio', 'Se integran en su patrimonio hasta que los entregue', 'Se integran en su patrimonio si lo prevén las bases', 'Se consideran ingresos propios de la entidad']::text[], 0, 'El artículo 12.1, sobre los fondos que entrega y distribuye la entidad colaboradora, dice: «Estos fondos, en ningún caso, se considerarán integrantes de su patrimonio».', 2, '2026-10-14', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
