insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgs-011', (select id from leyes where slug = 'ley-38-2003'), '13.2.f', 'Impide obtener la condición de beneficiario de una subvención:', array['Haber obtenido otra subvención el año anterior', 'Ser una persona jurídica sin ánimo de lucro', 'Aportar fondos propios a la actividad', 'Tener la residencia fiscal en un paraíso fiscal']::text[], 3, 'Según el artículo 13.2.f), no puede ser beneficiario quien incurra en «Tener la residencia fiscal en un país o territorio calificado reglamentariamente como paraíso fiscal».', 1, '2026-10-14', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
