insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgs-012', (select id from leyes where slug = 'ley-38-2003'), '14.1.d', 'El beneficiario debe comunicar la obtención de otras subvenciones que financien la actividad subvencionada:', array['En el plazo de un mes desde que las obtenga', 'Tan pronto como lo conozca y, en todo caso, antes de justificar los fondos', 'Junto con la solicitud de pago de la subvención', 'Solo si superan el coste de la actividad subvencionada']::text[], 1, 'El artículo 14.1.d) dice que «Esta comunicación deberá efectuarse tan pronto como se conozca y, en todo caso, con anterioridad a la justificación de la aplicación dada a los fondos percibidos».', 2, '2026-10-14', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
