insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgs-016', (select id from leyes where slug = 'ley-38-2003'), '20.3', 'El órgano responsable de la administración y custodia de la Base de Datos Nacional de Subvenciones es:', array['El Tribunal de Cuentas', 'La Agencia Estatal de Administración Tributaria', 'La Comisión Nacional de los Mercados y la Competencia', 'La Intervención General de la Administración del Estado']::text[], 3, 'El artículo 20.3 establece: «La Intervención General de la Administración del Estado es el órgano responsable de la administración y custodia de la BDNS».', 1, '2026-10-14', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
