insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgs-017', (select id from leyes where slug = 'ley-38-2003'), '22.1', 'El procedimiento ordinario de concesión de subvenciones se tramita:', array['Mediante concesión directa', 'Por prorrateo entre todos los solicitantes', 'En régimen de concurrencia competitiva', 'Por orden de presentación de las solicitudes']::text[], 2, 'El artículo 22.1 dispone: «El procedimiento ordinario de concesión de subvenciones se tramitará en régimen de concurrencia competitiva».', 1, '2026-10-14', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
