insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgs-018', (select id from leyes where slug = 'ley-38-2003'), '22.2.a', 'Una subvención está prevista nominativamente en los Presupuestos Generales del Estado cuando en los estados de gasto aparecen determinados, al menos:', array['Su dotación presupuestaria y su beneficiario', 'Su objeto y su plazo de justificación', 'Su beneficiario y sus bases reguladoras', 'Su dotación presupuestaria y su objeto']::text[], 0, 'El artículo 22.2.a) la define como «aquella en que al menos su dotación presupuestaria y beneficiario aparezcan determinados en los estados de gasto del Presupuesto».', 3, '2026-10-14', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
