insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgs-019', (select id from leyes where slug = 'ley-38-2003'), '28.1', 'El instrumento habitual para canalizar las subvenciones nominativas de los Presupuestos Generales del Estado es:', array['La convocatoria pública', 'La orden de bases reguladoras', 'El contrato de servicios', 'El convenio']::text[], 3, 'El artículo 28.1 dice: «Los convenios serán el instrumento habitual para canalizar las subvenciones previstas nominativamente en los Presupuestos Generales del Estado».', 1, '2026-10-14', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
