insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgs-020', (select id from leyes where slug = 'ley-38-2003'), '28.2', 'Las normas especiales reguladoras de las subvenciones directas por razones de interés público del artículo 22.2.c) las aprueba el Gobierno por:', array['Orden ministerial', 'Real decreto', 'Ley ordinaria', 'Acuerdo de la Comisión Delegada para Asuntos Económicos']::text[], 1, 'El artículo 28.2 dispone: «El Gobierno aprobará por real decreto, a propuesta del ministro competente» las normas especiales reguladoras de las subvenciones del «párrafo c) del apartado 2 del artículo 22».', 2, '2026-10-14', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
