insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgs-021', (select id from leyes where slug = 'ley-38-2003'), '30.2', 'Si las bases no dicen nada, la cuenta justificativa se presenta como máximo en el plazo de … desde que finaliza el plazo para realizar la actividad:', array['Un mes', 'Seis meses', 'Tres meses', 'Dos meses']::text[], 2, 'El artículo 30.2 indica que, a falta de previsión de las bases, la presentación se realizará «como máximo, en el plazo de tres meses desde la finalización del plazo para la realización de la actividad».', 2, '2026-10-14', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'lgs-021', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 37 where o.slug = 'admin-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgs-022', (select id from leyes where slug = 'ley-38-2003'), '31.3', 'Si el gasto subvencionable supera la cuantía del contrato menor, el beneficiario debe solicitar, como mínimo:', array['Tres ofertas de diferentes proveedores', 'Dos ofertas de diferentes proveedores', 'Cinco ofertas de diferentes proveedores', 'Una oferta y un informe de tasador']::text[], 0, 'El artículo 31.3 establece que «el beneficiario deberá solicitar como mínimo tres ofertas de diferentes proveedores, con carácter previo a la contracción del compromiso».', 1, '2026-10-14', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
