insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgs-023', (select id from leyes where slug = 'ley-38-2003'), '31.4.a', 'En bienes inscribibles en un registro público, el periodo de destino al fin de la subvención no puede ser inferior a:', array['Dos años', 'Cinco años', 'Cuatro años', 'Diez años']::text[], 1, 'El artículo 31.4.a) fija un período que «no podrá ser inferior a cinco años en caso de bienes inscribibles en un registro público, ni a dos años para el resto de bienes».', 3, '2026-10-14', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
