insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgs-024', (select id from leyes where slug = 'ley-38-2003'), '34.2', 'La resolución de concesión de la subvención conlleva:', array['La aprobación del gasto', 'El reconocimiento de la obligación', 'La ordenación del pago', 'El compromiso del gasto correspondiente']::text[], 3, 'El artículo 34.2 dice: «La resolución de concesión de la subvención conllevará el compromiso del gasto correspondiente». La aprobación del gasto es previa (artículo 34.1).', 2, '2026-10-14', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
