insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgs-025', (select id from leyes where slug = 'ley-38-2003'), '36.1.b', 'Es causa de nulidad de la resolución de concesión de una subvención:', array['La justificación insuficiente de la subvención', 'El incumplimiento de las medidas de difusión', 'La carencia o insuficiencia de crédito', 'La presentación de la cuenta justificativa fuera de plazo']::text[], 2, 'El artículo 36.1 señala como causa de nulidad, en la letra b), «La carencia o insuficiencia de crédito».', 2, '2026-10-14', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
