insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgs-026', (select id from leyes where slug = 'ley-38-2003'), '37.1', 'Cuando procede el reintegro, el interés de demora se exige desde:', array['El momento del pago de la subvención', 'La fecha de la resolución de concesión', 'El vencimiento del plazo de justificación', 'El inicio del procedimiento de reintegro']::text[], 0, 'El artículo 37.1 prevé el reintegro y «la exigencia del interés de demora correspondiente desde el momento del pago de la subvención hasta la fecha en que se acuerde la procedencia del reintegro».', 3, '2026-10-14', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
