insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('lgs-027', (select id from leyes where slug = 'ley-38-2003'), '39.1', 'El derecho de la Administración a reconocer o liquidar el reintegro de una subvención prescribe a los:', array['Cinco años', 'Tres años', 'Diez años', 'Cuatro años']::text[], 3, 'El artículo 39.1 dispone: «Prescribirá a los cuatro años el derecho de la Administración a reconocer o liquidar el reintegro».', 1, '2026-10-14', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
