insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('tra-003', (select id from leyes where slug = 'ley-19-2013'), '2.1.g', 'El título I se aplica a las sociedades mercantiles en cuyo capital la participación de las entidades del artículo 2 sea:', array['Superior al 50 por 100', 'Igual o superior al 25 por 100', 'Superior al 40 por 100', 'Igual o superior al 75 por 100']::text[], 0, 'El artículo 2.1.g) se refiere a las sociedades mercantiles en cuyo capital social la participación, directa o indirecta, de las entidades previstas «sea superior al 50 por 100».', 2, '2026-01-02', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
