insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('tra-011', (select id from leyes where slug = 'ley-19-2013'), '14.1.l', '¿Cuál de los siguientes es un límite al derecho de acceso previsto en el artículo 14 de la Ley 19/2013?', array['La imagen institucional del órgano', 'La protección del medio ambiente', 'La carga de trabajo de la unidad', 'La organización interna del servicio']::text[], 1, 'Entre los límites del artículo 14.1, el acceso podrá limitarse cuando suponga un perjuicio para «l) La protección del medio ambiente».', 1, '2026-01-02', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
