insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('tra-013', (select id from leyes where slug = 'ley-19-2013'), '16', 'Cuando se concede acceso parcial por aplicar un límite, ¿qué debe hacerse?', array['Pedir autorización previa al Consejo de Transparencia', 'Suspender el plazo para resolver hasta un mes más', 'Comunicarlo al Defensor del Pueblo', 'Indicar al solicitante que parte de la información ha sido omitida']::text[], 3, 'Según el artículo 16, se concederá el acceso parcial y en ese caso «deberá indicarse al solicitante que parte de la información ha sido omitida».', 2, '2026-01-02', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
