insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('tra-014', (select id from leyes where slug = 'ley-19-2013'), '17.3', 'Sobre la motivación de la solicitud de acceso a la información pública:', array['Es obligatoria si se piden datos personales', 'El solicitante no está obligado a motivarla', 'Su ausencia es causa de inadmisión', 'Debe acreditar un interés directo']::text[], 1, 'El artículo 17.3 dispone que «el solicitante no está obligado a motivar su solicitud de acceso a la información» y que su ausencia «no será por si sola causa de rechazo de la solicitud».', 1, '2026-01-02', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
