insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('tra-015', (select id from leyes where slug = 'ley-19-2013'), '17.2.c', 'La solicitud de acceso debe presentarse por un medio que permita tener constancia, entre otros datos, de:', array['Los motivos de la solicitud', 'La firma electrónica cualificada del solicitante', 'Una dirección de contacto, preferentemente electrónica', 'El interés legítimo del solicitante']::text[], 2, 'El artículo 17.2 exige constancia, entre otros datos, de «c) Una dirección de contacto, preferentemente electrónica, a efectos de comunicaciones».', 1, '2026-01-02', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
