insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('tra-016', (select id from leyes where slug = 'ley-19-2013'), '18.1.b', 'Se inadmitirán las solicitudes referidas a información de carácter auxiliar o de apoyo, como la contenida en:', array['Notas, borradores u opiniones', 'Contratos menores adjudicados', 'Resoluciones firmes', 'Presupuestos aprobados']::text[], 0, 'El artículo 18.1.b) inadmite las solicitudes referidas a información auxiliar o de apoyo «como la contenida en notas, borradores, opiniones, resúmenes, comunicaciones e informes internos».', 1, '2026-01-02', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
