insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('tra-018', (select id from leyes where slug = 'ley-19-2013'), '19.2', 'Si la solicitud no identifica de forma suficiente la información, se pedirá al solicitante que la concrete en un plazo de:', array['Diez días', 'Cinco días', 'Quince días', 'Un mes']::text[], 0, 'El artículo 19.2 establece que se pedirá al solicitante «que la concrete en un plazo de diez días», con indicación de que, si no lo hace, se le tendrá por desistido.', 2, '2026-01-02', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
