insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('tra-019', (select id from leyes where slug = 'ley-19-2013'), '19.3', 'Si la información solicitada puede afectar a derechos de terceros identificados, se les concede para alegaciones un plazo de:', array['Diez días', 'Quince días', 'Cinco días', 'Un mes']::text[], 1, 'Según el artículo 19.3, a esos terceros «se les concederá un plazo de quince días para que puedan realizar las alegaciones que estimen oportunas».', 2, '2026-01-02', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
