insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('tra-021', (select id from leyes where slug = 'ley-19-2013'), '20.1', 'Si el volumen o la complejidad de la información lo hacen necesario, el plazo para resolver la solicitud de acceso:', array['Podrá ampliarse por otro mes', 'Podrá ampliarse por quince días', 'Podrá ampliarse por dos meses', 'No podrá ampliarse']::text[], 0, 'El artículo 20.1 permite que el plazo se amplíe «por otro mes en el caso de que el volumen o la complejidad de la información que se solicita así lo hagan necesario y previa notificación al solicitante».', 2, '2026-01-02', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
