insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('tra-022', (select id from leyes where slug = 'ley-19-2013'), '20.4', 'Si vence el plazo máximo sin resolución expresa notificada, la solicitud de acceso se entiende:', array['Estimada', 'Estimada parcialmente', 'Caducada', 'Desestimada']::text[], 3, 'El artículo 20.4 dispone que, transcurrido el plazo máximo sin resolución expresa, «se entenderá que la solicitud ha sido desestimada».', 1, '2026-01-02', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
