insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('tra-023', (select id from leyes where slug = 'ley-19-2013'), '22.1', 'Cuando no pueda darse el acceso en el momento de notificar la resolución, deberá otorgarse en un plazo no superior a:', array['Cinco días', 'Quince días', 'Diez días', 'Un mes']::text[], 2, 'El artículo 22.1 dispone que en ese caso el acceso «deberá otorgarse, en cualquier caso, en un plazo no superior a diez días».', 3, '2026-01-02', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
