insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('tra-024', (select id from leyes where slug = 'ley-19-2013'), '22.4', 'Sobre el coste del acceso a la información pública, la Ley 19/2013 establece que:', array['Siempre exige el pago de una tasa', 'Es gratuito, aunque la expedición de copias puede generar exacciones', 'Es gratuito en todo caso, incluidas las copias', 'Solo es gratuito por vía electrónica']::text[], 1, 'El artículo 22.4 señala que «el acceso a la información será gratuito», aunque «la expedición de copias o la trasposición de la información a un formato diferente al original podrá dar lugar a la exigencia de exacciones».', 1, '2026-01-02', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
