insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('tra-025', (select id from leyes where slug = 'ley-19-2013'), '24.2', '¿En qué plazo se interpone la reclamación ante el Consejo de Transparencia y Buen Gobierno?', array['Diez días', 'Un mes', 'Dos meses', 'Tres meses']::text[], 1, 'El artículo 24.2 dispone que la reclamación «se interpondrá en el plazo de un mes a contar desde el día siguiente al de la notificación del acto impugnado».', 1, '2026-01-02', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
