insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('tra-026', (select id from leyes where slug = 'ley-19-2013'), '24.4', 'Si el Consejo de Transparencia no resuelve una reclamación en plazo, ¿qué ocurre?', array['Se entiende estimada a los tres meses', 'Se entiende desestimada al mes', 'Se entiende desestimada a los tres meses', 'Se entiende estimada a los dos meses']::text[], 2, 'Según el artículo 24.4, «el plazo máximo para resolver y notificar la resolución será de tres meses, transcurrido el cual, la reclamación se entenderá desestimada».', 2, '2026-01-02', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
