insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('teb-002', (select id from leyes where slug = 'trebep'), '56.1.c', 'Una edad máxima de acceso al empleo público distinta de la edad de jubilación forzosa solo puede establecerse:', array['Por ley', 'Por las bases de cada convocatoria', 'Por real decreto del Gobierno', 'Por acuerdo de la Mesa General de Negociación']::text[], 0, 'El artículo 56.1.c) dispone: «Sólo por ley podrá establecerse otra edad máxima, distinta de la edad de jubilación forzosa, para el acceso al empleo público».', 2, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
