insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('teb-004', (select id from leyes where slug = 'trebep'), '59.1', 'En las ofertas de empleo público se reserva para personas con discapacidad un cupo de las vacantes:', array['No inferior al cinco por ciento', 'No inferior al siete por ciento', 'No inferior al diez por ciento', 'No superior al dos por ciento']::text[], 1, 'El artículo 59.1 establece que «se reservará un cupo no inferior al siete por ciento de las vacantes para ser cubiertas entre personas con discapacidad».', 1, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
