insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('teb-007', (select id from leyes where slug = 'trebep'), '61.6', 'El sistema de concurso, consistente únicamente en la valoración de méritos, puede aplicarse a la selección de funcionarios de carrera:', array['Solo en virtud de ley y con carácter excepcional', 'Cuando lo prevean las bases de la convocatoria', 'En todo caso, como alternativa a la oposición', 'Solo para el acceso a los Subgrupos C1 y C2']::text[], 0, 'El artículo 61.6 señala: «Sólo en virtud de ley podrá aplicarse, con carácter excepcional, el sistema de concurso que consistirá únicamente en la valoración de méritos».', 2, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
