insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('teb-009', (select id from leyes where slug = 'trebep'), '62.1', 'Según el artículo 62.1 del TREBEP, ¿qué requisito para adquirir la condición de funcionario de carrera sigue inmediatamente al nombramiento?', array['La toma de posesión', 'La superación del proceso selectivo', 'La publicación de la lista de aprobados', 'El acto de acatamiento de la Constitución']::text[], 3, 'El artículo 62.1 enumera, por este orden, la superación del proceso selectivo, el «Nombramiento por el órgano o autoridad competente», el «Acto de acatamiento de la Constitución» y la «Toma de posesión dentro del plazo que se establezca».', 3, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
