insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('teb-010', (select id from leyes where slug = 'trebep'), '64.1', 'La renuncia voluntaria a la condición de funcionario:', array['Puede hacerse de palabra y surte efecto inmediato', 'Se entiende aceptada si la Administración no resuelve en un mes', 'Se manifiesta por escrito y debe aceptarse expresamente por la Administración', 'Requiere informe previo de la Junta de Personal']::text[], 2, 'El artículo 64.1 dispone que la renuncia «habrá de ser manifestada por escrito y será aceptada expresamente por la Administración».', 1, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
