insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('teb-013', (select id from leyes where slug = 'trebep'), '68.1', 'Desaparecida la causa, tiene derecho a que se le conceda la rehabilitación quien perdió la condición de funcionario por:', array['Pérdida de la nacionalidad', 'Separación del servicio firme', 'Renuncia voluntaria', 'Condena a inhabilitación absoluta']::text[], 0, 'El artículo 68.1 prevé que, en caso de «pérdida de la nacionalidad o jubilación por incapacidad permanente para el servicio», el interesado podrá solicitar la rehabilitación, «que le será concedida».', 2, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
