insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('teb-018', (select id from leyes where slug = 'trebep'), '54.11', 'Los empleados públicos garantizarán la atención al ciudadano en la lengua que lo solicite:', array['Siempre que sea oficial en la Unión Europea', 'Solo si es el castellano', 'Si el empleado la conoce', 'Siempre que sea oficial en el territorio']::text[], 3, 'El artículo 54.11 establece que «Garantizarán la atención al ciudadano en la lengua que lo solicite siempre que sea oficial en el territorio».', 1, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
