insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ue-002', (select id from leyes where slug = 'tue'), '3.1', 'Según el TUE, la Unión tiene como finalidad promover:', array['La paz, la seguridad y la prosperidad de sus Estados', 'La paz, sus valores y el bienestar de sus pueblos', 'El mercado interior, el euro y la cohesión social', 'La democracia, la libertad y el pleno empleo']::text[], 1, 'El artículo 3.1 TUE establece: «La Unión tiene como finalidad promover la paz, sus valores y el bienestar de sus pueblos».', 1, '2016-06-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
