insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ue-012', (select id from leyes where slug = 'tue'), '15.4', 'Salvo que los Tratados dispongan otra cosa, el Consejo Europeo se pronuncia:', array['Por mayoría cualificada', 'Por unanimidad', 'Por consenso', 'Por mayoría simple']::text[], 2, 'El artículo 15.4 TUE dice: «El Consejo Europeo se pronunciará por consenso, excepto cuando los Tratados dispongan otra cosa».', 2, '2016-06-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
